# osu!'s gameplay frame in osu!pixels -- the storyboard's space, which the
# background is drawn in -- and the 8px the playfield sits lower than centre
# in it (`OsuPlayfieldAdjustmentContainer`, AlignWithStoryboard).
OSU_FRAME_WIDTH = 640.0
OSU_FRAME_HEIGHT = 480.0
OSU_PLAYFIELD_SHIFT_Y = 8.0


def osu_circle_radius(circle_size: float) -> float:
    """osu!'s hit circle radius in osu!pixels at `circle_size`:
    `54.4 - 4.48 * CS` (32 at CS 5), the value both clients use."""
    return 54.4 - 4.48 * float(circle_size)


def display_name(name: str) -> str:
    label = TRANSFORMATION_LABELS.get(name) or name.replace("_", " ").title()
    return tr("Transformations", label)


def extract_background_filename(document) -> str:
    section = ""
    for line in document.lines:
        content = line.rstrip("\r\n")
        stripped = content.strip()
        if stripped.startswith("[") and stripped.endswith("]"):
            section = stripped[1:-1]
            continue
        if section != "Events" or not stripped or stripped.startswith("//"):
            continue
        try:
            fields = next(csv.reader([content], skipinitialspace=True))
        except (csv.Error, StopIteration):
            continue
        if len(fields) >= 3 and fields[0].strip() == "0":
            return fields[2].strip().strip('"')
    return ""


def set_document_background(document, filename: str) -> None:
    section = ""
    events_header = None
    for index, line in enumerate(document.lines):
        content = line.rstrip("\r\n")
        stripped = content.strip()
        if stripped.startswith("[") and stripped.endswith("]"):
            section = stripped[1:-1]
            if section == "Events":
                events_header = index
            continue
        if section != "Events" or not stripped or stripped.startswith("//"):
            continue
        try:
            fields = next(csv.reader([content], skipinitialspace=True))
        except (csv.Error, StopIteration):
            continue
        if len(fields) >= 3 and fields[0].strip() == "0":
            ending = "\r\n" if line.endswith("\r\n") else "\n" if line.endswith("\n") else ""
            document.lines[index] = f'0,0,"{filename}",0,0{ending}'
            return
    if events_header is None:
        ending = "\n"
        document.lines.extend([f"{ending}[Events]{ending}", f'0,0,"{filename}",0,0{ending}'])
    else:
        ending = "\r\n" if document.lines[events_header].endswith("\r\n") else "\n"
        document.lines.insert(events_header + 1, f'0,0,"{filename}",0,0{ending}')
        for note in document.hit_objects:
            if note.source_line_index > events_header:
                note.source_line_index += 1


PARAM_STYLE = """
QLabel#paramLabel { color: #aeb8c5; font-size: 12px; font-weight: 600; background: transparent; }
"""


class ParameterControl(QWidget):
    """One transformation parameter, as the approved Fancy Arranger mockup
    draws it: its name and its number on one line, the slider under them.

    With no `label` it is the compact form (slider, then number) for the
    sub-toolbar and anywhere else a caption already sits beside it. The
    number box carries its own step arrows (the window stylesheet's); the
    pink +/- pair beside it is gone, as it is from every other number.
    """

    changed = Signal()

    def __init__(self, definition: dict[str, Any], label: str | None = None) -> None:
        super().__init__(); self.definition = definition
        self.setStyleSheet(PARAM_STYLE)
        self.choice = None; self.slider = None; self.spin = None
        outer = QVBoxLayout(self); outer.setContentsMargins(0, 0, 0, 0); outer.setSpacing(4)
        head = QHBoxLayout(); head.setContentsMargins(0, 0, 0, 0); head.setSpacing(8)
        self.caption = None
        if label is not None:
            self.caption = QLabel(label); self.caption.setObjectName("paramLabel")
            head.addWidget(self.caption)
            head.addStretch(1)
            outer.addLayout(head)
        kind = definition["type"]
        if kind == "font":
            self.font_combo = QFontComboBox(); self.font_combo.setCurrentFont(QFont(str(definition.get("default", "Segoe UI"))))
            self.font_combo.currentFontChanged.connect(lambda _font: self.changed.emit())
            outer.addWidget(self.font_combo)
            return
        if kind == "text":
            self.text_input = QLineEdit(str(definition.get("default", "")))
            self.text_input.setPlaceholderText(tr("Parameters", "Enter text, for example 67, 日本, or ภาษาไทย"))
            self.text_input.textChanged.connect(self.changed)
            outer.addWidget(self.text_input)
            return
        if kind == "choice":
            self.choice_group = QButtonGroup(self); self.choice_group.setExclusive(True); self.choice_buttons = {}
            buttons = []
            for choice_label, value in definition["choices"]:
                button = QPushButton(tr("Parameters", str(choice_label))); button.setCheckable(True)
                button.setProperty("choice_value", value)
                self.choice_group.addButton(button); self.choice_buttons[value] = button; buttons.append(button)
            self.choice_buttons[definition["default"]].setChecked(True)
            self.choice_group.buttonClicked.connect(self.changed)
            pills = segmented(buttons)
            row = QHBoxLayout(); row.setContentsMargins(0, 0, 0, 0)
            row.addWidget(pills); row.addStretch(1)
            outer.addLayout(row)
            return
        if definition["key"] == "seed" or definition["key"].endswith("_seed"):
            self.scale = 1
            self.spin = QSpinBox()
            self.spin.setRange(int(definition["min"]), int(definition["max"]))
            self.spin.setValue(int(definition.get("default", 0)))
            self.spin.setMinimumWidth(110)
            random_button = QPushButton(tr("Parameters", "Random Seed"))
            random_button.setProperty("role", "ghost")
            random_button.setStyleSheet("QPushButton { border: 1px solid #3a4554; }")
            random_button.clicked.connect(self.randomize)
            row = QHBoxLayout(); row.setContentsMargins(0, 0, 0, 0); row.setSpacing(8)
            row.addWidget(self.spin, 1); row.addWidget(random_button)
            outer.addLayout(row)
            self.spin.valueChanged.connect(lambda _value: self.changed.emit())
            if self.caption is not None:
                scrub_label(self.caption, self.spin)
            return
        step = float(definition.get("step", 1 if kind == "int" else .1))
        self.scale = 1 if kind == "int" or step >= 1 else 10 if step >= .1 else 100
        self.slider = QSlider(Qt.Horizontal)
        self.slider.setRange(round(float(definition["min"]) * self.scale), round(float(definition["max"]) * self.scale))
        if kind == "int":
            self.spin = QSpinBox(); self.spin.setRange(int(definition["min"]), int(definition["max"])); self.spin.setSingleStep(int(definition.get("step", 1)))
        else:
            self.spin = QDoubleSpinBox(); self.spin.setRange(float(definition["min"]), float(definition["max"])); self.spin.setSingleStep(step); self.spin.setDecimals(2)
        self.spin.setFixedWidth(96)
        if self.caption is not None:
            # The number sits on the name's line, right-aligned; the slider
            # gets the full width under it, which is what makes it draggable.
            head.addWidget(self.spin)
            outer.addWidget(self.slider)
            scrub_label(self.caption, self.spin)
        else:
            row = QHBoxLayout(); row.setContentsMargins(0, 0, 0, 0); row.setSpacing(8)
            row.addWidget(self.slider, 1); row.addWidget(self.spin)
            outer.addLayout(row)
        self.slider.valueChanged.connect(self._from_slider); self.spin.valueChanged.connect(self._from_spin); self.set_value(definition["default"])

    def _from_slider(self, raw):
        self.spin.blockSignals(True); self.spin.setValue(raw / self.scale); self.spin.blockSignals(False); self.changed.emit()

    def _from_spin(self, value):
        self.slider.blockSignals(True); self.slider.setValue(round(float(value) * self.scale)); self.slider.blockSignals(False); self.changed.emit()

    def randomize(self):
        self.set_value(random.SystemRandom().randint(int(self.definition["min"]), int(self.definition["max"]))); self.changed.emit()

    def set_value(self, value):
        if self.definition["type"] == "font":
            self.font_combo.blockSignals(True); self.font_combo.setCurrentFont(QFont(str(value))); self.font_combo.blockSignals(False); return
        if self.definition["type"] == "text":
            self.text_input.blockSignals(True)
            self.text_input.setText(str(value))
            self.text_input.blockSignals(False)
            return

        if self.definition["type"] == "choice":
            for button in self.choice_group.buttons():
                if button.property("choice_value") == value:
                    button.blockSignals(True)
                    button.setChecked(True)
                    button.blockSignals(False)
                    return
            return

        # Seed controls deliberately have slider=None. Numeric restoration must
        # therefore treat the spin box as mandatory and the slider as optional.
        self.spin.blockSignals(True)
        self.spin.setValue(value)

        if self.slider is not None:
            self.slider.blockSignals(True)
            self.slider.setValue(round(float(value) * self.scale))
            self.slider.blockSignals(False)

        self.spin.blockSignals(False)

    def value(self):
        if self.definition["type"] == "font": return self.font_combo.currentFont().family()
        return self.text_input.text() if self.definition["type"] == "text" else self.choice_group.checkedButton().property("choice_value") if self.definition["type"] == "choice" else self.spin.value()


class DifficultyValueControl(QWidget):
    """AR or CS for the export: its short name, a slider and a number box.

    Was a caption, a 200px slider, a box and a pink +/- pair; the row ran off
    a 1920 screen, and the slider went with the +/- pair. It is back, short,
    because a CS is chosen by watching the circles grow and shrink on the
    canvas rather than by typing a number. The box stays for the exact value
    written to the file; the slider moves in the same 0.01 steps it holds.
    """

    SLIDER_STEPS_PER_UNIT = 100

    changed = Signal(float)

    def __init__(self, label: str, default: float, tooltip: str) -> None:
        super().__init__()
        self.setToolTip(tooltip)
        self.setObjectName("stepper")
        self.setStyleSheet(
            "QWidget#stepper { background: #252d39; border: 1px solid #3a4554; border-radius: 6px; }"
            "QWidget#stepper QLabel { color: #7d8794; font-size: 11px; font-weight: 700; background: transparent;"
            " padding-left: 8px; }"
            "QWidget#stepper QDoubleSpinBox { border: 0; background: transparent; }")
        self.setAttribute(Qt.WA_StyledBackground, True)
        layout = QHBoxLayout(self); layout.setContentsMargins(0, 0, 0, 0); layout.setSpacing(2)
        caption = QLabel(label); caption.setToolTip(tooltip); layout.addWidget(caption)
        self.value_box = QDoubleSpinBox(); self.value_box.setRange(0.0, 10.0); self.value_box.setDecimals(2)
        self.value_box.setSingleStep(0.1); self.value_box.setFixedWidth(84); self.value_box.setToolTip(tooltip)
        self.slider = QSlider(Qt.Horizontal)
        self.slider.setRange(0, int(10 * self.SLIDER_STEPS_PER_UNIT))
        self.slider.setPageStep(self.SLIDER_STEPS_PER_UNIT)
        # 110 where there is room, and it gives way first on a narrow window:
        # fixed at 110, the two of them pushed Export off a 1366 screen.
        self.slider.setMinimumWidth(56)
        self.slider.setMaximumWidth(110)
        self.slider.setToolTip(tooltip)
        layout.addWidget(self.slider)
        layout.addWidget(self.value_box)
        scrub_label(caption, self.value_box)
        # The box is the one source of truth and the only emitter: the slider
        # writes into it, so a drag fires `changed` once per step, not twice.
        self.slider.valueChanged.connect(
            lambda position: self.value_box.setValue(position / self.SLIDER_STEPS_PER_UNIT))
        self.value_box.valueChanged.connect(self._box_changed); self.set_value(default)

    def _box_changed(self, value: float) -> None:
        self.slider.blockSignals(True)
        self.slider.setValue(round(value * self.SLIDER_STEPS_PER_UNIT))
        self.slider.blockSignals(False)
        self.changed.emit(float(value))

    def value(self) -> float: return float(self.value_box.value())

    def set_value(self, value: float) -> None:
        self.value_box.setValue(max(0.0, min(10.0, float(value))))


class DrawingSurface(QWidget):
    def __init__(self):
        super().__init__();self.strokes=[];self.active=None;self.redo_strokes=[];self.setMinimumSize(700,450);self.setFocusPolicy(Qt.StrongFocus)
    def mousePressEvent(self,event):
        if event.button()==Qt.LeftButton:
            self.setFocus();self.active=[event.position()];self.strokes.append(self.active);self.redo_strokes.clear();event.accept();self.update()
    def mouseMoveEvent(self,event):
        if self.active is not None and event.buttons() & Qt.LeftButton:
            point=event.position()
            if (point-self.active[-1]).manhattanLength()>=1:self.active.append(point);self.update()
            event.accept()
    def mouseReleaseEvent(self,event):
        if event.button()==Qt.LeftButton:
            point=event.position()
            if self.active is not None and (point-self.active[-1]).manhattanLength()>=1:self.active.append(point)
            self.active=None;event.accept();self.update()
    def paintEvent(self,event):
        painter=QPainter(self);painter.fillRect(self.rect(),theme.color("#11151c"));painter.setRenderHint(QPainter.Antialiasing,True);painter.setPen(QPen(theme.color("#f3a6bd"),4,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
        for stroke in self.strokes:
            if len(stroke)==1:painter.drawPoint(stroke[0])
            for a,b in zip(stroke,stroke[1:]):painter.drawLine(a,b)
    def sampled_points(self):
        points=[]
        for stroke in self.strokes:
            for point in stroke:
                points.append((max(0.0,min(512.0,point.x()/max(1,self.width())*512.0)),max(0.0,min(384.0,point.y()/max(1,self.height())*384.0))))
        return points
    def clear(self):
        if self.strokes:self.redo_strokes.extend(reversed(self.strokes));self.strokes.clear();self.active=None;self.update()
    def undo(self):
        self.active=None
        if self.strokes:self.redo_strokes.append(self.strokes.pop());self.update()
    def redo(self):
        if self.redo_strokes:self.strokes.append(self.redo_strokes.pop());self.update()


class DrawingDialog(QDialog):
    def __init__(self,parent=None):
        super().__init__(parent);self.accepted_points=[];self.setWindowTitle(tr("DrawingDialog", "Drawing"));self.resize(780,560)
        icon=application_icon()
        if not icon.isNull():self.setWindowIcon(icon)
        layout=QVBoxLayout(self);label=QLabel(tr("DrawingDialog", "Draw one or more strokes. Notes are placed top-to-bottom, then horizontally within each row. Ctrl+Z: undo, Ctrl+Y: redo."));label.setWordWrap(True);layout.addWidget(label)
        self.surface=DrawingSurface();layout.addWidget(self.surface,1)
        row=QHBoxLayout();undo_button=QPushButton(tr("DrawingDialog", "Undo"));redo_button=QPushButton(tr("DrawingDialog", "Redo"));clear_button=QPushButton(tr("DrawingDialog", "Clear"));undo_button.clicked.connect(self.surface.undo);redo_button.clicked.connect(self.surface.redo);clear_button.clicked.connect(self.surface.clear);row.addWidget(undo_button);row.addWidget(redo_button);row.addWidget(clear_button)
        import_button=QPushButton(tr("DrawingDialog", "Import Image..."));import_button.clicked.connect(self.import_image);row.addWidget(import_button)
        layout.addLayout(row)
        self.undo_shortcut=QShortcut(QKeySequence("Ctrl+Z"),self);self.undo_shortcut.setContext(Qt.WidgetWithChildrenShortcut);self.undo_shortcut.activated.connect(self.surface.undo)
        self.redo_shortcut=QShortcut(QKeySequence("Ctrl+Y"),self);self.redo_shortcut.setContext(Qt.WidgetWithChildrenShortcut);self.redo_shortcut.activated.connect(self.surface.redo)
        buttons=QDialogButtonBox(QDialogButtonBox.Ok|QDialogButtonBox.Cancel);buttons.accepted.connect(self.accept);buttons.rejected.connect(self.reject);layout.addWidget(buttons)
    def import_image(self):
        """Trace a local image and add the result as Drawing strokes.

        trace_image already fits its output to the 512x384 playfield, so the
        only conversion needed is playfield -> surface widget coordinates,
        which is the exact inverse of DrawingSurface.sampled_points().

        Strokes are appended rather than replacing the canvas, so an import
        can never silently destroy hand-drawn work.
        """
        dialog=ImageTraceDialog(self)
        # Applied from here rather than inside the dialog: gui imports it, so
        # it cannot import back.
        if dialog.exec()!=QDialog.Accepted:
            return
        strokes=[stroke for stroke in dialog.accepted_strokes if len(stroke)>=2]
        if not strokes:
            return
        width=max(1,self.surface.width());height=max(1,self.surface.height())
        for stroke in strokes:
            self.surface.strokes.append([
                QPointF(x/PLAYFIELD_WIDTH*width, y/PLAYFIELD_HEIGHT*height)
                for x,y in stroke
            ])
        self.surface.active=None;self.surface.redo_strokes.clear();self.surface.update()

    def accept(self):
        points=self.surface.sampled_points()
        if len(points)<2:
            QMessageBox.information(self,tr("DrawingDialog", "Drawing"),tr("DrawingDialog", "Draw at least one stroke before pressing OK."))
            return
        self.accepted_points=points
        super().accept()


def shape_icon(name: str) -> QIcon:
    """A small line drawing of transformation `name`, for its tile.

    Two pixmaps: grey for the tile at rest, pink for the chosen one (QIcon's
    On state, which a checked QToolButton draws). Drawn rather than shipped
    as files so a new transformation needs one branch here, not an asset.
    """
    icon = QIcon()
    for colour, state in (("#aeb8c5", QIcon.Off), ("#f3a6bd", QIcon.On)):
        pixmap = QPixmap(64, 44)
        pixmap.setDevicePixelRatio(2.0)
        pixmap.fill(Qt.transparent)
        painter = QPainter(pixmap)
        painter.setRenderHint(QPainter.Antialiasing)
        painter.setPen(QPen(QColor(colour), 1.6, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
        painter.setBrush(Qt.NoBrush)
        _draw_shape_glyph(painter, name, colour)
        painter.end()
        icon.addPixmap(pixmap, QIcon.Normal, state)
    return icon


def _draw_shape_glyph(painter: QPainter, name: str, colour: str) -> None:
    """Draw `name` in a 32x22 box (the icon at 1x)."""
    cx, cy = 16.0, 11.0

    def poly(points, closed=True):
        path = QPainterPath(QPointF(*points[0]))
        for point in points[1:]:
            path.lineTo(QPointF(*point))
        if closed:
            path.closeSubpath()
        painter.drawPath(path)

    def curve(fn, steps=48):
        poly([fn(i / steps) for i in range(steps + 1)], closed=False)

    def dot(x, y, r=1.4):
        painter.save()
        painter.setBrush(QColor(colour))
        painter.drawEllipse(QPointF(x, y), r, r)
        painter.restore()

    if name == "circle":
        painter.drawEllipse(QPointF(cx, cy), 8, 8)
    elif name in ("ellipse", "arc"):
        if name == "ellipse":
            painter.drawEllipse(QPointF(cx, cy), 12, 7)
        else:
            curve(lambda t: (cx + 12 * math.cos(math.pi * (1 + t)), cy + 4 + 12 * math.sin(math.pi * (1 + t)) * 0.8))
    elif name == "square":
        painter.drawRect(QRectF(cx - 8, cy - 8, 16, 16))
    elif name == "triangle":
        poly([(cx, 3), (cx + 9, 19), (cx - 9, 19)])
    elif name == "diamond":
        poly([(cx, 2), (cx + 8, cy), (cx, 20), (cx - 8, cy)])
    elif name == "infinity":
        curve(lambda t: (cx + 12 * math.cos(2 * math.pi * t) / (1 + math.sin(2 * math.pi * t) ** 2),
                         cy + 12 * math.sin(2 * math.pi * t) * math.cos(2 * math.pi * t) / (1 + math.sin(2 * math.pi * t) ** 2)))
    elif name == "star":
        points = []
        for k in range(10):
            radius = 9 if k % 2 == 0 else 3.8
            angle = -math.pi / 2 + k * math.pi / 5
            points.append((cx + radius * math.cos(angle), cy + 1 + radius * math.sin(angle)))
        poly(points)
    elif name == "spiral":
        curve(lambda t: (cx + 9 * t * math.cos(6 * math.pi * t), cy + 9 * t * math.sin(6 * math.pi * t)), 80)
    elif name == "straight_line":
        poly([(4, 18), (28, 4)], closed=False)
    elif name == "wave":
        curve(lambda t: (3 + 26 * t, cy - 7 * math.sin(4 * math.pi * t)))
    elif name == "zigzag":
        poly([(3, 16), (9, 6), (15, 16), (21, 6), (27, 16)], closed=False)
    elif name in ("horizontal", "vertical"):
        for row in range(3):
            for column in range(5):
                x, y = 6 + column * 5, 5 + row * 6
                dot(x, y) if name == "horizontal" else dot(10 + row * 6, 2 + column * 4.5)
    elif name in ("taiko", "vertical_taiko"):
        for index in range(3):
            if name == "taiko":
                poly([(4, 5 + index * 6), (28, 5 + index * 6)], closed=False)
            else:
                poly([(9 + index * 7, 2), (9 + index * 7, 20)], closed=False)
        dot(12, 11, 2.2) if name == "taiko" else dot(16, 9, 2.2)
    elif name == "pinwheel":
        for blade in range(4):
            base = blade * math.pi / 2
            curve(lambda t, b=base: (cx + 9 * t * math.cos(b + 1.3 * t), cy + 9 * t * math.sin(b + 1.3 * t)), 16)
    elif name == "dvd_bouncing":
        painter.drawRect(QRectF(3, 2, 26, 18))
        poly([(6, 17), (14, 5), (22, 17), (26, 11)], closed=False)
    elif name == "random_walk":
        poly([(4, 14), (8, 9), (11, 13), (15, 6), (19, 11), (23, 8), (28, 15)], closed=False)
    elif name == "random":
        for x, y in ((6, 6), (13, 15), (19, 5), (25, 13), (9, 18), (22, 19), (28, 6)):
            dot(x, y)
    elif name == "text":
        font = QFont("Segoe UI", 11)
        font.setBold(True)
        painter.setFont(font)
        painter.drawText(QRectF(0, 0, 32, 22), Qt.AlignCenter, "Aa")
    elif name == "drawn_path":
        path = QPainterPath(QPointF(4, 16))
        path.cubicTo(QPointF(9, 2), QPointF(16, 22), QPointF(28, 5))
        painter.drawPath(path)
    elif name == "equation":
        font = QFont("Segoe UI", 10)
        font.setItalic(True)
        painter.setFont(font)
        painter.drawText(QRectF(0, 0, 32, 22), Qt.AlignCenter, "f(x)")
    else:  # none
        painter.drawEllipse(QPointF(cx, cy), 7, 7)
        poly([(cx - 5, cy + 5), (cx + 5, cy - 5)], closed=False)


TILE_GRID_STYLE = """
QToolButton#shapeTile {
    background: #222a36; color: #aeb8c5; border: 1px solid #303947; border-radius: 6px;
    padding: 5px 2px 4px; font-size: 11px; font-weight: 600;
}
QToolButton#shapeTile:hover { background: #2a3341; color: #e8edf3; }
QToolButton#shapeTile:checked { background: #2a2230; color: #ffffff; border: 1px solid #ff66aa; }
QLabel#sectionCaption { color: #7d8794; font-size: 10.5px; font-weight: 700; letter-spacing: 1px; background: transparent; }
QLabel#kbd { background: #252d39; border: 1px solid #3a4554; border-bottom: 2px solid #3a4554; border-radius: 3px;
    color: #aeb8c5; font-size: 10.5px; font-weight: 600; padding: 0 4px; }
QLabel#kbdText { color: #7d8794; font-size: 11.5px; background: transparent; }
"""


def section_caption(text: str) -> QLabel:
    label = QLabel(text.upper())
    label.setObjectName("sectionCaption")
    return label


def key_hint(keys: list[str], text: str) -> QWidget:
    """"[Shift] + [Wheel] 1 beat": key caps, so a hint reads as the keys."""
    box = QWidget()
    row = QHBoxLayout(box)
    row.setContentsMargins(0, 0, 0, 0)
    row.setSpacing(3)
    for index, key in enumerate(keys):
        if index:
            plus = QLabel("+")
            plus.setObjectName("kbdText")
            row.addWidget(plus)
        cap = QLabel(key)
        cap.setObjectName("kbd")
        cap.setFixedHeight(18)
        cap.setAlignment(Qt.AlignCenter)
        row.addWidget(cap, 0, Qt.AlignVCenter)
    words = QLabel(text)
    words.setObjectName("kbdText")
    row.addSpacing(3)
    row.addWidget(words, 0, Qt.AlignVCenter)
    box.setSizePolicy(QSizePolicy.Fixed, QSizePolicy.Fixed)
    return box


class TransformCanvas(QWidget):
    background_dropped = Signal(str)
    drag_offset_requested = Signal(object, float, float)
    def __init__(self) -> None:
        super().__init__()

        self.notes = []
        self.positions: dict[int, tuple[int, int]] = {}
        self.selected: set[int] = set()
        self.drag_last_position = None
        self.drag_group = None
        self.view_scale = 1.0
        self.view_offset_x = 0.0
        self.view_offset_y = 0.0
        self.render_rect = QRectF()
        self.playfield_rect = QRectF()

        self.background_pixmap = QPixmap()
        self.background_opacity = 0.55
        # Where each note is drawn while it glides from its old place to
        # `positions` (the target, which is what hit tests and callers read).
        # Seeing where each note goes is the point of the page.
        self._glide_from: dict[int, tuple[float, float]] = {}
        self._glide_t = 1.0
        self._glide = QVariantAnimation(self)
        self._glide.setStartValue(0.0)
        self._glide.setEndValue(1.0)
        self._glide.setDuration(260)
        self._glide.setEasingCurve(QEasingCurve.OutCubic)
        self._glide.valueChanged.connect(self._glide_step)
        # The export's CS, which sizes the circles (osu_circle_radius).
        self.circle_size = 7.0
        # The Settings switch; reduced_motion() is the OS's, this is the user's.
        self.animate_transforms = True
        self.setAcceptDrops(True)
        # Small enough for a half-screen window; the docks around it take what
        # is left, and the 16:9 frame letterboxes inside whatever this gets.
        self.setMinimumHeight(160)

    def set_state(
        self,
        notes,
        positions: dict[int, tuple[int, int]],
        selected: set[int],
    ) -> None:
        # A new target while the old one is still being reached starts from
        # where the notes are drawn now, so a slider dragged across its range
        # never makes them jump. Not while a note is being dragged by hand:
        # there the note follows the pointer, and easing it would lag behind.
        moved = positions is not self.positions and positions != self.positions
        if (moved and self.drag_last_position is None and self.animate_transforms
                and not reduced_motion() and self.isVisible()):
            self._glide_from = {
                note.original_index: self._drawn_position(note) for note in self.notes
            }
            self._glide_t = 0.0
            self._glide.stop()
            self._glide.start()
        self.notes = notes
        self.positions = positions
        self.selected = set(selected)
        self.update()

    def _glide_step(self, value) -> None:
        self._glide_t = float(value)
        self.update()

    def _drawn_position(self, note) -> tuple[float, float]:
        target = self.positions.get(note.original_index, (note.x, note.y))
        if self._glide_t >= 1.0:
            return target
        start = self._glide_from.get(note.original_index, target)
        t = self._glide_t
        return (start[0] + (target[0] - start[0]) * t, start[1] + (target[1] - start[1]) * t)

    def set_background(self, image_path: str | None) -> None:
        if image_path and Path(image_path).is_file():
            self.background_pixmap = QPixmap(image_path)
        else:
            self.background_pixmap = QPixmap()
        self.update()

    def set_background_opacity(self, value: int) -> None:
        self.background_opacity = max(0.0, min(1.0, value / 100.0))
        self.update()

    def dragEnterEvent(self, event) -> None:
        urls = event.mimeData().urls()
        if any(Path(url.toLocalFile()).suffix.lower() in {".jpg", ".jpeg", ".png", ".webp", ".bmp"} for url in urls):
            event.acceptProposedAction()

    def dropEvent(self, event) -> None:
        for url in event.mimeData().urls():
            candidate = Path(url.toLocalFile())
            if candidate.suffix.lower() in {".jpg", ".jpeg", ".png", ".webp", ".bmp"} and candidate.is_file():
                self.background_dropped.emit(str(candidate))
                event.acceptProposedAction()
                return

    def _update_view_geometry(self) -> None:
        # Fixed 16:9 preview, letterboxed inside the widget.
        available = self.rect().adjusted(12, 12, -12, -12)
        render_width = float(max(1, available.width()))
        render_height = render_width * 9.0 / 16.0
        if render_height > available.height():
            render_height = float(max(1, available.height()))
            render_width = render_height * 16.0 / 9.0
        self.render_rect = QRectF(
            available.center().x() - render_width / 2.0,
            available.center().y() - render_height / 2.0,
            render_width,
            render_height,
        )

        # osu!'s own placement, not the 4:3 playfield stretched to the full
        # height as it was -- which drew every pattern 25% larger than osu!
        # shows it over the same background. `OsuPlayfieldAdjustmentContainer`:
        # the 512x384 playfield is 80% of a 4:3 area (640x480 in osu!pixels,
        # the storyboard's own space), centred, and shifted down 8 osu!pixels
        # to line up with the storyboard -- osu!stable's (64, 56).
        frame_height = self.render_rect.height()
        frame_width = frame_height * 4.0 / 3.0
        if frame_width > self.render_rect.width():
            frame_width = self.render_rect.width()
            frame_height = frame_width * 3.0 / 4.0
        scale = frame_height / OSU_FRAME_HEIGHT
        frame_left = self.render_rect.center().x() - frame_width / 2.0
        frame_top = self.render_rect.center().y() - frame_height / 2.0
        self.playfield_rect = QRectF(
            frame_left + (OSU_FRAME_WIDTH - PLAYFIELD_WIDTH) / 2.0 * scale,
            frame_top + ((OSU_FRAME_HEIGHT - PLAYFIELD_HEIGHT) / 2.0 + OSU_PLAYFIELD_SHIFT_Y) * scale,
            PLAYFIELD_WIDTH * scale,
            PLAYFIELD_HEIGHT * scale,
        )

        self.view_scale = self.playfield_rect.width() / PLAYFIELD_WIDTH
        self.view_offset_x = self.playfield_rect.left()
        self.view_offset_y = self.playfield_rect.top()

    def resizeEvent(self, event) -> None:
        super().resizeEvent(event)
        self._update_view_geometry()
        self.update()

    def paintEvent(self, event) -> None:
        # First, not after the border: the border and the background read the
        # geometry too, and drew with the previous size's until the notes
        # asked for it again.
        self._update_view_geometry()
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing, True)
        painter.fillRect(self.rect(), theme.color("#11151c"))
        backdrop = self._scaled_background()
        if backdrop is not None:
            painter.drawPixmap(self.render_rect.topLeft(), backdrop)
        painter.setPen(QPen(theme.color("#465164"), 1))
        painter.drawRect(
            self.playfield_rect
        )

        radius = self._drawn_radius()
        view_scale = self.view_scale
        offset_x = self.view_offset_x
        offset_y = self.view_offset_y
        # A note is one of eight looks (kat/don x selected x finisher), so each
        # is rasterised once per radius and stamped. Anti-aliased ellipses cost
        # ~50us apiece and a dense map is thousands of them per glide frame.
        # Stamped in note order rather than batched by colour: overlapping
        # notes of different colours would swap which one is on top.
        selected = self.selected
        half = self._sprite_size(radius) / 2.0
        # Off-canvas notes (a transform can fling them anywhere) cost nothing.
        visible = self.rect().adjusted(-int(half), -int(half), int(half), int(half))
        for note in self.notes:
            position = self._drawn_position(note)
            x = offset_x + position[0] * view_scale
            y = offset_y + position[1] * view_scale
            if not visible.contains(int(x), int(y)):
                continue
            sprite = self._note_sprite(note.is_kat, note.original_index in selected, note.is_finisher, radius)
            painter.drawPixmap(QPointF(x - half, y - half), sprite)

    _KAT_BRUSH = QColor("#4aa3ff")
    _DON_BRUSH = QColor("#ff4f5e")
    _NOTE_PEN_WIDTH = 2
    _SELECTED_PEN = QPen(QColor("#ffd166"), _NOTE_PEN_WIDTH)
    _NORMAL_PEN = QPen(QColor("#f4f7fb"), _NOTE_PEN_WIDTH)

    def _sprite_size(self, radius: float) -> int:
        # The circle plus half the pen on each side, and a pixel of
        # anti-aliasing margin.
        return int(2 * radius + self._NOTE_PEN_WIDTH) + 2

    def _note_sprite(self, is_kat: bool, is_selected: bool, is_finisher: bool, radius: float):
        ratio = self.devicePixelRatioF()
        key = (round(radius, 2), ratio)
        if getattr(self, "_sprite_key", None) != key:
            self._sprite_key = key
            self._sprites: dict[tuple[bool, bool, bool], QPixmap] = {}
        look = (is_kat, is_selected, is_finisher)
        sprite = self._sprites.get(look)
        if sprite is None:
            size = self._sprite_size(radius)
            sprite = QPixmap(int(size * ratio), int(size * ratio))
            sprite.setDevicePixelRatio(ratio)
            sprite.fill(Qt.transparent)
            stamper = QPainter(sprite)
            stamper.setRenderHint(QPainter.Antialiasing, True)
            stamper.setBrush(self._KAT_BRUSH if is_kat else self._DON_BRUSH)
            stamper.setPen(self._SELECTED_PEN if is_selected else self._NORMAL_PEN)
            centre = QPointF(size / 2.0, size / 2.0)
            stamper.drawEllipse(centre, radius, radius)
            if is_finisher:
                stamper.setBrush(Qt.NoBrush)
                stamper.drawEllipse(centre, radius * 0.72, radius * 0.72)
            stamper.end()
            self._sprites[look] = sprite
        return sprite

    def _drawn_radius(self) -> float:
        # osu!'s circle at the export's CS, to scale with the playfield. Floored
        # at the pen width and a half: CS 10 is 9.6 osu!px, which on the 160px
        # minimum canvas is a radius the 2px outline alone would swallow, and a
        # note that is all outline is not visibly a note.
        return max(osu_circle_radius(self.circle_size) * self.view_scale, self._NOTE_PEN_WIDTH * 1.5)

    def _scaled_background(self):
        """The cropped, scaled, faded background, or None without one.

        Cached because the glide repaints 60 times a second and each paint was
        cropping and scaling a full-size image with opacity applied. Rebuilt
        only when the size, the image or the opacity changes.
        """
        if self.background_pixmap.isNull():
            return None
        size = self.render_rect.size().toSize()
        if size.isEmpty():
            return None
        ratio = self.devicePixelRatioF()
        key = (size.width(), size.height(), ratio, self.background_pixmap.cacheKey(), self.background_opacity)
        if getattr(self, "_background_cache_key", None) != key:
            source_width = self.background_pixmap.width()
            source_height = self.background_pixmap.height()
            source_ratio = source_width / max(1, source_height)
            if source_ratio > 16 / 9:
                crop_width = source_height * 16 / 9
                source = QRectF((source_width - crop_width) / 2, 0, crop_width, source_height)
            else:
                crop_height = source_width * 9 / 16
                source = QRectF(0, (source_height - crop_height) / 2, source_width, crop_height)
            baked = QPixmap(size * ratio)
            baked.setDevicePixelRatio(ratio)
            baked.fill(Qt.transparent)
            baker = QPainter(baked)
            baker.setRenderHint(QPainter.SmoothPixmapTransform, True)
            baker.setOpacity(self.background_opacity)
            baker.drawPixmap(QRectF(0, 0, size.width(), size.height()), self.background_pixmap, source)
            baker.end()
            self._background_cache = baked
            self._background_cache_key = key
        return self._background_cache

    def _note_at_canvas_position(self, position):
        self._update_view_geometry()
        if self.view_scale <= 0:
            return None
        playfield_x = (position.x() - self.view_offset_x) / self.view_scale
        playfield_y = (position.y() - self.view_offset_y) / self.view_scale
        best_note = None
        best_distance = float("inf")
        for note in self.notes:
            if note.original_index not in self.selected:
                continue
            x, y = self.positions.get(note.original_index, (note.x, note.y))
            distance = (x - playfield_x) ** 2 + (y - playfield_y) ** 2
            if distance < best_distance:
                best_distance = distance
                best_note = note
        # The circle as drawn, in playfield units, so what is grabbable is
        # what is seen (a fixed 60 was bigger than any CS but 0).
        hit_radius = self._drawn_radius() / self.view_scale
        return best_note if best_note is not None and best_distance <= hit_radius ** 2 else None

    def mousePressEvent(self, event) -> None:
        if event.button() != Qt.LeftButton:
            return
        note = self._note_at_canvas_position(event.position())
        if note is None:
            return
        self.drag_group = "kat" if note.is_kat else "don"
        self.drag_last_position = event.position()
        self.setCursor(Qt.ClosedHandCursor)
        event.accept()

    def mouseMoveEvent(self, event) -> None:
        if self.drag_last_position is None or self.view_scale <= 0:
            return
        delta = event.position() - self.drag_last_position
        self.drag_last_position = event.position()
        self.drag_offset_requested.emit(
            self.drag_group,
            delta.x() / self.view_scale,
            delta.y() / self.view_scale,
        )
        event.accept()

    def mouseReleaseEvent(self, event) -> None:
        if self.drag_last_position is None:
            return
        self.drag_last_position = None
        self.drag_group = None
        self.unsetCursor()
        event.accept()


def is_fake_slider(note) -> bool:
    """A drumroll with no playable duration: drawn, never hittable.

    The threshold is `gimmick_session.FAKE_SLIDER_MAX_LENGTH`, shared with the
    config that writes them, so what the toolbox can produce is exactly what
    the layer will admit. Exposed as `MainWindow.is_fake_slider` too, which is
    the name it has been reached by; the definition lives here because the
    editor timeline needs it and is built long before that class.
    """
    return (
        note.is_slider and note.length is not None
        and note.length <= FAKE_SLIDER_MAX_LENGTH
    )


class TimelineGameplay(TimeAxisMixin, QWidget):
    # Tools whose gesture is "drag a range", not "click a spot". Listed once
    # because mousePressEvent has to start the drag and mouseReleaseEvent has
    # to emit the range, and a tool added to one tuple and not the other is a
    # press that grabs the mouse and a release that never lets go.
    RANGE_TOOLS = ("function", "convert", "kiai")

    selection_changed = Signal(object)
    selection_finalized = Signal(object)
    seek_requested = Signal(float)
    snap_changed_by_wheel = Signal(int)
    # (note_kind, snapped_time_ms, new_combo, big) -- emitted on left click
    # when self.tool is "don"/"kat"; Shift-click places a big (finisher) note,
    # the same modifier that already marks a slider/spinner big on release.
    # The widget holds no MainWindow reference, so it emits the request rather
    # than mutating the document itself; the owner (MainWindow, per
    # difficulty) builds the HitObject.
    note_place_requested = Signal(str, float, bool, bool)
    # (note_kind, start_ms, end_ms, new_combo, big) -- slider/spinner
    # placement is a click-drag (start position to stop position), not a
    # single click; a plain click without drag arrives here too, with
    # start_ms == end_ms, and the owner falls back to a small default length.
    note_place_with_duration_requested = Signal(str, float, float, bool, bool)
    # (uid, new_end_ms) -- dragging an existing slider/spinner's right edge.
    note_duration_edit_requested = Signal(int, float)
    # (note uid) -- a fake slider's `length`, which is the one number that
    # decides how far it draws and is not reachable by dragging: its tail is
    # behind its head, so `_extendable_note_near_edge` never sees an edge.
    note_length_edit_requested = Signal(int)
    # uid of the note nearest a right click, within a small pixel radius.
    note_delete_requested = Signal(int)
    # list[uid] -- Delete/Backspace with a selection, Editor-page views only.
    # One signal for the whole selection so the owner can push a single undo
    # step instead of one per note.
    notes_delete_requested = Signal(object)
    # New window_ms after a Ctrl+wheel zoom. Zoom is a per-difficulty
    # property: every view of the same difficulty (chart and SV alike) has to
    # keep showing the same time span or they stop scrolling together.
    zoom_changed = Signal(float)
    # uid -- double click on a red line, in a view that allows it. Only the
    # barline gimmick layer does; everywhere else the red lines are drawn for
    # reference and do not respond. The owner reads the point's own values.
    timing_line_edit_requested = Signal(int)
    # list[uid] -- right click on a red line, or Delete with red lines selected.
    # One signal for the whole set so a bulk delete is a single undo step.
    timing_lines_delete_requested = Signal(object)
    # (start_ms, end_ms) -- drag-select with the function tool. The chart view's
    # equivalent of SVEditorView.function_range_requested, and the barline
    # layer's route to generating a run of red lines over a range.
    timing_function_range_requested = Signal(float, float)
    # (note uids, timing point uids, delta_ms) -- a select-tool drag that
    # started on an object or an owned red line rather than on empty space. The
    # view reports only what was actually grabbed; growing that into the whole
    # gimmick structure around it is the owner's job, because which lines belong
    # to which structure is its knowledge and not the view's.
    objects_move_requested = Signal(object, object, float)

    # The height every fixed pixel size in paintEvent was measured at. The
    # gimmick page's layers are drawn scaled against it, and so is a standalone
    # view now that MIN_HEIGHT is below it.
    DESIGN_HEIGHT = 180
    # The smallest a standalone view is allowed to get. Its own number rather
    # than DESIGN_HEIGHT because the two are different jobs: one is what the
    # artwork was measured at, the other is how much room a view demands on a
    # page that stacks several of them. Tied together, asking for a shorter
    # view also rescaled every tick and label in it.
    MIN_HEIGHT = 80
    # What the height control opens on. Not MIN_HEIGHT: the floor is how short
    # a view may be pushed, and lowering it should not shorten everybody's
    # views by itself.
    DEFAULT_VIEW_HEIGHT = 120

    # Note radius as a fraction of the view height, (full row, split row), and
    # its ceiling. A chart view is read as a row of timestamps rather than as
    # gameplay, so these are well under the sizes the view was first drawn at
    # -- tuned by eye against a stack of views rather than derived.
    NOTE_HEIGHT_FRACTIONS = (0.204, 0.141)
    NOTE_RADIUS_MAX = 25.0
    # The gimmick page keeps the pre-halving numbers: a band is 88px, so its
    # notes are already scaled down by the same height that scales everything
    # else there, and halving them again leaves less circle than the lines
    # drawn beside it.
    GIMMICK_NOTE_HEIGHT_FRACTIONS = (0.22, 0.15)
    GIMMICK_NOTE_RADIUS_MAX = 31.0
    # A finisher a third bigger again than its scale below makes it, on both
    # pages (owner, 2026-10-08): at the old size a big note in a dense row
    # did not stand out from the small ones around it. The hit test reads
    # the same radius, so the grab grows with it.
    FINISHER_ENLARGE = 1.33

    def __init__(self) -> None:
        super().__init__()

        self.notes = []
        self.note_times: list[int] = []
        self._max_extend_ms = 0.0
        self.timing_points: list[TimingPoint] = []
        self._timing_times: list[float] = []
        # Every point, inherited ones included. `timing_points` above is the
        # uninherited-only list the beat grid needs; a slider's length depends
        # on the SV in force at it, and that only exists on inherited points.
        self._sv_points: list[TimingPoint] = []
        # The map's [Difficulty] SliderMultiplier, the other half of that same
        # conversion. Falls back to osu!'s default until a document is loaded.
        self.slider_multiplier = SLIDER_MULTIPLIER_ASSUMED
        self.selected: set[int] = set()
        # Red lines picked by a drag, in a view that owns them. Kept apart from
        # `selected` (which is note original_index) because the barline layer
        # shows no notes at all and these are what its Delete acts on.
        self.selected_timing_uids: set[int] = set()
        # Predicate deciding which hit objects this view shows; see refresh_notes.
        self.object_filter = None
        # Draw the document's uninherited (BPM) points as vertical red lines.
        # Off for the shared player timeline and the Editor page's chart views,
        # where the snap grid already says where the beats are; on for the
        # gimmick layers, whose whole subject matter is red lines.
        self.show_timing_lines = False
        # Hand this view's red lines to its tools -- right click deletes one,
        # select drags one, a rubber band picks them up. The barline layer
        # only: a red line is that layer's material, and it is view-only
        # elsewhere.
        self.timing_edit_enabled = False
        # ...and let a double click on one open its BPM. Both structure layers,
        # because a fake slider's red line is the half of it that makes the
        # object fake and retiming that line is how a shiny is tuned. Separate
        # from `timing_edit_enabled` on purpose: the fake slider layer must not
        # let the line be dragged on its own, since a line pulled out from
        # under its sliders dismantles the structure rather than moving it
        # (only `_expand_move` knows how to move the whole thing, and it
        # recognises a structure by the object, not the line).
        self.timing_dialog_enabled = False
        # Right click on a drawn red line removes that line alone, with no
        # dragging or selecting. The fake slider layer: a mapper removing the
        # line under a slider wants the slider kept, and a right click on the
        # slider itself -- tried first -- still takes both.
        self.timing_delete_enabled = False
        # Restrict the drawn red lines to these milliseconds; None draws all of
        # them. The fake slider layer sets it to the fake sliders' own times, so
        # the line it shows is the one squashing the object beside it rather
        # than every red line in the map.
        self.timing_line_times: set[int] | None = None
        # Derives the above from the document on every refresh -- see
        # SVEditorView.point_times_for, which solves the same staleness.
        self.timing_line_times_for = None
        # How the hover preview draws a Don/Kat: as the note itself, as the
        # yellow fake slider it will become, or as the bar a barline note draws.
        # The shape a tool writes differs per layer, so the ghost has to as well.
        self.ghost_style = "note"
        # (start, end, distance, slider_offset) while the Multiple Fake Slider
        # tool is held, None otherwise -- the run its ghost previews. The offset
        # rides along because the view has no gimmick config of its own to read
        # it from. See `_set_gimmick_tool`.
        self.multi_run: tuple[int, int, int, int] | None = None
        # Write the BPM beside each red line this view owns. On in the barline
        # layer, whose whole material is red lines and where the number used to
        # be readable only by dropping down to the SV layer under it.
        self.show_bpm_labels = False
        # Milliseconds whose red line belongs to a *different* layer, drawn
        # dimmed and untouchable here. Supplied by the owner, because which
        # structure owns what is its knowledge, not the view's.
        self.foreign_times: set[int] = set()
        # ...derived from the document on every refresh, like the other two
        # `_for` hooks: the objects it depends on move as the map is edited.
        self.foreign_times_for = None
        # Milliseconds carrying a gimmick line -- the centre of a structure, as
        # opposed to one of the restore lines around it. A drag lands one of
        # these on the snap grid and a right click resolves to it, so which
        # lines they are has to be exact: the BPM that makes a line a gimmick
        # line is configurable per layer, and guessing "anything above 1000" got
        # a 900 BPM gimmick wrong in one direction and a real 1200 BPM section
        # wrong in the other. Supplied by the owner for the same reason
        # `foreign_times` is -- it holds the configs.
        self.gimmick_times: set[int] = set()
        self.gimmick_times_for = None
        # Milliseconds carrying a shiny note -- a stack of fake sliders on one
        # timestamp, which is what reads as white. Derived from the document per
        # refresh like the three sets above, because "is this a shiny" is a
        # question about how many objects share a millisecond and that changes
        # with every placement.
        self.shiny_times: set[int] = set()
        self.shiny_times_for = None
        # Two rows and a centred grid, for the fake slider layer alone: it shows
        # two kinds of drawn object one millisecond apart, and stacked on one
        # baseline at gimmick zoom they are the same blob. Fake sliders take the
        # upper row, shiny notes the lower, and the snap ticks move to the
        # middle so neither row is drawn over them.
        self.split_rows = False

        self.current_time = 0.0
        self.window_ms = 2000.0
        self.snap_divisor = 4
        # Bottom-anchored (today's shared player-deck timeline) by default.
        # Editor-page chart/gimmick views turn this on: snap ticks radiate
        # both above and below the baseline and notes sit centered on it.
        self.symmetric = False
        # What the view is *for*, apart from how it is drawn: an Editor-page
        # view (no click-to-seek, Delete deletes, a tool target) rather than
        # the Fancy Arranger's transform-selection surface. It used to be read
        # off `symmetric`, which stopped working once the Fancy timeline was
        # drawn centred too (2026-10-08). set_symmetric sets both.
        self.editor_view = False
        # "select" preserves today's drag-select-by-time-range behavior
        # (used by the shared Fancy Arranger timeline). Editor-page chart
        # views switch this via their own tool row; nothing else ever
        # changes it, so the shared timeline's behavior is untouched.
        self.tool = "select"
        self.new_combo = False

        self.drag_start_x: float | None = None
        self.drag_anchor_time: float | None = None
        self.drag_mouse_x = 0.0
        self.wheel_accumulator = 0.0
        self.alt_wheel_accumulator = 0.0
        self.last_rendered_time = -1.0
        self.auto_scroll_timer = QTimer(self)
        self.auto_scroll_timer.setInterval(16)
        self.auto_scroll_timer.timeout.connect(self._auto_scroll_selection)
        self.is_playing = False

        # Hover ghost: the note that would be placed if you clicked right
        # now, shown translucent. Needs mouse tracking since plain
        # mouseMoveEvent only fires with a button held otherwise.
        self.setMouseTracking(True)
        self._hover_time: float | None = None
        self._hover_y: float | None = None
        # The y a rubber band started at, which on a split layer is the row it
        # selects in. None for every drag that is not a selection.
        self._drag_y: float | None = None

        # Slider/spinner placement is click-drag (start -> stop), not a
        # single click with a fixed length.
        self._placing_tool: str | None = None
        self._placing_start_time: float | None = None
        self._placing_end_time: float | None = None
        # Dragging an existing slider/spinner's right edge to extend it.
        self._resizing_note = None
        self._resize_new_end_time: float | None = None
        # Whether a select-tool press on an object drags it to a new time
        # instead of starting a rubber-band selection.
        self.move_enabled = False
        # Whether double-clicking an object here types its length. Layer 2's,
        # because a fake slider is the only object whose length is a gimmick
        # parameter rather than a duration you drag.
        self.note_length_dialog_enabled = False
        # On a normal chart every click lands near a note, so a bare press
        # only starts a move when the note under it is already selected --
        # rubber-band selecting is still what an unselected note's click (or
        # drag) does, and a plain click with no drag still fully deselects
        # (see _finish_move) rather than reselecting what it landed on. A
        # gimmick layer has neither rule: the material is sparse, a structure
        # is placed and then nudged before it is ever selected, and a click
        # there always means "select this".
        self.move_requires_selection = False
        # Select-tool drag of something rather than of empty space -- see
        # objects_move_requested and _begin_move.
        self._move_note_uids: list[int] = []
        self._move_point_uids: list[int] = []
        self._move_origin: float | None = None
        self._move_anchor_time = 0.0
        self._move_delta = 0.0
        self._move_snaps = True
        self._move_divisor: int | None = None
        # What to place instead, if a grab under a placement tool turns out to
        # be a plain click rather than a drag.
        self._move_fallback: tuple | None = None

        self.don_brush = QColor(*DON_COLOR, 180)
        self.kat_brush = QColor(*KAT_COLOR, 180)
        self.slider_brush = QColor(*DRUMROLL_COLOR, 180)
        # An osu! skin's note art, or None for the built-in circles.
        self.skin = None
        self.ghost_don_brush = QColor(*DON_COLOR, 90)
        self.ghost_kat_brush = QColor(*KAT_COLOR, 90)
        self.ghost_slider_brush = QColor(*DRUMROLL_COLOR, 90)
        # A shiny note is several drumrolls on one millisecond, drawn as one
        # mark rather than as three overlapping yellows (which at this size is
        # just a blob).
        #
        # **White, for separation.** This layer is an editing view and the
        # colour is a label, not a simulation: white is the one thing that
        # cannot be mistaken for the drumroll yellow beside it, so a stack is
        # tellable from a lone fake slider at a glance.
        #
        # It is deliberately *not* what the game does, and the comment that
        # used to be here claimed otherwise -- that a stack "washes out to
        # white" in play. It does not: a pile of opaque heads reads as one
        # head, which is why the gameplay preview draws it flat #fbb706.
        self.shiny_brush = QColor(255, 254, 245, 235)
        self.ghost_shiny_brush = QColor(255, 254, 245, 120)
        # Spinner extent: grey so it reads as "this span is occupied" rather
        # than competing with don/kat/slider colour coding.
        self.spinner_band_brush = QColor(190, 195, 205, 70)
        self.spinner_edge_pen = QPen(QColor(220, 226, 236, 170), 2)
        # Captured here, after every fill above is built, so set_note_opacity
        # scales from the built-in look instead of compounding each time it is
        # called -- and so a fill added later is picked up by naming it once.
        self._base_note_alphas = {
            name: getattr(self, name).alpha() for name in (
                "don_brush", "kat_brush", "slider_brush",
                "ghost_don_brush", "ghost_kat_brush", "ghost_slider_brush",
                "shiny_brush", "ghost_shiny_brush", "spinner_band_brush",
            )
        }
        self.ghost_pen = QPen(QColor(255, 255, 255, 110), 2)
        self.normal_note_pen = QPen(QColor(255, 255, 255, 220), 2)
        self.selected_note_pen = QPen(QColor(255, 220, 110, 235), 3)
        self.baseline_pen = QPen(theme.color("#7a8492"), 2)
        self.bpm_label_pen = QPen(QColor(225, 230, 240, 200), 1)
        self.label_font = value_label_font(self.font())
        self.cursor_pen = QPen(QColor("#ffffff"), 3)
        # Two weights of red line: the ones this view owns, and the ones drawn
        # so the owned ones can be read in context.
        self.timing_line_pen = QPen(QColor(255, 90, 90, 235), 2)
        self.timing_line_ref_pen = QPen(QColor(255, 90, 90, 90), 1)
        # Where a line being dragged started. Dashed as well as faded, so it
        # cannot be misread as one of the reference lines above.
        self.timing_line_ghost_pen = QPen(QColor(255, 90, 90, 110), 2, Qt.DashLine)
        # Built once instead of constructing a QPen per tick per frame --
        # at fine snap divisors with many chart views open simultaneously,
        # that allocation churn was a real contributor to paint stutter.
        # (kind -> (QPen, tick_height))
        # Two ticks are two ticks only with a background pixel between them,
        # and the widest tick pen is 2px -- so a grid finer than this is a
        # filled rectangle drawn one line at a time. Read off the pens rather
        # than typed, so restyling a tick cannot silently invalidate it.
        self._tick_styles = {
            "beat": (QPen(QColor("#f2f2f2"), 2), 32),
            "half": (QPen(QColor("#ff5151"), 2), 24),
            "quarter": (QPen(QColor("#4b9cff"), 1), 18),
            "eighth": (QPen(QColor("#f2d34f"), 1), 12),
            "third": (QPen(QColor("#b578ff"), 1), 16),
            "fifth": (QPen(QColor("#f2d34f"), 1), 14),
            "seventh": (QPen(QColor("#55d6be"), 1), 12),
            "eleventh": (QPen(QColor("#ff9f40"), 1), 12),
            "thirteenth": (QPen(QColor("#8bd1ff"), 1), 12),
            "other": (QPen(QColor("#738098"), 1), 10),
        }
        self.beat_line_pen = QPen(QColor(255, 255, 255, 70), 1)
        self._min_tick_spacing_px = max(
            pen.width() for pen, _height in self._tick_styles.values()
        ) + 1

        self.setMinimumHeight(self.MIN_HEIGHT)
        self.setFocusPolicy(Qt.StrongFocus)
        # paintEvent opens with an opaque fill of the whole rect, so nothing
        # behind this widget is ever seen. Without the attribute Qt did not
        # know that, and on every frame repainted what sits underneath --
        # the EditorViewFrame's stylesheet (a rounded, bordered rect drawn
        # through QStyleSheetStyle) and the scroll viewport -- only to cover
        # it again. Measured: over half of a six-chart Editor frame was Qt's
        # own work in processEvents, not these paintEvents. If a paintEvent
        # here ever stops filling its whole rect, this has to go with it, or
        # stale pixels show through -- which is why it follows View opacity
        # (`set_view_opacity`): below 100% the fill lets the backdrop through.
        self.setAttribute(Qt.WA_OpaquePaintEvent, view_ground_is_opaque())

    def _draw_skinned_roll_body(self, painter, x, end_x, center_y, radius) -> bool:
        """A drumroll's stretched body and its tail cap, from the skin.

        The head is not drawn here: every note in this view goes through one
        `draw_note_sprite` call below, and a drumroll's head is that call with
        the drumroll colour. Returns whether the skin supplied the art, so the
        caller can fall back to its own bar.

        The alpha the view draws notes at is carried as painter opacity, the
        same way `draw_note_sprite` carries it -- these layers are deliberately
        translucent so the snap grid reads through them, and skin art is opaque.
        """
        skin = self.skin
        if skin is None:
            return False
        diameter = round(radius * 2)
        fill = self.slider_brush
        middle = skin.scaled("taiko-roll-middle", diameter,
                             QColor(fill.red(), fill.green(), fill.blue()))
        if middle is None:
            return False
        previous = painter.opacity()
        painter.setOpacity(previous * fill.alphaF())
        body_end = max(end_x, x)
        if body_end > x:
            painter.drawPixmap(
                QRectF(x, center_y - radius, body_end - x, radius * 2),
                middle, QRectF(middle.rect()),
            )
        # Origin TopLeft, per the wiki: the cap butts onto the end of the track
        # and reaches past it, the way the head reaches back past the start. A
        # negative length collapses the track, not the cap -- see
        # GameplayViewerView._draw_skinned_roll.
        tail = skin.scaled("taiko-roll-end", diameter,
                           QColor(fill.red(), fill.green(), fill.blue()))
        if tail is not None:
            painter.drawPixmap(
                QPointF(body_end, center_y - tail.height() / 2.0), tail)
        painter.setOpacity(previous)
        return True

    def set_note_opacity(self, percent: float) -> None:
        """Scale every note fill's alpha; NOTE_OPACITY_DEFAULT_PERCENT is the
        built-in look, and 100 draws them solid.

        The ghosts and the spinner band scale with the notes rather than being
        pinned, because what they are is "fainter than a note" -- holding them
        still while the notes went solid would have inverted that.
        """
        scale = max(NOTE_OPACITY_MIN_PERCENT, float(percent)) / NOTE_OPACITY_DEFAULT_PERCENT
        for name, alpha in self._base_note_alphas.items():
            getattr(self, name).setAlpha(max(1, min(255, round(alpha * scale))))
        self.update()

    def load_document(self, document) -> None:
        self.refresh_notes(document)
        self.current_time = float(
            self.notes[0].time if self.notes else 0
        )
        self.selected.clear()
        self.update()

    def refresh_notes(self, document) -> None:
        """Re-read notes/timing after an edit, without resetting cursor or selection.

        Placing or deleting a note must not jump the view back to the first
        note or clear the current selection the way a fresh load_document
        would.
        """
        # The gimmick editor's layers each show one kind of object, so that a
        # fake slider can be selected and dragged without the real chart's notes
        # sitting under the cursor. Everywhere else this is None and every
        # object is shown.
        if self.object_filter is None:
            self.notes = document.hit_objects
        else:
            self.notes = [note for note in document.hit_objects if self.object_filter(note)]
        if self.timing_line_times_for is not None:
            self.timing_line_times = self.timing_line_times_for(document)
        self.note_times = [note.time for note in self.notes]
        if self.foreign_times_for is not None:
            self.foreign_times = self.foreign_times_for(document)
        if self.gimmick_times_for is not None:
            self.gimmick_times = self.gimmick_times_for(document)
        if self.shiny_times_for is not None:
            self.shiny_times = self.shiny_times_for(document)
        if self.kiai_bands_for is not None:
            self.kiai_bands = self.kiai_bands_for(document)
        else:
            self.set_kiai_from(document.timing_points)
        # NOT shared with MainWindow._sorted_points/_uninherited_points_cached
        # (unlike SVEditorView's own timing_points/_beat_points) -- reverted
        # after a report that the regular Editor page's snap grid started
        # shifting position right after this sharing landed. Independent
        # investigation and repeated stress tests of the shared path found no
        # provable defect, but the report pointed at this exact view and this
        # exact change, and a wrong snap grid is worse than the sort it saves.
        # `extract_timing_points` is the same composition
        # (uninherited_points(sorted_by_time(...))), done locally again.
        self.timing_points = extract_timing_points(document)
        self._timing_times = [point.time for point in self.timing_points]
        self._sv_points = sorted_by_time(document.timing_points)
        self.slider_multiplier = document.slider_multiplier
        # Lines deleted elsewhere must not stay "selected" forever -- the same
        # rule SVEditorView.refresh_points applies to its own selection.
        self.selected_timing_uids &= {point.uid for point in self.timing_points}
        # Longest slider/spinner duration, so paintEvent can widen its visible-
        # notes lookup: a long spinner's band must stay drawn until its *end*
        # scrolls out of view, not just its start.
        self._max_extend_ms = 0.0
        for note in self.notes:
            if note.is_slider or note.is_spinner:
                end = self._note_end_time(note)
                if end is not None:
                    self._max_extend_ms = max(self._max_extend_ms, end - note.time)
        self.update()

    def set_tool(self, tool: str) -> None:
        self.tool = tool
        # The placement ghost is drawn from the tool, and a view repaints on
        # mouse move: picking Kat over a still cursor kept showing a Don until
        # the mouse twitched (owner, 2026-10-08). Same reason as Shift.
        self.update()

    def set_new_combo(self, value: bool) -> None:
        self.new_combo = bool(value)
        self.update()

    def set_snap_divisor(self, divisor: int) -> None:
        """Change the grid, not the playhead.

        Alt+wheel routes here through `snap_changed_by_wheel` on every open
        view, and this used to re-snap `current_time` onto the new grid and
        broadcast a seek -- so switching 1/4 to 1/3 physically moved every
        view's playhead. Looking at a different grid is not a request to
        move: the playhead self-corrects on the very next wheel notch anyway,
        since `wheel_seek_time` snaps from wherever `current_time` currently
        is before stepping, so sitting off-grid between notches costs
        nothing. Matches `SVEditorView.set_snap_divisor` and
        `GameplayViewerView.set_snap_divisor`, which never snapped here either.
        """
        self.snap_divisor = divisor
        self.update()

    def set_symmetric(self, symmetric: bool, editor_view: bool | None = None) -> None:
        self.symmetric = symmetric
        self.editor_view = symmetric if editor_view is None else editor_view
        self.update()

    def note_radii(self) -> tuple[float, float]:
        """(normal, finisher) drawn note radius, derived from the view height.

        One place, because the painter and the hit test both need it and a
        note you can see but not grab is the bug that comes of them drifting.

        Sized from the view, not typed: the gimmick page shows six layers as
        short bands, and a fixed 42px finisher there is taller than the band it
        sits in -- it spills past the edges and stops reading as centred on the
        baseline. Full-height views are unchanged, since they clamp at the
        sizes these used to be fixed at. A split layer halves it again: it
        draws two rows of objects instead of one, and at the full radius the
        two overlap and the pair reads as a single smear.

        The finisher ratio here is **not** the ruleset's. `TAIKO_STRONG_SCALE`
        (1.538x) is what a player sees and is what `GameplayViewerView` draws;
        on a timestamp row that far apart reads as two different kinds of
        object rather than one note and its louder twin, and the normal note
        has to shrink to absurdity for the big one to fit. `EDITOR_STRONG_SCALE`
        puts the normal note at 75% of the big one, which is the proportion the
        editor is read at. The gimmick page's bands keep
        the ruleset ratio along with their own sizes. No second cap on the
        finisher: `normal` is already capped.
        """
        fractions, ceiling = (
            (self.GIMMICK_NOTE_HEIGHT_FRACTIONS, self.GIMMICK_NOTE_RADIUS_MAX)
            if getattr(self, "gimmick_layer", None) is not None
            else (self.NOTE_HEIGHT_FRACTIONS, self.NOTE_RADIUS_MAX)
        )
        normal = min(ceiling, self.height() * fractions[bool(self.split_rows)])
        strong = (
            TAIKO_STRONG_SCALE
            if getattr(self, "gimmick_layer", None) is not None
            else EDITOR_STRONG_SCALE
        )
        return normal, normal * strong * self.FINISHER_ENLARGE

    def _note_near_x(self, x: float, radius_px: float | None = None, y: float | None = None):
        """Nearest note whose drawn circle covers `x`, for grabbing and deleting.

        The reach is the note's **own body**, not a fixed number: a normal note
        is drawn at up to 31px and a finisher at up to 42, so a flat 20 meant
        the outer two thirds of every circle looked grabbable and was not --
        which is what "you have to click exactly on the millisecond" was. A
        finisher is bigger on screen and is now bigger to grab, which is the
        point of drawing it bigger.

        `radius_px` overrides that for a caller that wants a fixed reach.

        `y` matters on a split layer and nowhere else. There the two rows hold
        two different structures a millisecond apart -- the same pixel column
        at any zoom the layer is readable at -- so the row the click landed in
        is the only thing that says which of them was meant. Without it the
        scan returned whichever came first in the document, and grabbing the
        fake slider drawn on the upper row dragged the shiny note under it
        (and the other way round).
        """
        wants_lower = None if y is None or not self.split_rows else y > self._baseline_y()
        normal_radius, finisher_radius = self.note_radii()
        best = None; best_distance = None
        for note in self.notes:
            if wants_lower is not None and (round(note.time) in self.shiny_times) != wants_lower:
                continue
            reach = radius_px if radius_px is not None else (
                finisher_radius if (note.is_finisher or note.is_spinner) else normal_radius
            )
            distance = abs(self.x_for_time(note.time) - x)
            if distance <= reach and (best_distance is None or distance < best_distance):
                best = note; best_distance = distance
        return best

    def _note_end_time(self, note) -> float | None:
        """End time of a slider or spinner, for edge hit-testing and resize."""
        if note.is_spinner:
            return float(note.end_time) if note.end_time is not None else None
        if note.is_slider and note.length is not None and note.slides is not None:
            timing = active_timing(self.timing_points, note.time)
            # `self.timing_points` is the uninherited-only list (see
            # extract_timing_points), where every point reads as 1.0x -- so the
            # SV has to come off the full list, which is what osu! resolves the
            # slider's speed from at the slider's own start time.
            sv = sv_at(self._sv_points, note.time)
            duration = duration_for_slider_length(
                note.length * note.slides, timing.beat_length, sv, self.slider_multiplier,
            )
            return note.time + duration if duration > 0 else None
        return None

    def _extendable_note_near_edge(self, x: float, radius_px: float = 16.0):
        """A slider/spinner whose right (end-time) edge is near x, for resize-by-drag."""
        best = None; best_distance = None
        for note in self.notes:
            if not (note.is_slider or note.is_spinner):
                continue
            end = self._note_end_time(note)
            if end is None:
                continue
            distance = abs(self.x_for_time(end) - x)
            if distance <= radius_px and (best_distance is None or distance < best_distance):
                best = note; best_distance = distance
        return best

    def mousePressEvent(self, event) -> None:
        if event.button()==Qt.RightButton:
            # A drag-selection is live and this press landed on the page's
            # timing bar rather than in the view: scrub the playhead there
            # instead of deleting whatever sits under the cursor, so a range
            # longer than one screenful can be built without dragging all the
            # way through it. Only reachable at all because grabMouse() during
            # the drag routes every event here regardless of where the cursor
            # actually is -- see TimeAxisMixin._press_is_on_timing_bar.
            if self.drag_anchor_time is not None and self._press_is_on_timing_bar(
                event.globalPosition().toPoint()
            ):
                self._bar_scrubbing = True
                self.current_time = self._time_on_timing_bar(event.globalPosition().toPoint())
                self.seek_requested.emit(self.current_time)
                self.drag_mouse_x = self.x_for_time(self.current_time)
                self._update_drag_selection()
                event.accept()
                return
            note = self._note_near_x(event.position().x(), y=event.position().y())
            if note is not None:
                self.note_delete_requested.emit(note.uid)
                event.accept()
                return
            # No note under the cursor: in a layer that owns its red lines, the
            # red line is what right click is for. Tried second so a layer
            # showing both never loses the note to the line beneath it.
            if self.timing_edit_enabled:
                point = (
                    self._gimmick_centre_near_x(event.position().x())
                    or self._timing_point_near_x(event.position().x())
                )
                if point is not None:
                    self.timing_lines_delete_requested.emit([point.uid])
            elif self.timing_delete_enabled:
                # Only the lines this view draws: no structure centre lookup,
                # because the point is to take the line and nothing around it.
                point = self._timing_point_near_x(event.position().x())
                if point is not None:
                    self.timing_lines_delete_requested.emit([point.uid])
            event.accept()
            return
        if event.button()!=Qt.LeftButton:
            return

        if self.tool in self.RANGE_TOOLS:
            # Same gesture as the SV editor's function tool: drag a range, then
            # answer a dialog about what to fill it with. The others share it --
            # they also act on a range, they just need nothing else asked.
            self.drag_start_x = event.position().x()
            self.drag_mouse_x = self.drag_start_x
            self.drag_anchor_time = self.time_for_x(self.drag_start_x)
            self._drag_y = None
            self.grabMouse()
            self.update()
            event.accept()
            return

        if self.tool in ("slider", "spinner"):
            # Extend an already-placed slider/spinner if the click landed
            # near its right edge; otherwise start placing a new one.
            existing = self._extendable_note_near_edge(event.position().x())
            if existing is not None:
                self._resizing_note = existing
                self._resize_new_end_time = self._note_end_time(existing)
                self.grabMouse()
                event.accept()
                return
            snapped = self.snap_ms(self.time_for_x(event.position().x()))
            self._placing_tool = self.tool
            self._placing_start_time = snapped
            self._placing_end_time = snapped
            self.grabMouse()
            event.accept()
            return

        if self.tool != "select":
            time_ms = self.snap_ms(self.time_for_x(event.position().x()))
            # The event's own modifiers, never the cached global -- see
            # `shift_is_held`. A tap of Shift used to stick.
            big = bool(event.modifiers() & Qt.ShiftModifier)
            # Pressing on something that is already there starts a move, even
            # with a placement tool in hand. Dragging is how a gimmick object
            # gets nudged, and having to switch back to Select first is the
            # reason it read as "objects can't be moved" -- after placing a run
            # of them, the placement tool is what you are still holding.
            #
            # A press that does not turn into a drag still places, so clicking
            # an existing note to retype it (Don over a Kat) is unchanged: the
            # placement is only handed over once the object has actually moved.
            grabbed = (
                self._note_near_x(event.position().x(), y=event.position().y())
                if self.move_enabled else None
            )
            if grabbed is not None:
                self._begin_move(grabbed, None, event.position().x())
                self._move_fallback = (self.tool, time_ms, self.new_combo, big)
                event.accept()
                return
            self.note_place_requested.emit(self.tool, time_ms, self.new_combo, big)
            event.accept()
            return

        # A tail grab takes priority over everything else select does, but
        # only within its own small radius (_extendable_note_near_edge's 16px,
        # tighter than the note body _note_near_x reaches with) -- so a click on
        # a slider's head or body still falls through to the move/rubber-band
        # handling below.
        # Independent of move_enabled: a drumroll's tail is draggable on any
        # layer, not only the gimmick ones where whole-object moving is
        # enabled. This is what lets a slider be lengthened without switching
        # back to the tool that created it (see the identical branch above
        # for "slider"/"spinner").
        existing = self._extendable_note_near_edge(event.position().x())
        if existing is not None:
            self._resizing_note = existing
            self._resize_new_end_time = self._note_end_time(existing)
            self.grabMouse()
            event.accept()
            return

        # Select mode, on top of something: drag it to a new time. A note is
        # tried before a red line so a layer showing both never loses the
        # object to the line under it.
        if self.move_enabled:
            grabbed_note = self._note_near_x(event.position().x(), y=event.position().y())
            grabbed_point = (
                self._timing_point_near_x(event.position().x())
                if grabbed_note is None and self.timing_edit_enabled else None
            )
            # A press that is literally on the note's circle moves it, selected
            # or not: that is what grabbing a thing means, and it costs the
            # rubber band only the object's own area -- everything above and
            # below the row still selects. `move_requires_selection` remains the
            # rule off the body, so a drag started in the space beside a note
            # still boxes rather than nudging whatever column it began in.
            on_body = grabbed_note is not None and self._press_is_on_note_body(
                grabbed_note, event.position().x(), event.position().y())
            if self.move_requires_selection and not on_body and not (
                (grabbed_note is not None and grabbed_note.original_index in self.selected)
                or (grabbed_point is not None and grabbed_point.uid in self.selected_timing_uids)
            ):
                grabbed_note = grabbed_point = None
            if grabbed_note is not None or grabbed_point is not None:
                self._begin_move(grabbed_note, grabbed_point, event.position().x())
                event.accept()
                return

        # A left click clears the selection before the drag rebuilds it, so a
        # plain click with no drag deselects rather than silently keeping a
        # selection the user has visibly moved on from.
        if self.selected:
            self.selected.clear()
            self.selection_changed.emit(set())
        self.drag_start_x=event.position().x(); self.drag_mouse_x=self.drag_start_x
        self._drag_y = event.position().y()
        self.drag_anchor_time=self.time_for_x(self.drag_start_x); self.grabMouse(); self.auto_scroll_timer.start(); self.update()
    def _begin_move(self, note, point, x: float) -> None:
        """Start a select-tool drag of whatever the click landed on.

        Grabbing something that is part of the current selection moves the whole
        selection; grabbing something outside it moves that alone and leaves the
        selection untouched -- the same rule every editor uses, and the one that
        makes "select a run of barlines, then shift all of them" possible.
        """
        # Whichever bar of a barline note was grabbed, the structure's centre is
        # what moves -- see _gimmick_centre_near_x.
        if point is not None:
            point = self._gimmick_centre_near_x(x) or point
        in_selection = (
            note is not None and note.original_index in self.selected
            or point is not None and point.uid in self.selected_timing_uids
        )
        if in_selection:
            self._move_note_uids = [n.uid for n in self.selected_notes()]
            self._move_point_uids = sorted(self.selected_timing_uids)
        else:
            self._move_note_uids = [note.uid] if note is not None else []
            self._move_point_uids = [point.uid] if point is not None else []
        self._move_origin = float(note.time if note is not None else point.time)
        # A note belongs on the beat grid, so its drag snaps to it -- and so
        # does a barline note, which is a note drawn out of red lines and is
        # placed on the grid to begin with.
        #
        # A plain red line is not: a barline gimmick's whole vocabulary is
        # millisecond offsets -- its restore lines sit +/-2ms from its centre --
        # and snapping those to a 125ms division meant every nudge smaller than
        # a beat rounded back to where it started, which reads as the drag doing
        # nothing. Only the structure's centre snaps; nudging any other line off
        # the grid by hand still works.
        self._move_snaps = note is not None or (
            point is not None and round(point.time) in self.gimmick_times
        )
        # An object off the current grid moves along its own: a 1/3 note
        # dragged with 1/4 selected stays a 1/3 note, instead of the first pixel
        # of the drag throwing it onto a grid it was never on. One that *is* on
        # the current grid (its own divisor divides the setting) moves exactly
        # as before -- otherwise a note on a beat could only move by beats.
        self._move_divisor = None
        if self._move_snaps:
            own = own_divisor(self.snap_points, self._move_origin)
            if own is not None and self.snap_divisor % own:
                self._move_divisor = own
        self._move_anchor_time = self.time_for_x(x)
        self._move_delta = 0.0
        self.grabMouse()
        self.update()

    def _update_move(self, x: float) -> None:
        """Land the *grabbed* object on a position and shift everything by that.

        Positioning the grabbed object rather than the cursor: otherwise the
        offset would depend on where inside the object the drag started, and a
        structure could never be landed exactly on a division.

        The grid for a note, whole milliseconds for a red line -- see
        `_begin_move`.
        """
        if self._move_origin is None:
            return
        wanted = self._move_origin + (self.time_for_x(x) - self._move_anchor_time)
        target = self.snap_ms(wanted, self._move_divisor) if self._move_snaps else round(wanted)
        # Nothing may be dragged to a negative time; clamping the delta rather
        # than each object keeps the structure's own shape intact.
        self._move_delta = max(-self._move_origin, target - self._move_origin)
        self.update()

    def _finish_move(self) -> None:
        self.releaseMouse()
        delta = self._move_delta
        note_uids, point_uids = self._move_note_uids, self._move_point_uids
        fallback = self._move_fallback
        self._move_note_uids = []
        self._move_point_uids = []
        self._move_origin = None
        self._move_delta = 0.0
        self._move_fallback = None
        if delta and (note_uids or point_uids):
            self.objects_move_requested.emit(note_uids, point_uids, delta)
        elif fallback is not None:
            # Never moved: this was a click with a placement tool held, so it
            # means what it always meant.
            self.note_place_requested.emit(*fallback)
        elif note_uids or point_uids:
            # A press on an object that never became a drag is a click, and a
            # click selects it -- on every page. Without this, clicking a
            # gimmick object did nothing at all: it could only be selected by
            # dragging a band around it, so Delete had nothing to act on
            # unless you knew that.
            #
            # The Editor page used to *clear* here instead, on the rule that a
            # plain click deselects. That rule belongs to a click on empty
            # space (see mouseReleaseEvent's rubber-band path, which still
            # clears), and applying it to a click on the object itself is what
            # made a note in the regular editor impossible to select the way
            # one in a gimmick layer is -- same widget, same yellow
            # `selected_note_pen`, opposite result from the same gesture.
            # Only this branch is shared; `move_requires_selection` still
            # governs what a press *off* the body grabs, so a drag started
            # beside a note on a dense chart still boxes rather than nudging.
            grabbed = set(note_uids)
            self.selected = {
                note.original_index for note in self.notes if note.uid in grabbed
            }
            self.selected_timing_uids = set(point_uids)
            self.selection_changed.emit(set(self.selected))
        self.update()

    def _update_drag_selection(self) -> None:
        if self.drag_anchor_time is None: return
        a,b=sorted((self.drag_anchor_time,self.time_for_x(self.drag_mouse_x)))
        first,last=bisect_left(self.note_times,a),bisect_right(self.note_times,b)
        # A split layer's band selects in the row it started in, so a run of
        # fake sliders can be taken without the shinies a millisecond from
        # them. Shift takes both.
        lower = self._selection_row()
        self.selected={
            n.original_index for n in self.notes[first:last]
            if lower is None or (round(n.time) in self.shiny_times) == lower
        }
        # A layer that owns its red lines selects those too, and only the ones
        # it owns: a line sitting on someone else's object is another layer's.
        if self.timing_edit_enabled:
            self.selected_timing_uids = {
                point.uid
                for point in self.timing_points
                if a <= point.time <= b and self._owns_timing_point(point)
            }
        self.selection_changed.emit(set(self.selected)); self.update()
    def mouseMoveEvent(self,event) -> None:
        if self._bar_scrubbing:
            self.current_time = self._time_on_timing_bar(event.globalPosition().toPoint())
            self.seek_requested.emit(self.current_time)
            self.drag_mouse_x = self.x_for_time(self.current_time)
            self._update_drag_selection()
            return
        if self._move_origin is not None:
            self._update_move(event.position().x())
            return
        if self._placing_tool is not None:
            snapped = max(
                self._placing_start_time,
                self.snap_ms(self.time_for_x(event.position().x())),
            )
            self._placing_end_time = snapped
            self.update()
            return
        if self._resizing_note is not None:
            minimum = self._resizing_note.time + 20.0
            snapped = max(minimum, self.snap_ms(self.time_for_x(event.position().x())))
            self._resize_new_end_time = snapped
            self.update()
            return
        if self.drag_anchor_time is not None:
            self.drag_mouse_x=event.position().x(); self._update_drag_selection()
            return
        # Repaint on every move, whatever the tool. The hover *ghost* is only
        # worth drawing for a placement tool, but draw_cursor_position writes
        # the millisecond under the cursor in every one of them -- and with
        # the repaint gated on the tool, that number only refreshed when
        # something else happened to repaint the view, which in select mode
        # meant clicking.
        self._hover_time = self.time_for_x(event.position().x())
        self._hover_y = event.position().y()
        self.update()

    def _selection_row(self, y: float | None = None) -> bool | None:
        """The row `y` (default: the band's start) is in on a split layer --
        True for the lower one -- or None where selection spans the whole view:
        off a split layer, with Shift held, or with no y to go by."""
        y = self._drag_y if y is None else y
        if not self.split_rows or y is None or shift_is_held():
            return None
        return y > self._baseline_y()

    def _row_span(self, y: float | None) -> tuple[float, float]:
        """(top, bottom) of what `_selection_row(y)` covers."""
        lower = self._selection_row(y)
        if lower is None:
            return 0.0, float(self.height())
        middle = float(self._baseline_y())
        return (middle, float(self.height())) if lower else (0.0, middle)

    def cursor_line_span(self) -> tuple[float, float]:
        return self._row_span(self._drag_y if self.drag_anchor_time is not None else self._hover_y)

    def leaveEvent(self, event) -> None:
        """Hand the readout back to the playhead when the cursor leaves."""
        self._hover_time = None
        super().leaveEvent(event)
        self.update()

    def _auto_scroll_selection(self) -> None:
        if self.drag_anchor_time is None: self.auto_scroll_timer.stop(); return
        if self.auto_scroll_step(self.drag_mouse_x): self._update_drag_selection()
    def mouseReleaseEvent(self,event) -> None:
        if event.button() == Qt.RightButton:
            # A right release only ever matters here as the end of a bar-scrub
            # (see mousePressEvent above) -- it must never fall through to the
            # generic release logic below, which would end whatever drag a
            # left button is still holding open.
            self._bar_scrubbing = False
            event.accept()
            return
        if self._move_origin is not None:
            self._finish_move()
            return
        if self._placing_tool is not None:
            self.releaseMouse()
            tool = self._placing_tool
            start = self._placing_start_time
            end = max(start, self._placing_end_time if self._placing_end_time is not None else start)
            # Combine the event's own modifiers with the global state, same
            # as wheelEvent elsewhere in this class: the global state alone
            # can be stale, and (for synthetic/test events especially) the
            # event's own modifiers may be the only place Shift shows up.
            # The event's own modifiers, never the cached global -- see
            # `shift_is_held`. A tap of Shift used to stick.
            big = bool(event.modifiers() & Qt.ShiftModifier)
            self._placing_tool = None
            self._placing_start_time = None
            self._placing_end_time = None
            self.note_place_with_duration_requested.emit(tool, start, end, self.new_combo, big)
            self.update()
            return
        if self._resizing_note is not None:
            self.releaseMouse()
            note = self._resizing_note
            new_end = self._resize_new_end_time
            self._resizing_note = None
            self._resize_new_end_time = None
            if new_end is not None:
                self.note_duration_edit_requested.emit(note.uid, new_end)
            self.update()
            return
        if self.drag_anchor_time is None: return
        if self.tool in self.RANGE_TOOLS:
            self.releaseMouse()
            start, end = sorted((self.drag_anchor_time, self.time_for_x(event.position().x())))
            if self.tool == "kiai":
                # Snapped here rather than by the handler -- see
                # SVEditorView.mouseReleaseEvent, which owns the same gesture
                # in the Kiai and Sound Volume layer and for the same reason:
                # only the view knows Ctrl means whole milliseconds.
                start, end = self.snap_ms(start), self.snap_ms(end)
            self.drag_start_x = None
            self.drag_anchor_time = None
            self.update()
            self.timing_function_range_requested.emit(start, end)
            return
        self.auto_scroll_timer.stop(); self.releaseMouse()
        # Click-to-seek is a Fancy-Arranger-timeline convenience; Editor-page
        # views (symmetric) must not jump the shared playhead just because
        # someone clicked inside them to select/place/inspect a note.
        if not self.editor_view and abs(event.position().x()-(self.drag_start_x or 0.0))<5:
            self.current_time=self.snap_ms(self.time_for_x(event.position().x())); self.seek_requested.emit(self.current_time)
        self.drag_start_x=None; self.drag_anchor_time=None; self.update()
        # Previewing on every mouse-move would be far too expensive, so the
        # expensive refresh is deferred until the drag actually ends.
        self.selection_finalized.emit(set(self.selected))

    def selected_notes(self) -> list:
        """Selected notes in time order, for copy and for Delete."""
        return sorted(
            (note for note in self.notes if note.original_index in self.selected),
            key=lambda note: (note.time, note.uid),
        )

    def keyPressEvent(self, event) -> None:
        if event.key() == Qt.Key_Escape:
            # Only swallow Esc when it actually cleared something. With no
            # selection it belongs to the window, which uses it to leave the
            # editor for the song list.
            if self.selected or self.selected_timing_uids:
                self.selected.clear()
                self.selected_timing_uids.clear()
                self.selection_changed.emit(set())
                self.update()
                event.accept()
                return
            super().keyPressEvent(event)
            return

        if event.key() in (Qt.Key_Delete, Qt.Key_Backspace):
            # Editor-page views only. The shared Fancy Arranger timeline
            # (symmetric=False) is a transform-selection surface, where
            # Delete would destroy notes someone was only trying to arrange.
            if self.editor_view and self.selected:
                self.notes_delete_requested.emit([note.uid for note in self.selected_notes()])
            if self.editor_view and self.selected_timing_uids:
                self.timing_lines_delete_requested.emit(sorted(self.selected_timing_uids))
            event.accept()
            return

        if event.matches(QKeySequence.StandardKey.SelectAll):
            self.selected = {
                note.original_index
                for note in self.notes
            }
            self.selection_changed.emit(set(self.selected))
            self.update()
            return

        super().keyPressEvent(event)

    def _next_timing_time_after(self, time_ms: float) -> float | None:
        """Start of the next timing section strictly after `time_ms`."""
        times = self._snap_times or self._timing_times
        index = bisect_right(times, time_ms)
        return times[index] if index < len(times) else None

    def _draw_snap_grid(
        self,
        painter: QPainter,
        baseline_y: int,
    ) -> None:
        start_time = self.current_time - self.window_ms / 2
        end_time = self.current_time + self.window_ms / 2

        if end_time <= start_time:
            return

        # _tick_styles' heights are pixels at DESIGN_HEIGHT. Sized from the view
        # for the same reason the note radii are: on the gimmick page's short
        # bands a full-size tick growing in from each edge meets the one
        # opposite, and the notes end up drawn on top of a solid grid.
        tick_scale = min(1.0, self.height() / self.DESIGN_HEIGHT)
        divisor = self.snap_divisor
        snap_points = self.snap_beat_points
        timing = active_timing(
            snap_points,
            start_time,
        )
        # The walk below only moves forward, and the timing section it is in
        # changes once or twice in a window -- but it used to binary-search the
        # whole point list again for every single tick. Profiling one gimmick
        # page frame caught 152 of those searches, 30 per grid draw. Hold the
        # section until the walk reaches the next timing point instead.
        #
        # Conservative on purpose: an inherited point expires the section
        # without changing which uninherited one is active, so that case costs
        # a search that returns what we already had -- never a stale section.
        section_expires = -math.inf

        # A gimmick map's "invisible note" points carry beat_length = 0.0001,
        # which puts millions of sub-pixel ticks in one window -- a hard freeze,
        # not a slow frame. Nothing this fine is visible anyway (see
        # `_min_tick_spacing_px`), so it is not drawn.
        min_snap_length = (
            self.window_ms / max(1.0, float(self.width())) * self._min_tick_spacing_px
        )

        # Collected per tick kind and stroked in one drawLines each, rather
        # than setPen + drawLine per tick. Worth about half the raster call
        # (1882 lines: 1.67ms one at a time, 0.89ms batched) and no more --
        # the frame was never in the pen changes, it was in the walk below.
        batches: dict[str, list[QLine]] = {}
        tick_heights = {
            name: round(height * tick_scale)
            for name, (_pen, height) in self._tick_styles.items()
        }

        # Floored with the same minimum: a million-BPM point makes snap_length
        # small enough that the division below overflows to infinity, and
        # int(inf) raises. Only the *starting* tick is affected, and the loop
        # skips those sections whole anyway.
        snap_length = max(timing.beat_length / divisor, min_snap_length)
        # The divisor actually drawn, coarsened per section so the grid stays
        # legible instead of turning into fill. Measured on nbt-hwt's hidden
        # anti-barline (a 12345 BPM wall): a 1/4 grid there is 1.15px apart,
        # 1422 ticks a frame, 15.3ms of a 16.3ms chart paint against an 8.33ms
        # budget -- and every one of those ticks lands on a pixel its
        # neighbour already covered. Only ever a divisor *of* the setting, so
        # what is drawn is a subset of the real grid rather than a different
        # one.
        grid_divisor = divisor

        tick_time = (
            timing.time
            + int(
                (start_time - timing.time)
                // snap_length
            )
            * snap_length
        )

        # Everything below is per tick, and a heavy gimmick section still has
        # ~470 of them per band after the coarsening above -- a band paint was
        # 3.1ms, the grid most of it (tools/measure_wheel_seek.py --gimmick
        # --from 117000 --profile, Nbt-Hwt's hidden anti-barline wall). So
        # what only changes per *section* is worked out per section: which
        # kind each position in the beat is, and the lines each kind draws
        # into. Locals rather than attributes for the same reason.
        x_for_time = self.x_for_time
        right_edge = float(self.width() + 1)
        height = self.height()
        split_rows, symmetric = self.split_rows, self.symmetric
        kinds: list[tuple[list[QLine], int]] = []
        # Every whole beat also gets a faint line the full height of the view,
        # under the ticks, as in the approved mockup: the ticks stay where each
        # layer wants them (edges, or the middle on a split layer) and the line
        # is what the eye follows down through the notes. Identity, not a
        # second lookup: `kinds` below hands out this very list for "beat".
        beat_lines = batches.setdefault("beat", [])
        full_beats: list[QLine] = []

        while tick_time <= end_time + snap_length:
            at = tick_time + 0.001
            if at >= section_expires:
                # -inf is the walk's first section, not a red line it crossed.
                crossed = section_expires != -math.inf
                timing = active_timing(snap_points, at)
                following = self._next_timing_time_after(tick_time)
                section_expires = math.inf if following is None else following
                grid_divisor = divisor
                for candidate in divisors_descending(divisor):
                    if timing.beat_length / candidate >= min_snap_length:
                        grid_divisor = candidate
                        break
                kinds = []
                for position in range(grid_divisor):
                    kind = tick_kind(position, grid_divisor)
                    lines = batches.get(kind)
                    if lines is None:
                        lines = batches[kind] = []
                    kinds.append((lines, tick_heights[kind]))
                # Restart the walk on this section's own red line. Carrying the
                # previous section's phase across it drew every tick after an
                # off-grid red line where the *old* timing said, not where a
                # note snaps (`snap_time` anchors on the red line) -- and since
                # the phase came from whichever section the window opened in,
                # the grid after the line shifted as the view scrolled.
                # Counted from the last tick drawn, not this one: this one has
                # already overshot the red line, and starting from it skipped
                # the section's own downbeat -- the white beat tick on the line.
                # Only on a line actually crossed: the walk's first section is
                # already phased on its own red line, and restarting there
                # jumped a view opening before a map's first red line straight
                # to it, so the grid to its left vanished.
                section_snap = timing.beat_length / grid_divisor
                if crossed and section_snap >= min_snap_length:
                    drawn = tick_time - snap_length
                    tick_time = timing.time + max(0, math.floor(
                        (drawn - timing.time) / section_snap + 1e-6
                    ) + 1) * section_snap

            snap_length = timing.beat_length / grid_divisor
            if snap_length < min_snap_length:
                next_section = self._next_timing_time_after(tick_time)
                if next_section is None or next_section > end_time:
                    break
                tick_time = next_section
                continue

            lines, tick_height = kinds[round((tick_time - timing.time) / snap_length) % grid_divisor]
            # Clamped to just off either edge before it reaches Qt: drawLine
            # takes a C int, and one 0.00001 BPM section puts the tick after
            # this one billions of pixels out. Handing that over raises
            # OverflowError *inside* paintEvent, which aborts the whole frame --
            # grid, notes and all -- and looks like the map vanishing.
            #
            # Drawn at `osu_snap_ms(tick_time)`, not at the exact fractional
            # beat: objects snap to a whole millisecond and osu! takes that one
            # *down* (see `osu_snap_ms`), so a grid drawn at the unrounded
            # position sits up to a whole millisecond off the note it is meant
            # to mark. The walk itself still steps by the exact `snap_length` --
            # only the drawn position is snapped, never accumulated back into
            # `tick_time`, which keeps the grid from drifting off its own beats
            # across a long section.
            x = round(max(-1.0, min(right_edge, x_for_time(osu_snap_ms(tick_time)))))
            if lines is beat_lines:
                full_beats.append(QLine(x, 0, x, height))

            if split_rows:
                # Straddling the middle instead of growing in from the edges:
                # this layer's objects are up against the top and bottom, and
                # ticks there were drawn through them. See `_row_y`.
                lines.append(QLine(x, baseline_y - tick_height // 2, x, baseline_y + tick_height // 2))
            elif symmetric:
                # Notes alone stay centered on the baseline; ticks anchor to
                # the view's top and bottom edges and grow inward, framing
                # the notes rather than straddling the middle with them.
                lines.append(QLine(x, 0, x, tick_height))
                lines.append(QLine(x, height, x, height - tick_height))
            else:
                lines.append(QLine(x, baseline_y, x, baseline_y - tick_height))

            tick_time += snap_length

        if full_beats:
            painter.setPen(self.beat_line_pen)
            painter.drawLines(full_beats)
        for kind, lines in batches.items():
            if lines:
                painter.setPen(self._tick_styles[kind][0])
                painter.drawLines(lines)

    def _owns_timing_point(self, point: TimingPoint) -> bool:
        """Whether this view's tools act on `point`, or merely show it.

        Ownership is decided by which *structure* a line belongs to, not by
        whether some hit object shares its millisecond. It used to be the
        latter, which was true only while a barline note wrote no note of its
        own: once it did, its middle line -- the 60000 BPM line that is the
        whole gimmick -- landed on that note and became untouchable in the one
        layer that exists to touch it.
        """
        return round(point.time) not in self.foreign_times

    def _visible_timing_points(self):
        """The document's red lines inside the window, at most one per pixel.

        A barline gimmick puts thousands of uninherited points in one screen,
        most of them on the same pixel column. Drawing every one is a line per
        point per frame for a result indistinguishable from drawing one.
        """
        if not self.show_timing_lines or not self.timing_points:
            return
        start_time = self.current_time - self.window_ms / 2
        end_time = self.current_time + self.window_ms / 2
        first = bisect_left(self._timing_times, start_time)
        after_last = bisect_right(self._timing_times, end_time)
        previous: tuple[int, bool] | None = None
        for point in self.timing_points[first:after_last]:
            if self.timing_line_times is not None and round(point.time) not in self.timing_line_times:
                continue
            owned = self._owns_timing_point(point)
            x = round(self.x_for_time(point.time))
            if previous == (x, owned):
                continue
            previous = (x, owned)
            yield point, x, owned

    def _draw_timing_lines(self, painter: QPainter) -> None:
        # Same two-places-at-once rule the dragged notes follow: a line being
        # moved is drawn at its destination, and faintly where it came from.
        moving = set(self._move_point_uids) if self._move_origin is not None else frozenset()
        # Labels are spaced the same way the SV editor spaces its own: a
        # barline gimmick stacks thousands of lines in one window, and a number
        # beside each of them is a solid grey block.
        last_label_x = -1e9
        for point, x, owned in self._visible_timing_points():
            if point.uid in moving:
                painter.setPen(self.timing_line_ghost_pen)
                painter.drawLine(x, 0, x, self.height())
                x = round(self.x_for_time(point.time + self._move_delta))
            if point.uid in self.selected_timing_uids:
                painter.setPen(self.selected_note_pen)
            else:
                painter.setPen(self.timing_line_pen if owned else self.timing_line_ref_pen)
            painter.drawLine(x, 0, x, self.height())
            if (
                self.show_bpm_labels and owned and point.bpm
                and x - last_label_x >= SV_LABEL_MIN_SPACING_PX
            ):
                last_label_x = x
                painter.save()
                painter.setFont(self.label_font)
                painter.setPen(self.bpm_label_pen)
                painter.drawText(QPointF(x + 4, self.height() - 4), f"{point.bpm:.0f} BPM")
                painter.restore()

    def _gimmick_centre_near_x(self, x: float, radius_px: float = 12.0):
        """The owned gimmick line in the same pixel neighbourhood as `x`, if any.

        A barline note is up to seven red lines inside twelve milliseconds. At
        any zoom you can read a chart at they are the same pixel column, so
        "the nearest line" picks between its centre and its restores by
        rounding error -- and only the centre is the object. Right click and
        drag both ask for it here, so grabbing a barline note means the same
        thing wherever inside it the cursor was.

        `<=`, not `<`, on the tie itself: two points can legitimately share one
        exact millisecond (a converter's green line stacked on the chart's own,
        deliberately never deduped -- see `_convert_to_anti_barline`), and
        `self.timing_points` is stable-sorted from insertion order, so the last
        of an exact tie is the one osu! actually honours. `<` kept whichever
        was inserted first -- the superseded one -- so a click there grabbed
        and showed a dead point while the effective one sat untouched under it.
        """
        best = None
        best_distance = None
        for point in self.timing_points:
            if round(point.time) not in self.gimmick_times or not self._owns_timing_point(point):
                continue
            distance = abs(self.x_for_time(point.time) - x)
            if distance <= radius_px and (best_distance is None or distance <= best_distance):
                best = point
                best_distance = distance
        return best

    def _timing_point_near_x(self, x: float, radius_px: float = 12.0):
        """The owned red line nearest `x`, for the double-click BPM edit.

        Restricted to the lines this view actually draws. A layer that filters
        them (`timing_line_times`, the fake slider layer) would otherwise hand
        back a line that is not on screen at all -- the chart's own timing, or
        a barline gimmick's -- and open a dialog for something invisible.

        `<=` on the tie: see `_gimmick_centre_near_x` on why the last of an
        exact-millisecond tie, not the first, is the point actually in force.
        """
        best = None
        best_distance = None
        for point in self.timing_points:
            if self.timing_line_times is not None and round(point.time) not in self.timing_line_times:
                continue
            if not self._owns_timing_point(point):
                continue
            distance = abs(self.x_for_time(point.time) - x)
            if distance <= radius_px and (best_distance is None or distance <= best_distance):
                best = point
                best_distance = distance
        return best

    def mouseDoubleClickEvent(self, event) -> None:
        """Double click a red line to retype its BPM, where that is allowed.

        Reached before mousePressEvent's tool handling gets a second click, so a
        placement tool being active does not swallow it.
        """
        if event.button() != Qt.LeftButton:
            super().mouseDoubleClickEvent(event)
            return
        # The object before the line under it, the same order mousePressEvent
        # resolves a grab in: on layer 2 the fake slider and the red line that
        # squashes it are a millisecond apart, which is one pixel column at any
        # zoom the layer is readable at, and the line is the half you did not
        # click on.
        if self.note_length_dialog_enabled:
            note = self._note_near_x(event.position().x(), y=event.position().y())
            if note is not None and note.length is not None:
                self.note_length_edit_requested.emit(note.uid)
                event.accept()
                return
        if not self.timing_dialog_enabled:
            super().mouseDoubleClickEvent(event)
            return
        point = self._timing_point_near_x(event.position().x())
        if point is None or point.bpm is None:
            super().mouseDoubleClickEvent(event)
            return
        self.timing_line_edit_requested.emit(point.uid)
        event.accept()

    def paintEvent(self, event) -> None:
        painter = QPainter(self)
        painter.fillRect(self.rect(), view_ground("#151b24"))
        self.draw_kiai_bands(painter)

        baseline_y = self._baseline_y()
        normal_note_radius, finisher_note_radius = self.note_radii()

        self._draw_snap_grid(painter, baseline_y)
        self._draw_timing_lines(painter)

        painter.setPen(self.baseline_pen)
        painter.drawLine(0, baseline_y, self.width(), baseline_y)

        start_time = self.current_time - self.window_ms / 2
        end_time = self.current_time + self.window_ms / 2

        # Only visit notes inside the visible window instead of scanning the
        # complete beatmap on every audio-position update. Widened on the left
        # by the longest slider/spinner duration so a long note whose start
        # has scrolled off-screen still gets drawn while its end is visible.
        first_visible = bisect_left(self.note_times, start_time - self._max_extend_ms)
        after_last_visible = bisect_right(self.note_times, end_time)

        if self.drag_anchor_time is not None:
            anchor_x=self.x_for_time(self.drag_anchor_time); current_x=max(0.0,min(float(self.width()),self.drag_mouse_x))
            left,width=min(anchor_x,current_x),abs(current_x-anchor_x)
            top, bottom = self._row_span(self._drag_y)
            painter.fillRect(QRectF(left,top,width,bottom-top),QColor(190,195,205,28))
            painter.setPen(QPen(QColor(220,225,235,70),1)); painter.drawRect(QRectF(left,top,width,bottom-top-1))
        painter.setRenderHint(QPainter.Antialiasing, True)

        # Notes being dragged are drawn where they are *going*, with a
        # translucent copy left where they came from -- see _draw_move_ghost.
        # Without the preview, a drag showed the object standing still and only
        # a marker line moving, so there was nothing to line the object up with.
        moving_notes = set(self._move_note_uids) if self._move_origin is not None else frozenset()

        for note in self.notes[first_visible:after_last_visible]:
            x = self.x_for_time(note.time)
            # A dragged note is previewed at its destination, so its body (a
            # slider bar, a spinner band) has to travel with its head.
            shift = 0.0
            if note.uid in moving_notes:
                self._draw_move_ghost(painter, note, x, baseline_y, normal_note_radius, finisher_note_radius)
                shift = self._move_delta
                x = self.x_for_time(note.time + shift)
            # Spinners always render at the finisher/"big note" size,
            # independent of the finisher hitsound bit -- a plain visual
            # convention for this app, not a gameplay difference.
            radius = (
                finisher_note_radius
                if (note.is_finisher or note.is_spinner)
                else normal_note_radius
            )
            shiny = self.split_rows and round(note.time) in self.shiny_times
            note_center_y = self.note_center_y(note, baseline_y, radius)
            note_pen = self.selected_note_pen if note.original_index in self.selected else self.normal_note_pen

            if note.is_spinner:
                # A spinner is a duration, but only its start had any visual
                # weight, so where it *ended* was invisible unless you dragged
                # its edge and watched the ghost. Grey band from start to end,
                # with a cap at each edge.
                spinner_end = self._note_end_time(note)
                if spinner_end is not None and spinner_end > note.time:
                    end_x = self.x_for_time(spinner_end + shift)
                    band = QRectF(x, note_center_y - radius * 0.5, end_x - x, radius)
                    painter.setBrush(self.spinner_band_brush)
                    painter.setPen(Qt.NoPen)
                    painter.drawRoundedRect(band, radius * 0.25, radius * 0.25)
                    painter.setPen(self.spinner_edge_pen)
                    for edge_x in (x, end_x):
                        painter.drawLine(
                            QPointF(edge_x, note_center_y - radius * 0.7),
                            QPointF(edge_x, note_center_y + radius * 0.7),
                        )
                pixmap = spinner_pixmap()
                if not pixmap.isNull():
                    size = radius * 2
                    target = QRectF(x - radius, note_center_y - radius, size, size)
                    painter.drawPixmap(target, pixmap, QRectF(pixmap.rect()))
                    if note.original_index in self.selected:
                        painter.setBrush(Qt.NoBrush)
                        painter.setPen(note_pen)
                        painter.drawEllipse(QPointF(x, note_center_y), radius, radius)
                    continue

            # A fake slider is a head and nothing else here. It has no body to
            # cap -- its end precedes its start, or trails it by a rounding
            # artefact -- but `_draw_skinned_roll_body` stamps `taiko-roll-end`
            # at `body_end` whether or not a track got drawn, so every fake
            # slider in the editor wore a cap butted against its own head. The
            # scrolling body belongs to the gameplay preview, which draws the
            # extent to scale; this view has no room to say anything but where
            # the object is.
            if note.is_slider and not is_fake_slider(note):
                end_time = self._note_end_time(note)
                end_x = x
                if end_time is not None and end_time > note.time:
                    end_x = self.x_for_time(end_time + shift)
                # A drumroll is `taikohitcircle` + `taiko-roll-middle` +
                # `taiko-roll-end`, here as well as in the gameplay preview: the
                # skin is meant to reach every view that draws a note, and a
                # timeline that drew its own bar beside a skinned head was the
                # one place the two disagreed. The head itself is drawn by the
                # shared call below, so this is the body and its cap.
                if not self._draw_skinned_roll_body(
                    painter, x, end_x, note_center_y, radius
                ) and end_x > x:
                    bar = QRectF(x, note_center_y - radius * 0.4, end_x - x, radius * 0.8)
                    painter.setBrush(self.slider_brush)
                    painter.setPen(Qt.NoPen)
                    painter.drawRoundedRect(bar, radius * 0.4, radius * 0.4)

            # Semi-transparent fill keeps the snap grid visible through notes;
            # with a skin loaded that alpha becomes painter opacity so the art
            # stays see-through too. See draw_note_sprite.
            draw_note_sprite(
                painter,
                self.shiny_brush if shiny
                else self.slider_brush if note.is_slider
                else (self.kat_brush if note.is_kat else self.don_brush),
                note_pen,
                x,
                note_center_y,
                radius,
                self.skin,
                big=note.is_finisher,
                selected=note.original_index in self.selected,
            )

        self._draw_placement_ghost(painter, baseline_y, normal_note_radius, finisher_note_radius)
        self.draw_ctrl_precision_line(painter)
        self.draw_cursor_position(painter)

        cursor_x = self.width() // 2
        painter.setPen(self.cursor_pen)
        if self.symmetric:
            painter.drawLine(cursor_x, 0, cursor_x, self.height())
        else:
            painter.drawLine(
                cursor_x,
                baseline_y - 92,
                cursor_x,
                baseline_y + 7,
            )

    def _baseline_y(self) -> float:
        """The y objects are centred on. Bottom-anchored views draw lower."""
        return self.height() // 2 if self.symmetric else self.height() // 2 + 34

    def note_center_y(self, note, baseline_y: float, radius: float) -> float:
        """The y `note` is drawn centred on. Shared with the painter, so what
        the cursor can land on is what the eye can see."""
        if self.split_rows:
            return self._row_y(baseline_y, round(note.time) in self.shiny_times)
        return baseline_y if self.symmetric else baseline_y - radius

    def _press_is_on_note_body(self, note, x: float, y: float) -> bool:
        """Whether (x, y) is inside the circle drawn for `note`.

        `_note_near_x` deliberately ignores y off a split layer -- a right
        click anywhere in the band should still delete what is in that column.
        Starting a *move* is the one thing that has to be stricter: on a normal
        chart every column has a note in it, so a press that begins a
        rubber-band selection would grab one instead. Requiring the press to be
        on the object itself leaves the whole height above and below the row
        for selecting.
        """
        normal_radius, finisher_radius = self.note_radii()
        radius = finisher_radius if (note.is_finisher or note.is_spinner) else normal_radius
        centre_y = self.note_center_y(note, self._baseline_y(), radius)
        dx = self.x_for_time(note.time) - x
        dy = centre_y - y
        return dx * dx + dy * dy <= radius * radius

    def _row_y(self, baseline_y: float, lower: bool) -> float:
        """Centre of the upper or lower object row on a split layer.

        A quarter of the band either side of the middle: the snap ticks are
        drawn across the middle, so the rows sit clear of them rather than
        being cut in half by the grid.
        """
        offset = self.height() * 0.24
        return baseline_y + offset if lower else baseline_y - offset

    def _draw_move_ghost(
        self, painter: QPainter, note, x: float, baseline_y: int,
        normal_radius: float, finisher_radius: float,
    ) -> None:
        """Translucent copy of a dragged note, where it started.

        The drag is only committed on release, so during it the object needs to
        say two things at once: where it is going (the solid sprite, drawn at
        the destination) and where it would go back to if the drag were
        abandoned. The same ghost brushes the placement preview uses, so a
        faded object means the same thing throughout the view.
        """
        radius = finisher_radius if (note.is_finisher or note.is_spinner) else normal_radius
        shiny = self.split_rows and round(note.time) in self.shiny_times
        brush = (
            self.ghost_shiny_brush if shiny
            else self.ghost_slider_brush if (note.is_slider or note.is_spinner)
            else self.ghost_kat_brush if note.is_kat
            else self.ghost_don_brush
        )
        draw_note_sprite(
            painter, brush, self.ghost_pen, x,
            self._row_y(baseline_y, shiny) if self.split_rows
            else baseline_y if self.symmetric
            else baseline_y - radius,
            radius, self.skin, big=note.is_finisher,
        )

    def _draw_extend_ghost(
        self, painter: QPainter, baseline_y: int, normal_radius: float, finisher_radius: float,
        tool: str, start_time: float, end_time: float, big: bool,
    ) -> None:
        """Translucent preview of a slider/spinner being placed or resized."""
        radius = finisher_radius if (big or tool == "spinner") else normal_radius
        note_center_y = baseline_y if self.symmetric else baseline_y - radius
        x1 = self.x_for_time(start_time)
        x2 = self.x_for_time(max(start_time, end_time))

        if tool == "spinner":
            pixmap = spinner_pixmap()
            if not pixmap.isNull():
                painter.setOpacity(0.45)
                size = radius * 2
                painter.drawPixmap(QRectF(x1 - radius, note_center_y - radius, size, size), pixmap, QRectF(pixmap.rect()))
                painter.setOpacity(1.0)
            if x2 > x1:
                painter.setPen(QPen(QColor(255, 255, 255, 110), 3))
                painter.drawLine(QPointF(x1, note_center_y), QPointF(x2, note_center_y))
            return

        if x2 > x1:
            bar = QRectF(x1, note_center_y - radius * 0.4, x2 - x1, radius * 0.8)
            painter.setBrush(self.ghost_slider_brush)
            painter.setPen(Qt.NoPen)
            painter.drawRoundedRect(bar, radius * 0.4, radius * 0.4)
        painter.setBrush(self.ghost_slider_brush)
        painter.setPen(self.ghost_pen)
        painter.drawEllipse(QPointF(x1, note_center_y), radius, radius)

    def _draw_placement_ghost(self, painter: QPainter, baseline_y: int, normal_radius: float, finisher_radius: float) -> None:
        # Paint time, so there is no event to read: the live hardware state
        # rather than Qt's cached one, or a stale Shift bit draws every
        # ghost at finisher size. See `shift_is_held`.
        shift_held = shift_is_held()

        if self._placing_tool in ("slider", "spinner") and self._placing_start_time is not None:
            self._draw_extend_ghost(
                painter, baseline_y, normal_radius, finisher_radius, self._placing_tool,
                self._placing_start_time, self._placing_end_time or self._placing_start_time, shift_held,
            )
            return
        if self._resizing_note is not None and self._resize_new_end_time is not None:
            note = self._resizing_note
            tool = "spinner" if note.is_spinner else "slider"
            self._draw_extend_ghost(
                painter, baseline_y, normal_radius, finisher_radius, tool,
                note.time, self._resize_new_end_time, note.is_finisher,
            )
            return
        # "regular" is the fake slider layer's own tool -- it writes a shape
        # rather than a note, so it previews through _draw_layer_ghost below.
        # Without it here the one tool whose whole output is a drawn object was
        # the one tool that showed nothing under the cursor.
        if self.tool not in ("don", "kat", "regular", "shiny", "multi", "slider", "spinner") or self._hover_time is None:
            return

        snapped = self.snap_ms(self._hover_time)
        x = self.x_for_time(snapped)
        # "multi" places a run either side of the click, so its own x can be off
        # screen while the run is not; it does its own bounds check per ghost.
        if self.tool != "multi" and (x < -60 or x > self.width() + 60):
            return

        if self.tool == "multi":
            self._draw_multi_run_ghost(painter, baseline_y, normal_radius, finisher_radius, snapped, shift_held)
            return

        if self.tool == "slider":
            self._draw_extend_ghost(painter, baseline_y, normal_radius, finisher_radius, "slider", snapped, snapped, shift_held)
            return

        radius = finisher_radius if (self.tool == "spinner" or shift_held) else normal_radius
        note_center_y = baseline_y if self.symmetric else baseline_y - radius

        if self.ghost_style != "note" and self.tool in ("don", "kat", "regular", "shiny"):
            # Don is the small variant and Kat the big one in both layers, the
            # way the finisher bit decides size in a normal chart -- here the
            # tool decides it, since these structures carry no hitsound of their
            # own until they are written. A plain fake slider and a shiny have
            # no such pair, so Shift picks their size the same way it does for a
            # Don or Kat in a normal chart -- see gimmick_session.fake_slider.
            shift_sizes = shift_held and self.tool in ("regular", "shiny")
            self._draw_layer_ghost(
                painter, x, baseline_y,
                finisher_radius if (self.tool == "kat" or shift_sizes) else normal_radius,
            )
            return
        if self.tool == "spinner":
            pixmap = spinner_pixmap()
            if not pixmap.isNull():
                painter.setOpacity(0.45)
                size = radius * 2
                painter.drawPixmap(QRectF(x - radius, note_center_y - radius, size, size), pixmap, QRectF(pixmap.rect()))
                painter.setOpacity(1.0)
                return
            brush = QColor(255, 255, 255, 70)
        else:
            brush = self.ghost_kat_brush if self.tool == "kat" else self.ghost_don_brush
        painter.setBrush(brush)
        painter.setPen(self.ghost_pen)
        painter.drawEllipse(QPointF(x, note_center_y), radius, radius)

    def _draw_multi_run_ghost(
        self, painter: QPainter, baseline_y: int, normal_radius: float,
        finisher_radius: float, snapped: float, shift_held: bool,
    ) -> None:
        """The Multiple Fake Slider tool's preview: the whole run, not one dot.

        The tool writes N structures at `click+start .. click+end` stepped by
        `distance`, so a single ghost under the cursor said nothing about what
        a click was about to place -- and Shift, which sizes every one of them,
        showed nothing at all because "multi" was missing from the tool list in
        `_draw_placement_ghost`.

        Positions are the tool's own (`_multi_fake_slider_commands`), plus the
        `fake_slider_offset_ms` that puts each drawn object one offset after
        its structure -- the ghost stands where the slider lands, not where the
        structure is anchored. Shift sizes them the same way it sizes a
        Don or Kat in a normal chart; see `gimmick_session.fake_slider`, which
        honours `big` for `kind="regular"`.
        """
        if not self.multi_run:
            return
        start, end, distance, offset = self.multi_run
        if distance <= 0:
            return
        radius = finisher_radius if shift_held else normal_radius
        position = start
        while position <= end:
            x = self.x_for_time(snapped + position + offset)
            # Per ghost, because a long run reaches well past both edges.
            if -60 <= x <= self.width() + 60:
                if self.ghost_style != "note":
                    self._draw_layer_ghost(painter, x, baseline_y, radius)
                else:
                    painter.setBrush(self.ghost_don_brush)
                    painter.setPen(self.ghost_pen)
                    y = baseline_y if self.symmetric else baseline_y - radius
                    painter.drawEllipse(QPointF(x, y), radius, radius)
            position += distance

    def _draw_layer_ghost(self, painter: QPainter, x: float, baseline_y: float, radius: float) -> None:
        """Don/Kat previewed as what *this layer* writes, not as a note.

        Same translucency as the normal chart's ghost -- what changes is the
        shape, because the structure does:

        * **fake_slider** -- the yellow drumroll body a fake slider is drawn as.
        * **barline** -- a bar, since a run of red lines is what that layer
          writes and a circle would promise a note that is not there. Kat's
          three mirrored pairs make it the wider bar to Don's one.
        """
        # A shiny previews white and on the lower row, which is exactly where it
        # will be drawn once written -- the two tools in this layer place the
        # same shape a millisecond apart, so the row is the only thing under the
        # cursor that says which one is about to happen.
        shiny = self.tool == "shiny"
        painter.setBrush(self.ghost_shiny_brush if shiny else self.ghost_slider_brush)
        painter.setPen(self.ghost_pen)
        if self.ghost_style == "fake_slider":
            y = self._row_y(baseline_y, shiny) if self.split_rows else baseline_y
            painter.drawEllipse(QPointF(x, y), radius, radius)
            return
        half_width = max(2.0, radius * 0.22)
        painter.drawRect(QRectF(x - half_width, baseline_y - radius, half_width * 2, radius * 2))


# Range for mapping SV multiplier to vertical position in the SV graph;
# log-scaled since SV is inherently multiplicative (0.5x and 2x are equally
# "far" from 1x). Doesn't affect stored values, only where the line is drawn.
# The floor is fixed: anything slower than SV_VISUAL_MIN is simply drawn along
# the bottom of the graph rather than dragging the whole axis down with it.
# Only the ceiling autoscales, and only upward past SV_VISUAL_MAX -- see
# SVEditorView.update_scale.
SV_VISUAL_MIN = 0.1
SV_VISUAL_MAX = 2.5

# Absolute limits on the axis, whatever the map contains.
SV_SCALE_FLOOR = 0.01
SV_SCALE_CEILING = 100.0

# The axis only ever sits on "round" values -- 0.5x, 1.5x, 2.0x -- rather than
# whatever min/max the visible points happen to have. An axis labelled 0.43x to
# 3.17x is arithmetically correct and useless to read against.
SV_BOUND_STEPS = ((0.5, 0.5), (0.1, 0.1), (0.0, 0.01))
# A bound is pushed outward once a value gets within this ratio of it, rather
# than only once it crosses -- a line drawn hard against the edge of the graph
# is already unreadable.
SV_BOUND_NEAR = 1.05
# ...and pulled back in only once the visible range fits this much inside the
# current bound. Without the gap, scrolling across a section that straddles a
# ladder step would retune the axis on alternate frames.
SV_BOUND_SLACK = 1.3

# Minimum horizontal gap between two SV value labels on the graph. A generated
# sweep can put hundreds of points in one screen; labelling every one is both
# unreadable and a drawText per point per frame.
SV_LABEL_MIN_SPACING_PX = 46.0

# Decimals an SV value can be *typed* to. A green line's multiplier is
# -100/beat_length, so under a 60000 BPM red line the SV that moves a note a
# visible distance differs from its neighbour in the seventh decimal. The graph
# still labels at 2dp: it is read at a glance, and 8 decimals on every point is
# a smear -- the spin boxes are where a value is actually tuned.
SV_DECIMALS = 8

# The smallest step a vertical drag commits to. Typing still reaches SV_DECIMALS
# -- this is only what a mouse-move quantizes *to* before it is even sent
# onward. At full float precision a drag emits a new value on essentially
# every pixel, so _edit_sv_point's full refresh (history push, hitsound
# schedule rebuild, every open view) ran once per pixel too -- measured at
# ~17ms a call on a 3000-point gimmick chart (tools/measure_sv_drag.py),
# against a mouse that can deliver a move every few ms. Rounding to this step
# and skipping a call whose value did not actually change (see
# SVEditorView.mouseMoveEvent) is what lets most of those moves cost nothing.
SV_DRAG_STEP = 0.01

# A click on a green line within this many pixels of its actual value dot
# adjusts the SV (vertical); farther away on the same line -- the vertical
# guide line is drawn full-height, so a click anywhere along it lands "on" the
# line -- retimes it (horizontal) instead. Smaller than the line's own hit
# radius, so the dot is a precise target inside a more forgiving line.
SV_DOT_HIT_RADIUS_PX = 10.0


def _sv_bound_step(value: float) -> float:
    """Ladder spacing at `value`: coarse for normal SV, finer near zero."""
    for threshold, step in SV_BOUND_STEPS:
        if value >= threshold:
            return step
    return SV_BOUND_STEPS[-1][1]


def sv_bound_below(value: float) -> float:
    """Largest ladder value strictly below `value`.

    Strictly below, so the line is never drawn along the very edge of the
    graph. Falls to a finer step when the coarse one would land on (or under)
    zero, which a logarithmic axis cannot represent.
    """
    for _threshold, step in SV_BOUND_STEPS:
        candidate = (math.ceil(value / step - 1e-9) - 1) * step
        if candidate >= SV_SCALE_FLOOR:
            return min(candidate, SV_SCALE_CEILING)
    return SV_SCALE_FLOOR


def sv_bound_above(value: float) -> float:
    """Smallest ladder value strictly above `value`."""
    step = _sv_bound_step(value)
    candidate = (math.floor(value / step + 1e-9) + 1) * step
    return max(SV_SCALE_FLOOR * 2, min(candidate, SV_SCALE_CEILING))


class SVEditorView(TimeAxisMixin, QWidget):
    """M4: view and edit [TimingPoints]' inherited (SV) points on a time axis.

    Vertical-line colour follows the same rule as the timing overview bar,
    resolved per timestamp rather than per point: **red** where only an
    uninherited (BPM) point sits, **green** where only inherited (SV) points
    sit, **yellow** where both share the millisecond. Resolving per point
    instead drew the two lines on top of each other and whichever came last
    in file order won, which is why a BPM point with SV stacked on it used to
    render as a plain green line.

    A line connects the effective SV over time; dragging a point in select
    *or* green-line mode moves it, either vertically (SV) or horizontally
    (retime), decided by how close the click landed to the point's own value
    dot -- see _drag_axis_for_click. Green-line mode also shows a snapped
    ghost line under the cursor before placing, mirroring the chart view's
    placement ghost. Holds no MainWindow reference -- like TimelineGameplay,
    it emits requests and the owner applies them.
    """

    seek_requested = Signal(float)
    snap_changed_by_wheel = Signal(int)
    # (start_ms, end_ms) -- drag-select in function mode.
    function_range_requested = Signal(float, float)
    # (snapped_time_ms, sv) -- click in green-line mode.
    point_add_requested = Signal(float, float)
    # (uid, new_time_ms) -- horizontal drag of a line (green or red) in select
    # mode, snapped to the grid. Retiming only, no SV change.
    point_time_edit_requested = Signal(int, float)
    # (uid, new_sv) -- vertical drag of a green line's own value dot. An
    # uninherited point has no SV, so this never fires for one. Kept as its
    # own signal (rather than folded into point_time_edit_requested) because
    # _drag_axis_for_click makes a drag either-or, never both, so each drag
    # only ever emits one of the two -- letting a continuous drag merge into a
    # single undo step instead of interleaving two command shapes that can't
    # merge with each other.
    point_sv_edit_requested = Signal(int, float)
    # (uid, volume 0-100). The Kiai and Sound Volume layer's own edit: its
    # vertical axis is hitsound volume, not SV, so a drag there writes this.
    point_volume_edit_requested = Signal(int, int)
    # Double click in that layer: type the volume, with no time field.
    point_volume_dialog_requested = Signal(int)
    # uid -- right click near an inherited point.
    point_delete_requested = Signal(int)
    # uid -- double click on a line of either kind. Same signal and same dialog
    # as TimelineGameplay's: a green line's SV and a red line's BPM are the same
    # edit seen from two views, and both can be retimed there.
    timing_line_edit_requested = Signal(int)
    # list[uid] -- Delete/Backspace with green lines selected. One signal for
    # the whole selection so the owner can push a single undo step.
    points_delete_requested = Signal(object)
    # New window_ms after a Ctrl+wheel zoom -- see TimelineGameplay.zoom_changed.
    zoom_changed = Signal(float)

    # Twice the chart views' limit: an SV sweep is read across a whole section,
    # a note pattern is not. This was already true before the shared axis was
    # extracted -- it is a deliberate difference, not drift.
    MAX_WINDOW_MS = 120000.0

    # See TimelineGameplay.DESIGN_HEIGHT: the height the graph's margins were
    # measured at. MIN_HEIGHT is this view's floor outside the gimmick page,
    # and is below it, so a short view scales its margins down rather than
    # keeping 56 designed pixels of them in a 120px band.
    DESIGN_HEIGHT = TimelineGameplay.DESIGN_HEIGHT
    MIN_HEIGHT = TimelineGameplay.MIN_HEIGHT

    def __init__(self) -> None:
        super().__init__()

        self.timing_points: list[TimingPoint] = []
        self.current_time = 0.0
        self.window_ms = 4000.0
        self.snap_divisor = 4
        # "select" mirrors TimelineGameplay's default; changed only by this
        # view's own tool row entry (global, per the Editor page's tool
        # rows), never anything else.
        self.tool = "select"
        # Set true only for the Kiai and Sound Volume layer (MainWindow.
        # _add_editor_view). Switches the vertical axis, the connected curve
        # and vertical drags from SV to a plain 0-100 volume percentage; the
        # red/green/yellow line placement itself is unchanged.
        self.volume_mode = False

        self.drag_start_x: float | None = None
        self.drag_anchor_time: float | None = None
        self.drag_mouse_x = 0.0
        self.wheel_accumulator = 0.0
        self.last_rendered_time = -1.0
        self._drag_point: TimingPoint | None = None
        self._drag_axis: str = "time"  # "time" or "value", set by _begin_point_drag
        self._last_drag_value: float | None = None
        # Paint caches, rebuilt per edit rather than per frame -- see
        # _rebuild_caches for why that distinction is load-bearing.
        # Milliseconds this view shows SV for, or None to show every point.
        # The gimmick page's three SV layers each own one structure's SV --
        # see MainWindow._sv_layer_times -- and set this to the timestamps of
        # the objects they belong to. Only inherited points survive the filter,
        # which is also why those layers draw green where the plain SV editor
        # draws yellow: the red line sharing the millisecond is not in the view.
        #
        # `point_times_for` derives it from the document on every refresh, which
        # is what keeps it honest: an edit anywhere can add the very object a
        # layer is keyed to, and refreshes arrive from several paths.
        self.point_times: set[int] | None = None
        self.point_times_for = None
        self._visible_points: list[TimingPoint] = []
        # Write the BPM beside each red line. Off in the barline SV layer: the
        # number belongs next to the lines themselves, which is layer 3, and a
        # barline gimmick puts thousands of them in one window.
        self.show_bpm_labels = True
        self._series: list[tuple[float, float]] = []
        self._series_times: list[float] = []
        # Effective volume over time, used only when volume_mode is True. Kept
        # separate from _series/_series_times rather than repurposing them:
        # SV resolution resets to 1.0x at an uninherited point, volume does
        # not (every point, red or green, carries its own .volume), so the
        # two curves are built by different rules from the same points.
        self._volume_series: list[tuple[float, float]] = []
        self._volume_series_times: list[float] = []
        self._line_kinds: dict[float, str] = {}
        self._line_kind_times: list[float] = []
        self._bpm_at: dict[float, float] = {}
        self._beat_points: list[TimingPoint] = []
        # What the caches above were last built from -- see set_timing_points.
        self._cache_key = None
        self._cache_len = -1
        # Vertical scale, refitted to the visible SV on every paint. Starts at
        # the historical fixed window so an empty view still looks sensible.
        self.autoscale = True
        self.scale_min = SV_VISUAL_MIN
        self.scale_max = SV_VISUAL_MAX
        # Rubber-band selection over a time range (select tool, empty space).
        # Kept separate from drag_anchor_time, which is function mode's range.
        self.select_anchor_time: float | None = None
        self.select_mouse_x = 0.0
        self.auto_scroll_timer = QTimer(self)
        self.auto_scroll_timer.setInterval(16)
        self.auto_scroll_timer.timeout.connect(self._auto_scroll_selection)
        # uids of inherited points picked in select mode, so Delete/Backspace
        # and Ctrl+C have something to act on.
        self.selected_uids: set[int] = set()

        # Ghost preview of the green line a click would place: needs mouse
        # tracking, since plain mouseMoveEvent only fires with a button held.
        self.setMouseTracking(True)
        self._hover_time: float | None = None
        self._hover_sv: float | None = None

        self.red_pen = QPen(QColor(255, 90, 90, 230), 2)
        self.green_pen = QPen(QColor(90, 225, 130, 230), 2)
        # Both kinds share this millisecond -- same convention the timing
        # overview bar already uses for its markers.
        self.yellow_pen = QPen(QColor(255, 212, 0, 235), 2)
        self.selected_pen = QPen(QColor(255, 255, 255, 240), 3)
        self.ghost_pen = QPen(QColor(140, 255, 185, 130), 2, Qt.DashLine)
        self.graph_pen = QPen(QColor(140, 255, 185, 210), 2)
        self.range_brush = QColor(190, 195, 205, 40)
        self.label_pen = QPen(QColor(225, 230, 240, 235), 1)
        # The numbers on the graph, as the approved mockup draws them: the app
        # font, bold, and the SV or volume values in the theme's accent so they
        # read apart from the line labels. Kept off the painter's own font,
        # which the shared cursor readout also uses.
        self.label_font = value_label_font(self.font())
        self.value_pen = QPen(theme.color("#ff9dcc"), 1)
        self.cursor_pen = QPen(QColor("#ffffff"), 2)

        self.setMinimumHeight(self.MIN_HEIGHT)
        self.setFocusPolicy(Qt.StrongFocus)
        # paintEvent opens with an opaque fill of the whole rect, so nothing
        # behind this widget is ever seen. Without the attribute Qt did not
        # know that, and on every frame repainted what sits underneath --
        # the EditorViewFrame's stylesheet (a rounded, bordered rect drawn
        # through QStyleSheetStyle) and the scroll viewport -- only to cover
        # it again. Measured: over half of a six-chart Editor frame was Qt's
        # own work in processEvents, not these paintEvents. If a paintEvent
        # here ever stops filling its whole rect, this has to go with it, or
        # stale pixels show through -- which is why it follows View opacity
        # (`set_view_opacity`): below 100% the fill lets the backdrop through.
        self.setAttribute(Qt.WA_OpaquePaintEvent, view_ground_is_opaque())

    # -- data ----------------------------------------------------------------

    def load_document(self, document) -> None:
        self.refresh_points(document)
        self.current_time = float(self.timing_points[0].time if self.timing_points else 0)
        self.update()

    def refresh_points(self, document) -> None:
        """Re-read timing points after an edit, without resetting the cursor."""
        if self.point_times_for is not None:
            self.point_times = self.point_times_for(document)
        self.set_timing_points(document.timing_points)
        # Points deleted elsewhere must not stay "selected" forever.
        live = {point.uid for point in self.timing_points}
        self.selected_uids &= live
        self.update()

    def set_timing_points(self, points) -> None:
        """Adopt a point list (any order) and rebuild the paint caches."""
        self.timing_points = (
            self.sorted_points_for(points) if self.sorted_points_for is not None
            else sorted_by_time(points)
        )
        # Every edit refreshes every gimmick layer, and placing a note changes no
        # timing point at all -- yet each SV layer rebuilt its caches from the
        # whole list: 71ms of a 192ms placement on a 21k-point gimmick map.
        # Skip the rebuild when nothing it reads has changed. The key is the
        # points' own fields rather than an edit counter, because TimingPoint
        # is mutable and edited in place (set_kiai, set_sv, drags), and a
        # counter some path forgot to bump would leave a layer silently stale.
        # ~2.5ms to build at that size, against ~18ms per layer skipped.
        #
        # A changed point count cannot match, so it rebuilds without paying for
        # the key: building it anyway made every fake slider placement -- which
        # always inserts points -- 23ms slower than no skip at all. The key is
        # then built on the next same-length refresh, costing one rebuild there.
        if len(self.timing_points) != self._cache_len:
            self._cache_len = len(self.timing_points)
            self._cache_key = None
        else:
            key = (
                [
                    (p.uid, p.time, p.beat_length, p.uninherited_flag, p.volume, p.effects, p.meter)
                    for p in self.timing_points
                ],
                None if self.point_times is None else frozenset(self.point_times),
                self.volume_mode, self.show_bpm_labels, self.autoscale,
            )
            if key == self._cache_key:
                return
            self._cache_key = key
        if self.kiai_bands_for is not None:
            self.kiai_bands = self.kiai_bands_for(self.timing_points)
        else:
            self.set_kiai_from(self.timing_points)
        self._rebuild_caches()

    def _rebuild_caches(self) -> None:
        """Per-timestamp series and line colours, computed once per edit.

        These used to be rebuilt from every point on every paint -- three full
        passes per frame, per open view, at the playback frame rate. On an
        ordinary map that is invisible; on a gimmick map carrying tens of
        thousands of timing points it is the difference between scrolling and
        a frozen window.
        """
        self._visible_points = (
            self.timing_points if self.point_times is None
            else [
                point for point in self.timing_points
                if not point.uninherited and round(point.time) in self.point_times
            ]
        )
        # Only one of these two series is ever read -- `_draw_sv_curve` picks
        # `_volume_series` in volume_mode and `_series` otherwise, and
        # `volume_mode` is set once at construction and never toggled, so the
        # other one is dead weight on every refresh. Same reasoning as
        # `_bpm_at` below: built only where it is read. `sv_series()` (test
        # only) returns `[]` on a volume_mode view as a result -- it was never
        # meaningful there anyway.
        kinds: dict[float, set[bool]] = {}
        if self.volume_mode:
            self._series, self._series_times = [], []
            # Effective volume: unlike SV, every point (red or green) carries
            # its own value and none of them reset it, so this is a plain
            # last-in-file-order-wins fold over the same points, iterated in
            # `self.timing_points`' sorted (stable) order.
            by_time_volume: dict[float, float] = {}
            for point in self._visible_points:
                kinds.setdefault(point.time, set()).add(point.uninherited)
                by_time_volume[point.time] = float(point.volume)
            self._volume_series = sorted(by_time_volume.items())
            self._volume_series_times = [time_ms for time_ms, _volume in self._volume_series]
        else:
            self._volume_series, self._volume_series_times = [], []
            by_time: dict[float, float] = {}
            for point in self._visible_points:
                kinds.setdefault(point.time, set()).add(point.uninherited)
                if point.uninherited and point.time in by_time:
                    # An inherited point already claimed this millisecond; a red
                    # line stacked with a green one does not reset it back to 1.0x.
                    continue
                by_time[point.time] = point.sv_multiplier
            self._series = sorted(by_time.items())
            self._series_times = [time_ms for time_ms, _sv in self._series]
        # Keyed by the point's exact time, not by a rounded millisecond: this
        # is where the line is *drawn*, and a point at 4845.4 rounded to 4845
        # drew half a millisecond away from the note it belongs to -- invisible
        # at chart zoom, a third of the view at the 20ms floor, which is where
        # gimmick work happens. Rounding also merged two points half a
        # millisecond apart into one line.
        self._line_kinds = {
            time_ms: "yellow" if len(flags) > 1 else "red" if True in flags else "green"
            for time_ms, flags in kinds.items()
        }
        self._line_kind_times = sorted(self._line_kinds)
        # Only built where it is read, and reading `.bpm` once per point
        # rather than twice: it is a division behind a property, this runs for
        # every point in every SV view on every refresh, and a gimmick map
        # carries tens of thousands of them. The label pass is the only
        # consumer, so a view that does not draw labels does not pay for it.
        self._bpm_at = {}
        if self.show_bpm_labels:
            for point in self.timing_points:
                if not point.uninherited:
                    continue
                bpm = point.bpm
                if bpm:
                    self._bpm_at[point.time] = bpm
        # The red lines on their own. active_uninherited_at steps back over
        # inherited points one at a time, and this view's whole subject matter
        # is maps with thousands of them between two red lines -- asking it
        # against the full list, once per curve segment per frame, was the SV
        # editor's entire paint cost.
        self._beat_points = (
            self.uninherited_points_for(self.timing_points) if self.uninherited_points_for is not None
            else uninherited_points(self.timing_points)
        )
        # Their times alone, so _draw_sv_curve can tell when its walk leaves
        # the current section with one C-level bisect instead of asking
        # active_timing again for every segment.
        self._beat_times = [point.time for point in self._beat_points]
        if self.volume_mode:
            # Volume is a plain 0-100% scale, never the log SV ladder -- set
            # here too (not only in update_scale) so a mouse handler that
            # reads scale_min/max between paints never sees a stale SV range.
            self.scale_min, self.scale_max = 0.0, 100.0
        elif self.autoscale:
            # The ceiling follows the whole document, not the visible window: a
            # bound refitted per frame moved every time a fast point crossed
            # the view edge, which read as the graph flickering while scrolling.
            highest = max((sv for _time_ms, sv in self._series), default=1.0)
            self.scale_max = max(SV_VISUAL_MAX, sv_bound_above(highest))

    def set_snap_divisor(self, divisor: int) -> None:
        self.snap_divisor = divisor
        self.update()

    def set_tool(self, tool: str) -> None:
        self.tool = tool
        self.update()  # the green line ghost; see TimelineGameplay.set_tool

    def line_kinds(self) -> dict[float, str]:
        """{millisecond: "red" | "green" | "yellow"} for the vertical lines, cached per edit.

        One entry per *timestamp*, not per point. Painting one line per point
        meant an uninherited and an inherited point sharing a millisecond drew
        over each other and file order picked the winner, so a BPM line with
        SV stacked on it rendered green -- indistinguishable from a plain SV
        point. Same convention as TimingOverviewBar's markers: yellow means
        both kinds are here.
        """
        return self._line_kinds

    def selected_points(self) -> list[TimingPoint]:
        """Selected inherited points in time order, for copy and for Delete."""
        return sorted(
            (point for point in self.timing_points if point.uid in self.selected_uids),
            key=lambda point: (point.time, point.uid),
        )

    # -- SV <-> vertical position ----------------------------------------------

    def _margin_scale(self) -> float:
        """How much of the designed margins this view's height can afford.

        The margins hold the axis labels and the BPM text, and at DESIGN_HEIGHT
        they cost 56 of 180 pixels. Kept at that on a gimmick band -- a third of
        its height -- they left the curve confined to the middle of the view.
        """
        return min(1.0, self.height() / self.DESIGN_HEIGHT)

    def _graph_top(self) -> float:
        return 20.0 * self._margin_scale()

    def _graph_bottom(self) -> float:
        return self.height() - 36.0 * self._margin_scale()

    def _sv_to_y(self, sv: float, top: float, bottom: float) -> float:
        low, high = self.scale_min, self.scale_max
        clamped = max(low, min(high, sv))
        if self.volume_mode:
            # Linear 0-100%, not log SV -- math.log(0) would crash here, and a
            # log scale has no meaning for a volume percentage anyway.
            ratio = (clamped - low) / (high - low)
        else:
            ratio = (math.log(clamped) - math.log(low)) / (math.log(high) - math.log(low))
        return bottom - ratio * (bottom - top)

    def _y_to_sv(self, y: float, top: float, bottom: float) -> float:
        """The SV under `y`, which is **not** bounded by the drawn axis.

        SV_VISUAL_MIN/MAX are a *drawing* bound -- the floor is fixed so one
        0.05x stop does not squash a whole map into the top of the graph. The
        values a green line may hold are SV_SCALE_FLOOR..SV_SCALE_CEILING.
        Clamping to the graph made the bottom pixel 0.1x, so everything down
        to 0.01x was unreachable by dragging, and mirrored it at the top: the
        ceiling autoscales to the map's own maximum, so no drag could ever
        make a point faster than the fastest one already there. Drag past
        either edge and the log scale carries on to the real limit.

        Volume is the exception: 0-100% is the whole range, not a window on
        one, so there is nothing outside it to reach.
        """
        low, high = self.scale_min, self.scale_max
        ratio = (bottom - y) / max(1.0, bottom - top)
        if self.volume_mode:
            return low + max(0.0, min(1.0, ratio)) * (high - low)
        # Clamped in log space: a cursor thrown far off the widget would
        # otherwise overflow math.exp before anything got to bound it.
        return math.exp(min(math.log(SV_SCALE_CEILING), max(
            math.log(SV_SCALE_FLOOR),
            math.log(low) + ratio * (math.log(high) - math.log(low)))))

    def update_scale(self) -> tuple[float, float]:
        """The current axis. Both bounds are decided per *document*, not per frame.

        * The floor is fixed at SV_VISUAL_MIN. Slow sections are read against
          the same baseline everywhere, and one 0.05x stop no longer squashes a
          whole map's worth of ordinary SV into the top of the graph -- it just
          sits on the ground (_sv_to_y clamps).
        * The ceiling is SV_VISUAL_MAX unless the map exceeds it, in which case
          it rises to the enclosing round value (`sv_bound_above`), set in
          `_rebuild_caches`. Fitting it to the *visible window* instead meant it
          moved every time a fast point crossed the view edge -- the graph
          visibly flickering while scrolling, and the sticky-bound machinery
          that used to damp that was only ever treating the symptom.

        Kept as a method (rather than reading the attribute) because
        `autoscale = False` still has to freeze whatever a caller set by hand.

        In volume_mode the whole SV_BOUND ladder is bypassed: the axis is
        always a fixed 0%-100%, because that is what a volume percentage is.
        """
        if self.volume_mode:
            self.scale_min, self.scale_max = 0.0, 100.0
            return self.scale_min, self.scale_max
        return self.scale_min, self.scale_max

    def sv_series(self) -> list[tuple[float, float]]:
        """[(time, effective SV)], one entry per timestamp, cached per edit.

        A red (uninherited) line resets SV to 1.0x, but only when nothing else
        sits on that millisecond: mappers routinely stack a green line on a red
        one precisely to set the speed the new BPM section starts at, and osu!
        gives the later line in file order the final say. Emitting one entry
        per *point* meant the red line contributed a 1.0x sample the green line
        immediately overwrote, which showed up as a spike down to 1.0x at every
        BPM change that had SV on it.
        """
        return self._series

    def _nearest_inherited(self, x: float, radius_px: float = 20.0) -> TimingPoint | None:
        # Hit-testing follows what is drawn, or a filtered layer would grab and
        # edit a point it never showed.
        #
        # `<=` on the tie, not `<`: two green lines can share one exact
        # millisecond -- a converter's own SV stacked on the chart's, kept
        # rather than deduped so the layer has no gaps -- and `_visible_points`
        # is stable-sorted from insertion order, so the last of an exact tie is
        # the one osu! actually reads. Picking the first instead grabbed and
        # showed the superseded line while the effective one sat under it.
        best = None
        best_distance = None
        for point in self._visible_points:
            if point.uninherited:
                continue
            distance = abs(self.x_for_time(point.time) - x)
            if distance <= radius_px and (best_distance is None or distance <= best_distance):
                best = point
                best_distance = distance
        return best

    def _nearest_point(self, x: float, radius_px: float = 20.0) -> TimingPoint | None:
        """Nearest point of either kind, for select-mode drag-to-retime.

        `<=` on the tie: see `_nearest_inherited` on why the last of an
        exact-millisecond tie is the point actually in force.
        """
        best = None
        best_distance = None
        for point in self._visible_points:
            distance = abs(self.x_for_time(point.time) - x)
            if distance <= radius_px and (best_distance is None or distance <= best_distance):
                best = point
                best_distance = distance
        return best

    def _placement_time(self, x: float) -> float:
        """Where a green line placed at `x` would go.

        In a layer that owns a fixed set of milliseconds (`point_times`), the
        nearest of those rather than the nearest snap division. A green line
        anywhere else in such a layer is invisible in it -- `_rebuild_caches`
        filters on exactly this set -- and gets reset to 1.0x by the next
        uninherited line anyway, which is why placement used to look like it
        did nothing at all.
        """
        if self.point_times:
            return float(min(self.point_times, key=lambda t: abs(self.x_for_time(t) - x)))
        return self.snap_ms(self.time_for_x(x))

    def _dot_position(self, point: TimingPoint) -> QPointF:
        """Screen position of a green point's value dot, for the click-radius
        test that decides whether a drag adjusts SV or retimes the line."""
        return QPointF(
            self.x_for_time(point.time),
            self._sv_to_y(point.sv_multiplier, self._graph_top(), self._graph_bottom()),
        )

    def _drag_axis_for_click(self, point: TimingPoint, pos: QPointF) -> str:
        """"value" (adjust SV) if the click landed on the point's dot, else
        "time" (retime). An uninherited point has no SV, so it is always
        "time" -- see SV_DOT_HIT_RADIUS_PX for the threshold.

        **Always "value" in volume_mode**, dot or no dot. That layer's vertical
        axis is hitsound volume, and its lines belong to the milliseconds they
        sit on -- a barline, a note, a kiai edge. Retiming one there does not
        move a value, it moves the section boundary out from under whatever put
        it there, so the layer offers no horizontal drag at all.
        """
        if self.volume_mode:
            return "value"
        if point.uninherited:
            return "time"
        dot = self._dot_position(point)
        distance = math.hypot(pos.x() - dot.x(), pos.y() - dot.y())
        return "value" if distance <= SV_DOT_HIT_RADIUS_PX else "time"

    # -- mouse -----------------------------------------------------------------

    def mouseDoubleClickEvent(self, event) -> None:
        """Double click any line to retype its SV (or BPM) and its time.

        Reaches red lines too: this view draws both kinds, and a BPM line
        double-clicked here is the same edit the chart layers offer.
        """
        if event.button() != Qt.LeftButton:
            super().mouseDoubleClickEvent(event)
            return
        point = self._nearest_point(event.position().x())
        if point is None:
            super().mouseDoubleClickEvent(event)
            return
        if self.volume_mode:
            # Same rule as the drag above: this layer types a volume, and the
            # generic line dialog would have offered a time field that must not
            # be there.
            self.point_volume_dialog_requested.emit(point.uid)
        else:
            self.timing_line_edit_requested.emit(point.uid)
        event.accept()

    def _begin_point_drag(self, point: TimingPoint, axis: str, press_y: float = 0.0) -> None:
        self._drag_point = point
        self._drag_axis = axis
        # A value drag is relative to where it was pressed -- see
        # SV_DRAG_STEP. Held here because the point is replaced on every edit.
        self._drag_press_y = press_y
        self._drag_start_sv = point.sv_multiplier
        # See mouseMoveEvent: what the last emitted value-drag step was, so a
        # fresh drag does not inherit the previous one's and skip its own
        # first, genuinely-new step. The SV it starts at counts as sent, so a
        # press that never moves emits nothing.
        self._last_drag_value = None if self.volume_mode else self._drag_start_sv
        self.selected_uids = {point.uid}
        self.grabMouse()
        self.update()

    def mousePressEvent(self, event) -> None:
        if event.button() == Qt.RightButton:
            # A drag-selection (function-range or select-mode rubber-band) is
            # live and this press landed on the page's timing bar rather than
            # in the view: scrub the playhead there instead of deleting a
            # point, the same reasoning as TimelineGameplay.mousePressEvent.
            if (self.drag_anchor_time is not None or self.select_anchor_time is not None) and (
                self._press_is_on_timing_bar(event.globalPosition().toPoint())
            ):
                self._bar_scrubbing = True
                self._scrub_bar_to(event.globalPosition().toPoint())
                event.accept()
                return
            point = self._nearest_inherited(event.position().x())
            if point is not None:
                self.point_delete_requested.emit(point.uid)
            event.accept()
            return
        if event.button() != Qt.LeftButton:
            return

        if self.tool in ("function", "kiai", "volume"):
            # Same gesture for all three: drag a range, then the owner decides
            # what to do with it. Kiai and Volume are the Kiai and Sound Volume
            # layer's tools -- see MainWindow._sv_range_action.
            self.drag_start_x = event.position().x()
            self.drag_mouse_x = self.drag_start_x
            self.drag_anchor_time = self.time_for_x(self.drag_start_x)
            self.grabMouse()
            self.update()
            event.accept()
            return

        if self.tool == "green_line":
            # Landing on an existing green line adjusts it (drag its SV) the
            # same way select mode does, instead of stacking a second point
            # on top of it -- one inherited point per millisecond is the rule
            # the owner enforces anyway, so placing here could only ever have
            # replaced what was already there.
            existing = self._nearest_inherited(event.position().x())
            if existing is not None:
                self._begin_point_drag(existing, self._drag_axis_for_click(existing, event.position()),
                                       event.position().y())
                event.accept()
                return
            time_ms = self._placement_time(event.position().x())
            # Quantized like a drag (SV_DRAG_STEP): a placed line otherwise
            # landed at whatever float the pixel mapped to -- 1.2371... -- and
            # the ghost promised a rounder value than the click delivered.
            sv = round(self._y_to_sv(event.position().y(), self._graph_top(), self._graph_bottom())
                       / SV_DRAG_STEP) * SV_DRAG_STEP
            self.point_add_requested.emit(time_ms, sv)
            event.accept()
            return

        # select: click a line (green or red) to select it and drag it. A
        # click on a green line's own value dot adjusts its SV (vertical);
        # anywhere else along the line retimes it (horizontal) instead -- see
        # _drag_axis_for_click. On empty space, start a rubber-band selection
        # over a time range instead -- and clear what was selected, so a
        # plain click deselects.
        point = self._nearest_point(event.position().x())
        if point is not None:
            self._begin_point_drag(point, self._drag_axis_for_click(point, event.position()),
                                   event.position().y())
            event.accept()
            return
        self.selected_uids.clear()
        self.select_anchor_time = self.time_for_x(event.position().x())
        self.select_mouse_x = event.position().x()
        self.grabMouse()
        self.auto_scroll_timer.start()
        self.update()
        event.accept()

    def _update_range_selection(self) -> None:
        if self.select_anchor_time is None:
            return
        a, b = sorted((self.select_anchor_time, self.time_for_x(self.select_mouse_x)))
        self.selected_uids = {
            point.uid
            for point in self._visible_points
            if not point.uninherited and a <= point.time <= b
        }
        self.update()

    def _scrub_bar_to(self, global_pos) -> None:
        """Move the playhead to the timing bar under `global_pos`, and grow
        whichever range drag is currently live to follow it.

        The anchor stays pinned in time -- only `current_time` changes, and
        the view scrolls under it -- so the far edge (`self.time_for_x` of the
        moving side) always reads as the scrub target once the view re-centres
        on it. Only one of `drag_anchor_time` / `select_anchor_time` is ever
        set at a time (function-range mode vs. select mode), so exactly one
        branch here has anything to update.
        """
        self.current_time = self._time_on_timing_bar(global_pos)
        self.seek_requested.emit(self.current_time)
        if self.drag_anchor_time is not None:
            self.drag_mouse_x = self.x_for_time(self.current_time)
            self.update()
        elif self.select_anchor_time is not None:
            self.select_mouse_x = self.x_for_time(self.current_time)
            self._update_range_selection()

    def _auto_scroll_selection(self) -> None:
        """Scroll the view when a rubber-band drag runs past its edges.

        Same acceleration curve as TimelineGameplay's: without it, a selection
        can never be larger than one screenful, since the view stands still
        however far the cursor goes.
        """
        if self.select_anchor_time is None:
            self.auto_scroll_timer.stop()
            return
        if self.auto_scroll_step(self.select_mouse_x):
            self._update_range_selection()

    def mouseMoveEvent(self, event) -> None:
        if self._bar_scrubbing:
            self._scrub_bar_to(event.globalPosition().toPoint())
            return
        if self.drag_anchor_time is not None:
            self.drag_mouse_x = event.position().x()
            self.update()
            return
        if self.select_anchor_time is not None:
            self.select_mouse_x = event.position().x()
            self._update_range_selection()
            return
        if self._drag_point is not None:
            if self._drag_axis == "value":
                if self.volume_mode:
                    # _y_to_sv is linear 0-100 here (see update_scale), so the
                    # number already is a volume percentage -- already coarse
                    # enough (100 steps) that the SV_DRAG_STEP problem below
                    # barely reaches it, but the same skip is free to apply.
                    value = round(self._y_to_sv(
                        event.position().y(), self._graph_top(), self._graph_bottom()))
                else:
                    # One SV_DRAG_STEP per pixel from the press, not the log
                    # axis under the cursor: a pixel of that axis is 0.03x at
                    # 1.0x and more above it, so an absolute drag skipped most
                    # of the steps it was rounded to.
                    moved = round(self._drag_press_y - event.position().y())
                    # Unmoved, the typed 8-decimal value stays as it was
                    # rather than being snapped to 0.01 by a jittery click.
                    value = self._drag_start_sv if moved == 0 else round(max(
                        SV_SCALE_FLOOR, min(SV_SCALE_CEILING, (round(
                            self._drag_start_sv / SV_DRAG_STEP) + moved) * SV_DRAG_STEP)), 2)
                # A mouse delivers far more move events than this many steps
                # actually exist across a typical drag range -- most of them
                # would otherwise ask for the exact value already in force.
                # See SV_DRAG_STEP for what skipping that costs elsewhere.
                if value != self._last_drag_value:
                    self._last_drag_value = value
                    if self.volume_mode:
                        self.point_volume_edit_requested.emit(self._drag_point.uid, int(value))
                    else:
                        self.point_sv_edit_requested.emit(self._drag_point.uid, value)
            else:
                # Same rule as placement: in a layer keyed to its own objects,
                # a line dragged between them would vanish from the layer that
                # was dragging it.
                self.point_time_edit_requested.emit(
                    self._drag_point.uid, self._placement_time(event.position().x())
                )
            self.update()
            return
        # Ghost preview: only green-line mode has something to preview, but
        # the cursor millisecond is drawn in every mode -- see
        # TimelineGameplay.mouseMoveEvent for why the repaint is unconditional.
        self._hover_time = self.time_for_x(event.position().x())
        self._hover_sv = round(self._y_to_sv(event.position().y(), self._graph_top(), self._graph_bottom())
                               / SV_DRAG_STEP) * SV_DRAG_STEP
        self.update()

    def leaveEvent(self, event) -> None:
        """See TimelineGameplay.leaveEvent."""
        self._hover_time = None
        self._hover_sv = None
        super().leaveEvent(event)
        self.update()

    def mouseReleaseEvent(self, event) -> None:
        if event.button() == Qt.RightButton:
            # A right release only ever matters here as the end of a
            # bar-scrub (see mousePressEvent above) -- it must never fall
            # through to the generic release logic below, which would end
            # whatever drag a left button is still holding open.
            self._bar_scrubbing = False
            event.accept()
            return
        if self.drag_anchor_time is not None:
            self.releaseMouse()
            a, b = sorted((self.drag_anchor_time, self.time_for_x(self.drag_mouse_x)))
            if self.tool == "kiai":
                # A kiai section starts and ends on the grid the mapper is
                # looking at, not on whatever fraction of a millisecond the
                # cursor happened to be over -- and `snap_ms` is also where
                # Ctrl means "whole milliseconds instead", which is the
                # override this tool needs for sections that dodge a line.
                a, b = self.snap_ms(a), self.snap_ms(b)
            self.drag_start_x = None
            self.drag_anchor_time = None
            self.update()
            if b - a >= 1.0:
                self.function_range_requested.emit(max(0.0, a), max(0.0, b))
            return
        if self.select_anchor_time is not None:
            self.auto_scroll_timer.stop()
            self.releaseMouse()
            self.select_anchor_time = None
            self.update()
            return
        if self._drag_point is not None:
            self.releaseMouse()
            self._drag_point = None

    # -- keyboard --------------------------------------------------------------

    def keyPressEvent(self, event) -> None:
        if event.key() == Qt.Key_Escape:
            # See TimelineGameplay.keyPressEvent: an Esc with nothing selected
            # is the window's, for leaving the editor.
            if self.selected_uids:
                self.selected_uids.clear()
                self.update()
                event.accept()
                return
            super().keyPressEvent(event)
            return

        if event.key() in (Qt.Key_Delete, Qt.Key_Backspace):
            if self.selected_uids:
                self.points_delete_requested.emit([point.uid for point in self.selected_points()])
            event.accept()
            return

        if event.matches(QKeySequence.StandardKey.SelectAll):
            start_time = self.current_time - self.window_ms / 2
            end_time = self.current_time + self.window_ms / 2
            self.selected_uids = {
                point.uid
                for point in self._visible_points
                if not point.uninherited and start_time <= point.time <= end_time
            }
            self.update()
            event.accept()
            return

        super().keyPressEvent(event)

    # -- paint -------------------------------------------------------------

    def paintEvent(self, event) -> None:
        painter = QPainter(self)
        painter.fillRect(self.rect(), view_ground("#151b24"))
        self.draw_kiai_bands(painter)
        painter.setRenderHint(QPainter.Antialiasing, True)

        top = self._graph_top()
        bottom = self._graph_bottom()
        start_time = self.current_time - self.window_ms / 2
        end_time = self.current_time + self.window_ms / 2
        self.update_scale()

        for anchor, mouse_x in (
            (self.drag_anchor_time, self.drag_mouse_x),
            (self.select_anchor_time, self.select_mouse_x),
        ):
            if anchor is None:
                continue
            anchor_x = self.x_for_time(anchor)
            current_x = max(0.0, min(float(self.width()), mouse_x))
            left, width = min(anchor_x, current_x), abs(current_x - anchor_x)
            painter.fillRect(QRectF(left, 0, width, self.height()), self.range_brush)

        painter.setPen(QPen(theme.color("#3a4554"), 1))
        painter.drawLine(0, int(bottom), self.width(), int(bottom))
        self._draw_scale_guides(painter, top, bottom)

        pens = {"red": self.red_pen, "green": self.green_pen, "yellow": self.yellow_pen}
        # Only scanned when something is actually selected: during playback --
        # the case that has to stay cheap on a map with thousands of points --
        # nothing is.
        selected_times = (
            {point.time for point in self.timing_points if point.uid in self.selected_uids}
            if self.selected_uids
            else frozenset()
        )

        # Slice to the window rather than testing every timestamp for
        # visibility: a gimmick map has tens of thousands, and this runs at the
        # playback frame rate in every open SV view.
        first = bisect_left(self._line_kind_times, start_time - self.window_ms * 0.1)
        after_last = bisect_right(self._line_kind_times, end_time + self.window_ms * 0.1)
        # A barline gimmick stacks thousands of lines within one window, most of
        # them on the same pixel column: skip a repeat of the same kind at the
        # same x, and space the BPM labels like the SV ones already are.
        last_drawn: tuple[int, str] | None = None
        previous_x = -1e9
        for time_ms in self._line_kind_times[first:after_last]:
            kind = self._line_kinds[time_ms]
            x = self.x_for_time(time_ms)
            if x < -80 or x > self.width() + 80:
                continue
            selected = time_ms in selected_times
            clear_of_previous = x - previous_x >= SV_LABEL_MIN_SPACING_PX
            previous_x = x
            if not selected and last_drawn == (round(x), kind):
                continue
            last_drawn = (round(x), kind)
            if selected:
                painter.setPen(self.selected_pen)
                painter.drawLine(round(x), 0, round(x), self.height())
            painter.setPen(pens[kind])
            painter.drawLine(round(x), 0, round(x), self.height())
            bpm = self._bpm_at.get(time_ms) if self.show_bpm_labels else None
            if bpm and clear_of_previous:
                painter.save()
                painter.setFont(self.label_font)
                painter.setPen(self.label_pen)
                painter.drawText(QPointF(x + 4, self.height() - 6), f"{bpm:.0f} BPM")
                painter.restore()

        self._draw_sv_curve(painter, top, bottom, start_time, end_time)
        self._draw_placement_ghost(painter, top, bottom)
        self.draw_ctrl_precision_line(painter)
        self.draw_cursor_position(painter)

        cursor_x = self.width() // 2
        painter.setPen(self.cursor_pen)
        painter.drawLine(cursor_x, 0, cursor_x, self.height())

    def _draw_scale_guides(self, painter: QPainter, top: float, bottom: float) -> None:
        """Label the autoscaled range, so "high" on the graph means something.

        Without these the curve is unreadable after autoscaling: the same
        shape can be a 0.9x-1.1x wobble or a 1x-8x sweep.
        """
        painter.setPen(QPen(QColor(120, 132, 150, 90), 1, Qt.DotLine))
        painter.drawLine(0, int(top), self.width(), int(top))
        painter.save()
        painter.setFont(self.label_font)
        painter.setPen(self.label_pen)
        if self.volume_mode:
            painter.drawText(QPointF(4, top + 12), f"{self.scale_max:.0f}%")
            painter.drawText(QPointF(4, bottom - 4), f"{self.scale_min:.0f}%")
        else:
            painter.drawText(QPointF(4, top + 12), f"{self.scale_max:.2f}x")
            painter.drawText(QPointF(4, bottom - 4), f"{self.scale_min:.2f}x")
        painter.restore()

    def _draw_sv_curve(
        self, painter: QPainter, top: float, bottom: float, start_time: float, end_time: float,
    ) -> None:
        """The SV line: straight segments from each point to the next.

        SV is physically a step function -- it holds a value until the next
        point -- and drawing that literally, as horizontal runs joined by
        vertical risers, made every generated sweep look like a staircase
        whatever easing produced it. Connecting the points instead lets the
        generating function show in its own output: linear reads straight, sin
        reads as an S, exponential reads as a hockey stick.

        Straight segments, not a smoothed curve. A spline through the points
        invents curvature between them that no stored value justifies, and near
        a sharp SV change it overshoots past values the document does not
        contain. Dots mark the real points, so the line is never mistaken for a
        claim that SV ramps continuously between them.
        """
        # In volume_mode this plots effective volume (carried forward from
        # each point's own .volume, never reset by an uninherited point) --
        # see _rebuild_caches -- rather than effective SV. Same step/diagonal
        # drawing rules either way: a volume sweep generated by the Volume
        # tool (2d) is eased between existing points exactly like an SV sweep,
        # so the same visual makes the easing shape readable.
        series = self._volume_series if self.volume_mode else self._series
        series_times = self._volume_series_times if self.volume_mode else self._series_times
        if not series:
            return

        # Sliced by bisect, not by filtering the whole series three times: this
        # runs per frame per view, and a gimmick map carries tens of thousands
        # of points.
        margin = self.window_ms * 0.1
        first = bisect_left(series_times, start_time - margin)
        after_last = bisect_right(series_times, end_time + margin)
        # Anchor to the neighbours just outside the window, or the curve would
        # start and end abruptly at the view edges as it scrolls.
        visible = series[max(0, first - 1):min(len(series), after_last + 1)]
        if not visible:
            return

        points = [QPointF(self.x_for_time(t), self._sv_to_y(sv, top, bottom)) for t, sv in visible]

        painter.setPen(self.graph_pen)
        if len(points) == 1:
            painter.drawLine(QPointF(0.0, points[0].y()), QPointF(float(self.width()), points[0].y()))
        else:
            # Beyond the outermost points there is nothing to interpolate
            # toward, so the line runs flat out to the view edges.
            painter.drawLine(QPointF(0.0, points[0].y()), points[0])
            painter.drawLine(points[-1], QPointF(float(self.width()), points[-1].y()))
            # A gap of at least two whole beats between consecutive points
            # isn't a ramp the document defined -- SV physically holds its
            # value until the next point, so draw that literally (flat, then
            # a riser) instead of a diagonal implying a gradual change.
            # Closer points keep the diagonal, which is what makes a
            # generated sweep's easing shape (linear/sin/exponential/...)
            # readable in the first place.
            # `visible` is time-ordered, so the beat section only moves
            # forward -- but this asked active_timing for every single
            # segment, which profiling caught at 219 lookups per frame across
            # the gimmick page's SV bands, each one a binary search plus a
            # backward walk. Hold the section until the walk leaves it.
            beat_length = 0.0
            section_expires = -math.inf
            for i in range(1, len(points)):
                prev_point, point = points[i - 1], points[i]
                prev_time, time = visible[i - 1][0], visible[i][0]
                if prev_time >= section_expires:
                    beat_length = active_timing(self._beat_points, prev_time).beat_length
                    following = bisect_right(self._beat_times, prev_time)
                    section_expires = (
                        self._beat_times[following]
                        if following < len(self._beat_times)
                        else math.inf
                    )
                if time - prev_time >= 2 * beat_length:
                    painter.drawLine(prev_point, QPointF(point.x(), prev_point.y()))
                    painter.drawLine(QPointF(point.x(), prev_point.y()), point)
                else:
                    painter.drawLine(prev_point, point)

        painter.setBrush(QColor(140, 255, 185, 200))
        painter.setPen(Qt.NoPen)
        for point in points:
            if -20 <= point.x() <= self.width() + 20:
                painter.drawEllipse(point, 2.5, 2.5)

        # One label per point is unreadable once a sweep is dense -- the text
        # overlaps into a smear and costs a drawText per point per frame. Label
        # only a point that stands clear of its *predecessor*, which is a
        # property of the pair: chaining from the last label instead made which
        # points got labelled depend on where the window happened to start, so
        # they blinked on and off as the view scrolled.
        painter.save()
        painter.setFont(self.label_font)
        painter.setPen(self.value_pen)
        ascent = painter.fontMetrics().ascent()
        for i, (point, (_time_ms, sv)) in enumerate(zip(points, visible)):
            if not 0 <= point.x() <= self.width():
                continue
            if i and point.x() - points[i - 1].x() < SV_LABEL_MIN_SPACING_PX:
                continue
            label = f"{sv:.0f}%" if self.volume_mode else f"{sv:.2f}x"
            painter.drawText(QPointF(point.x() + 3, self._label_baseline(point.y(), ascent)), label)
        painter.restore()

    def _draw_placement_ghost(self, painter: QPainter, top: float, bottom: float) -> None:
        """Dashed preview of the green line a click would place, at the snapped
        time and the SV the cursor's height maps to -- the SV editor's
        equivalent of the chart view's translucent note ghost.
        """
        if self.tool != "green_line" or self._hover_time is None:
            return
        snapped = self._placement_time(self.x_for_time(self._hover_time))
        x = self.x_for_time(snapped)
        if x < -40 or x > self.width() + 40:
            return
        painter.setPen(self.ghost_pen)
        painter.drawLine(round(x), 0, round(x), self.height())
        if self._hover_sv is not None:
            y = self._sv_to_y(self._hover_sv, top, bottom)
            painter.setBrush(QColor(140, 255, 185, 130))
            painter.setPen(Qt.NoPen)
            painter.drawEllipse(QPointF(x, y), 4, 4)
            painter.save()
            painter.setFont(self.label_font)
            painter.setPen(self.value_pen)
            painter.drawText(
                QPointF(x + 6, self._label_baseline(y, painter.fontMetrics().ascent(), 6)),
                f"{self._hover_sv:.2f}x")
            painter.restore()

    @staticmethod
    def _label_baseline(y: float, ascent: int, gap: float = 4) -> float:
        """Above the point, unless that runs off the top of the view.

        The graph's top margin is 20px scaled by the band's height -- about 7px
        on a gimmick band -- so a point at the top of the range (100% volume,
        the highest SV) put its label's ascent above y=0 and cut it off. Below
        the point it reads just as well.
        """
        if y - gap - ascent >= 0:
            return y - gap
        return y + gap + ascent


# Screen distance one whole beat covers at 1.0x SV. osu!taiko's scroll speed is
# proportional to BPM x SV, so a beat occupies the same distance at every BPM --
# which is what makes this a constant rather than a function of beat length.
# Object sizes, taken from osu!taiko rather than chosen. `TaikoHitObject
# .DEFAULT_SIZE = 0.475f` is a fraction of the playfield height (its
# `BASE_HEIGHT` is 200), so a note's diameter is 0.475 of the lane and its
# radius half of that. What was here before -- `min(30.0, height * 0.19)` --
# was both too small and capped at a pixel count, so the notes stopped growing
# with the view and the proportions drifted further the taller it got.
TAIKO_NOTE_SIZE = 0.475
# `TaikoStrongableHitObject.STRONG_SCALE = 1 / 0.65f`, i.e. a finisher is about
# 1.538x a normal note, not the 1.4x assumed here before.
TAIKO_STRONG_SCALE = 1.0 / 0.65
# The editor timeline's own finisher ratio: a normal note is 75% of a big one.
# Deliberately not the ruleset's 1.538x (which is 65%) -- see
# `TimelineGameplay.note_radii`. Between the two: far enough apart that a
# finisher reads as one at a glance, close enough that the normal note does not
# have to shrink for it. The gameplay preview and the gimmick bands are
# unaffected and keep the ruleset's own number.
EDITOR_STRONG_SCALE = 1.0 / 0.75


# --- Playfield geometry, in osu!'s own units --------------------------------
# `TaikoPlayfield.BASE_HEIGHT = 200`, and every playfield element in the
# skinning wiki is sized against that same 200: the bar is 1024x200, the
# barline 4x175, the scrolling background 776x162. So
# this view's height *is* the 200, and each fraction below is the wiki's number
# over 200 -- which is also what keeps the note at `TAIKO_NOTE_SIZE` of the
# height without the two systems disagreeing.
PLAYFIELD_UNIT = 200.0
# taiko-barline, 4x175, centred on the bar.
PLAYFIELD_BARLINE_WIDTH = 4.0 / PLAYFIELD_UNIT
PLAYFIELD_BARLINE_HEIGHT = 175.0 / PLAYFIELD_UNIT

# One osu!stable gamefield unit (a 480-tall screen), as a fraction of the
# playfield height. The playfield is BASE_HEIGHT 200 of lazer's 768-tall screen
# (`TaikoPlayfieldAdjustmentContainer`), so a stable unit is 768/480/200 of it.
# Horizontal scroll and the visible range are stable units in osu!'s own code,
# so this is what ties them to the view height the notes are already sized by.
STABLE_UNIT_PER_PLAYFIELD = 768.0 / 480.0 / PLAYFIELD_UNIT
# The hit target's centre, in playfield units from the left edge: the right
# area is padded by INPUT_DRUM_WIDTH (180), and the hit target is a 200-wide
# container at X = -24 in it (`TaikoPlayfield`). 256 playfield units is exactly
# the 160 stable units `ComputeTimeRange` measures from, so the two agree.
GAMEPLAY_HIT_X_UNITS = 180.0 - 24.0 + 200.0 / 2.0
# The input drum, ppy/osu `TaikoPlayfield.INPUT_DRUM_WIDTH`, drawn only by the
# autoplay. Its pieces as `LegacyInputDrum` places them, in playfield units:
# (half, element, x, y, mirrored), with halves numbered 1 left kat, 2 left
# don, 3 right don, 4 right kat. Stable's offsets are 480-space, hence 1.6.
INPUT_DRUM_WIDTH = 180.0
_RIGHT_HALF_X = INPUT_DRUM_WIDTH - (INPUT_DRUM_WIDTH / 1.6 - 56) * 1.6
DRUM_LAYOUT = (
    (2, "taiko-drum-inner", 0.0, 0.0, False),
    (1, "taiko-drum-outer", 0.0, 0.0, True),
    (3, "taiko-drum-inner", _RIGHT_HALF_X, 0.0, True),
    (4, "taiko-drum-outer", _RIGHT_HALF_X, 0.0, False),
)
DRUM_LAYOUT_PRE_2_1 = (
    (2, "taiko-drum-inner", 18 * 1.6, 31 * 1.6, False),
    (1, "taiko-drum-outer", 8 * 1.6, 23 * 1.6, True),
    (3, "taiko-drum-inner", INPUT_DRUM_WIDTH - (INPUT_DRUM_WIDTH / 1.6 - 54) * 1.6, 31 * 1.6, True),
    (4, "taiko-drum-outer", INPUT_DRUM_WIDTH - (INPUT_DRUM_WIDTH / 1.6 - 53) * 1.6, 23 * 1.6, False),
)
# LegacyHalfDrum's press: `FadeTo(1, 80 * (1 - Alpha)).Delay(100)
# .FadeOut(50)`. osu-framework's Delay counts from the *start* of the
# sequence, not the end of the fade before it, so the half goes dark at 100ms
# and is gone at 150ms. Read as consecutive steps it held for 230ms.
DRUM_HIT_DOWN_MS = 80.0
DRUM_HIT_OUT_AT_MS = 100.0
DRUM_HIT_UP_MS = 50.0
DRUM_HIT_LIT_MS = DRUM_HIT_OUT_AT_MS + DRUM_HIT_UP_MS


def _drum_hit_alpha(since: float, start: float) -> float:
    """A drum half `since` ms after a hit that found it at alpha `start`."""
    if since < 0.0 or since >= DRUM_HIT_LIT_MS:
        return 0.0
    if since >= DRUM_HIT_OUT_AT_MS:
        return 1.0 - (since - DRUM_HIT_OUT_AT_MS) / DRUM_HIT_UP_MS
    fade_in = DRUM_HIT_DOWN_MS * (1.0 - start)
    if since >= fade_in:
        return 1.0
    t = since / fade_in
    return start + (1.0 - start) * (1.0 - (1.0 - t) ** 2)
# LegacyKiaiGlow.
KIAI_GLOW_IN_MS = 100.0
KIAI_GLOW_OUT_MS = 600.0
KIAI_GLOW_SCALE = 0.8  # TaikoLegacyHitTarget.SCALE
HIT_TARGET_NOTE_ALPHA = 0.22  # its taikobigcircle
# Its approachcircle: `SCALE + 0.03` of the art's own size, not fitted to the
# note. Fitting it was wrong both ways (owner, 2026-10-11): by canvas, a ring
# drawn on a 192px canvas came out a different size from one on 128; by
# visible ink, riun's soft rainbow glow counted as ring and the line inside it
# landed smaller than the note.
HIT_TARGET_RING_SCALE = KIAI_GLOW_SCALE + 0.03
KIAI_GLOW_KICK = 0.15
KIAI_GLOW_KICK_MS = 80.0
KIAI_GLOW_COLOR = QColor(255, 228, 0)
# Scroll distance per beat at 1.0x SV, in stable units:
# `100 * SliderMultiplier * VELOCITY_MULTIPLIER(1.4)`. `_scroll_scale` already
# carries SliderMultiplier / SLIDER_MULTIPLIER_ASSUMED, so the assumed value is
# folded back in here and the product is osu!'s number.
GAMEPLAY_STABLE_UNITS_PER_BEAT = 100.0 * 1.4 * SLIDER_MULTIPLIER_ASSUMED
# osu!lazer's `LockPlayfieldAspectRange` (on by default) clamps the screen
# aspect it computes the visible time from to at most 16:9: a wider screen
# makes the playfield taller rather than showing more of the chart. So a view
# wider than that has a right edge past which osu! shows nothing, and the
# preview dims it. False is osu!stable's (and lazer-unlocked's) behaviour, where
# a wider screen simply shows more -- one switch, pending the owner's call.
GAMEPLAY_MAX_ASPECT = 16.0 / 9.0
GAMEPLAY_LOCK_ASPECT = True
# The gameplay preview's height floor, below which a note is too small to read.
GAMEPLAY_MIN_HEIGHT = 170


def osu_screen_height_for(width: int) -> int:
    """The preview height at which `width` is exactly a 16:9 osu! screen:
    the screen is 480 stable units high and 16/9 of that wide, and the view's
    height is the playfield's 200 units (`STABLE_UNIT_PER_PLAYFIELD`)."""
    screen_width_per_height = STABLE_UNIT_PER_PLAYFIELD * 480.0 * GAMEPLAY_MAX_ASPECT
    return max(GAMEPLAY_MIN_HEIGHT, round(width / screen_width_per_height))

# --- Mods, from ppy/osu's own TaikoMod* (read 2026-09-24) ------------------
# Every string that lists mods uses this order, which is osu!'s: HD, the rate
# mod, HR/EZ, FL -- "HDNCHR", never "NCHDHR".
MOD_ORDER = ("HD", "NC", "DT", "DC", "HT", "HR", "EZ", "FL")
# Rate mods: (song rate, whether the song's pitch moves with it). DT/HT are
# osu!'s AdjustableProperty.Tempo (pitch kept, the same WSOLA the speed buttons
# use); NC/DC are Frequency (resampled, the song's pitch follows the rate). The
# hitsounds keep their own pitch under all four -- the owner's call.
RATE_MODS = {"NC": (1.5, True), "DT": (1.5, False), "DC": (0.75, True), "HT": (0.75, False)}
SCROLL_MODS = ("HR", "EZ")
# TaikoModEasy / TaikoModHardRock multiply the map's SliderMultiplier, so the
# scroll speed and every drumroll's length change together, as in game.
MOD_SLIDER_MULTIPLIER = {"EZ": 0.8, "HR": 1.4 * 4.0 / 3.0}
# TaikoModHidden: a hit starts fading when it is a full scroll length out
# (fade_out_start_time 1) and is gone 0.375 of that length later. Hits only:
# drumrolls and swells are not in its list and stay visible.
HD_FADE_START = 1.0
HD_FADE_DURATION = 0.375
# TaikoModFlashlight: a circle of radius 200 playfield units (the playfield's
# height), black by 1.4x that (`CircularFlashlight`'s smoothstep, smoothness
# 1.4). Centred at stable (208, 208): `new Vector2(208 * 1.6 * Scale.X)` sets
# both axes. The playfield's top is at stable y 135
# (`TaikoPlayfieldAdjustmentContainer.Y = 135 / 480`), so the centre sits
# slightly right of the hit target and slightly below the lane's middle.
# Not modelled: the 2.5x it opens to during a break (breaks are not parsed).
FL_RADIUS_UNITS = 200.0
FL_SMOOTHNESS = 1.4
FL_CENTRE_STABLE = 208.0
FL_PLAYFIELD_TOP_STABLE = 135.0


# The pill row's layout, and only that: scroll, visibility, rate.
MOD_PILL_GROUPS = (("HR", "EZ"), ("HD", "FL"), ("DT", "NC", "HT", "DC"))
# Hard-coded, like the note colours: a mod is the same colour in every theme,
# and none of these is a pink-palette key `theme` would move. Red and green
# are osu!'s own mod-select colours (DifficultyIncrease / Reduction).
MOD_COLORS = {
    "HD": "#ffc801", "FL": "#85858f", "HR": "#fe6465",
    "DT": "#8c65ff", "NC": "#5b5fe0",
    "EZ": "#b0ff65", "HT": "#b0ff65", "DC": "#b0ff65",
}
# A mod switched on fills with its colour, except where white on that colour
# cannot be read (owner, 2026-10-08): osu!'s green is 1.2:1 against white, so
# a lit EZ/HT/DC fills with the same green darkened to 4.6:1. Off, the pill
# keeps osu!'s own green tint.
MOD_FILLS = {"EZ": "#4a8413", "HT": "#4a8413", "DC": "#4a8413"}
# FL was #2c2c30, which against the ground is no colour at all: it is light
# gray now, and that old gray is what a hover shows (owner, 2026-10-08).
MOD_HOVERS = {"FL": "#2c2c30"}


def mod_pill_style(mod: str) -> str:
    """One mod pill: tinted with its colour while off, filled with it while on.
    White text both ways (owner's call). Set on the button itself, so it wins
    over the segment's shared pink `:checked`."""
    colour = MOD_COLORS[mod]
    # The segment's own ground, as the active theme draws it, so the tint
    # sits on the same colour in every theme.
    base = theme.color("#252d39")
    own = QColor(colour)
    def mix(amount: float) -> str:
        return QColor(
            round(base.red() + (own.red() - base.red()) * amount),
            round(base.green() + (own.green() - base.green()) * amount),
            round(base.blue() + (own.blue() - base.blue()) * amount),
        ).name()
    return (
        f"QPushButton {{ background: {mix(0.16)}; color: #ffffff;"
        f" border-bottom: 2px solid {mix(0.7)}; }}"
        f"QPushButton:hover {{ background: {MOD_HOVERS.get(mod) or mix(0.32)}; color: #ffffff; }}"
        f"QPushButton:checked {{ background: {MOD_FILLS.get(mod, colour)}; color: #ffffff; font-weight: 700;"
        " border-bottom: 2px solid #ffffff; }"
    )


def mod_string(mods) -> str:
    """`mods` as osu! writes them: "HDDT", in MOD_ORDER, "" for none."""
    return "".join(mod for mod in MOD_ORDER if mod in mods)


def flashlight_combo_scale(combo: int) -> float:
    """`ModFlashlight`'s combo scale: smaller from 100 combo and from 200."""
    if combo >= 200:
        return 0.625
    if combo >= 100:
        return 0.8125
    return 1.0
# Cap on how far the visible-note lookup will search either way. A near-zero SV
# section makes one screen cover an unbounded amount of *time*, and scanning a
# whole map for it would cost a frame.
GAMEPLAY_MAX_LOOKAHEAD_MS = 30000.0


class GameplayViewerView(QWidget):
    """M6: read-only preview that scrolls the way osu!taiko does.

    Chart and SV views plot on a *time* axis, where an SV change is invisible
    by construction -- spacing there only ever reflects the clock. Here x is a
    distance integrated from the scroll velocity (`px_per_beat * SV /
    beat_length`), so a 2.0x section really is twice as spread out and a
    generated sweep can be judged without exporting and opening osu!.

    Read-only: no tools, no selection, no editing signals. The wheel seeks the
    shared playhead like every other view, and Ctrl+wheel changes the base
    scroll speed -- a property of this preview alone, never of the map.
    """

    seek_requested = Signal(int)

    def __init__(self) -> None:
        super().__init__()
        # paintEvent fills the whole rect; saying so keeps the page's map
        # backdrop out of every per-frame repaint -- while View opacity is
        # 100%, which is what `view_ground_is_opaque` says.
        self.setAttribute(Qt.WA_OpaquePaintEvent, view_ground_is_opaque())
        self.notes = []
        self.note_times: list[int] = []
        # Predicate deciding which hit objects scroll past; see refresh_notes.
        self.object_filter = None
        # Both kinds, sorted: SV needs the inherited points, the beat grid and
        # barlines need the uninherited ones.
        self.timing_points: list[TimingPoint] = []
        self.beat_points: list[TimingPoint] = []
        self._beat_times: list[float] = []
        # (start_ms, end_ms) kiai sections; see refresh_notes and paintEvent's
        # pulse block. kiai_bands_for lets a host share the cached bands the
        # way other views do -- see MainWindow._share_kiai_bands.
        self.kiai_bands: list[tuple[int, int]] = []
        self.kiai_bands_for = None
        # The map's [Difficulty] SliderMultiplier, until a document is loaded.
        self.slider_multiplier = SLIDER_MULTIPLIER_ASSUMED
        # Scroll velocity in beats per millisecond, one entry per timing-point
        # timestamp, so velocity_at is a binary search instead of a walk.
        self._velocity_times: list[float] = []
        self._velocities: list[float] = []
        self._slowest_velocity = 1.0 / 500.0
        self._max_extend_ms = 0.0
        # Slider/spinner end time by note uid, rebuilt per edit -- see
        # refresh_notes. Circles are simply absent.
        self._end_times: dict[int, float] = {}

        self.current_time = 0.0
        self.snap_divisor = 4
        self.wheel_accumulator = 0.0
        self.last_rendered_time = -1.0
        # The mods in force (see MOD_ORDER). HR/EZ change the map's own
        # SliderMultiplier, so the document is kept to re-derive from.
        self.mods: frozenset[str] = frozenset()
        self._document = None

        self.don_brush = QColor(*DON_COLOR)
        self.kat_brush = QColor(*KAT_COLOR)
        self.slider_brush = QColor(*DRUMROLL_COLOR)
        self.spinner_band_brush = QColor(190, 195, 205, 90)
        self.note_pen = QPen(QColor(15, 18, 24, 220), 2)
        # An osu! skin's own note art, or the built-in drawing when no skin is
        # chosen and for any element a chosen skin does not ship.
        self.skin = TaikoSkin()

        self.barline_pen = QPen(QColor(225, 230, 240, 90), 1)
        self.hit_pen = QPen(QColor(255, 255, 255, 120), 2)
        self.lane_brush = QColor(28, 33, 43)

        self.setMinimumHeight(GAMEPLAY_MIN_HEIGHT)
        self.setFocusPolicy(Qt.StrongFocus)
        # A fraction of the osu!-screen height below, for the song select's
        # smaller preview; None is the whole of it.
        self.height_share: float | None = None
        # Called with the new height whenever resizeEvent sets one.
        self.height_changed = None
        # The song select's preview sits on the detail pane, not on a page
        # backdrop, so Settings > View opacity is not about it.
        self.follows_view_opacity = True
        # The song select's bare stage (owner, 2026-10-08): black, no skin
        # playfield, no cover past osu!'s screen edge, and the hit target
        # nearer the left -- a glance at the chart, not a picture of the game.
        self.plain_stage = False
        # The chart's opacity, apart from the playfield's: song select fades
        # one chart out and the next in (owner, 2026-10-09) while the stage
        # and the hit target stay put. Barlines and notes; never the lane.
        self.chart_opacity = 1.0
        self._chart_fade: QVariantAnimation | None = None
        self._chart_fade_then = None
        self.hit_x_units = GAMEPLAY_HIT_X_UNITS
        # (style, binding, left_handed) while an autoplay plays this preview,
        # else None. Its hits, per drum half (1-4), sorted: see _rebuild_hits.
        self.autoplay: tuple[str, str, bool] | None = None
        self._half_hits: dict[int, list[float]] = {}
        self._all_hits: list[float] = []

    def resizeEvent(self, event) -> None:
        """Take the height that makes this view exactly an osu! screen.

        The playfield's width on a 16:9 screen is 6.83x its height (see
        `osu_screen_height_for`), and a dock is usually much wider than that
        against its height -- 1882x170 is 11:1 -- so the preview showed osu!'s
        screen and then a dark band where osu! shows nothing. Owner's call,
        2026-09-26, against an osu!stable screenshot of the same frame: fit the
        view instead. Height follows width only, so setting it here settles in
        one pass. The floor stays: a panel too narrow for it reads as a
        narrower screen rather than shrinking to nothing.
        """
        super().resizeEvent(event)
        height = osu_screen_height_for(self.width())
        if self.height_share is not None:
            height = round(height * self.height_share)
        if height != self.height():
            self.setFixedHeight(height)
            if self.height_changed is not None:
                self.height_changed(height)

    def fade_chart(self, to: float, duration_ms: int, then=None) -> None:
        """Take `chart_opacity` to `to` over `duration_ms`, eased out, and
        call `then` once it is there. At once under reduced motion."""
        if self._chart_fade is None:
            self._chart_fade = QVariantAnimation(self)
            self._chart_fade.setEasingCurve(QEasingCurve.OutCubic)
            self._chart_fade.valueChanged.connect(self._set_chart_opacity)
            self._chart_fade.finished.connect(lambda: self._chart_fade_then and self._chart_fade_then())
        fade = self._chart_fade
        fade.stop()  # a fade cut short never calls its `then`
        self._chart_fade_then = then
        if reduced_motion() or duration_ms <= 0 or not self.isVisible():
            self._set_chart_opacity(to)
            if then is not None:
                then()
            return
        fade.setStartValue(self.chart_opacity)
        fade.setEndValue(float(to))
        fade.setDuration(duration_ms)
        fade.start()

    def _set_chart_opacity(self, value) -> None:
        self.chart_opacity = float(value)
        self.update()

    # -- document ------------------------------------------------------------

    def load_document(self, document) -> None:
        self.refresh_notes(document)
        self.current_time = float(self.notes[0].time if self.notes else 0)
        self.update()

    def refresh_notes(self, document) -> None:
        # Same predicate TimelineGameplay.object_filter is: the gimmick page's
        # per-layer gameplay previews show one layer's objects scrolling, so a
        # fake slider can be judged without the real chart's notes over it.
        # Timing is never filtered -- it is what moves the notes.
        if self.object_filter is None:
            self.notes = document.hit_objects
        else:
            self.notes = [note for note in document.hit_objects if self.object_filter(note)]
        self.note_times = [note.time for note in self.notes]
        self.timing_points = sorted_by_time(document.timing_points)
        if self.kiai_bands_for is not None:
            self.kiai_bands = self.kiai_bands_for(document)
        else:
            self.kiai_bands = kiai_spans(self.timing_points, KIAI_OPEN_END_MS)
        self._document = document
        self.slider_multiplier = document.slider_multiplier * self._mod_slider_factor()
        self.beat_points = uninherited_points(self.timing_points)
        self._beat_times = [point.time for point in self.beat_points]
        self._rebuild_velocities()
        # End times once per edit, not per note per frame. Every visible note
        # asked for one while painting, and each answer cost two binary searches
        # over the full point list.
        self._max_extend_ms = 0.0
        self._end_times = {}
        self._phantom_ends = {}
        for note in self.notes:
            end = self._compute_end_time(note)
            if end is not None:
                self._end_times[note.uid] = end
                self._max_extend_ms = max(self._max_extend_ms, end - note.time)
                continue
            # A fake slider's body runs *backwards* from its head. Cached in the
            # same pass rather than recomputed while painting, because a shiny
            # note is a stack of twenty of them on one millisecond.
            phantom = self._compute_phantom_end(note)
            if phantom is not None:
                self._phantom_ends[note.uid] = phantom
                # It is drawn forward of its head all the same -- the negative
                # duration becomes a track reaching *right* -- so it widens the
                # slice like any other body. Without this a long one vanished
                # the moment its head left the window, taking a thousand pixels
                # of still-visible track with it.
                self._max_extend_ms = max(
                    self._max_extend_ms, abs(phantom - note.time))
        self._rebuild_hits()
        self.update()

    def set_autoplay(self, setting: tuple[str, str, bool] | None) -> None:
        if setting == self.autoplay:
            return
        self.autoplay = setting
        self._rebuild_hits()
        self.update()

    def _rebuild_hits(self) -> None:
        """Every drum half the autoplay hits and when, once per edit -- a frame
        only bisects these. Rest and break lengths are judged against the
        map's main tempo: a gimmick's 60000 BPM line would make every gap in
        the chart a rest."""
        self._half_hits = {half: [] for half in (1, 2, 3, 4)}
        self._all_hits = []
        if self.autoplay is None or not self.notes:
            return
        style, binding, left = self.autoplay
        circles = [note for note in self.notes if note.is_circle]
        beat = most_common_beat_length(self.timing_points, self.notes[-1].time) or 500.0
        hits = list(zip(
            (float(note.time) for note in circles),
            autoplay.note_halves(
                [(note.time, note.is_kat, note.is_finisher) for note in circles],
                beat, style, binding, left)))
        for note in self.notes:
            if note.is_slider and note.uid in self._end_times:
                hits.extend(autoplay.roll_halves(drumroll_tick_times(
                    note, self.beat_points, self.timing_points, self.slider_multiplier), left))
        hits.sort(key=lambda hit: hit[0])
        for time_ms, halves in hits:
            self._all_hits.append(time_ms)
            for half in halves:
                self._half_hits[half].append(time_ms)

    # Timing points move the notes here (that is the whole point of the view),
    # so an SV edit refreshes exactly like a note edit does.
    refresh_points = refresh_notes

    def set_skin(self, skin: TaikoSkin) -> None:
        self.skin = skin
        self.update()

    def set_snap_divisor(self, divisor: int) -> None:
        self.snap_divisor = divisor

    def set_time(self, time_ms: int, force: bool = False) -> None:
        self.current_time = max(0.0, float(time_ms))
        if force or abs(self.current_time - self.last_rendered_time) >= 16.0:
            self.last_rendered_time = self.current_time
            self.update()

    def _note_end_time(self, note) -> float | None:
        """End time of a slider or spinner; None for a circle."""
        return self._end_times.get(note.uid)

    def _phantom_end_time(self, note) -> float | None:
        """Where a negative-length slider's body would reach, behind its head.

        Only fake sliders have one. See `_compute_phantom_end`.
        """
        return self._phantom_ends.get(note.uid)

    def _compute_phantom_end(self, note) -> float | None:
        """The end time of a fake slider, which is *before* its start.

        A fake slider is a drumroll with a negative `length` -- the canonical
        one is `256,192,54692,2,12,L|624:192,643,-0.0001`. The duration derived
        from it is negative, so the drumroll ends before it begins, no tick is
        ever generated and nothing is hittable, while osu! still draws the head.
        That is the whole trick, and it is why `GimmickConfig.__post_init__`
        rejects a non-negative length instead of clamping it: a positive one is
        a real, scoreable drumroll.

        The negative extent is real geometry, not an error to swallow, so it is
        computed and handed to the painter rather than discarded. Drawn, it
        shows how far behind the head the body reaches -- which is what decides
        whether two stacked fake sliders overlap.
        """
        if not note.is_slider or note.length is None or note.slides is None:
            return None
        timing = active_uninherited_at(self.beat_points, note.time)
        duration = duration_for_slider_length(
            note.length * note.slides, timing.beat_length,
            sv_at(self.timing_points, note.time), self.slider_multiplier,
        )
        return note.time + duration if duration < 0 else None

    def _compute_end_time(self, note) -> float | None:
        if note.is_spinner:
            return float(note.end_time) if note.end_time is not None else None
        if note.is_slider and note.length is not None and note.slides is not None:
            # beat_points, not timing_points: active_uninherited_at steps back
            # over inherited points one at a time, and an SV-heavy map puts
            # thousands of them between two red lines.
            timing = active_uninherited_at(self.beat_points, note.time)
            duration = duration_for_slider_length(
                note.length * note.slides, timing.beat_length,
                sv_at(self.timing_points, note.time), self.slider_multiplier,
            )
            return note.time + duration if duration > 0 else None
        return None

    # -- scroll velocity -----------------------------------------------------

    def _rebuild_velocities(self) -> None:
        """Scroll velocity in beats per millisecond, per timing-point timestamp.

        Velocities, not an integrated distance: in osu!taiko each object
        approaches the hit position at the speed in force **at its own time**,
        so a green line moves everything after it (including a note sitting on
        it) and objects can pass each other. Integrating one shared scroll
        position across the whole chart is osu!mania's model, not this one.

        Stored in beats rather than pixels so the base scroll speed stays a
        pure render-time scale: Ctrl+wheel costs a repaint, not a rebuild.
        """
        # Read once for the whole table rather than per point: it is a
        # property of the map, and it cannot change inside one rebuild.
        scroll_scale = self._scroll_scale
        points = self.timing_points
        beat_length = active_uninherited_at(points, points[0].time if points else 0.0).beat_length
        sv = 1.0
        times: list[float] = []
        velocities: list[float] = []
        index = 0
        while index < len(points):
            time_ms = points[index].time
            group_end = index
            while group_end < len(points) and points[group_end].time == time_ms:
                group_end += 1
            group = points[index:group_end]
            index = group_end
            for point in group:
                if point.uninherited:
                    beat_length = point.beat_length
            # An inherited point sharing the timestamp wins over the 1.0x reset
            # an uninherited one would apply -- the same rule as sv_series, for
            # the same reason: a green line stacked on a red one is how mappers
            # set the speed a new BPM section starts at.
            inherited = [point for point in group if point.inherited]
            if inherited:
                sv = inherited[-1].sv_multiplier
            else:
                sv = 1.0
            times.append(time_ms)
            velocities.append(self._beats_per_ms(beat_length, sv) * scroll_scale)
        if not times:
            times, velocities = [0.0], [self._beats_per_ms(beat_length, 1.0) * scroll_scale]
        self._velocity_times = times
        self._velocities = velocities
        # The slowest section decides how far ahead a full screen can reach,
        # and so how many notes the visible-range lookup has to consider.
        self._slowest_velocity = min(velocities)

    @property
    def _scroll_scale(self) -> float:
        """The map's own SliderMultiplier, as a factor on scroll speed.

        osu!taiko's scroll distance is
        `base_distance(100) * SliderMultiplier * VELOCITY_MULTIPLIER(1.4) *
        ScrollSpeed / beatLength` (`DrumRoll.cs`, `TaikoBeatmapConverter.cs`),
        so SliderMultiplier moves every object on screen. This view used to
        leave it out entirely, which meant two maps whose SliderMultiplier
        differed -- 0.6 against 2.0 is an ordinary spread -- were previewed at
        identical spacing while scrolling more than three times apart in game.
        The map's own value only reached the drumroll *durations*, so the
        bodies were right and the space between notes was not.

        Normalised against the value assumed before the parser read the real
        one, so a typical map previews at the scale it always has and only maps
        that actually differ move. The absolute speed is the Ctrl+wheel zoom's
        business; this is about the ratios between maps.
        """
        return max(0.01, self.slider_multiplier) / SLIDER_MULTIPLIER_ASSUMED

    @staticmethod
    def _beats_per_ms(beat_length: float, sv: float) -> float:
        # Guarded rather than trusted: the invisible-note gimmick authors
        # beat_length = 0.0001, and a hand-edited map can carry a zero.
        return max(0.01, sv) / max(1e-4, beat_length)

    def velocity_at(self, time_ms: float) -> float:
        """Scroll velocity in force at `time_ms`, in scroll units per ms.

        Beats per millisecond scaled by `_scroll_scale`, so the map's
        SliderMultiplier is already in it -- see that property.
        """
        index = max(0, bisect_right(self._velocity_times, time_ms) - 1)
        return self._velocities[index]

    def slowest_velocity_in(self, start_ms: float, end_ms: float) -> float:
        """Slowest velocity in force anywhere in `[start_ms, end_ms)`.

        Barline spacing has to be judged over a whole timing section, and the
        velocity at its red line does not describe it: a green line partway
        through moves every measure line after it, `x_for_time` resolves each
        one at its *own* time, and taking the red line's speed for the whole
        section made the two disagree. Slowest is the safe direction for both
        things this feeds -- the widest on-screen window and the largest line
        count -- so an SV change inside a section can never drop a line.
        """
        if not self._velocities:
            return self._slowest_velocity
        first = max(0, bisect_right(self._velocity_times, start_ms) - 1)
        last = bisect_left(self._velocity_times, end_ms)
        return min(self._velocities[first:max(last, first + 1)])

    def x_for_time(self, time_ms: float) -> float:
        """Where an object at `time_ms` currently sits.

        Its own velocity, not the playhead's: that is what makes a green line
        move every object after it while leaving the ones before it alone.
        """
        return self._hit_x() + (time_ms - self.current_time) * self.velocity_at(time_ms) * self.px_per_beat

    @property
    def px_per_beat(self) -> float:
        """Pixels one beat of scroll covers at 1.0x SV -- osu!'s distance,
        measured in the view's own height.

        This was a flat 200 screen pixels whatever the view's size, while every
        other size in it scaled with the height, so a wide, short dock (1882x170
        in the profiling runs) put a whole in-game screen of notes into a
        corner and filled the rest with chart osu! would not show yet.
        """
        return self.height() * STABLE_UNIT_PER_PLAYFIELD * GAMEPLAY_STABLE_UNITS_PER_BEAT

    def _hit_x(self) -> float:
        return self.height() * self.hit_x_units / PLAYFIELD_UNIT

    def osu_edge_x(self) -> float:
        """Where osu!'s screen ends: 16:9 of a screen whose playfield is this
        tall (see GAMEPLAY_LOCK_ASPECT). Beyond the view's width, the view."""
        if not GAMEPLAY_LOCK_ASPECT or self.plain_stage:
            return float(self.width())
        edge = self.height() * STABLE_UNIT_PER_PLAYFIELD * 480.0 * GAMEPLAY_MAX_ASPECT
        return min(float(self.width()), edge)

    def _mod_slider_factor(self) -> float:
        factor = 1.0
        for mod in SCROLL_MODS:
            if mod in self.mods:
                factor *= MOD_SLIDER_MULTIPLIER[mod]
        return factor

    def set_mods(self, mods) -> None:
        """Apply the mods the preview can show: HR/EZ, HD, FL. Rate mods move
        the song, and the preview follows song time on its own."""
        mods = frozenset(mods)
        if mods == self.mods:
            return
        scroll_changed = (
            {m for m in SCROLL_MODS if m in mods} != {m for m in SCROLL_MODS if m in self.mods}
        )
        self.mods = mods
        if scroll_changed and self._document is not None:
            self.refresh_notes(self._document)
        self.update()

    def _scroll_length_px(self) -> float:
        """osu!'s scroll length on this view, hit target to screen edge --
        what TaikoModHidden's preempt is a fraction of."""
        if GAMEPLAY_LOCK_ASPECT:
            edge = self.height() * STABLE_UNIT_PER_PLAYFIELD * 480.0 * GAMEPLAY_MAX_ASPECT
        else:
            edge = float(self.width())
        return max(1.0, edge - self._hit_x())

    def hidden_alpha(self, x: float) -> float:
        """How visible a hit at `x` is under HD: 1 as it enters, 0 once it has
        covered HD_FADE_DURATION of the scroll length. Linear, as the FadeOut
        it copies is."""
        if "HD" not in self.mods:
            return 1.0
        travelled = (x - self._hit_x()) / self._scroll_length_px()
        gone_at = HD_FADE_START - HD_FADE_DURATION
        return max(0.0, min(1.0, (travelled - gone_at) / HD_FADE_DURATION))

    def flashlight_combo(self) -> int:
        """The combo FL sizes itself by. Nobody is playing a preview, so this
        is the full-combo count: every hit before the playhead."""
        return sum(
            1 for note in self.notes[:bisect_left(self.note_times, self.current_time)]
            if note.is_circle
        )

    def _draw_flashlight(self, painter: QPainter) -> None:
        if "FL" not in self.mods:
            return
        unit = self.height() * STABLE_UNIT_PER_PLAYFIELD
        centre = QPointF(FL_CENTRE_STABLE * unit, (FL_CENTRE_STABLE - FL_PLAYFIELD_TOP_STABLE) * unit)
        radius = (self.height() * FL_RADIUS_UNITS / PLAYFIELD_UNIT
                  * flashlight_combo_scale(self.flashlight_combo()))
        outer = radius * FL_SMOOTHNESS
        inner = radius / outer
        gradient = QRadialGradient(centre, outer)
        gradient.setColorAt(0.0, QColor(0, 0, 0, 0))
        gradient.setColorAt(inner, QColor(0, 0, 0, 0))
        # The shader's smoothstep, sampled: a linear ramp between the two radii
        # reads as a harder edge than osu! draws.
        for step in range(1, 8):
            t = step / 8.0
            eased = t * t * (3.0 - 2.0 * t)
            gradient.setColorAt(inner + (1.0 - inner) * t, QColor(0, 0, 0, round(255 * eased)))
        gradient.setColorAt(1.0, QColor(0, 0, 0, 255))
        painter.fillRect(self.rect(), QBrush(gradient))

    def _draw_past_osu_edge(self, painter: QPainter) -> None:
        """Cover what osu! would not show. Opaque: a faint note behind a tint
        still reads as "coming up", and osu! shows nothing there at all. A thin
        line marks the edge itself."""
        edge = self.osu_edge_x()
        if edge >= self.width():
            return
        painter.fillRect(QRectF(edge, 0.0, self.width() - edge, self.height()), QColor(12, 15, 20))
        painter.setPen(QPen(QColor(255, 255, 255, 40), 1))
        painter.drawLine(QPointF(edge, 0.0), QPointF(edge, float(self.height())))

    def visible_time_range(self) -> tuple[float, float]:
        """Time bounds wide enough to contain everything on screen.

        Bounded by the *slowest* velocity in the map, so it never misses an
        object, and clamped: a near-stopped section would otherwise put an
        unbounded amount of time on one screen and turn this into a full scan.
        """
        reach = self.osu_edge_x() / max(1e-6, self._slowest_velocity * self.px_per_beat)
        reach = min(reach, GAMEPLAY_MAX_LOOKAHEAD_MS)
        return self.current_time - reach, self.current_time + reach

    def barline_times(self, start_ms: float, end_ms: float) -> list[float]:
        """Barlines on screen for the frame at `current_time`, within the range:
        one at every uninherited point, plus one each `meter` beats (4 by
        default) after it until the next one.

        A point with omit-first-barline set contributes its later measure lines
        but not the one on the point itself -- that is the flag's whole purpose,
        and barline gimmicks set it in bulk.

        Each section is walked only across the slice of time it is actually on
        screen for, at the slowest speed in force anywhere in it. The passed
        range is sized for the map's slowest section, and a section past 60000
        BPM crosses the whole of it in a fraction of a millisecond: walking that
        one from `start_ms` spent the entire per-frame line budget far off the
        left edge and drew nothing, which is what made those barlines -- the
        only thing still visible in a gimmick section, since its notes travel
        too fast to see -- go missing.

        There is deliberately no cap on how many lines come back. A dense
        section can legitimately want a great many, and the count that used to
        be capped was spent in time order, so slow sections ahead of the
        playhead exhausted it before the walk reached the section the playhead
        was actually in. The only real ceiling is the screen: two barlines that
        round to the same pixel column are one line, so a column already claimed
        this frame is skipped. That bounds what comes back by the width of the
        widget without a number to pick, and it cannot starve a later section --
        every line that survives is one the user can see.
        """
        times: list[float] = []
        claimed_columns: set[int] = set()
        width = self.width()
        hit_x = self._hit_x()
        first_point = bisect_left(self._beat_times, start_ms) - 1
        for index in range(max(0, first_point), len(self.beat_points)):
            point = self.beat_points[index]
            if point.time > end_ms:
                break
            section_end = (
                self.beat_points[index + 1].time
                if index + 1 < len(self.beat_points)
                else float("inf")
            )
            if section_end < start_ms:
                continue
            if point.beat_length <= 0:
                continue
            # Same floor _beats_per_ms puts on beat length. An invisible-note
            # gimmick authors 1e-9 here, and pairing an unclamped measure with a
            # clamped velocity would ask the walk below for millions of lines.
            measure = max(1e-4, point.beat_length) * max(1, point.meter)
            velocity = self.slowest_velocity_in(point.time, min(section_end, end_ms))
            # How much time this section fits on screen. Generous by a factor of
            # two: the hit position is not centered, so both sides need less
            # than a full width, and over-reaching only ever costs a little walk.
            reach = width / max(1e-9, velocity * self.px_per_beat)
            window_start = max(start_ms, self.current_time - reach)
            window_end = min(end_ms, self.current_time + reach)
            if window_end < point.time or window_end < window_start or section_end <= window_start:
                continue
            # Not a budget -- exactly the measure lines this window holds, which
            # is what stops a minutes-long section from being walked to its end.
            # Measured against the window rather than the widget: `reach` is
            # applied to both sides, so the walk spans two screens' worth of
            # time and a width's worth of lines ran out halfway across it.
            remaining = int((window_end - window_start) / measure) + 2
            # Jump straight to the first measure line on screen: a section is
            # routinely minutes long and walking it from the point is not.
            step = 0 if point.time >= window_start else int((window_start - point.time) // measure)
            while remaining > 0:
                remaining -= 1
                time_ms = point.time + step * measure
                if time_ms > window_end or time_ms >= section_end:
                    break
                if time_ms >= window_start and not (step == 0 and point.omit_first_barline):
                    # Each line's own velocity, matching x_for_time -- a green
                    # line inside the section moves this one but not the ones
                    # before it.
                    column = round(
                        hit_x
                        + (time_ms - self.current_time)
                        * self.velocity_at(time_ms)
                        * self.px_per_beat
                    )
                    if column not in claimed_columns:
                        claimed_columns.add(column)
                        times.append(time_ms)
                step += 1
        return times

    # -- input ---------------------------------------------------------------

    def wheelEvent(self, event) -> None:
        angle = event.angleDelta()
        pixel = event.pixelDelta()
        delta = angle.y() or angle.x() or pixel.y() or pixel.x()
        if delta == 0:
            event.accept()
            return

        modifiers = event.modifiers() | QApplication.keyboardModifiers()
        if modifiers & Qt.ControlModifier:
            # Swallowed, not acted on. This view exists to show the chart at
            # the speed the *player* sees, which is the map's own scroll
            # velocity -- rescaling it is a picture of something the game will
            # never draw, so there is nothing here for Ctrl+wheel to mean.
            event.accept()
            return

        threshold = 40.0 if angle.isNull() == 0 else 120.0
        self.wheel_accumulator += delta
        steps = int(self.wheel_accumulator / threshold)
        if steps:
            self.wheel_accumulator -= steps * threshold
            divisor = 1 if modifiers & Qt.ShiftModifier else self.snap_divisor
            self.current_time = wheel_seek_time(
                self.beat_points, self.current_time, -1 if steps > 0 else 1, divisor
            )
            TimeAxisMixin.wheel_seek_in_progress = True
            try:
                self.seek_requested.emit(round(self.current_time))
            finally:
                TimeAxisMixin.wheel_seek_in_progress = False
            self.update()
        event.accept()

    # -- paint ---------------------------------------------------------------

    def paintEvent(self, event) -> None:
        painter = QPainter(self)
        if self.plain_stage:
            ground = QColor(0, 0, 0)
        elif self.follows_view_opacity:
            ground = view_ground("#12161d")
        else:
            ground = theme.color("#12161d")
        painter.fillRect(self.rect(), ground)

        center_y = self.height() / 2
        normal_radius = self.height() * TAIKO_NOTE_SIZE / 2.0
        big_radius = normal_radius * TAIKO_STRONG_SCALE

        # The kiai pulse is needed before anything is drawn -- the playfield
        # itself lights up, not only the notes -- so it is computed here rather
        # than in the flash pass at the bottom. kiai_bands is sorted by start,
        # so bisect straight to the band the playhead could be in.
        band_index = bisect_right(self.kiai_bands, self.current_time, key=lambda band: band[0]) - 1
        anchor_ms = None
        if 0 <= band_index < len(self.kiai_bands):
            band_start, band_end = self.kiai_bands[band_index]
            if band_start <= self.current_time < band_end:
                anchor_ms = band_start
            elif self.current_time >= band_end:
                anchor_ms = self._unfinished_pulse_anchor(band_start, band_end)
        pulse = beat_pulse(self.beat_points, self.current_time, anchor_ms) if anchor_ms is not None else 0.0

        painter.setRenderHint(QPainter.SmoothPixmapTransform, True)
        self._draw_playfield(painter, center_y, normal_radius, big_radius, pulse)

        start_time, end_time = self.visible_time_range()
        hit_x = self._hit_x()
        if self._autoplay_shown():
            self._draw_kiai_glow(painter, hit_x, center_y, band_index)

        first = bisect_left(self.note_times, start_time - self._max_extend_ms)
        after_last = bisect_right(self.note_times, end_time)

        painter.setRenderHint(QPainter.Antialiasing, False)
        # The chart fades (fade_chart); the playfield drawn above does not.
        painter.setOpacity(self.chart_opacity)
        marker = self.skin.stretched(
            "taiko-barline",
            max(1, round(self.height() * PLAYFIELD_BARLINE_WIDTH)),
            round(self.height() * PLAYFIELD_BARLINE_HEIGHT),
        )
        painter.setPen(self.barline_pen)
        top, bottom = round(center_y - big_radius * 1.2), round(center_y + big_radius * 1.2)
        for time_ms in self.barline_times(start_time, end_time):
            x = self.x_for_time(time_ms)
            if not -1.0 <= x <= self.width() + 1.0:
                continue
            if marker is not None:
                draw_pixmap_subpixel(
                    painter, marker, x - marker.width() / 2.0, center_y - marker.height() / 2.0)
            else:
                painter.drawLine(round(x), top, round(x), bottom)

        painter.setOpacity(1.0)
        painter.setRenderHint(QPainter.Antialiasing, True)
        if not self.plain_stage:
            self._draw_hit_target_note(painter, hit_x, center_y, big_radius)
        ring = self._hit_ring()
        if ring is not None:
            painter.drawPixmap(QPointF(hit_x - ring.width() / 2.0, center_y - ring.height() / 2.0), ring)
        else:
            painter.setPen(self.hit_pen)
            painter.setBrush(Qt.NoBrush)
            painter.drawEllipse(QPointF(hit_x, center_y), normal_radius, normal_radius)
        # osu!'s own order (ppy/osu HitObjectContainer.Compare): the earlier
        # StartTime is on top, whatever the SV -- a shiny's note at T covers the
        # fake sliders it carries at T+1..3. A tie goes to the object added
        # first -- added when it comes on screen, and two objects on one
        # millisecond scroll at one speed, so that is file order. Barlines and
        # the hit target are an
        # underlay beneath all of it (TaikoPlayfield), drumrolls and spinners
        # included -- they share the one container with the notes.
        painter.setRenderHint(QPainter.Antialiasing, True)
        painter.setOpacity(self.chart_opacity)
        visible = list(enumerate(self.notes[first:after_last], first))
        visible.sort(key=lambda item: (-item[1].time, -item[0]))
        for _index, note in visible:
            self._draw_note(painter, note, center_y, normal_radius, big_radius)

        # Second pass, so stacked objects compound: a note drawn on top of an
        # earlier note's flash would wipe it, and stacking a fake slider on a
        # note is exactly how a mapper makes that note read brighter.
        #
        # This pass *is* the shine. A shiny note is a stack of fake sliders
        # under one note, and each of them takes its own kiai stamp here -- so
        # the note above them reads brighter the deeper the stack, with no
        # counting and no separate effect. It must not happen outside a chorus:
        # a glow that is always on is not a pulse, it is just a differently
        # coloured note, and it made every stack glow everywhere.
        #
        # Gated on the *playhead* alone. Arriving at a chorus lights up the
        # whole screen, which is what it does in game -- so every visible
        # object flashes, not only the ones whose own millisecond is inside
        # the section. Notes were previously filtered by their own kiai state
        # as well, which meant the section's first beat lit up a handful of
        # notes and left the rest of the screen dark.
        if pulse > 0.0:
            # The built-in stand-in for `taiko-bar-right-glow`: only drawn
            # when the skin has no kiai state of its own for the lane, or the
            # lane would be washed twice over.
            if self.plain_stage or not self.skin.has("taiko-bar-right-glow"):
                playfield_alpha = round(PLAYFIELD_PULSE_ALPHA * pulse)
                if playfield_alpha > 0:
                    painter.setOpacity(1.0)  # the lane lights whatever the chart is doing
                    painter.fillRect(self.rect(), QColor(255, 255, 255, playfield_alpha))
                    painter.setOpacity(self.chart_opacity)
            for note in self.notes[first:after_last]:
                end_time = self._note_end_time(note)
                hit = self._has_been_hit(note)
                # A circle that has been played is gone and has nothing to
                # light. A slider always has something: its cap, which outlives
                # its head -- a fake slider's included, since that passes
                # straight through the hit position.
                if hit and not note.is_slider:
                    continue
                # Not a spinner: its art is not a CirclePiece, and the full
                # drumroll-strength stamp it took lit the whole swell yellow on
                # every beat of a chorus, which osu! does not do.
                if note.is_spinner:
                    continue
                x = self.x_for_time(note.time)
                radius = big_radius if (note.is_finisher or note.is_spinner) else normal_radius
                if not -radius <= x <= self.width() + radius:
                    continue
                # A fake slider takes its own stamp like every other object --
                # that *is* the shiny: a stack of them under one note, each
                # stamping the same millisecond, so the note above reads
                # brighter the deeper the pile with nothing counting it.
                strength = kiai_flash_strength(note)
                big = note.is_finisher or note.is_spinner
                # A real roll past the target has lost its head, so only its
                # cap lights from here on.
                if not hit:
                    alpha = self.hidden_alpha(x) if note.is_circle else 1.0
                    if alpha > 0.0:
                        painter.save()
                        painter.setOpacity(painter.opacity() * alpha)
                        draw_kiai_flash(
                            painter, x, center_y, radius, pulse, strength, self.skin, big,
                            colour=KIAI_CIRCLE_PULSE_COLOR if note.is_circle else KIAI_PULSE_COLOR)
                        painter.restore()
                # A roll's cap is part of the object and pulses with it. Its own
                # shape and its own anchor, or the light lands on the track
                # rather than on the cap -- see draw_note_light.
                #
                # **Only where the cap can be seen.** The head is drawn last and
                # covers it, so on a roll with no track to speak of the cap sits
                # behind the head, and lighting it puts a second stamp on the
                # head's right half and nowhere else -- which reads as a note
                # lit down one side. Once the head is gone the cap is all there
                # is, so then it lights on its own.
                if note.is_slider:
                    if end_time is not None:
                        span = end_time - note.time
                    else:
                        phantom = self._phantom_end_time(note)
                        span = 0.0 if phantom is None else abs(phantom - note.time)
                    end_x = x + span * self.velocity_at(note.time) * self.px_per_beat
                    if hit or end_x > x:
                        draw_kiai_flash(
                            painter, max(end_x, x), center_y, radius, pulse,
                            strength, self.skin, big, "taiko-roll-end", True,
                        )
        painter.setOpacity(1.0)
        if self._autoplay_shown():
            # Over the notes: a roll passing the target slides under the drum.
            self._draw_input_drum(painter, center_y)
        self._draw_flashlight(painter)
        self._draw_past_osu_edge(painter)

    def _draw_hit_target_note(self, painter, hit_x, center_y, big_radius) -> None:
        """The grey note sitting in the hit target (owner, 2026-10-10):
        ppy/osu `TaikoLegacyHitTarget`'s `taikobigcircle`, untinted, at alpha
        0.22 and SCALE (0.8) of its own size. Drawn under the ring rather than
        over it as lazer does -- at 0.22 the order barely shows, and under is
        what was asked for. Without the art, a white disc the size of a
        finisher at the same alpha."""
        previous = painter.opacity()
        painter.setOpacity(previous * HIT_TARGET_NOTE_ALPHA)
        circle = self.skin.natural(
            "taikobigcircle", self.height() / PLAYFIELD_UNIT * KIAI_GLOW_SCALE)
        if circle is not None:
            painter.drawPixmap(
                QPointF(hit_x - circle.width() / 2.0, center_y - circle.height() / 2.0), circle)
        else:
            painter.setPen(Qt.NoPen)
            painter.setBrush(QColor(255, 255, 255))
            painter.drawEllipse(QPointF(hit_x, center_y), big_radius, big_radius)
        painter.setOpacity(previous)

    # -- autoplay ------------------------------------------------------------

    def _autoplay_shown(self) -> bool:
        # Never on song select's bare stage (owner, 2026-10-10).
        return self.autoplay is not None and not self.plain_stage

    def _half_alpha(self, half: int) -> float:
        """How lit drum half `half` is now: ppy/osu `LegacyHalfDrum`, see
        DRUM_HIT_OUT_AT_MS. A hit landing while the half is still lit fades
        in from where it is, over the part of 80ms that is left -- osu!'s
        `80 * (1 - Alpha)` -- so a stream on one half does not blink."""
        times = self._half_hits.get(half)
        if not times:
            return 0.0
        index = bisect_right(times, self.current_time) - 1
        if index < 0:
            return 0.0
        start = 0.0
        if index > 0:
            start = _drum_hit_alpha(times[index] - times[index - 1], 0.0)
        return _drum_hit_alpha(self.current_time - times[index], start)

    def _draw_input_drum(self, painter, center_y) -> None:
        """`taiko-bar-left` and the four drum halves, lit by the autoplay.

        Laid out as ppy/osu's `LegacyInputDrum` does, in its own units: the
        drum is INPUT_DRUM_WIDTH (180) of the playfield's 200, and each half
        is the same art, the right one mirrored. The rim art is drawn
        mirrored on the *left* -- skinners draw it for the right -- which is
        why `taiko-drum-outer` is flipped where `-inner` is not. Skins before
        2.1 place the pieces at stable's offsets instead.
        """
        unit = self.height() / PLAYFIELD_UNIT
        skin = self.skin
        painter.save()
        painter.setClipRect(QRectF(0.0, 0.0, INPUT_DRUM_WIDTH * unit, float(self.height())))
        bar = skin.natural("taiko-bar-left", unit)
        if bar is not None:
            painter.drawPixmap(QPointF(0.0, 0.0), bar)
        else:
            painter.fillRect(QRectF(0.0, 0.0, INPUT_DRUM_WIDTH * unit, float(self.height())),
                             QColor(18, 21, 28))
        layout = DRUM_LAYOUT if skin.version >= 2.1 else DRUM_LAYOUT_PRE_2_1
        for half, element, x, y, mirrored in layout:
            alpha = self._half_alpha(half)
            if not skin.has(element):
                self._draw_builtin_half(painter, half, center_y, alpha)
                continue
            if alpha <= 0.0:
                continue
            pixmap = skin.natural(element, unit, mirrored)
            if pixmap is not None:
                painter.setOpacity(alpha)
                painter.drawPixmap(QPointF(x * unit, y * unit), pixmap)
        painter.restore()

    def _draw_builtin_half(self, painter, half, center_y, alpha) -> None:
        """A drum half for a skin with no art for it: a half disc (don) or
        half ring (kat), outlined always, filled while lit."""
        height = self.height()
        centre = QPointF(INPUT_DRUM_WIDTH / 2.0 * height / PLAYFIELD_UNIT, center_y)
        outer, inner = height * 0.34, height * 0.24
        path = QPainterPath()
        path.setFillRule(Qt.OddEvenFill)
        if half in (1, 4):
            path.addEllipse(centre, outer, outer)
        path.addEllipse(centre, inner, inner)
        left = half in (1, 2)
        side = QPainterPath()
        side.addRect(QRectF(centre.x() - outer if left else centre.x(), 0.0, outer, float(height)))
        path = path.intersected(side)
        painter.save()
        painter.setOpacity(1.0)
        painter.setPen(QPen(QColor(255, 255, 255, 60), 1))
        painter.setBrush(Qt.NoBrush)
        painter.drawPath(path)
        if alpha > 0.0:
            painter.setOpacity(alpha)
            painter.setPen(Qt.NoPen)
            painter.setBrush(self.kat_brush if half in (1, 4) else self.don_brush)
            painter.drawPath(path)
        painter.restore()

    def _draw_kiai_glow(self, painter, hit_x, center_y, band_index) -> None:
        """`taiko-glow` behind the hit target, ppy/osu `LegacyKiaiGlow`: in over
        100ms when a kiai starts, out over 600ms after it ends, tinted
        (255, 228, 0), at TaikoLegacyHitTarget.SCALE -- and kicked 0.15 larger
        by each hit, easing back over 80ms."""
        if not 0 <= band_index < len(self.kiai_bands):
            return
        band_start, band_end = self.kiai_bands[band_index]
        now = self.current_time
        if now < band_end:
            alpha = min(1.0, (now - band_start) / KIAI_GLOW_IN_MS)
        else:
            alpha = 1.0 - (now - band_end) / KIAI_GLOW_OUT_MS
        if alpha <= 0.0:
            return
        unit = self.height() / PLAYFIELD_UNIT
        glow = self.skin.natural("taiko-glow", unit, colour=KIAI_GLOW_COLOR)
        if glow is None:
            return
        scale = KIAI_GLOW_SCALE
        index = bisect_right(self._all_hits, now) - 1
        if index >= 0 and now < band_end:
            since = now - self._all_hits[index]
            if since < KIAI_GLOW_KICK_MS:
                t = since / KIAI_GLOW_KICK_MS
                scale += KIAI_GLOW_KICK * (1.0 - t) ** 2
        width, height = glow.width() * scale, glow.height() * scale
        previous = painter.opacity()
        painter.setOpacity(previous * alpha)
        painter.drawPixmap(
            QRectF(hit_x - width / 2.0, center_y - height / 2.0, width, height),
            glow, QRectF(glow.rect()))
        painter.setOpacity(previous)

    def _unfinished_pulse_anchor(self, band_start, band_end) -> float | None:
        """`band_start` while the pulse the section left running is still fading.

        A kiai section shorter than one beat starts a pulse it cannot finish:
        at `band_end` the flash cut to black mid-fade, which reads as the
        chorus being switched off rather than as a beat. The pulse that was in
        progress when the section ended is allowed to run out -- so the
        shortest possible kiai still shows one whole beat of light, and a
        section that ends exactly on a beat is unchanged (`ceil` returns the
        boundary itself).

        **Under 60 BPM only** (`KIAI_PULSE_CARRY_MIN_BEAT_MS`). Above it the
        beat is short enough that a section ending inside one simply stops,
        which is what the end of a chorus should look like; carrying it there
        would hold light past a kiai the map has finished with. Only a beat
        long enough for the cut to land on a flash still visibly fading gets
        to finish.

        Anchored on the section rather than on the playhead: past `band_end`
        there is no kiai to look up, and the fade has to keep the phase it
        started with.
        """
        point = pulse_beat_point(self.beat_points, band_start)
        if point is None or point.beat_length <= KIAI_PULSE_CARRY_MIN_BEAT_MS:
            return None
        span = band_end - band_start
        finish = band_start + math.ceil(span / point.beat_length) * point.beat_length
        return band_start if self.current_time < finish else None

    def _has_been_hit(self, note) -> bool:
        """Whether `note`'s circle head is played, and so off the screen.

        osu!taiko takes a circle away the instant it reaches the hit position:
        that *is* what being hit looks like. Letting it carry on past the
        target is a thing the game never shows.

        A **fake slider** counts too, but only its head: what is left behind is
        the region it draws and never lets anybody hit, which is the whole
        point of the object and the thing worth still seeing.

        A real drumroll is still being hit while its body crosses the target,
        so it travels through and out the far side; a spinner occupies its
        whole span in place. Neither is ever "hit" in this sense.
        """
        if note.is_spinner or note.time > self.current_time:
            return False
        return not (note.is_slider and self._note_end_time(note) is not None)

    def _draw_note(self, painter, note, center_y, normal_radius, big_radius) -> None:
        x = self.x_for_time(note.time)
        radius = big_radius if (note.is_finisher or note.is_spinner) else normal_radius
        end_time = self._note_end_time(note)
        # A slider or spinner body travels with its *head*: it is one object at
        # one speed, not a series of points each reading its own timing.
        end_x = (
            x + (end_time - note.time) * self.velocity_at(note.time) * self.px_per_beat
            if end_time is not None and end_time > note.time
            else x
        )
        # A fake slider is drawn forward of its head and outlives it, so
        # neither this cull nor the hit test below describes it. It does both
        # for itself.
        if note.is_slider and end_time is None:
            self._draw_fake_slider(painter, note, x, center_y, radius)
            return
        # The time-range slice is bounded by the slowest section in the map, so
        # a fast one lands objects well off either edge; drop those here.
        if end_x + radius < 0 or x - radius > self.width():
            return

        if note.is_spinner:
            painter.setPen(Qt.NoPen)
            painter.setBrush(self.spinner_band_brush)
            painter.drawRoundedRect(
                QRectF(x, center_y - radius, max(1.0, end_x - x), radius * 2), radius, radius
            )
            pixmap = spinner_pixmap()
            if not pixmap.isNull():
                size = radius * 2
                painter.drawPixmap(
                    QRectF(x - radius, center_y - radius, size, size), pixmap, QRectF(pixmap.rect())
                )
            return

        if note.is_slider:
            if self._draw_skinned_roll(
                painter, x, end_x, center_y, radius, note.is_finisher):
                return
            painter.setPen(self.note_pen)
            painter.setBrush(self.slider_brush)
            painter.drawRoundedRect(
                QRectF(x - radius, center_y - radius, max(2 * radius, end_x - x + 2 * radius), radius * 2),
                radius,
                radius,
            )
            return

        if self._has_been_hit(note):
            return
        alpha = self.hidden_alpha(x)
        if alpha <= 0.0:
            return
        if alpha < 1.0:
            painter.save()
            painter.setOpacity(painter.opacity() * alpha)
        draw_note_sprite(
            painter, self.kat_brush if note.is_kat else self.don_brush, self.note_pen,
            x, center_y, radius, self.skin,
            big=note.is_finisher or note.is_spinner,
        )
        if alpha < 1.0:
            painter.restore()

    def _draw_playfield(self, painter, center_y, normal_radius, big_radius, pulse) -> None:
        """The skin's playfield, back to front, under everything else.

        The bar, then the bar's kiai overlay, which pulses with the notes. A
        skin without a bar gets the built-in lane, the same per-element
        fallback the notes use.

        No `taiko-glow` or `lighting`: those are a bloom around the hit target,
        and nothing is being judged there. Kiai shows as the notes pulsing and
        the lane taking its kiai state, both of which say something.
        """
        if self.plain_stage:
            return
        width, height = self.width(), self.height()
        skin = self.skin
        # `taiko-slider` (the scrolling background) is not drawn: owner's call,
        # 2026-10-07 -- the bar is the lane. Without a bar, the built-in lane.
        bar = skin.stretched("taiko-bar-right", width, height)
        if bar is None:
            painter.fillRect(
                QRectF(0, center_y - big_radius * 1.2, width, big_radius * 2.4),
                self.lane_brush,
            )
            return

        painter.drawPixmap(QPointF(0.0, 0.0), bar)
        if pulse > 0.0:
            # Pulses with the notes: `pulse` is the same per-beat flash.
            glow = skin.stretched("taiko-bar-right-glow", width, height)
            if glow is not None:
                opacity = painter.opacity()
                painter.setOpacity(opacity * pulse * KIAI_GLOW_STRENGTH)
                painter.drawPixmap(QPointF(0.0, 0.0), glow)
                painter.setOpacity(opacity)


    def _hit_ring(self) -> QPixmap | None:
        """The skin's `approachcircle` as ppy/osu `TaikoLegacyHitTarget` draws
        it: its own size, @2x counted as half, at HIT_TARGET_RING_SCALE of the
        200-unit playfield -- the same rule as the grey note under it."""
        return self.skin.natural("approachcircle", self.height() / PLAYFIELD_UNIT * HIT_TARGET_RING_SCALE)

    def _cap_height(self, diameter: int) -> int:
        """`taiko-roll-end`'s drawn height, so its *ink* matches the note's.

        Skins pad the two elements differently -- one real skin fills 0.83 of
        `taikohitcircle`'s box and 1.00 of `taiko-roll-end`'s -- so scaling both
        to the note diameter drew a cap visibly larger than the note it caps,
        with its yellow showing past the note's edge. Dividing by each one's own
        ink ratio makes the two agree however a skin padded them.
        """
        head_ink = self.skin.ink_height("taikohitcircle")
        cap_ink = self.skin.ink_height("taiko-roll-end")
        if cap_ink <= 0.0:
            return diameter
        return max(1, round(diameter * head_ink / cap_ink))

    def _draw_skinned_roll(
        self, painter, x, end_x, center_y, radius, big: bool = False,
    ) -> bool:
        """A drumroll as its three skin pieces: head, stretched body, tail cap.

        `taikohitcircle` + `taiko-roll-middle` + `taiko-roll-end`, laid out the
        way the skinning wiki specifies them:

        * the head is the ordinary note circle in the drumroll's colour, which
          is what osu! does (`DrumRollCirclePiece` is a circle piece with the
          drumroll accent);
        * `taiko-roll-middle` is **1px wide, origin TopLeft** -- it is the
          track, meant to be stretched the length of the body rather than
          tiled, so it is drawn from the head's own x across the span;
        * `taiko-roll-end` is **64x128, origin TopLeft** -- "the end part of a
          roll". TopLeft, so it butts onto the far end of the track and reaches
          *past* it by its own width, exactly as the head reaches back past the
          start by its radius. Centred on the end (which is what this did) the
          roll came up half a radius short.

        Only a **real** roll reaches here. A negative length is a fake slider,
        which is a bare track with no head and no cap -- a different object,
        drawn by `_draw_fake_slider`.

        All three tint from the drumroll colour, multiplicatively, which is the
        blend mode the wiki gives for both roll pieces.
        """
        diameter = round(radius * 2)
        cap = self._cap_height(diameter)
        middle = self.skin.scaled("taiko-roll-middle", diameter, self.slider_brush)
        if middle is None:
            return False
        body_end = max(end_x, x)
        if body_end > x:
            painter.drawPixmap(
                QRectF(x, center_y - radius, body_end - x, radius * 2),
                middle, QRectF(middle.rect()),
            )
        tail = self.skin.scaled("taiko-roll-end", cap, self.slider_brush)
        if tail is not None:
            draw_pixmap_subpixel(painter, tail, body_end, center_y - tail.height() / 2.0)
        # `big` matters here as much as it does for a finisher note: a big
        # drumroll's head is `taikobigcircle`, which skinners redraw rather
        # than scale up -- some are a different shape, some carry a second ring
        # the small one does not have. Scaling `taikohitcircle` to the finisher
        # diameter drew the wrong artwork at the right size.
        draw_note_sprite(
            painter, self.slider_brush, self.note_pen, x, center_y, radius,
            self.skin, big=big)
        return True

    def _draw_fake_slider(self, painter, note, x, center_y, radius) -> None:
        """A negative-length fake slider: a head, and a track reaching right.

        `taikohitcircle` in the drumroll colour, the same head a real roll has,
        plus `taiko-roll-middle` laid from the object's own x and reaching to
        its **right** by the magnitude of the negative length. No
        `taiko-roll-end`: the cap belongs to a roll that ends, and this one
        ends before it starts. At the hit position the whole thing disappears
        with nothing left travelling on.

        The track is drawn **to scale**, which is why the two ends of the range
        look like different objects and are not. A `-800` track is over a
        thousand pixels of the same yellow at the same height, so the head sits
        at its left edge and reads as part of the bar; the canonical `-0.0001`
        collapses the track to nothing and leaves the head as the only thing
        on screen. Padding the track to visibility would invent geometry the
        map does not have, and dropping the head because a long one hides it
        made every short fake slider -- which is most of them -- invisible.

        It appears at full opacity like any other object. There is no fade-in:
        a stack of them is a stack of identical opaque objects and reads as
        one, and what makes a shiny note brighter is the kiai stamp each of
        them takes, not any difference in how they are drawn.

        **Only the head is taken away at the hit position.** The track and its
        cap pass straight through and carry on out to the left, the way a real
        roll's do -- so the object outlives its own millisecond and cannot be
        culled on where its head is.
        """
        end_time = self._phantom_end_time(note)
        if end_time is None:
            return
        width = abs(end_time - note.time) * self.velocity_at(note.time) * self.px_per_beat
        cap = self._cap_height(round(radius * 2))
        # The cap butts onto the far end of the track and reaches past it by its
        # own width (origin TopLeft), so that -- not the head -- is the right
        # edge of what gets drawn.
        if x + width + cap < 0 or x - radius > self.width():
            return
        if width >= 0.5:
            track = self.skin.scaled(
                "taiko-roll-middle", round(radius * 2), self.slider_brush)
            if track is not None:
                painter.drawPixmap(
                    QRectF(x, center_y - radius, width, radius * 2),
                    track, QRectF(track.rect()),
                )
            else:
                # No skin: the same track in the drumroll colour, since the
                # built-in lane has no art of its own.
                painter.setPen(Qt.NoPen)
                painter.setBrush(self.slider_brush)
                painter.drawRect(QRectF(x, center_y - radius, width, radius * 2))
        tail = self.skin.scaled("taiko-roll-end", cap, self.slider_brush)
        if tail is not None:
            draw_pixmap_subpixel(painter, tail, x + width, center_y - tail.height() / 2.0)
        else:
            # Without a skin there is no cap art, so the stand-in is the
            # drumroll colour in the shape a built-in drumroll ends in: a disc.
            painter.setPen(self.note_pen)
            painter.setBrush(self.slider_brush)
            painter.drawEllipse(
                QPointF(x + width + radius / 2.0, center_y), radius, radius)
        if not self._has_been_hit(note):
            # Last, so it sits on the near end of its own track the way a real
            # roll's head does -- and gone once played, like any circle.
            draw_note_sprite(
                painter, self.slider_brush, self.note_pen, x, center_y, radius,
                self.skin, big=note.is_finisher,
            )


def timeline_bar_data(document, duration_ms: int):
    """Everything a TimingOverviewBar draws, derived once.

    Three bars exist -- one per page -- and they all show the same document, so
    this is computed once per edit and applied to each of them rather than each
    walking the whole map for itself. Returned as a plain tuple so a bar can
    adopt it without knowing where it came from.
    """
    duration = max(duration_ms, document.hit_objects[-1].time if document.hit_objects else 1, 1)
    kiai = kiai_ranges(document, duration)
    bookmarks, preview_time = editor_timeline_metadata(document)
    markers = [(round(point.time), point.uninherited) for point in document.timing_points]
    # Grouped once per edit, not per frame: a gimmick map carries tens of
    # thousands of points and the bar repaints on every clock tick.
    groups: dict[int, set] = {}
    for time_ms, uninherited in markers:
        groups.setdefault(time_ms, set()).add(uninherited)
    kinds = sorted(
        (time_ms, "yellow" if len(flags) > 1 else "red" if True in flags else "green")
        for time_ms, flags in groups.items()
    )
    return duration, kiai, markers, bookmarks, preview_time, kinds


class TimingOverviewBar(QWidget):
    seek_requested = Signal(int)
    def __init__(self) -> None:
        super().__init__()
        self.duration_ms=1; self.current_time=0; self.viewport_start=0; self.viewport_end=0
        self.kiai=[]; self.timing_markers=[]; self._marker_kinds=[]; self.bookmarks=[]; self.preview_time=None; self.dragging=False
        self._marker_cache_key=None; self._marker_lines=[]; self._last_seek_ms=None
        # Everything but the playhead, the viewport box and the preview line is
        # fixed for the life of a document, so it is painted once into a pixmap
        # rather than 120 times a second. Same idiom as DensityOverview below.
        self.static_layer=QPixmap(); self.static_layer_dirty=True
        # Two sources say how long the bar is: the document (its last object,
        # via timeline_bar_data) and the decoded track (set_duration). They
        # differ -- 170343 against 170793ms on can you hear my voice -- and each
        # used to overwrite the other, so every edit squeezed the bar to the
        # document's length and the info timer stretched it back: dragging a
        # green line made every marker jump sideways and back on each step.
        # Both are kept and the longer one drawn.
        self._document_ms=1; self._media_ms=0
        self.setFixedHeight(28); self.setCursor(Qt.PointingHandCursor)
    def load_document(self,document,duration_ms:int)->None:
        self.apply_document_data(timeline_bar_data(document,duration_ms))

    def apply_document_data(self,data)->None:
        """Adopt data already derived by `timeline_bar_data`.

        Split out because three of these bars exist -- one per page -- all
        showing the same document. Each one deriving it for itself walked every
        timing point in the map three times over on every edit.
        """
        self._document_ms,self.kiai,self.timing_markers,self.bookmarks,self.preview_time,self._marker_kinds=data
        self.duration_ms=max(self._document_ms,self._media_ms)
        self._marker_cache_key=None
        self.static_layer_dirty=True
        self.update()

    def set_duration(self,value:int)->None:
        # Guarded on an actual change, like DensityOverview's. The duration is
        # re-asserted by the timeline info refresh many times a second, and
        # dirtying the static layer each time rebuilt ~1150 marker lines for a
        # value that had not moved -- which is exactly the cost that layer
        # exists to avoid.
        if value<=0:return
        self._media_ms=value
        duration=max(self._document_ms,value)
        if duration!=self.duration_ms:
            self.duration_ms=duration;self.static_layer_dirty=True;self.update()
    def set_time(self,value:int)->None:self.current_time=max(0,min(value,self.duration_ms));self.update()
    def set_viewport(self,center:int,window_ms:float)->None:
        self.viewport_start=max(0,center-window_ms/2);self.viewport_end=min(self.duration_ms,center+window_ms/2);self.update()
    def _seek(self,x:float)->None:
        """Emit a seek, but only for a millisecond that is not already in force.

        One plain click is a press *and* a release at the same pixel, and both
        used to emit. The audio engine coalesces a burst (`SEEK_COALESCE_MS`),
        so the duplicate was not dropped but *parked*: it landed 50ms later as
        a second full sink teardown and rebuild, which is the one hiccup heard
        just after every click on the bar. A slow drag that stays inside one
        millisecond was paying the same way.
        """
        value=round(max(0,min(1,x/max(1,self.width())))*self.duration_ms)
        if value==self._last_seek_ms:return
        self._last_seek_ms=value;self.seek_requested.emit(value)
    def _marker_line_positions(self):
        """(x, kind) per pixel column, cached until the bar or the map changes.

        The bar is a few hundred pixels wide, so a gimmick map's thousands of
        markers collapse onto the same handful of columns -- recomputing that
        every clock tick was the widget's whole paint cost.

        A column holding both kinds is yellow, the same rule `timeline_bar_data`
        applies to two points at the same millisecond. Kept per-column and not
        per-kind because the paint loop draws green last, so a red point sharing
        a pixel with an inherited one was overpainted and read as green.
        """
        key=(self.width(),self.duration_ms,len(self._marker_kinds))
        if key!=self._marker_cache_key:
            columns={}
            for time_ms,kind in self._marker_kinds:
                x=round(time_ms/self.duration_ms*self.width())
                prior=columns.get(x)
                columns[x]=kind if prior is None or prior==kind else "yellow"
            self._marker_cache_key=key;self._marker_lines=sorted(columns.items())
        return self._marker_lines
    def mousePressEvent(self,event)->None:
        # Cleared first so a second click on the same pixel still seeks:
        # playback has moved on since, so it is a real request to go back.
        if event.button()==Qt.LeftButton:self.dragging=True;self._last_seek_ms=None;self._seek(event.position().x())
    def mouseMoveEvent(self,event)->None:
        if self.dragging:self._seek(event.position().x())
    def mouseReleaseEvent(self,event)->None:
        if self.dragging:self._seek(event.position().x())
        self.dragging=False
    def resizeEvent(self,event)->None:
        self.static_layer_dirty=True
        super().resizeEvent(event)
    def _rebuild_static_layer(self)->None:
        """The bar minus the three things that move.

        A gimmick map puts a marker on most of the bar's ~1000 pixel columns,
        and each one is a setPen and a drawLine -- measured at 1150 of each per
        frame, 1.29ms, on a 28-pixel-tall widget that cost more than the full
        timeline above it. None of it changes while the song plays.
        """
        if self.width()<=0 or self.height()<=0:return
        layer=QPixmap(self.size());layer.fill(theme.color("#0d1219"))
        painter=QPainter(layer);painter.setRenderHint(QPainter.Antialiasing,False)
        center=self.height()//2
        kiai_height=max(3,self.height()//3);kiai_top=center-kiai_height//2
        painter.setPen(Qt.NoPen)
        for start,end in self.kiai:
            x=start/self.duration_ms*self.width();w=max(1,(end-start)/self.duration_ms*self.width())
            painter.fillRect(QRectF(x,kiai_top,w,kiai_height),QColor(255,170,0,82))
        painter.setPen(QPen(QColor(255,255,255,190),1));painter.drawLine(0,center,self.width(),center)
        colors={"yellow":QColor("#ffd400"),"red":QColor("#ff4545"),"green":QColor("#45d65a")}
        # Grouped by colour so the pen is set three times instead of once per
        # marker: setPen was measured at the same call count as drawLine.
        for kind,color in colors.items():
            painter.setPen(QPen(color,1))
            for x,marker_kind in self._marker_line_positions():
                if marker_kind==kind:painter.drawLine(x,1,x,center-1)
        painter.setPen(QPen(QColor("#3e9bff"),1))
        for bookmark in self.bookmarks:
            x=round(bookmark/self.duration_ms*self.width());painter.drawLine(x,center+1,x,self.height()-2)
        painter.end();self.static_layer=layer;self.static_layer_dirty=False
    def paintEvent(self,event)->None:
        if self.static_layer_dirty or self.static_layer.size()!=self.size():self._rebuild_static_layer()
        painter=QPainter(self);painter.drawPixmap(0,0,self.static_layer)
        painter.setRenderHint(QPainter.Antialiasing,False)
        center=self.height()//2
        if self.preview_time is not None:
            x=round(self.preview_time/self.duration_ms*self.width());painter.setPen(QPen(QColor("#ffd400"),1));painter.drawLine(x,center+1,x,self.height()-2)
        if self.viewport_end>self.viewport_start:
            x=self.viewport_start/self.duration_ms*self.width();w=(self.viewport_end-self.viewport_start)/self.duration_ms*self.width()
            painter.setPen(QPen(QColor(255,255,255,65),1));painter.setBrush(Qt.NoBrush);painter.drawRect(QRectF(x,1,w,self.height()-2))
        x=round(self.current_time/self.duration_ms*self.width());painter.setPen(QPen(QColor("#ffffff"),1));painter.drawLine(x,0,x,self.height())


# The density histogram (owner, 2026-10-08): one bar per 1% of the song, each
# as tall as its note rate against a fixed ceiling -- DENSITY_FULL_NOTES in
# DENSITY_FULL_BEATS beats of the chart's most common BPM, a 1/4 stream. Read
# against the chart's own tempo rather than against its busiest bar, so a
# chart with one dense burst no longer draws everything else as nothing, and
# a gimmick's 60000 BPM line cannot set the scale.
DENSITY_BARS = 100
DENSITY_FULL_NOTES = 16
DENSITY_FULL_BEATS = 4


def most_common_beat_length(points, last_time: float) -> float | None:
    """`song_library.most_common_beat_length` over timing points: the density
    view's tempo and the difficulty rows' "(250)" are one rule."""
    return library_common_beat_length(
        [(point.time, point.beat_length) for point in points if point.uninherited], last_time)


def density_bars(times, duration_ms: float, beat_length: float | None) -> list[tuple[float, float, float]]:
    """[(start, end, level 0..1)], one bar per DENSITY_BARS-th of the song.
    `times` sorted. Level 1 is DENSITY_FULL_NOTES notes per DENSITY_FULL_BEATS
    beats of `beat_length` or more; without a tempo, against the busiest bar."""
    duration_ms = max(1.0, float(duration_ms))
    step = duration_ms / DENSITY_BARS
    counts = []
    for index in range(DENSITY_BARS):
        start, end = index * step, (index + 1) * step
        counts.append((start, end, bisect_left(times, end) - bisect_left(times, start)))
    if beat_length:
        full = DENSITY_FULL_NOTES * step / (DENSITY_FULL_BEATS * beat_length)
    else:
        full = max((count for _start, _end, count in counts), default=1)
    full = max(full, 1e-9)
    return [(start, end, min(1.0, count / full)) for start, end, count in counts]


class DensityOverview(QWidget):
    seek_requested = Signal(int)
    def __init__(self) -> None:
        super().__init__(); self.duration_ms=1; self.current_time=0; self.viewport_start=0; self.viewport_end=0; self.windows=[]; self.dragging=False
        self._last_seek_ms=None
        self.static_layer = QPixmap()
        self.static_layer_dirty = True
        self.setFixedHeight(58); self.setCursor(Qt.PointingHandCursor)
    def load_document(self,document,duration_ms:int)->None:
        self.duration_ms=max(duration_ms,document.hit_objects[-1].time if document.hit_objects else 1,1)
        times=[n.time for n in document.hit_objects]
        beat=most_common_beat_length(extract_timing_points(document), times[-1] if times else 0)
        self.windows=density_bars(times, self.duration_ms, beat)
        self.static_layer_dirty=True; self.update()
    def set_duration(self,value:int)->None:
        if value>0 and value!=self.duration_ms:
            self.duration_ms=value; self.static_layer_dirty=True; self.update()
    def set_time(self,value:int)->None:self.current_time=max(0,min(value,self.duration_ms));self.update()
    def set_viewport(self,center:int,window_ms:float)->None:
        self.viewport_start=max(0,center-window_ms/2); self.viewport_end=min(self.duration_ms,center+window_ms/2); self.update()
    def _seek(self,x:float)->None:
        """See `TimingOverviewBar._seek`: a press and a release at the same
        pixel are one click, and the duplicate became a delayed sink rebuild."""
        value=round(max(0,min(1,x/max(1,self.width())))*self.duration_ms)
        if value==self._last_seek_ms:return
        self._last_seek_ms=value;self.seek_requested.emit(value)
    def mousePressEvent(self,event)->None:
        # Cleared first so a second click on the same pixel still seeks:
        # playback has moved on since, so it is a real request to go back.
        if event.button()==Qt.LeftButton:self.dragging=True;self._last_seek_ms=None;self._seek(event.position().x())
    def mouseMoveEvent(self,event)->None:
        if self.dragging:self._seek(event.position().x())
    def mouseReleaseEvent(self,event)->None:
        if self.dragging:self._seek(event.position().x())
        self.dragging=False
    def resizeEvent(self,event)->None:
        self.static_layer_dirty=True
        super().resizeEvent(event)
    def _rebuild_static_layer(self)->None:
        if self.width()<=0 or self.height()<=0:return
        layer=QPixmap(self.size()); layer.fill(QColor("#000000")); painter=QPainter(layer); painter.setPen(Qt.NoPen)
        for start,end,level in self.windows:
            if not level:continue
            x=start/self.duration_ms*self.width();w=max(1.0,(end-start)/self.duration_ms*self.width());h=max(1.0,level*(self.height()-8))
            intensity=level; green=round(255+(216-255)*intensity); blue=round(255+(77-255)*intensity)
            painter.fillRect(QRectF(x,self.height()-h,w,h),QColor(255,green,blue))
        painter.end(); self.static_layer=layer; self.static_layer_dirty=False
    def paintEvent(self,event)->None:
        if self.static_layer_dirty or self.static_layer.size()!=self.size(): self._rebuild_static_layer()
        painter=QPainter(self); painter.drawPixmap(0,0,self.static_layer)
        if self.viewport_end>self.viewport_start:
            vx=self.viewport_start/self.duration_ms*self.width(); vw=(self.viewport_end-self.viewport_start)/self.duration_ms*self.width()
            painter.setPen(QPen(QColor(255,255,255,85),1)); painter.setBrush(Qt.NoBrush); painter.drawRect(QRectF(vx,1,vw,self.height()-2))
        x=self.current_time/self.duration_ms*self.width();painter.setPen(QPen(QColor("#ffffff"),2));painter.drawLine(round(x),0,round(x),self.height())


def freeze_preview_value(value):
    """Convert nested preview parameters into stable, hashable cache data."""
    if isinstance(value, dict):
        return tuple(sorted((str(key), freeze_preview_value(item)) for key, item in value.items()))
    if isinstance(value, (list, tuple)):
        return tuple(freeze_preview_value(item) for item in value)
    if isinstance(value, set):
        return tuple(sorted(freeze_preview_value(item) for item in value))
    return value

class SnapSlider(QWidget):
    """Beat snap as a slider over SNAP_DIVISORS: "Snap", the track, "1/4".

    It stands in for the QComboBox each editor page had, so it answers the
    handful of calls those combos got -- currentData, findData,
    setCurrentIndex, currentIndexChanged -- and none of their callers change.
    A combo hid 22 divisors behind a click; the slider shows where the current
    one sits among them, with the ones people use labelled underneath.

    The wheel is the slider's own (`_page_wheel_target` leaves every
    QAbstractSlider alone), which is what the combo's wheel did too.
    """

    currentIndexChanged = Signal(int)

    # The divisors labelled under the track, and clickable. Not 2, 3 and 6:
    # 1-16 are consecutive steps about 10px apart, so their labels ran into
    # one another as "1234". Every divisor is still a drag or a notch away.
    TICKS = (1, 4, 8, 12, 16, 32, 64)
    HANDLE = 14
    STYLE = f"""
        QSlider::groove:horizontal {{ height: 4px; border-radius: 2px; background: #3a4554; }}
        QSlider::sub-page:horizontal {{ border-radius: 2px; background: #ff66aa; }}
        QSlider::handle:horizontal {{
            width: {HANDLE}px; height: {HANDLE}px; margin: -5px 0; border-radius: 7px;
            background: {ACCENT_PINK}; border: 1px solid #ff9dcc;
        }}
    """

    def __init__(self, divisor: int = 4, parent: QWidget | None = None) -> None:
        super().__init__(parent)
        self.divisors = tuple(SNAP_DIVISORS)
        layout = QGridLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setHorizontalSpacing(8)
        layout.setVerticalSpacing(0)
        caption = QLabel(tr("MainWindow", "Snap"))
        caption.setStyleSheet("color: #7d8794; font-size: 11px; font-weight: 700;")
        layout.addWidget(caption, 0, 0, 2, 1)
        self.slider = QSlider(Qt.Horizontal)
        self.slider.setRange(0, len(self.divisors) - 1)
        self.slider.setPageStep(1)
        self.slider.setFixedWidth(220)
        self.slider.setStyleSheet(self.STYLE)
        self.slider.setFocusPolicy(Qt.NoFocus)
        layout.addWidget(self.slider, 0, 1)
        self.ticks = _SnapTicks(self)
        layout.addWidget(self.ticks, 1, 1)
        self.value_label = QLabel()
        self.value_label.setStyleSheet(f"color: {ACCENT_PINK}; font-weight: 700;")
        # Wide enough for "1/64", so the track does not shift as it changes.
        self.value_label.setMinimumWidth(self.value_label.fontMetrics().horizontalAdvance("1/64") + 6)
        layout.addWidget(self.value_label, 0, 2, 2, 1)
        self.slider.valueChanged.connect(self._slider_moved)
        self.slider.valueChanged.connect(self.ticks.update)
        self.setCurrentIndex(max(0, self.findData(divisor)))

    def _slider_moved(self, index: int) -> None:
        self.value_label.setText(f"1/{self.divisors[index]}")
        self.slider.setToolTip(tr("MainWindow", "Beat snap") + f" 1/{self.divisors[index]}")
        self.currentIndexChanged.emit(index)

    def wheelEvent(self, event) -> None:
        # Over the caption, the ticks or the value, as over the track: one
        # notch is one divisor, the way the combo's wheel was.
        delta = event.angleDelta().y() or event.angleDelta().x()
        if delta:
            self.slider.setValue(self.slider.value() + (1 if delta > 0 else -1))
        event.accept()

    def currentIndex(self) -> int:
        return self.slider.value()

    def currentData(self) -> int:
        return self.divisors[self.slider.value()]

    def count(self) -> int:
        return len(self.divisors)

    def findData(self, divisor) -> int:
        try:
            return self.divisors.index(int(divisor))
        except (ValueError, TypeError):
            return -1

    def setCurrentIndex(self, index: int) -> None:
        # blockSignals on this widget still silences a caller's "quiet" set,
        # as it did on the combo: the slider moves, but currentIndexChanged is
        # emitted by this widget, and that is the signal that is blocked.
        self.slider.setValue(index)
        # The label has to exist on the first call too, when nothing moved.
        self.value_label.setText(f"1/{self.divisors[index]}")

    def tick_x(self, index: int) -> float:
        """Where the handle's centre sits for `index`, in slider coordinates."""
        span = self.slider.width() - self.HANDLE
        return self.HANDLE / 2 + span * index / max(1, len(self.divisors) - 1)


class _SnapTicks(QWidget):
    """The labelled divisors under a SnapSlider's track. Click one to pick it."""

    def __init__(self, owner: SnapSlider) -> None:
        super().__init__(owner)
        self.owner = owner
        font = QFont(self.font())
        font.setPixelSize(10)
        self.setFont(font)
        self.setFixedHeight(QFontMetrics(font).height())
        self.setCursor(Qt.PointingHandCursor)

    def _positions(self):
        for divisor in SnapSlider.TICKS:
            index = self.owner.findData(divisor)
            if index >= 0:
                yield divisor, index, self.owner.tick_x(index)

    def paintEvent(self, event) -> None:
        painter = QPainter(self)
        painter.setPen(theme.color("#7d8794"))
        metrics = painter.fontMetrics()
        current = self.owner.currentData()
        for divisor, _index, x in self._positions():
            text = str(divisor)
            if divisor == current:
                painter.setPen(theme.color("#e8edf3"))
            painter.drawText(QPointF(x - metrics.horizontalAdvance(text) / 2, metrics.ascent()), text)
            if divisor == current:
                painter.setPen(theme.color("#7d8794"))

    def mousePressEvent(self, event) -> None:
        x = event.position().x()
        nearest = min(self._positions(), key=lambda item: abs(item[2] - x), default=None)
        if nearest is not None:
            self.owner.slider.setValue(nearest[1])
            self.update()


class ElidedLabel(QLabel):
    def __init__(self, text: str = "", parent=None) -> None:
        super().__init__(text, parent)

        self._full_text = text
        # Plain, never auto-detected rich text: what this shows comes from
        # .osu files (names, difficulty, artist), and a QLabel on AutoText
        # renders a difficulty called "<img src=...>" as markup.
        self.setTextFormat(Qt.PlainText)
        self.setSizePolicy(
            QSizePolicy.Ignored,
            QSizePolicy.Preferred,
        )
        self.setMinimumWidth(0)
        self.setToolTip(text)

    def setText(self, text: str) -> None:
        self._full_text = str(text)
        self.setToolTip(self._full_text)
        self._update_elided_text()

    def resizeEvent(self, event) -> None:
        super().resizeEvent(event)
        self._update_elided_text()

    def _update_elided_text(self) -> None:
        available_width = max(0, self.width() - 4)

        elided = self.fontMetrics().elidedText(
            self._full_text,
            Qt.ElideRight,
            available_width,
        )

        super().setText(elided)


def view_type_caption(view_type: str) -> str:
    """The name AddViewDialog gives `view_type`, for a view's header.

    Literal tr() calls, one per type, for the same reason AddViewDialog uses
    them: the i18n gate scans for tr("context", "constant") pairs.
    """
    return {
        "chart": tr("MainWindow", "Chart"),
        "chart_regular": tr("MainWindow", "Regular Chart Only"),
        "chart_fake_slider": tr("MainWindow", "Fake Sliders Only"),
        "chart_barline": tr("MainWindow", "Barlines Only"),
        "sv": tr("MainWindow", "SV Editor"),
        "kiai_sound": tr("MainWindow", "Kiai and Sound Volume"),
        "gameplay": tr("MainWindow", "Gameplay Viewer"),
        "gameplay_regular": tr("MainWindow", "Gameplay: Regular Chart Only"),
        "gameplay_fake_slider": tr("MainWindow", "Gameplay: Fake Sliders Only"),
        "gameplay_barline": tr("MainWindow", "Gameplay: Barlines Only"),
        "density": tr("MainWindow", "Density"),
    }.get(view_type, "")


class EditorViewFrame(QWidget):
    """One view with a header on its left: what it is, and close/move/lock.

    The header used to be a row of four pink buttons above every view, with
    the difficulty at the far right of it. Stacked seven deep on the gimmick
    page that was ~180px of chrome and 28 pink buttons, all equally loud. It
    is now a strip beside the view (HEADER_WIDTH): the kind of view, then the
    name -- the difficulty in pink on the Editor page, the layer's own name on
    the gimmick page -- and the four buttons, quiet, shown while the pointer
    is over the view or the view is locked. Every view loses the same width,
    so the hit positions, each centred in its own view, still line up.

    The difficulty is still shown once per view and nowhere else; the group
    header above a difficulty's views carries no label.

    Holds no MainWindow reference; the owner wires content in via set_content
    and listens for `closed`.
    """

    closed = Signal(object)
    # (frame, -1 up / +1 down). Two buttons rather than one, because a single
    # glyph cannot say which way -- and a drag handle would have to fight the
    # views underneath it, every one of which already drags.
    move_requested = Signal(object, int)
    # (frame, where the pointer is, global). The header *is* a handle after
    # all: it is the one part of a view that does not drag notes. Pressed and
    # carried past the system's drag distance, the owner starts a ReorderDrag.
    drag_started = Signal(object, object)

    HEADER_WIDTH = 148
    # The frame's own sheet is selector-less, so it reaches every descendant:
    # each rule below names its own border to undo that.
    #
    # Edge to edge since 2026-10-07: square, with one divider under each view
    # and no gap between them, so the page's backdrop shows only where View
    # opacity lets it. It used to show in a strip between every pair of views.
    FRAME_STYLE = "background: {ground}; border: 0; border-bottom: 1px solid #303947; border-radius: 0;"
    # The approved mockup's focused lane: a 2px rim in the theme's focus colour
    # rather than a 1px one in a muted shade of it, which beside the other
    # lanes' 1px #303947 read as no difference at all.
    # The 2px rim is drawn *over* the view by `_FrameOverlay`, so it can carry
    # the song list's running lights -- and so focusing a view changes nothing
    # about its box. It used to inset the lane by 2px a side, which narrowed
    # it by 4px and slid every snap tick off-centre (owner, 2026-10-08).
    # How far the other views fade while one is focused (owner, 2026-10-08):
    # a wash of the page's own ground over them, not View opacity, which is
    # how much of the map shows through and stays as set.
    UNFOCUSED_WASH = 0.45
    HEADER_STYLE = "QWidget#viewHeader { border: 0; border-right: 1px solid #303947; border-radius: 0; }"
    # The song select's selection: a pink rim at the left edge and a tint.
    FOCUSED_HEADER_STYLE = (
        "QWidget#viewHeader { border: 0; border-left: 3px solid #ff66aa;"
        " border-right: 1px solid #303947; border-radius: 0;"
        " background: qlineargradient(x1:0, y1:0, x2:1, y2:0,"
        " stop:0 rgba(255,102,170,46), stop:0.7 rgba(255,102,170,10)); }"
    )

    def __init__(self, view_type: str, difficulty_label: str, compact: bool = False) -> None:
        super().__init__()
        self.view_type = view_type
        self.locked = False
        self.compact = compact
        self.focused = False
        self.content: QWidget | None = None

        self.setStyleSheet(self._frame_style())
        # A plain QWidget does not paint its own sheet: without this the rim
        # above was never drawn, focused or not, and nothing marked the view
        # the tool row acts on but the header's left edge. Its content paints
        # opaque (WA_OpaquePaintEvent), so this costs nothing per frame.
        self.setAttribute(Qt.WA_StyledBackground, True)

        layout = QHBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 1)
        layout.setSpacing(0)

        self.header = QWidget()
        self.header.setObjectName("viewHeader")
        self.header.setAttribute(Qt.WA_StyledBackground, True)
        self.header.setFixedWidth(self.HEADER_WIDTH)
        self.header.setStyleSheet(self.HEADER_STYLE)
        header = QVBoxLayout(self.header)
        header.setContentsMargins(10, 5 if compact else 7, 6, 4 if compact else 6)
        header.setSpacing(1)

        # A gimmick layer's name already says what it is ("SV (barlines)"),
        # so only the Editor page's views, named by difficulty, get a kind.
        self.kind_label = QLabel("" if compact else view_type_caption(view_type).upper())
        self.kind_label.setStyleSheet(self._caption_style(False))
        header.addWidget(self.kind_label)
        # Hidden once parented, never shown here: setVisible(True) on a label
        # with no parent yet makes it a top-level window of its own, which
        # flashed on screen and hung test_gimmick_editor's setUp.
        self.kind_label.setHidden(not self.kind_label.text())

        # Wrapped, not elided: two lines fit in the shortest view, and
        # "The Pharaoh's C..." cut off the part that told two apart.
        self.difficulty_name_label = QLabel()
        self.difficulty_name_label.setTextFormat(Qt.PlainText)
        self.difficulty_name_label.setWordWrap(True)
        self.difficulty_name_label.setStyleSheet(self._name_style(False))
        # Word wrap only breaks at spaces, so a one-word name wider than the
        # header ("worldwidesuperstar") ran under the view beside it instead.
        # Under a stylesheet font() still reports the base weight, so the
        # measure is a bold copy -- the weight the label is drawn in.
        bold = QFont(self.difficulty_name_label.font())
        bold.setBold(True)
        room = self.HEADER_WIDTH - header.contentsMargins().left() - header.contentsMargins().right()
        self.difficulty_name_label.setText(breakable_words(difficulty_label, QFontMetrics(bold), room))
        self.difficulty_name_label.setToolTip(difficulty_label)
        header.addWidget(self.difficulty_name_label)
        header.addStretch(1)

        # Quiet until wanted: shown while the pointer is over this view, and
        # always while it is locked, so a locked view says so.
        self.controls = QWidget()
        self.controls.setStyleSheet("border: 0; background: transparent;")
        controls = QHBoxLayout(self.controls)
        controls.setContentsMargins(0, 0, 0, 0)
        controls.setSpacing(1)
        chrome_button_style = (
            "QPushButton { background: transparent; color: #7d8794; border: 0;"
            " border-radius: 4px; font-weight: 600; padding: 1px 5px; }"
            "QPushButton:hover { background: #2a3341; color: #e8edf3; }"
            "QPushButton:checked { color: #ffb347; }"
        )

        self.close_button = QPushButton("\u2715")
        self.close_button.setToolTip(tr("MainWindow", "Close view"))
        self.close_button.clicked.connect(lambda: self.closed.emit(self))
        self.move_up_button = QPushButton("\u25b2")
        self.move_up_button.setToolTip(tr("MainWindow", "Move view up"))
        self.move_up_button.clicked.connect(lambda: self.move_requested.emit(self, -1))
        self.move_down_button = QPushButton("\u25bc")
        self.move_down_button.setToolTip(tr("MainWindow", "Move view down"))
        self.move_down_button.clicked.connect(lambda: self.move_requested.emit(self, 1))
        self.lock_button = QPushButton("\U0001f512")
        self.lock_button.setCheckable(True)
        self.lock_button.setToolTip(tr("MainWindow", "Lock view (read-only)"))
        self.lock_button.toggled.connect(self._set_locked)
        # In the order the row reads: move it, freeze it, get rid of it.
        for button in (self.move_up_button, self.move_down_button, self.lock_button, self.close_button):
            button.setFocusPolicy(Qt.NoFocus)
            button.setStyleSheet(chrome_button_style)
            controls.addWidget(button)
        controls.addStretch(1)
        header.addWidget(self.controls)
        self.controls.setVisible(False)

        layout.addWidget(self.header)
        self._content_layout = QVBoxLayout()
        self._content_layout.setContentsMargins(0, 0, 0, 0)
        layout.addLayout(self._content_layout, 1)
        tick_while_shown(self, self._repaint_rim)
        # The labels take no clicks, so a press on them reaches the header.
        # The buttons take theirs, and keep the arrow.
        self.header.setCursor(Qt.OpenHandCursor)
        for button in self.controls.findChildren(QPushButton):
            button.setCursor(Qt.ArrowCursor)
        self._drag_from: QPoint | None = None
        self.header.installEventFilter(self)
        self.dimmed = False
        self._overlay = _FrameOverlay(self)

    def eventFilter(self, watched, event) -> bool:
        if watched is not self.header:
            return False
        kind = event.type()
        if kind == QEvent.MouseButtonPress and event.button() == Qt.LeftButton:
            self._drag_from = event.globalPosition().toPoint()
        elif kind == QEvent.MouseMove and self._drag_from is not None:
            here = event.globalPosition().toPoint()
            if (here - self._drag_from).manhattanLength() >= QApplication.startDragDistance():
                self._drag_from = None
                self.drag_started.emit(self, here)
                return True
        elif kind == QEvent.MouseButtonRelease:
            self._drag_from = None
        return False

    def _rim_region(self) -> QRegion:
        outer = self.rect()
        return QRegion(outer).subtracted(QRegion(outer.adjusted(2, 2, -2, -2)))

    def _repaint_rim(self) -> None:
        # The rim only: the lanes under it are repainted by the playhead, and
        # a frame-wide update here would repaint them all a second time.
        if self.focused:
            self._overlay.update(self._rim_region())

    def resizeEvent(self, event) -> None:
        super().resizeEvent(event)
        self._overlay.setGeometry(self.rect())

    def _show_overlay(self) -> None:
        # Hidden when it has nothing to draw, so an ordinary view pays nothing.
        self._overlay.setVisible(self.focused or self.dimmed)
        self._overlay.raise_()
        self._overlay.update()

    def set_dimmed(self, dimmed: bool) -> None:
        """Fade this view while another one on its page is focused.

        Never the gameplay preview (owner, 2026-10-09): it is watched, not
        edited, and the point of it is seeing the result of an edit made in
        another view -- the moment that faded it."""
        dimmed = dimmed and self.view_type != "gameplay"
        if dimmed != self.dimmed:
            self.dimmed = dimmed
            self._show_overlay()

    def showEvent(self, event) -> None:
        # Measured after polish (and after parenting, which is what makes the
        # app-wide sheet apply): a typed width once left the glyphs negative
        # room and Qt drew nothing.
        super().showEvent(event)
        equalize_button_widths((
            self.close_button, self.move_up_button, self.move_down_button,
            self.lock_button,
        ))

    def enterEvent(self, event) -> None:
        super().enterEvent(event)
        self.controls.setVisible(True)

    def leaveEvent(self, event) -> None:
        super().leaveEvent(event)
        self.controls.setVisible(self.locked)

    def set_focused(self, focused: bool) -> None:
        """Mark this as the view the tool row acts on. Nothing on screen said
        which one that was; the row follows whichever view last had focus."""
        if focused == self.focused:
            return
        self.focused = focused
        self.header.setStyleSheet(self.FOCUSED_HEADER_STYLE if focused else self.HEADER_STYLE)
        self._show_overlay()
        # The caption names what is focused, in the accent, as in the mockup.
        self.kind_label.setStyleSheet(self._caption_style(focused))
        self.difficulty_name_label.setStyleSheet(self._name_style(focused))

    def _frame_style(self) -> str:
        ground = view_ground("#1b212b")
        rgba = f"rgba({ground.red()}, {ground.green()}, {ground.blue()}, {ground.alpha()})"
        return self.FRAME_STYLE.format(ground=rgba)

    def refresh_ground(self) -> None:
        """Re-read View opacity (`set_view_opacity`)."""
        self.setStyleSheet(self._frame_style())

    def _caption_style(self, focused: bool) -> str:
        colour = "#ff9dcc" if focused else "#7d8794"
        return f"color: {colour}; font-size: 10px; font-weight: 700; border: 0; background: transparent;"

    def _name_style(self, focused: bool) -> str:
        # A gimmick layer has no caption, so there the name carries the mark.
        colour = "#ff9dcc" if focused and self.compact else ("#e8edf3" if self.compact else ACCENT_PINK)
        return f"color: {colour}; font-weight: 700; border: 0; background: transparent;"

    def set_content(self, widget: QWidget) -> None:
        self.content = widget
        self._content_layout.addWidget(widget)
        self._overlay.raise_()  # a child added later stacks above it

    def _set_locked(self, locked: bool) -> None:
        self.locked = locked
        if self.content is not None:
            self.content.setEnabled(not locked)
        self.controls.setVisible(locked or self.underMouse())


class _FrameOverlay(QWidget):
    """What lies over a view without being part of it: the focused view's
    living rim, or the wash that fades the others. Takes no input and has no
    layout space, so neither changes where anything in the view is."""

    def __init__(self, frame: EditorViewFrame) -> None:
        super().__init__(frame)
        self.frame = frame
        self.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        self.setAttribute(Qt.WA_NoSystemBackground, True)
        self.hide()

    def paintEvent(self, event) -> None:
        frame = self.frame
        painter = QPainter(self)
        if frame.focused:
            paint_living_rim(painter, QRectF(self.rect()), 0, 2, True)
        elif frame.dimmed:
            wash = theme.color("#11151c")
            wash.setAlphaF(EditorViewFrame.UNFOCUSED_WASH)
            painter.fillRect(event.rect(), wash)


BACKDROP_OPACITY_DEFAULT_PERCENT = 25

# The song select's chart preview, as a share of a gameplay view's height.
SONG_SELECT_PREVIEW_DEFAULT_PERCENT = 67
SONG_SELECT_PREVIEW_MIN_PERCENT = 50
SONG_SELECT_PREVIEW_MAX_PERCENT = 75
# Its hit target, in playfield units from the left: osu!'s is 256, which
# leaves the input drum's width empty in a view that draws no drum. 120 still
# clears a finisher's radius (73) with room for the target's rim.
SONG_SELECT_HIT_X_UNITS = 120.0

# Settings > View opacity: how much of each editor view's own ground covers
# the page's map backdrop. 100 is the old look and the cheap path -- the lanes
# stay WA_OpaquePaintEvent, so the backdrop is never repainted under them.
VIEW_OPACITY_DEFAULT_PERCENT = 100
_view_ground_alpha = 255


def view_ground_is_opaque() -> bool:
    return _view_ground_alpha >= 255


def view_ground(colour: str) -> QColor:
    """A lane's ground colour at the View opacity in force."""
    ground = theme.color(colour)
    ground.setAlpha(_view_ground_alpha)
    return ground


def set_view_opacity(percent: int, widgets) -> None:
    """Apply View opacity to `widgets` (lanes and frames) and to every one
    built after this. Live: Settings calls it while its slider moves."""
    global _view_ground_alpha
    _view_ground_alpha = round(max(0, min(100, int(percent))) * 2.55)
    for widget in widgets:
        if not getattr(widget, "follows_view_opacity", True):
            continue
        if isinstance(widget, EditorViewFrame):
            widget.refresh_ground()
        else:
            widget.setAttribute(Qt.WA_OpaquePaintEvent, view_ground_is_opaque())
            widget.update()


class MapBackdrop(QWidget):
    """A page's floor: the window's navy with the active map's background
    faded into it, cropped to fill.

    One per page rather than one per lane, so ten open difficulties cost
    nothing extra. The faded image is baked into a single cached pixmap and
    rebuilt only when the size, the picture or the opacity changes, so a paint
    is one blit -- and the lanes that sit on it are opaque and say so
    (WA_OpaquePaintEvent), which keeps their per-frame repaints from reaching
    it at all.
    """

    @staticmethod
    def ground() -> QColor:
        # Read as it paints, so a theme switch reaches it (theme.switch).
        return theme.color("#191f29")

    def __init__(self) -> None:
        super().__init__()
        self.setObjectName("mapBackdrop")
        self._path: Path | None = None
        self._source: QPixmap | None = None
        self._percent = BACKDROP_OPACITY_DEFAULT_PERCENT
        self._baked: QPixmap | None = None

    def set_background(self, path: Path | None) -> None:
        if path == self._path:
            return
        self._path = path
        source = QPixmap(str(path)) if path is not None else None
        self._source = source if source is not None and not source.isNull() else None
        self._baked = None
        self.update()

    def set_opacity(self, percent: int) -> None:
        percent = max(0, min(100, int(percent)))
        if percent != self._percent:
            self._percent = percent
            self._baked = None
            self.update()

    def _bake(self) -> QPixmap:
        size = self.size()
        baked = QPixmap(size)
        baked.fill(self.ground())
        if self._source is not None and self._percent > 0:
            cover = self._source.scaled(size, Qt.KeepAspectRatioByExpanding, Qt.SmoothTransformation)
            painter = QPainter(baked)
            painter.setOpacity(self._percent / 100.0)
            painter.drawPixmap((size.width() - cover.width()) // 2, (size.height() - cover.height()) // 2, cover)
            painter.end()
        return baked

    def paintEvent(self, event) -> None:
        if self._source is None or self._percent == 0:
            QPainter(self).fillRect(event.rect(), self.ground())
            return
        if self._baked is None or self._baked.size() != self.size():
            self._baked = self._bake()
        QPainter(self).drawPixmap(event.rect(), self._baked, event.rect())


def see_through(*widgets: QWidget) -> None:
    """Let a page's backdrop show through these chrome containers.

    The window's `QWidget { background }` rule paints every plain widget
    opaque, so the ones between a page and its lanes opt out by property (see
    the `seeThrough` rule in MainWindow's stylesheet) rather than the rule
    being loosened for everything. A scroll area's container is also filled by
    QScrollArea itself, which the stylesheet does not reach.
    """
    for widget in widgets:
        widget.setProperty("seeThrough", True)
        widget.setAutoFillBackground(False)


def breakable_words(text: str, metrics: QFontMetrics, width: int) -> str:
    """`text` with a zero-width break point between the letters of any word
    wider than `width`, so word wrap can split it. Words that fit are left
    whole: breaking every word would split ordinary names mid-word too."""
    def split(word: str) -> str:
        return ZERO_WIDTH_SPACE.join(word) if metrics.horizontalAdvance(word) > width else word
    return " ".join(split(word) for word in text.split(" "))


ZERO_WIDTH_SPACE = "\u200b"


def opaque_strip(strip: QHBoxLayout) -> QWidget:
    """The page's snap / time / timing bar / transport / mods row, on the app's
    own ground rather than the map's backdrop.

    As a bare layout it sat directly on the backdrop, and the backdrop rule
    makes every label on the page transparent, so the art showed between and
    behind the controls -- a strip of tools reading as part of the picture.
    """
    holder = QWidget()
    holder.setObjectName("controlStrip")
    holder.setAttribute(Qt.WA_StyledBackground, True)
    strip.setContentsMargins(4, 3, 4, 3)
    holder.setLayout(strip)
    return holder


def see_through_row(row: QWidget) -> QWidget:
    """`row` and the plain containers inside it. Buttons, boxes and other
    controls keep their own fills: only a bare QWidget is chrome."""
    see_through(row, *(w for w in row.findChildren(QWidget) if type(w) is QWidget))
    return row


def add_view_row(on_click) -> QPushButton:
    """"+ Add view" as a dashed row under a page's stack of views.

    It was a "+" in the playback strip, beside the view-size stepper's own
    +/-, and three "+" in a row said nothing about which one opened a view.
    Under the stack is where the new view appears. Not inside the stack's
    layout: that ends in its stretch, and group reordering and insertion both
    count on it.
    """
    button = QPushButton("+  " + tr("MainWindow", "Add view"))
    button.setToolTip(tr("MainWindow", "open new view"))
    button.setFocusPolicy(Qt.NoFocus)
    button.setStyleSheet(
        "QPushButton { background: transparent; color: #7d8794; border: 1px dashed #3a4554;"
        " border-radius: 6px; padding: 5px; font-weight: 600; }"
        "QPushButton:hover { color: #f3a6bd; border-color: #b0587f; background: rgba(255,102,170,13); }"
    )
    button.clicked.connect(on_click)
    return button


def is_text_entry(widget) -> bool:
    """A box the keyboard types into: what Esc leaves before anything else."""
    return isinstance(widget, (QLineEdit, QAbstractSpinBox, QTextEdit, QPlainTextEdit)) or (
        isinstance(widget, QComboBox) and widget.isEditable())


def add_view_on_empty_right_click(container: QWidget, on_click) -> None:
    """Right click on the bare space under a page's views is "Add view" too.

    A context menu request a child leaves unhandled travels up to its parent,
    so a right click on a view arrives here as well. "No child under the
    point" was the test, and it held in the 10px gaps *between* views too --
    a right click meant for a view's edge opened the dialog (owner's report).
    So: below the last view, and nowhere else.
    """
    def below_the_views(pos) -> bool:
        # Never mid-drag (owner, 2026-10-08): a selection box dragged down
        # past the last view puts the pointer here with the left button held,
        # and a right click then is part of that gesture, not a request.
        if QApplication.mouseButtons() & Qt.LeftButton:
            return False
        children = container.findChildren(QWidget, options=Qt.FindDirectChildrenOnly)
        bottom = max((c.geometry().bottom() for c in children if c.isVisibleTo(container)), default=-1)
        return pos.y() > bottom

    container.setContextMenuPolicy(Qt.CustomContextMenu)
    container.customContextMenuRequested.connect(
        lambda pos: on_click() if below_the_views(pos) else None)


class AddViewDialog(QDialog):
    """Choose a view type and difficulty for a new view.

    The two editors offer their own lists. The layer-restricted types -- one
    gimmick layer's objects, as a chart or as a preview -- only answer a
    question the gimmick page asks, and on the Editor page they were eight
    entries between the five that page is actually for. The plain views of a
    whole chart are offered in both, since reading the real chart is as useful
    beside a gimmick layer as it is on its own.
    """

    def __init__(
        self, difficulties: list[tuple[str, Path]], parent=None,
        current: Path | None = None, gimmick: bool = False,
    ) -> None:
        super().__init__(parent)
        self.setWindowTitle(tr("MainWindow", "Add view"))
        icon = application_icon()
        if not icon.isNull():
            self.setWindowIcon(icon)

        layout = QFormLayout(self)

        self.type_combo = QComboBox()
        # Literal tr() calls, one per type: the i18n coverage gate statically
        # scans for tr("context", "constant") pairs and would silently miss a
        # dynamic VIEW_TYPE_LABELS[key] lookup here.
        self.type_combo.addItem(tr("MainWindow", "Chart"), "chart")
        if gimmick:
            self.type_combo.addItem(tr("MainWindow", "Regular Chart Only"), "chart_regular")
            self.type_combo.addItem(tr("MainWindow", "Fake Sliders Only"), "chart_fake_slider")
            self.type_combo.addItem(tr("MainWindow", "Barlines Only"), "chart_barline")
        self.type_combo.addItem(tr("MainWindow", "SV Editor"), "sv")
        self.type_combo.addItem(tr("MainWindow", "Kiai and Sound Volume"), "kiai_sound")
        self.type_combo.addItem(tr("MainWindow", "Gameplay Viewer"), "gameplay")
        if gimmick:
            self.type_combo.addItem(tr("MainWindow", "Gameplay: Regular Chart Only"), "gameplay_regular")
            self.type_combo.addItem(tr("MainWindow", "Gameplay: Fake Sliders Only"), "gameplay_fake_slider")
            self.type_combo.addItem(tr("MainWindow", "Gameplay: Barlines Only"), "gameplay_barline")
        self.type_combo.addItem(tr("MainWindow", "Density"), "density")
        layout.addRow(tr("MainWindow", "View type"), self.type_combo)

        # The gimmick page edits exactly one difficulty, so it keeps the plain
        # combo it always had -- one entry, disabled by the caller. Only the
        # Editor page gets the list below.
        self.difficulty_combo: QComboBox | None = None
        self.difficulty_list: QListWidget | None = None
        self.all_difficulties_check: QCheckBox | None = None
        if gimmick:
            self.difficulty_combo = QComboBox()
            for label, path in difficulties:
                self.difficulty_combo.addItem(label, str(path))
            found = (
                self.difficulty_combo.findData(str(current))
                if current is not None else -1
            )
            if found >= 0:
                self.difficulty_combo.setCurrentIndex(found)
            layout.addRow(tr("MainWindow", "Difficulty"), self.difficulty_combo)
            self._add_buttons(layout)
            return

        # A checkable list rather than a combo: a mapset is several
        # difficulties of one song, and opening a chart for each of them meant
        # walking this dialog once per difficulty. Ticking is also how "all of
        # them" is expressed, so there is no separate All entry competing with
        # the real ones for a slot in the list.
        self.difficulty_list = QListWidget()
        self.difficulty_list.setSelectionMode(QAbstractItemView.NoSelection)
        for label, path in difficulties:
            item = QListWidgetItem(label)
            item.setData(Qt.UserRole, str(path))
            item.setFlags(item.flags() | Qt.ItemIsUserCheckable)
            item.setCheckState(Qt.Unchecked)
            self.difficulty_list.addItem(item)
        # The difficulty being edited, not whichever one sorts first: adding a
        # view is nearly always about the one already open. Falls back to the
        # first, so the dialog never opens with nothing to add.
        self._check_default(str(current) if current is not None else None)
        self._size_difficulty_list()
        self.difficulty_list.itemChanged.connect(self._difficulty_checked)
        smooth(self.difficulty_list)

        self.all_difficulties_check = QCheckBox(
            tr("MainWindow", "All taiko difficulties"))
        self.all_difficulties_check.toggled.connect(self._toggle_all_difficulties)

        difficulty_box = QWidget()
        difficulty_rows = QVBoxLayout(difficulty_box)
        difficulty_rows.setContentsMargins(0, 0, 0, 0)
        difficulty_rows.setSpacing(4)
        difficulty_rows.addWidget(self.all_difficulties_check)
        difficulty_rows.addWidget(self.difficulty_list)
        layout.addRow(tr("MainWindow", "Difficulty"), difficulty_box)
        self._add_buttons(layout)

    def _add_buttons(self, layout: QFormLayout) -> None:
        buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        buttons.accepted.connect(self.accept)
        buttons.rejected.connect(self.reject)
        layout.addRow(buttons)

    def _size_difficulty_list(self) -> None:
        """Tall enough to show every difficulty, up to most of the screen.

        Derived from the rows rather than a typed height: a typed 140px showed
        four difficulties and made a mapset of twelve a scrolling exercise in a
        dialog whose whole job is ticking them. Bounded by the screen the
        dialog opens on, so a set of forty still leaves the OK button on it.
        """
        rows = self.difficulty_list.count()
        row_height = max(
            self.difficulty_list.sizeHintForRow(0) if rows else 0,
            self.fontMetrics().height() + 6,
        )
        frame = 2 * self.difficulty_list.frameWidth() + 4
        wanted = rows * row_height + frame
        screen = self.screen() or QApplication.primaryScreen()
        ceiling = (
            int(screen.availableGeometry().height() * 0.6) if screen is not None
            else wanted
        )
        self.difficulty_list.setMinimumHeight(min(wanted, ceiling))

    def _items(self):
        if self.difficulty_list is None:
            return []
        return [
            self.difficulty_list.item(index)
            for index in range(self.difficulty_list.count())
        ]

    def _check_default(self, wanted: str | None) -> None:
        """Tick the difficulty being edited, or the first one."""
        items = self._items()
        if not items:
            return
        match = next(
            (item for item in items if item.data(Qt.UserRole) == wanted), items[0])
        match.setCheckState(Qt.Checked)

    def _toggle_all_difficulties(self, checked: bool) -> None:
        # Blocked because itemChanged fires per row and would otherwise untick
        # this box again on the first one it sets.
        self.difficulty_list.blockSignals(True)
        for item in self._items():
            item.setCheckState(Qt.Checked if checked else Qt.Unchecked)
        self.difficulty_list.blockSignals(False)

    def _difficulty_checked(self, _item) -> None:
        """Unticking one row is no longer "all of them"."""
        every = all(item.checkState() == Qt.Checked for item in self._items())
        if every != self.all_difficulties_check.isChecked():
            self.all_difficulties_check.blockSignals(True)
            self.all_difficulties_check.setChecked(every)
            self.all_difficulties_check.blockSignals(False)

    def selected_view_type(self) -> str:
        return str(self.type_combo.currentData())

    def selected_difficulty_paths(self) -> list[Path]:
        if self.difficulty_combo is not None:
            return [Path(self.difficulty_combo.currentData())]
        return [
            Path(item.data(Qt.UserRole))
            for item in self._items()
            if item.checkState() == Qt.Checked
        ]

    def selected_difficulty_path(self) -> Path:
        """The first ticked difficulty.

        Kept for the callers that only ever want one -- the gimmick page, which
        offers a single entry, and the tests that pin which difficulty the
        dialog opens on.
        """
        paths = self.selected_difficulty_paths()
        return paths[0] if paths else Path(self._items()[0].data(Qt.UserRole))


class GimmickEntryDialog(QDialog):
    """Asked once per difficulty, the first time the Gimmick tab is opened.

    Gimmick editing fills a map with 60000 BPM lines and objects that cannot be
    hit. That is not something to do to the only copy of a chart by accident, so
    the default answer creates a separate difficulty and the dialog says plainly
    what each button does before anything is written.

    The answer is remembered permanently (gimmick_index.json), so this is asked
    once per difficulty rather than once per visit.
    """

    CREATE = "create"
    USE_CURRENT = "use_current"
    CANCEL = "cancel"

    def __init__(self, version: str, parent=None, references: list[tuple[str, Path]] | None = None) -> None:
        super().__init__(parent)
        self.setWindowTitle(tr("MainWindow", "Gimmick editor"))
        icon = application_icon()
        if not icon.isNull():
            self.setWindowIcon(icon)
        self._action = self.CANCEL

        layout = QVBoxLayout(self)
        layout.setSpacing(12)

        headline = QLabel(tr("MainWindow", "Edit gimmicks on a new difficulty?"))
        headline.setStyleSheet("font-weight: 600;")
        layout.addWidget(headline)

        body = QLabel(
            tr(
                "MainWindow",
                "Yes creates a new difficulty called \"{0}\" in this song folder, "
                "copied from the one you have open, and edits that.\n\n"
                "Use This One edits the difficulty you already have open, without "
                "making a copy.\n\n"
                "Either way, keep an un-gimmicked version of the chart: gimmick "
                "timing cannot be cleanly undone once the file is saved.",
            ).format(gimmick_version_for(version))
        )
        body.setWordWrap(True)
        layout.addWidget(body)

        # Which difficulty the grid comes from. Asked here rather than
        # discovered later because the answer has to be settled before the first
        # placement writes a 60000 BPM line into whatever would otherwise have
        # been the source of it.
        layout.addWidget(QLabel(tr("MainWindow", "Timing reference")))
        self.reference_combo = QComboBox()
        # Difficulty names are long and the combo sized itself to the shortest
        # one, so the entry it was showing was usually elided into
        # unreadability -- the one control on this dialog whose whole job is to
        # say which file you are choosing.
        self.reference_combo.setSizeAdjustPolicy(QComboBox.AdjustToContents)
        self.reference_combo.setMinimumWidth(360)
        for label, path in references or ():
            self.reference_combo.addItem(label, str(path))
        note = QLabel()
        note.setWordWrap(True)
        note.setStyleSheet("color:#ffb347;border:0;")
        if self.reference_combo.count():
            note.setText(tr(
                "MainWindow",
                "Snaps, scrolling and the BPM overlay follow this difficulty's timing "
                "for the life of the pairing, so the barlines you place here never move "
                "the grid you place them against.",
            ))
        else:
            self.reference_combo.addItem(
                tr("MainWindow", "This difficulty (no other one exists)"), ""
            )
            note.setText(tr(
                "MainWindow",
                "There is no other difficulty in this song folder to take timing from. "
                "The one you have open will be used, which works until it has gimmicks "
                "of its own -- making a plain, correctly-timed difficulty first is worth "
                "the minute it costs.",
            ))
        layout.addWidget(self.reference_combo)
        layout.addWidget(note)

        buttons = QDialogButtonBox()
        # Explicit roles rather than Yes/No: all three are affirmative answers
        # to different questions, and only Cancel actually leaves.
        create = buttons.addButton(tr("MainWindow", "Yes"), QDialogButtonBox.AcceptRole)
        use_current = buttons.addButton(
            tr("MainWindow", "Use This One"), QDialogButtonBox.ActionRole
        )
        buttons.addButton(tr("MainWindow", "No"), QDialogButtonBox.RejectRole)
        create.clicked.connect(lambda: self._finish(self.CREATE))
        use_current.clicked.connect(lambda: self._finish(self.USE_CURRENT))
        buttons.rejected.connect(self.reject)
        layout.addWidget(buttons)

        equalize_button_widths((create, use_current))

    def _finish(self, action: str) -> None:
        self._action = action
        self.accept()

    def selected_action(self) -> str:
        """CREATE, USE_CURRENT, or CANCEL if the dialog was dismissed."""
        return self._action

    def selected_reference(self) -> Path | None:
        """The difficulty to take timing from, or None for the open one."""
        data = self.reference_combo.currentData()
        return Path(data) if data else None


# -- config sheet diagrams ---------------------------------------------------
#
# The explain panel's pictures. Each is drawn from a GimmickConfig with the
# same offsets gimmick_session writes, so the picture is the structure and not
# an illustration of it.

# Read as each diagram is drawn, so a theme switch reaches them.
def _diagram_ink() -> QColor:
    return theme.color("#e8edf3")


def _diagram_muted() -> QColor:
    return theme.color("#7d8794")

_DIAGRAM_RULE = QColor(255, 255, 255, 20)


# Off while a diagram is drawn as a Convert Notes tile: at that size its
# labels are a smudge, and the tile's own caption names the structure.
_diagram_labels = True


def _diagram_text(painter: QPainter, x: float, y: float, text: str, color: QColor | None = None,
                  align=Qt.AlignLeft, bold: bool = False) -> None:
    if not _diagram_labels:
        return
    if color is None:
        color = _diagram_muted()
    font = painter.font()
    font.setPixelSize(10)
    font.setBold(bold)
    painter.setFont(font)
    painter.setPen(color)
    width = painter.fontMetrics().horizontalAdvance(text)
    left = x - width / 2 if align == Qt.AlignHCenter else x - width if align == Qt.AlignRight else x
    painter.drawText(QPointF(left, y), text)


def paint_barline_notes(painter: QPainter, rect: QRect, config: GimmickConfig) -> None:
    """A Don and a Kat drawn out of bars: the squash on the note, the
    restores at each spacing (mirrored or trailing), on a ms axis."""
    mid = rect.center().x()
    kats = (config.kat_spacing1_ms, config.kat_spacing2_ms, config.kat_spacing3_ms)
    reach = max(10, config.spacing_ms + 1, max(kats) + 1)
    px_per_ms = (rect.width() / 2 - 18) / reach
    rows = (
        ("DON", 0.30, (config.spacing_ms,), config.mirror_don_lines, QColor(*DON_COLOR)),
        ("KAT", 0.66, kats, config.mirror_kat_lines, QColor(*KAT_COLOR)),
    )
    for name, fraction, spacings, mirrored, color in rows:
        y = rect.top() + rect.height() * fraction
        _diagram_text(painter, rect.left() + 8, y - 20, name, bold=True)
        painter.setPen(QPen(_DIAGRAM_RULE, 1))
        painter.drawLine(QPointF(rect.left() + 8, y), QPointF(rect.right() - 8, y))
        offsets = [-value for value in spacings] + list(spacings) if mirrored else list(spacings)
        painter.setPen(QPen(_diagram_ink(), 2.5))
        for offset in offsets:
            x = mid + offset * px_per_ms
            painter.drawLine(QPointF(x, y - 15), QPointF(x, y + 15))
        painter.setPen(QPen(color, 2, Qt.DashLine))
        painter.drawLine(QPointF(mid, y - 15), QPointF(mid, y + 15))
        painter.setPen(Qt.NoPen)
        painter.setBrush(color)
        painter.drawEllipse(QPointF(mid, y), 4, 4)
    step = 5 if reach <= 20 else 10 if reach <= 50 else 50
    tick = -(reach // step) * step
    while tick <= reach:
        label = f"+{tick}" if tick > 0 else str(tick)
        _diagram_text(painter, mid + tick * px_per_ms, rect.bottom() - 6, label, align=Qt.AlignHCenter)
        tick += step
    _diagram_text(painter, rect.right() - 8, rect.top() + 14, "ms", align=Qt.AlignRight)


def paint_anti_barline(painter: QPainter, rect: QRect, config: GimmickConfig) -> None:
    """The wall with a Don slit and a Kat slit, widths in wall ticks."""
    gap = max(1.6, 115.0 / max(1, config.anti_lines_per_beat))
    top, bottom = rect.top() + 18, rect.bottom() - 40
    don = (rect.left() + rect.width() * 0.30, config.anti_don_ticks)
    kat = (rect.left() + rect.width() * 0.66, config.anti_kat_ticks)
    painter.setPen(QPen(_diagram_ink(), 1.2))
    x = rect.left() + 8.0
    while x < rect.right() - 8:
        in_slit = any(start < x < start + ticks * gap + 0.01 for start, ticks in (don, kat))
        if not in_slit:
            painter.drawLine(QPointF(x, top), QPointF(x, bottom))
        x += gap
    for (start, ticks), name, color in ((don, "Don", QColor(*DON_COLOR)), (kat, "Kat", QColor(*KAT_COLOR))):
        _diagram_text(painter, start + ticks * gap / 2, bottom + 16, f"{name} {ticks}",
                      color, Qt.AlignHCenter, bold=True)
    _diagram_text(painter, rect.left() + 8, rect.bottom() - 6,
                  tr("MainWindow", "{count} lines per beat").format(count=config.anti_lines_per_beat))


def paint_shiny_stack(painter: QPainter, rect: QRect, config: GimmickConfig) -> None:
    """Two notes at T: one with its shiny stack from the shiny offset, one
    with a plain fake slider at the fake slider offset. On the same axis, so
    the two offsets meeting -- amber -- is visible as the same column."""
    left = rect.left() + 34
    px_per_ms = (rect.width() - 60) / 6
    clash = config.shiny_offset_ms == config.fake_slider_offset_ms
    rows = ((tr("MainWindow", "Shiny"), rect.top() + rect.height() * 0.28),
            (tr("MainWindow", "Fake slider"), rect.top() + rect.height() * 0.62))
    for name, y in rows:
        _diagram_text(painter, rect.left() + 8, y - 17, name.upper(), bold=True)
        painter.setPen(QPen(_DIAGRAM_RULE, 1))
        painter.drawLine(QPointF(rect.left() + 8, y), QPointF(rect.right() - 8, y))
    shiny_y, fake_y = rows[0][1], rows[1][1]
    for index in reversed(range(config.shiny_count)):
        x = left + (config.shiny_offset_ms + index) * px_per_ms
        if x > rect.right():
            continue
        colour = QColor(*DRUMROLL_COLOR)
        painter.setPen(QPen(QColor(255, 255, 255, 200), 1.5))
        painter.setBrush(colour)
        painter.drawEllipse(QPointF(x, shiny_y), 10, 10)
    fake_x = left + config.fake_slider_offset_ms * px_per_ms
    painter.setPen(QPen(QColor(255, 255, 255, 200), 1.5))
    painter.setBrush(QColor(*DRUMROLL_COLOR))
    painter.drawEllipse(QPointF(fake_x, fake_y), 10, 10)
    for y in (shiny_y, fake_y):
        painter.setPen(QPen(Qt.white, 2))
        painter.setBrush(QColor(*DON_COLOR))
        painter.drawEllipse(QPointF(left, y), 11, 11)
    if clash:
        painter.setPen(QPen(QColor(WARN_COLOR), 1.5, Qt.DashLine))
        painter.setBrush(Qt.NoBrush)
        painter.drawRect(QRectF(fake_x - 14, shiny_y - 15, 28, fake_y - shiny_y + 30))
    for ms in range(7):
        x = left + ms * px_per_ms
        _diagram_text(painter, x, rect.bottom() - 8, f"+{ms}" if ms else "T", align=Qt.AlignHCenter)


def paint_hidden_anti_barline(painter: QPainter, rect: QRect, config: GimmickConfig) -> None:
    """One sheet of bars, and a slit that narrows as it nears the hit
    position: the raised SV pushes bars ahead in proportion to how far away
    they still are, so the gap is a wedge that closes at the target."""
    top, bottom = rect.top() + 14, rect.bottom() - 26
    target = rect.left() + 24
    slit_right = rect.right() - rect.width() * 0.18
    excess = max(0.0, config.hidden_don_sv / max(config.hidden_base_sv, 1e-9) - 1.0)
    painter.setPen(QPen(_diagram_ink(), 1))
    x = rect.left() + 8.0
    gap = 3.2
    while x < rect.right() - 8:
        distance = max(0.0, x - target) / max(1.0, slit_right - target)
        half = min(28.0, 4 + 900 * excess * distance) if x < slit_right else 0
        centre = target + (slit_right - target) * 0.75
        if not (half and abs(x - centre) < half):
            painter.drawLine(QPointF(x, top), QPointF(x, bottom))
        x += gap
    painter.setPen(QPen(theme.color("#ff66aa"), 2))
    painter.drawLine(QPointF(target, top - 4), QPointF(target, bottom + 4))
    _diagram_text(painter, target + 4, rect.bottom() - 8, tr("MainWindow", "hit position"), theme.color("#f3a6bd"))


def paint_fake_slider_structure(painter: QPainter, rect: QRect, config: GimmickConfig) -> None:
    """A note at T -- faint when hidden -- and its fake slider at the offset."""
    left = rect.left() + 40
    px_per_ms = (rect.width() - 70) / max(4, config.fake_slider_offset_ms + 1)
    y = rect.center().y() - 6
    painter.setPen(QPen(_DIAGRAM_RULE, 1))
    painter.drawLine(QPointF(rect.left() + 8, y), QPointF(rect.right() - 8, y))
    note = QColor(*DON_COLOR)
    note.setAlphaF(0.3 if config.hide_note else 1.0)
    painter.setPen(QPen(QColor(255, 255, 255, 90 if config.hide_note else 230), 2))
    painter.setBrush(note)
    painter.drawEllipse(QPointF(left, y), 14, 14)
    fake_x = left + config.fake_slider_offset_ms * px_per_ms
    painter.setPen(QPen(QColor(255, 255, 255, 220), 2))
    painter.setBrush(QColor(*DRUMROLL_COLOR))
    painter.drawEllipse(QPointF(fake_x, y), 14, 14)
    _diagram_text(painter, left, rect.bottom() - 10, "T", align=Qt.AlignHCenter)
    _diagram_text(painter, fake_x, rect.bottom() - 10, f"+{config.fake_slider_offset_ms} ms", align=Qt.AlignHCenter)


def _tile_picture(painter_fn, config: GimmickConfig) -> QPixmap:
    """A structure's diagram, small and unlabelled, for a Convert Notes tile."""
    global _diagram_labels
    pixmap = QPixmap(140, 56)
    pixmap.fill(Qt.transparent)
    painter = QPainter(pixmap)
    painter.setRenderHint(QPainter.Antialiasing)
    painter.setOpacity(0.85)
    _diagram_labels = False
    try:
        painter_fn(painter, QRect(0, 0, 140, 56), config)
    finally:
        _diagram_labels = True
        painter.end()
    return pixmap


class GimmickConfigDialog(SheetDialog):
    """One layer's toolbox settings, as a config sheet.

    Two layers, two configs: the barline layer's red line spacing and the fake
    slider layer's offset are separate numbers that must not agree, so each
    layer opens its own dialog and both show the caution naming the other's
    value. `other` is that other config -- read only, for the caution.

    The barline layer's Config is three tools' settings (barline notes, the
    Red Line tool, anti-barline), so each gets its own section; one unbroken
    list of 13 numbers put "Redline BPM" and "Anti-barline barline BPM" ten
    rows apart with nothing saying which tool either belonged to.
    """

    def __init__(self, config: GimmickConfig, layer_id: str, other: GimmickConfig, parent=None) -> None:
        sv = layer_id.startswith("sv_")
        barline = layer_id == "barline"
        if sv:
            title = tr("MainWindow", "SV layer settings")
            subtitle = tr("MainWindow", "Saved with this layer. Used by its Green Line and Function tools.")
        elif barline:
            title = tr("MainWindow", "Barline settings")
            subtitle = tr("MainWindow", "Saved with this layer. Used by the Don, Kat, Red Line and Convert Notes tools.")
        else:
            title = tr("MainWindow", "Fake slider settings")
            subtitle = tr("MainWindow", "Saved with this layer. Used by the Fake Slider, Don, Kat, Shiny and Multiple tools.")
        super().__init__(title, subtitle, action=tr("MainWindow", "Save"), rail=not sv, explain=not sv, parent=parent)
        self.layer_id = layer_id
        self._other = other
        icon = application_icon()
        if not icon.isNull():
            self.setWindowIcon(icon)

        self.bpm_spin = QDoubleSpinBox()
        self.bpm_spin.setRange(1.0, 1000000.0)
        self.bpm_spin.setDecimals(0)
        self.bpm_spin.setValue(config.gimmick_bpm)

        # The other half of the pair the owner asked to separate: the BPM
        # above is how invisible the note is, this one is how fast the chart
        # runs once the structure has given it back. Unchecked is the
        # chart's own BPM at that millisecond, which is what every structure
        # written before this dial existed used. Same shape as the two BPM
        # boxes below it.
        self.restore_bpm_check = QCheckBox(tr("MainWindow", "Custom"))
        self.restore_bpm_check.setChecked(config.restore_bpm is not None)
        self.restore_bpm_spin = QDoubleSpinBox()
        self.restore_bpm_spin.setRange(0.001, 1000000.0)
        self.restore_bpm_spin.setDecimals(3)
        self.restore_bpm_spin.setValue(
            config.restore_bpm if config.restore_bpm is not None
            else DEFAULT_RED_LINE_BPM
        )
        self.restore_bpm_spin.setEnabled(self.restore_bpm_check.isChecked())
        self.restore_bpm_check.toggled.connect(self.restore_bpm_spin.setEnabled)

        self.sv_offset_spin = QSpinBox()
        self.sv_offset_spin.setRange(-5000, 5000)
        self.sv_offset_spin.setValue(config.sv_offset_ms)

        self.spacing_spin = QSpinBox()
        self.spacing_spin.setRange(1, 1000)
        self.spacing_spin.setValue(config.spacing_ms)
        self.spacing_spin.valueChanged.connect(self._update_caution)

        # Kat's three mirrored pairs, independently configurable -- see the
        # comment above `gimmick_session.DEFAULT_SPACING_MS`. Each feeds the
        # same caution as the Don spacing above: any one of the four landing
        # on the fake slider's own offset is a collision (`spacing_collides`
        # now checks all four), so every spin box here re-runs it.
        self.kat_spacing1_spin = QSpinBox()
        self.kat_spacing1_spin.setRange(1, 1000)
        self.kat_spacing1_spin.setValue(config.kat_spacing1_ms)
        self.kat_spacing1_spin.valueChanged.connect(self._update_caution)

        self.kat_spacing2_spin = QSpinBox()
        self.kat_spacing2_spin.setRange(1, 1000)
        self.kat_spacing2_spin.setValue(config.kat_spacing2_ms)
        self.kat_spacing2_spin.valueChanged.connect(self._update_caution)

        self.kat_spacing3_spin = QSpinBox()
        self.kat_spacing3_spin.setRange(1, 1000)
        self.kat_spacing3_spin.setValue(config.kat_spacing3_ms)
        self.kat_spacing3_spin.valueChanged.connect(self._update_caution)

        self.fake_offset_spin = QSpinBox()
        self.fake_offset_spin.setRange(1, 1000)
        self.fake_offset_spin.setValue(config.fake_slider_offset_ms)
        self.fake_offset_spin.valueChanged.connect(self._update_caution)

        self.length_spin = QDoubleSpinBox()
        # Short enough to derive no duration: anything longer is a real,
        # hittable drumroll. The upper bound is the config's own, so the box
        # cannot ask for a length `GimmickConfig` would reject -- and it
        # reaches the positive near-zero form (`0.001`) as well as the
        # canonical negative one.
        self.length_spin.setRange(-100000.0, FAKE_SLIDER_MAX_LENGTH)
        self.length_spin.setDecimals(4)
        self.length_spin.setValue(config.fake_slider_length)

        self.fake_sv_spin = TrimmedDoubleSpinBox()
        self.fake_sv_spin.setRange(0.01, 100.0)
        self.fake_sv_spin.setDecimals(SV_DECIMALS)
        self.fake_sv_spin.setValue(config.fake_slider_sv)

        self.place_notes_check = QCheckBox(
            tr("MainWindow", "Also place the note itself")
        )
        self.place_notes_check.setChecked(config.place_notes)

        # Plain fake sliders only -- Don/Kat need their squash and a shiny is
        # identified by its line. Off is the bare drawn object, which is what
        # the Multiple tool wants: on, it writes one line per slider in a run,
        # each restating a BPM already in force.
        self.fake_red_line_check = QCheckBox(
            tr("MainWindow", "Write a red line for plain fake sliders")
        )
        self.fake_red_line_check.setChecked(config.fake_slider_red_line)

        # Mirrored reads as one object centred on the note; unticked, the bars
        # all trail it -- a squash on the note and its restores after it, which
        # is the style several hand-made maps are written in and which nothing
        # here could ask for before. One box per kind, beside that kind's own
        # spacings: Don and Kat are separate structures layered on one region,
        # and a single box made a centred Don force a centred Kat.
        self.mirror_don_check = QCheckBox(
            tr("MainWindow", "Mirror Don bars on both sides")
        )
        self.mirror_don_check.setChecked(config.mirror_don_lines)
        self.mirror_kat_check = QCheckBox(
            tr("MainWindow", "Mirror Kat bars on both sides")
        )
        self.mirror_kat_check.setChecked(config.mirror_kat_lines)

        self.offset_spin = QSpinBox()
        self.offset_spin.setRange(-1000, 1000)
        self.offset_spin.setValue(config.red_line_offset_ms)

        # An uninherited point's BPM is also its scroll speed, so the plain red
        # line tool is a speed change with no green line involved -- but only
        # when it carries a BPM of its own. Unchecked it writes the chart's own
        # BPM, which is the line that changes nothing but where the bars fall.
        self.red_bpm_check = QCheckBox(tr("MainWindow", "Custom"))
        self.red_bpm_check.setChecked(config.red_line_bpm is not None)
        self.red_bpm_spin = QDoubleSpinBox()
        self.red_bpm_spin.setRange(0.001, 1000000.0)
        self.red_bpm_spin.setDecimals(3)
        self.red_bpm_spin.setValue(
            config.red_line_bpm if config.red_line_bpm is not None
            else DEFAULT_RED_LINE_BPM
        )
        self.red_bpm_spin.setEnabled(self.red_bpm_check.isChecked())
        self.red_bpm_check.toggled.connect(self.red_bpm_spin.setEnabled)

        # Beats per bar for that same line. osu! reads meter from the
        # uninherited point in force, so a standalone red line re-bars
        # everything after it -- at 4/4 unless it is told otherwise. The
        # ceiling matches TimingLineDialog's, where anti-barline's 999 lives.
        self.red_meter_spin = QSpinBox()
        self.red_meter_spin.setRange(1, 10000)
        self.red_meter_spin.setValue(config.red_line_meter)

        # Bit 3 of the effects field. A fake slider's 60000 BPM line draws a bar
        # nobody asked for; the barline layer's whole output is bars, so it is
        # offered here only.
        self.omit_barline_check = QCheckBox()
        self.omit_barline_check.setChecked(config.omit_barline)

        self.shiny_offset_spin = QSpinBox()
        self.shiny_offset_spin.setRange(1, 1000)
        self.shiny_offset_spin.setValue(config.shiny_offset_ms)
        self.shiny_offset_spin.valueChanged.connect(self._update_caution)

        self.shiny_count_spin = QSpinBox()
        self.shiny_count_spin.setRange(1, 50)
        self.shiny_count_spin.setValue(config.shiny_count)

        self.shiny_bpm_spin = QDoubleSpinBox()
        self.shiny_bpm_spin.setRange(0.001, 1000.0)
        self.shiny_bpm_spin.setDecimals(3)
        self.shiny_bpm_spin.setValue(config.shiny_bpm_multiplier)

        # Same trade as fake_red_line_check, for a shiny's own line. Free to
        # turn off when the shiny decorates a note already in the chart --
        # the note alone still identifies it. A shiny with no note of its own
        # loses the only thing that told it apart from a plain fake slider.
        # The other half of that line: without a restore it governs the rest
        # of the map, and the second line a mapper would place by hand is
        # exactly the one the Red Line tool refuses, since the slider's own
        # line already owns that millisecond.
        self.fake_restore_after_check = QCheckBox(
            tr("MainWindow", "Restore the chart BPM 1 ms later"))
        self.fake_restore_after_check.setChecked(config.fake_slider_restore_after)

        self.shiny_red_line_check = QCheckBox(
            tr("MainWindow", "Write a red line for shiny notes")
        )
        self.shiny_red_line_check.setChecked(config.shiny_red_line)

        self.fake_slider_bpm_spin = QDoubleSpinBox()
        self.fake_slider_bpm_spin.setRange(0.001, 1000.0)
        self.fake_slider_bpm_spin.setDecimals(3)
        self.fake_slider_bpm_spin.setValue(config.fake_slider_bpm_multiplier)

        # The anti-barline converter's four numbers. All four are ratios and
        # counts rather than milliseconds, so they hold at any BPM: the wall is
        # a fraction of a beat, the slowdown a factor of it, and the two slit
        # widths a count of wall ticks.
        self.anti_density_spin = QSpinBox()
        self.anti_density_spin.setRange(1, 10000)
        self.anti_density_spin.setValue(config.anti_lines_per_beat)
        # Same shape as the plain red-line BPM above, and for the same reason:
        # unchecked writes the chart's own BPM at each line, which only moves
        # where the bars fall; a typed value is the scroll effect, since an
        # uninherited point's BPM is its scroll speed. DEFAULT_RED_LINE_BPM is
        # only the number the box opens on -- it is never written unless
        # Custom is ticked.
        self.anti_bpm_check = QCheckBox(tr("MainWindow", "Custom"))
        self.anti_bpm_check.setChecked(config.anti_wall_bpm is not None)
        self.anti_bpm_spin = QDoubleSpinBox()
        self.anti_bpm_spin.setRange(0.001, 1000000.0)
        self.anti_bpm_spin.setDecimals(3)
        self.anti_bpm_spin.setValue(
            config.anti_wall_bpm if config.anti_wall_bpm is not None
            else DEFAULT_RED_LINE_BPM
        )
        self.anti_bpm_spin.setEnabled(self.anti_bpm_check.isChecked())
        self.anti_bpm_check.toggled.connect(self.anti_bpm_spin.setEnabled)
        self.anti_don_spin = QSpinBox()
        self.anti_don_spin.setRange(1, 1000)
        self.anti_don_spin.setValue(config.anti_don_ticks)
        self.anti_kat_spin = QSpinBox()
        self.anti_kat_spin.setRange(1, 1000)
        self.anti_kat_spin.setValue(config.anti_kat_ticks)

        # Units live in the box, so the labels lose their "(ms)".
        for spin in (self.bpm_spin, self.restore_bpm_spin, self.red_bpm_spin, self.anti_bpm_spin):
            spin.setSuffix(" BPM")
        for spin in (self.spacing_spin, self.kat_spacing1_spin, self.kat_spacing2_spin,
                     self.kat_spacing3_spin, self.fake_offset_spin, self.offset_spin,
                     self.shiny_offset_spin, self.sv_offset_spin):
            spin.setSuffix(" ms")
        for spin in (self.fake_sv_spin, self.fake_slider_bpm_spin, self.shiny_bpm_spin):
            spin.setSuffix("\u00d7")
        self.anti_don_spin.setSuffix(" " + tr("MainWindow", "ticks"))
        self.anti_kat_spin.setSuffix(" " + tr("MainWindow", "ticks"))
        self.shiny_count_spin.setSuffix(" " + tr("MainWindow", "sliders"))
        own, custom = tr("MainWindow", "Chart's own"), tr("MainWindow", "Custom")
        self.restore_bpm_widget = own_or_custom(self.restore_bpm_check, self.restore_bpm_spin, own, custom)
        self.red_bpm_widget = own_or_custom(self.red_bpm_check, self.red_bpm_spin, own, custom)
        self.anti_bpm_widget = own_or_custom(self.anti_bpm_check, self.anti_bpm_spin, own, custom)
        self.omit_barline_check.setText(tr("MainWindow", "Omit barline"))
        self.mirror_don_check.setText(tr("MainWindow", "Mirror on both sides"))
        self.mirror_kat_check.setText(tr("MainWindow", "Mirror on both sides"))
        self.place_notes_check.setText(tr("MainWindow", "Also place the note"))

        # Each layer is shown the numbers it actually uses. The rest are still
        # carried through `config()` untouched, so opening one layer's dialog
        # cannot silently reset the other's structure.
        sheet = self.sheet
        self.caution = QLabel()
        self.shiny_caution = QLabel()
        self.kat_caution = QLabel()
        if sv:
            section = sheet.add_section("sv", tr("MainWindow", "Green lines"))
            section.field(tr("MainWindow", "Position offset"), self.sv_offset_spin, span=2)
            hint = QLabel(tr(
                "MainWindow",
                "How far ahead of its object this layer's green lines sit. An SV point "
                "governs what comes after it, so a note needs its line slightly early; a "
                "timing line needs it on the same millisecond, which is why the two "
                "gimmick SV layers default to 0.",
            ))
            hint.setObjectName("fieldNote")
            hint.setWordWrap(True)
            section.add(hint, 2)
            self.resize(460, 300)
        else:
            every = sheet.add_section(
                "every", tr("MainWindow", "Every structure"),
                tr("MainWindow", "The hidden note, and the chart after it"))
            every.field(tr("MainWindow", "Invisible note BPM"), self.bpm_spin, tr(
                "MainWindow",
                "The red line on the note's own millisecond. At 60000 BPM the note "
                "scrolls 392 px per ms, so it is never on screen and the structure "
                "around it is the whole object."), default="60000 BPM")
            every.field(tr("MainWindow", "Red line BPM after the structure"), self.restore_bpm_widget, tr(
                "MainWindow",
                "How fast the chart runs once the structure hands it back. Chart's own "
                "reads the BPM in force at that millisecond, which is what every "
                "structure written before this setting used."),
                span=2, default=own, scrub=self.restore_bpm_spin)
        if barline:
            don = sheet.add_section("don", tr("MainWindow", "Barline Don"),
                                    tr("MainWindow", "One pair of bars"), QColor(*DON_COLOR).name())
            don.field(tr("MainWindow", "Spacing"), self.spacing_spin, tr(
                "MainWindow",
                "How far from the note each bar sits. 1 ms is the tightest the file "
                "format allows, and reads as one thin object."), default="1 ms")
            don.break_row()
            don.switch(self.mirror_don_check, tr(
                "MainWindow", "Off: one bar after the note, as most hand-made maps do."),
                default=tr("MainWindow", "off"))
            kat = sheet.add_section("kat", tr("MainWindow", "Barline Kat"),
                                    tr("MainWindow", "Three pairs, so a Kat reads wider than a Don"), QColor(*KAT_COLOR).name())
            kat_help = tr(
                "MainWindow",
                "Kat's three bars, each set on its own so several structures can be "
                "layered on one region. The three must all differ.")
            spacings = QWidget()
            spacing_row = QHBoxLayout(spacings)
            spacing_row.setContentsMargins(0, 0, 0, 0)
            spacing_row.setSpacing(12)
            for label, spin in ((tr("MainWindow", "Spacing 1"), self.kat_spacing1_spin),
                                (tr("MainWindow", "Spacing 2"), self.kat_spacing2_spin),
                                (tr("MainWindow", "Spacing 3"), self.kat_spacing3_spin)):
                spacing_row.addWidget(sheet.field(label, spin, kat_help), 1)
            kat.add(spacings, 2)
            kat.switch(self.mirror_kat_check, tr(
                "MainWindow", "On: bars either side, centred on the note."), default=tr("MainWindow", "on"))
            self.kat_caution = kat.caution(tr(
                "MainWindow",
                "The three Kat spacings must all be different: two bars on one "
                "millisecond are one red line."))
            red = sheet.add_section("red", tr("MainWindow", "Red Line tool"),
                                    tr("MainWindow", "A plain red line where you click"), "#ff5a5a")
            red.field(tr("MainWindow", "Offset"), self.offset_spin, tr(
                "MainWindow", "Moves each placed red line off the snap by this much."), default="0 ms")
            red.field(tr("MainWindow", "Meter"), self.red_meter_spin, tr(
                "MainWindow",
                "Beats per bar for the line. osu! reads meter from the red line in "
                "force, so this re-bars everything after it."), default="4")
            red.field(tr("MainWindow", "BPM"), self.red_bpm_widget, tr(
                "MainWindow",
                "A red line's BPM is also its scroll speed. Chart's own changes nothing "
                "but where the bars fall; a number is a speed change with no green line."),
                span=2, default=own, scrub=self.red_bpm_spin)
            red.switch(self.place_notes_check, tr(
                "MainWindow", "A hittable note on the snap, so the bars are something the player plays."),
                default=tr("MainWindow", "on"))
            anti = sheet.add_section("anti", tr("MainWindow", "Anti-barline"),
                                     tr("MainWindow", "A wall of bars with a slit where each note is"), "#e8edf3")
            anti.field(tr("MainWindow", "Lines per beat"), self.anti_density_spin, tr(
                "MainWindow", "How tight the wall is. The reference section (mekurume) uses 72."), default="36")
            anti.field(tr("MainWindow", "Don slit"), self.anti_don_spin, tr(
                "MainWindow",
                "Wall lines left out for a Don. The slit width is what tells Don from "
                "Kat, since the notes themselves are invisible."), default="1")
            anti.field(tr("MainWindow", "Wall BPM"), self.anti_bpm_widget, tr(
                "MainWindow",
                "Below the chart's own BPM the wall packs tighter: a red line's BPM is "
                "also its scroll speed, so a third of the BPM draws the same lines a "
                "third as far apart."), span=2, default=own, scrub=self.anti_bpm_spin)
            anti.field(tr("MainWindow", "Kat slit"), self.anti_kat_spin, tr(
                "MainWindow", "Wall lines left out for a Kat. Wider than Don's, or the two cannot be told apart."),
                default="2")
            self.caution = anti.caution()
            self.resize(980, 660)
        elif not sv:
            fake = sheet.add_section("slider", tr("MainWindow", "Fake slider"),
                                     tr("MainWindow", "A drumroll too short to hit: only its head is drawn"),
                                     QColor(*DRUMROLL_COLOR).name())
            fake.field(tr("MainWindow", "Offset"), self.fake_offset_spin, tr(
                "MainWindow",
                "How far after the snap the fake slider sits. Must differ from the "
                "shiny offset and from every barline spacing."), default="2 ms")
            fake.field(tr("MainWindow", "Length"), self.length_spin, tr(
                "MainWindow",
                "Anything longer than 0.001 is a real, hittable drumroll. -0.0001 is "
                "the canonical fake slider; long negative lengths draw a track to the "
                "right of the head."), default="-0.001")
            fake.field(tr("MainWindow", "Red line BPM"), self.fake_slider_bpm_spin, tr(
                "MainWindow", "The slider's own red line as a multiple of the chart's BPM. 1\u00d7 restates the BPM in force."),
                default="1\u00d7")
            fake.break_row()
            fake.switch(self.fake_red_line_check, tr(
                "MainWindow", "Off leaves the bare object, which is what the Multiple tool wants."),
                default=tr("MainWindow", "on"))
            fake.switch(self.fake_restore_after_check, tr(
                "MainWindow", "Without it the slider's line governs the rest of the map."),
                default=tr("MainWindow", "off"))
            fake.switch(self.omit_barline_check, tr(
                "MainWindow", "The slider's 60000 BPM line would otherwise stamp a bar nobody asked for."),
                default=tr("MainWindow", "on"))
            self.caution = fake.caution()
            donkat = sheet.add_section("donkat", tr("MainWindow", "Don / Kat"),
                                       tr("MainWindow", "A note that becomes a fake slider in flight"))
            donkat.field(tr("MainWindow", "Gimmick SV"), self.fake_sv_spin, tr(
                "MainWindow",
                "The green line that takes the already squashed note the rest of the "
                "way off screen."), default="10\u00d7")
            shiny = sheet.add_section("shiny", tr("MainWindow", "Shiny"),
                                      tr("MainWindow", "A stack of fake sliders under one note"), "#ffffff")
            shiny.field(tr("MainWindow", "Offset"), self.shiny_offset_spin, tr(
                "MainWindow",
                "The first fake slider of the stack sits this long after the note, the "
                "rest one ms apart."), default="1 ms")
            shiny.field(tr("MainWindow", "Stack size"), self.shiny_count_spin, tr(
                "MainWindow",
                "How many fake sliders sit under the note. In a kiai section each one "
                "adds its own flash, so a deeper stack shines brighter."), default="3")
            shiny.field(tr("MainWindow", "Red line BPM"), self.shiny_bpm_spin, tr(
                "MainWindow", "The shiny's own red line as a multiple of the chart's BPM."), default="1\u00d7")
            shiny.break_row()
            shiny.switch(self.shiny_red_line_check, tr(
                "MainWindow", "Off is fine when the shiny decorates a note already in the chart."),
                default=tr("MainWindow", "on"))
            self.shiny_caution = shiny.caution(tr(
                "MainWindow",
                "The shiny offset equals the fake slider offset. Both land on the same "
                "millisecond, and a stack of fake sliders on one millisecond is what a "
                "shiny is, so the two can no longer be told apart."))
            self.resize(980, 640)
        if not sv:
            sheet.set_help_default(
                tr("MainWindow", "Hover or focus a setting"),
                tr("MainWindow", "This panel says what it does and its default. The picture above follows your numbers."))
            self.diagram = Diagram(self._paint_diagram)
            sheet.set_diagram(self.diagram, tr("MainWindow", "Preview"))
            sheet.section_changed.connect(lambda _key: self.diagram.refresh())
            for spin in self.findChildren(QAbstractSpinBox):
                spin.valueChanged.connect(self.diagram.refresh)
            for check in self.findChildren(QCheckBox):
                check.toggled.connect(self.diagram.refresh)
        self.restore_button.clicked.connect(self._restore_defaults)
        self._last_good = config
        self._update_caution()

    def _update_caution(self) -> None:
        """Warn, don't refuse: the two values only actually clash where a
        barline note and a fake slider land on the same snap.

        `config()` can raise while the three Kat spin boxes are mid-edit --
        keyboard tracking fires on every keystroke, so typing a second Kat
        spacing through a value that briefly matches another is a live,
        reachable state, not just a theoretical one. Caught here rather than
        avoided: the cautions simply hold their last picture until the typing
        settles on something constructible again. `accept()` is the actual
        gate against leaving the dialog with a broken combination.
        """
        kats = (self.kat_spacing1_spin, self.kat_spacing2_spin, self.kat_spacing3_spin)
        kat_clash = len({spin.value() for spin in kats}) < 3
        if self.layer_id == "barline":
            self.kat_caution.setVisible(kat_clash)
            for spin in kats:
                set_warning(spin, kat_clash)
            self.sheet.set_rail_warning("kat", kat_clash)
        try:
            edited = self.config()
        except GimmickConfigError:
            return
        self._last_good = edited
        shiny = shiny_collides(edited)
        self.shiny_caution.setVisible(shiny)
        spacing = spacing_collides(*self._configs_for(edited))
        self.caution.setVisible(spacing)
        self.caution.setText(tr(
            "MainWindow",
            "Caution: one of the barline spacings (Don or Kat) is the same "
            "as the fake slider offset. A fake slider writes 60000 BPM at "
            "its own millisecond and the chart's BPM one offset later, so a "
            "barline note placed on the same snap will fight it for that "
            "line.",
        ))
        # The fields that clash turn amber, not just the paragraph.
        _barline_config, fake_config = self._configs_for(edited)
        offset = fake_config.fake_slider_offset_ms
        if self.layer_id == "barline":
            for spin in (self.spacing_spin, *kats):
                set_warning(spin, (spacing and spin.value() == offset) or (spin in kats and kat_clash))
            self.sheet.set_rail_warning("anti", spacing)
        elif self.layer_id == "fake_slider":
            set_warning(self.fake_offset_spin, shiny or spacing)
            set_warning(self.shiny_offset_spin, shiny)
            self.sheet.set_rail_warning("slider", shiny or spacing)
            self.sheet.set_rail_warning("shiny", shiny)

    def _configs_for(self, edited: GimmickConfig) -> tuple[GimmickConfig, GimmickConfig]:
        """(barline config, fake slider config), whichever this dialog edits."""
        return (edited, self._other) if self.layer_id == "barline" else (self._other, edited)

    def _restore_defaults(self) -> None:
        """Every field this layer shows back to `GimmickConfig()`'s value.

        Only the fields on screen: the rest belong to the other layer's
        structures, and `config()` carries them through untouched.
        """
        default = GimmickConfig()
        values = {
            self.bpm_spin: default.gimmick_bpm, self.spacing_spin: default.spacing_ms,
            self.kat_spacing1_spin: default.kat_spacing1_ms, self.kat_spacing2_spin: default.kat_spacing2_ms,
            self.kat_spacing3_spin: default.kat_spacing3_ms, self.offset_spin: default.red_line_offset_ms,
            self.red_meter_spin: default.red_line_meter, self.anti_density_spin: default.anti_lines_per_beat,
            self.anti_don_spin: default.anti_don_ticks, self.anti_kat_spin: default.anti_kat_ticks,
            self.fake_offset_spin: default.fake_slider_offset_ms, self.length_spin: default.fake_slider_length,
            self.fake_sv_spin: default.fake_slider_sv, self.fake_slider_bpm_spin: default.fake_slider_bpm_multiplier,
            self.shiny_offset_spin: default.shiny_offset_ms, self.shiny_count_spin: default.shiny_count,
            self.shiny_bpm_spin: default.shiny_bpm_multiplier, self.sv_offset_spin: default.sv_offset_ms,
        }
        checks = {
            self.mirror_don_check: default.mirror_don_lines, self.mirror_kat_check: default.mirror_kat_lines,
            self.place_notes_check: default.place_notes, self.omit_barline_check: default.omit_barline,
            self.fake_red_line_check: default.fake_slider_red_line,
            self.fake_restore_after_check: default.fake_slider_restore_after,
            self.shiny_red_line_check: default.shiny_red_line,
            self.restore_bpm_check: default.restore_bpm is not None,
            self.red_bpm_check: default.red_line_bpm is not None,
            self.anti_bpm_check: default.anti_wall_bpm is not None,
        }
        # A widget this layer never placed has no window of its own.
        for widget, value in values.items():
            if widget.window() is self:
                widget.setValue(value)
        for widget, value in checks.items():
            if widget.window() is self:
                widget.setChecked(value)

    def _paint_diagram(self, painter: QPainter, rect: QRect) -> None:
        """The structure the numbers draw, from the last valid `config()`."""
        config = self._last_good
        if self.layer_id == "barline":
            if self.sheet.active_section == "anti":
                paint_anti_barline(painter, rect, config)
            else:
                paint_barline_notes(painter, rect, config)
        else:
            paint_shiny_stack(painter, rect, config)

    def accept(self) -> None:
        # The three Kat spin boxes have no shared range to enforce
        # distinctness the way a single min/max keeps every other field here
        # constructible -- so unlike them, this one combination has to be
        # checked by hand before the dialog is allowed to close, or an
        # invalid GimmickConfig would reach `_open_gimmick_config` and raise
        # there instead, with no field left focused to point at the mistake.
        try:
            self.config()
        except GimmickConfigError as error:
            QMessageBox.warning(self, tr("MainWindow", "Cannot save this"), str(error))
            return
        super().accept()

    def config(self) -> GimmickConfig:
        return GimmickConfig(
            gimmick_bpm=self.bpm_spin.value(),
            spacing_ms=self.spacing_spin.value(),
            kat_spacing1_ms=self.kat_spacing1_spin.value(),
            kat_spacing2_ms=self.kat_spacing2_spin.value(),
            kat_spacing3_ms=self.kat_spacing3_spin.value(),
            fake_slider_length=self.length_spin.value(),
            red_line_offset_ms=self.offset_spin.value(),
            fake_slider_offset_ms=self.fake_offset_spin.value(),
            fake_slider_sv=self.fake_sv_spin.value(),
            fake_slider_red_line=self.fake_red_line_check.isChecked(),
            fake_slider_restore_after=self.fake_restore_after_check.isChecked(),
            anti_lines_per_beat=self.anti_density_spin.value(),
            anti_wall_bpm=(
                self.anti_bpm_spin.value() if self.anti_bpm_check.isChecked() else None
            ),
            anti_don_ticks=self.anti_don_spin.value(),
            anti_kat_ticks=self.anti_kat_spin.value(),
            place_notes=self.place_notes_check.isChecked(),
            mirror_don_lines=self.mirror_don_check.isChecked(),
            mirror_kat_lines=self.mirror_kat_check.isChecked(),
            sv_offset_ms=self.sv_offset_spin.value(),
            red_line_bpm=(
                self.red_bpm_spin.value() if self.red_bpm_check.isChecked() else None
            ),
            red_line_meter=self.red_meter_spin.value(),
            omit_barline=self.omit_barline_check.isChecked(),
            shiny_offset_ms=self.shiny_offset_spin.value(),
            shiny_count=self.shiny_count_spin.value(),
            shiny_bpm_multiplier=self.shiny_bpm_spin.value(),
            shiny_red_line=self.shiny_red_line_check.isChecked(),
            fake_slider_bpm_multiplier=self.fake_slider_bpm_spin.value(),
            restore_bpm=(
                self.restore_bpm_spin.value()
                if self.restore_bpm_check.isChecked() else None
            ),
        )


class ConvertNotesDialog(SheetDialog):
    """Which structure Convert Notes draws over a dragged range, and its numbers.

    Both gimmick layers ask. The fake slider layer has one structure to draw and
    so asks only for its numbers; the barline layer has three -- bars drawn
    around each note, bars taken away where each note is, or a sheet of bars
    whose slits are cut with SV -- and asks which first.

    The numbers are **per call**. They open on the layer's saved Config so the
    common case is one click, and what is typed here is used for this drag and
    forgotten -- a section whose slits want to be wider than the last one's is
    the normal case, not a reason to re-save the layer.
    """

    # This layer's own Don/Kat structure, whichever layer that is.
    STRUCTURE = "structure"
    ANTI = "anti"
    HIDDEN = "hidden"

    def __init__(self, config: GimmickConfig, layer_id: str = "barline", parent=None,
                 start_ms: float | None = None, end_ms: float | None = None,
                 sv_inputs=None, experimental: bool = False) -> None:
        subtitle = tr("MainWindow", "These numbers are for this conversion only; the layer's Config is not changed.")
        if start_ms is not None and end_ms is not None:
            subtitle = tr("MainWindow", "Range: {0} to {1}").format(
                format_time(round(start_ms)), format_time(round(end_ms))) + ". " + subtitle
        title = tr("MainWindow", "Experimental Conversion") if experimental else tr("MainWindow", "Convert notes")
        super().__init__(title, subtitle, action=tr("MainWindow", "Convert"), rail=False, parent=parent)
        # Keep SV (owner, 2026-10-09): (timing points, notes, start, end) to
        # read the chart's own SV from. `experimental` is the whole-map
        # converter: Keep SV always on, and no hidden anti-barline.
        self._sv_inputs = sv_inputs
        self.experimental = experimental
        self._runs: dict[str, list] = {}
        self._table_mode: str | None = None
        self._base = config
        self.layer_id = layer_id
        icon = application_icon()
        if not icon.isNull():
            self.setWindowIcon(icon)
        self.restore_button.hide()

        barline = layer_id == "barline"
        sheet = self.sheet
        self.mode_combo = QComboBox()
        if barline:
            # Literal tr() calls, one per option -- see AddViewDialog on the gate.
            self.mode_combo.addItem(tr("MainWindow", "Barline notes"), self.STRUCTURE)
            self.mode_combo.addItem(tr("MainWindow", "Anti-barline"), self.ANTI)
            tiles = [
                (tr("MainWindow", "Barline notes") + "\n" + tr("MainWindow", "Each note drawn out of bars."),
                 _tile_picture(paint_barline_notes, config)),
                (tr("MainWindow", "Anti-barline") + "\n" + tr("MainWindow", "Each note is a slit."),
                 _tile_picture(paint_anti_barline, config)),
            ]
            if not experimental:
                self.mode_combo.addItem(tr("MainWindow", "Hidden anti-barline"), self.HIDDEN)
                tiles.append(
                    (tr("MainWindow", "Hidden anti-barline") + "\n" + tr("MainWindow", "SV opens the slits."),
                     _tile_picture(paint_hidden_anti_barline, config)))
            picker = sheet.field(tr("MainWindow", "Convert to"), bind_tiles(self.mode_combo, tiles))
            sheet.add_widget(picker)
            self._barline_page(config)
            self._anti_page(config)
            if not experimental:
                self._hidden_page(config)
            if sv_inputs is not None:
                self._curves_page()
        else:
            self.mode_combo.addItem(tr("MainWindow", "Fake sliders"), self.STRUCTURE)
            self._fake_slider_page(config)
        self.mode_combo.currentIndexChanged.connect(self._show_mode)

        sheet.set_help_default(
            tr("MainWindow", "What it writes, per note"),
            tr("MainWindow", "Every plain note in the range becomes this structure, on its own millisecond. "
                             "Finishers, drumrolls and fake sliders are left as they are."))
        self._last_good = config
        self.diagram = Diagram(self._paint_diagram)
        sheet.set_diagram(self.diagram, tr("MainWindow", "Preview"))
        for spin in self.findChildren(QAbstractSpinBox):
            spin.valueChanged.connect(self._changed)
        for check in self.findChildren(QCheckBox):
            check.toggled.connect(self._changed)
        self._show_mode()
        self.resize(1000 if barline else 860, 640 if barline else 560)

    # -- pages ---------------------------------------------------------------

    def _show_mode(self, _index: int = 0) -> None:
        keys = {self.mode()}
        if self._curves_wanted():
            keys.add("curves")
            self._fill_curves()
        self.sheet.show_only(keys)
        self._changed()

    # -- Keep SV -------------------------------------------------------------

    def _curve_choices(self) -> list[tuple[str, str]]:
        """What a run can be told it is: Generate SV's curves, by its names,
        and the chart's own step."""
        return [
            (sv_curves.STEP, tr("MainWindow", "Step")),
            ("linear", tr("MainWindow", "Linear")),
            ("sin_in", tr("MainWindow", "Sin In")),
            ("sin_out", tr("MainWindow", "Sin Out")),
            ("exp1.3", tr("MainWindow", "Exp 1.3")),
            ("exp1.6", tr("MainWindow", "Exp 1.6")),
            ("true_exp", tr("MainWindow", "True Exp")),
            ("sin", tr("MainWindow", "Sin")),
        ]

    def _curves_page(self) -> None:
        section = self.sheet.add_section("curves", tr("MainWindow", "Detected SV curves"), tr(
            "MainWindow", "Each run of green lines and the curve it follows. Change one if the guess is wrong."))
        self.curve_table = QTableWidget(0, 4)
        self.curve_table.setHorizontalHeaderLabels([
            tr("MainWindow", "Time"), tr("MainWindow", "SV"), tr("MainWindow", "Curve"), tr("MainWindow", "Notes")])
        self.curve_table.verticalHeader().hide()
        self.curve_table.setEditTriggers(QAbstractItemView.NoEditTriggers)
        self.curve_table.setSelectionMode(QAbstractItemView.NoSelection)
        self.curve_table.horizontalHeader().setStretchLastSection(True)
        self.curve_table.setMinimumHeight(240)
        smooth(self.curve_table)
        section.add(self.curve_table, 2)

    def _curves_wanted(self) -> bool:
        if self._sv_inputs is None or self.mode() == self.HIDDEN:
            return False
        if self.experimental:
            return True
        return self.mode() == self.STRUCTURE and self.keep_sv_check.isChecked()

    def _sv_mode(self) -> str:
        """Barline notes keep a lone jump a step; the anti-barline wall ramps
        every gap the chart changed speed in (owner, 2026-10-09)."""
        return sv_curves.BARLINE if self.mode() == self.STRUCTURE else sv_curves.ANTI

    def runs(self) -> list:
        """The detected runs for the current mode, with any curve the mapper
        corrected. Read once per mode: a whole map takes seconds."""
        mode = self._sv_mode()
        if mode not in self._runs:
            points, notes, start_ms, end_ms = self._sv_inputs
            QApplication.setOverrideCursor(Qt.WaitCursor)
            try:
                self._runs[mode] = sv_curves.detect_runs(
                    sv_curves.anchors(points, notes, start_ms, end_ms), mode)
            finally:
                QApplication.restoreOverrideCursor()
        return self._runs[mode]

    def _fill_curves(self) -> None:
        mode = self._sv_mode()
        if self._table_mode == mode:
            return
        self._table_mode = mode
        runs = self.runs()
        choices = self._curve_choices()
        table = self.curve_table
        table.setRowCount(len(runs))
        for row, run in enumerate(runs):
            table.setItem(row, 0, QTableWidgetItem(
                f"{format_time(round(run.start.time))} \u2013 {format_time(round(run.end.time))}"))
            table.setItem(row, 1, QTableWidgetItem(
                f"{run.start.value:.2f}\u00d7 \u2192 {run.end.value:.2f}\u00d7"))
            combo = QComboBox()
            for function, label in choices:
                combo.addItem(label, function)
            if combo.findData(run.function) < 0:
                # A fitted "Exp x": its own exponent, as Generate SV writes it.
                combo.addItem(f"Exp {run.function[3:]}", run.function)
            combo.setCurrentIndex(combo.findData(run.function))
            combo.currentIndexChanged.connect(
                lambda _index, run=run, combo=combo: setattr(run, "function", combo.currentData()))
            table.setCellWidget(row, 2, combo)
            table.setItem(row, 3, QTableWidgetItem(str(run.count)))
        table.resizeColumnsToContents()

    def sv_model(self):
        """`sv_curves.SvModel` for this conversion, or None without Keep SV."""
        if not self._curves_wanted():
            return None
        points, notes, _start, _end = self._sv_inputs
        return sv_curves.SvModel(self.runs(), points, notes)

    def _changed(self, *_args) -> None:
        try:
            self._last_good = self.config()
        except GimmickConfigError:
            pass
        self.diagram.refresh()

    def _paint_diagram(self, painter: QPainter, rect: QRect) -> None:
        mode = self.mode()
        if mode == self.ANTI:
            paint_anti_barline(painter, rect, self._last_good)
        elif mode == self.HIDDEN:
            paint_hidden_anti_barline(painter, rect, self._last_good)
        elif self.layer_id == "barline":
            paint_barline_notes(painter, rect, self._last_good)
        else:
            paint_fake_slider_structure(painter, rect, self._last_good)

    def _hide_note_check(self, config: GimmickConfig) -> QCheckBox:
        """The one option both structures share.

        A Don or Kat structure hides the note it is drawn around by putting a
        60000 BPM line on the note's own millisecond -- the note then scrolls
        392px/ms, which is to say it is never on screen, and the bars or the
        fake slider beside it are all the player sees. Unticked, that line
        carries the chart's *own* BPM instead and omits its barline, so it
        changes nothing except restarting measure counting: the note stays
        visible and the structure is drawn around a note you can see.
        """
        check = QCheckBox(tr("MainWindow", "Hide the note itself"))
        check.setChecked(config.hide_note)
        return check

    def _hide_note_help(self) -> str:
        return tr(
            "MainWindow",
            "On, the note is squashed to invisibility by a gimmick-BPM line and only "
            "the structure is seen. Off, that line carries the chart's own BPM with "
            "its barline detached, so the note stays visible inside the structure.",
        )

    def _slit_note_hint(self) -> str:
        """The extra half of the story on a converter whose structure is a hole.

        Everywhere else the option is "structure with or without a visible note
        in it". Here the invisible note is what makes the gap read as an object
        at all, so showing it changes what the section says rather than only how
        it looks -- worth one line, not worth refusing the option over.
        """
        return tr(
            "MainWindow",
            "Showing the note changes what this gimmick reads as: the slit is a hole "
            "in a sheet of bars, and an invisible note is what makes that hole the "
            "object. Shown, the note travels through its own slit at the chart's "
            "normal speed while the sheet crawls at the wall speed.",
        )

    def _barline_page(self, config: GimmickConfig) -> None:
        section = self.sheet.add_section(self.STRUCTURE, tr("MainWindow", "Barline notes"),
                                         tr("MainWindow", "Each note drawn out of bars"))
        self.bpm_spin = QDoubleSpinBox()
        self.bpm_spin.setRange(1.0, 1000000.0)
        self.bpm_spin.setDecimals(0)
        self.bpm_spin.setSuffix(" BPM")
        self.bpm_spin.setValue(config.gimmick_bpm)
        section.field(tr("MainWindow", "Invisible note BPM"), self.bpm_spin, tr(
            "MainWindow", "The red line on each note's own millisecond, which carries the note off screen."))

        self.spacing_spin = QSpinBox()
        self.spacing_spin.setRange(1, 1000)
        self.spacing_spin.setSuffix(" ms")
        self.spacing_spin.setValue(config.spacing_ms)
        section.field(tr("MainWindow", "Don spacing"), self.spacing_spin, tr(
            "MainWindow", "How far from the note each Don bar sits."))

        # Three boxes, three labels, one loop -- but the labels are separate
        # tr() literals for the same reason every other option list here is:
        # the catalog is scanned for literals, not built at runtime.
        self.kat_spins = []
        labels = (tr("MainWindow", "Kat spacing 1"), tr("MainWindow", "Kat spacing 2"),
                  tr("MainWindow", "Kat spacing 3"))
        row = QWidget()
        row_layout = QHBoxLayout(row)
        row_layout.setContentsMargins(0, 0, 0, 0)
        row_layout.setSpacing(12)
        for label, value in zip(labels, (
            config.kat_spacing1_ms, config.kat_spacing2_ms, config.kat_spacing3_ms,
        )):
            spin = QSpinBox()
            spin.setRange(1, 1000)
            spin.setSuffix(" ms")
            spin.setValue(value)
            self.kat_spins.append(spin)
            row_layout.addWidget(self.sheet.field(label, spin, tr(
                "MainWindow", "Kat's three bars. The three must all differ.")), 1)
        section.add(row, 2)
        self.mirror_don_check = QCheckBox(tr("MainWindow", "Mirror Don bars"))
        self.mirror_don_check.setChecked(config.mirror_don_lines)
        section.switch(self.mirror_don_check, tr("MainWindow", "On both sides of the note."), span=1)
        self.mirror_kat_check = QCheckBox(tr("MainWindow", "Mirror Kat bars"))
        self.mirror_kat_check.setChecked(config.mirror_kat_lines)
        section.switch(self.mirror_kat_check, tr("MainWindow", "On both sides of the note."), span=1)

        self.hide_note_check = self._hide_note_check(config)
        section.switch(self.hide_note_check, tr("MainWindow", "Off keeps the note visible inside its bars."),
                       self._hide_note_help(), span=1)
        self.omit_note_barline_check = QCheckBox(tr("MainWindow", "Omit barline at each note"))
        self.omit_note_barline_check.setChecked(config.omit_note_barline)
        # A shown note's line already omits its barline, so the box only
        # means something while the note is hidden.
        self.omit_note_barline_check.setEnabled(self.hide_note_check.isChecked())
        self.hide_note_check.toggled.connect(self.omit_note_barline_check.setEnabled)
        section.switch(self.omit_note_barline_check, tr("MainWindow", "The note's own line draws no bar."), span=1)
        # Per selection, Barline notes only (owner, 2026-10-09). The whole-map
        # converter keeps SV always, so it shows no switch for it.
        self.keep_sv_check = QCheckBox(tr("MainWindow", "Keep SV"))
        if self._sv_inputs is not None and not self.experimental:
            section.switch(self.keep_sv_check, tr(
                "MainWindow", "Every line the bars add gets the chart's own SV back, following its curves."), span=1)
            self.keep_sv_check.toggled.connect(self._show_mode)

    def _fake_slider_page(self, config: GimmickConfig) -> None:
        section = self.sheet.add_section(self.STRUCTURE, tr("MainWindow", "Fake sliders"),
                                         tr("MainWindow", "Each note becomes a fake slider in flight"))
        self.bpm_spin = QDoubleSpinBox()
        self.bpm_spin.setRange(1.0, 1000000.0)
        self.bpm_spin.setDecimals(0)
        self.bpm_spin.setSuffix(" BPM")
        self.bpm_spin.setValue(config.gimmick_bpm)
        section.field(tr("MainWindow", "Invisible note BPM"), self.bpm_spin, tr(
            "MainWindow", "The red line on each note's own millisecond, which carries the note off screen."))

        self.fake_offset_spin = QSpinBox()
        self.fake_offset_spin.setRange(1, 1000)
        self.fake_offset_spin.setSuffix(" ms")
        self.fake_offset_spin.setValue(config.fake_slider_offset_ms)
        section.field(tr("MainWindow", "Fake slider offset"), self.fake_offset_spin, tr(
            "MainWindow", "How far after the note the fake slider sits."))

        self.length_spin = QDoubleSpinBox()
        # The config's own bound, so the box cannot ask for a length
        # GimmickConfig would reject -- see GimmickConfigDialog.
        self.length_spin.setRange(-100000.0, FAKE_SLIDER_MAX_LENGTH)
        self.length_spin.setDecimals(4)
        self.length_spin.setValue(config.fake_slider_length)
        section.field(tr("MainWindow", "Fake slider length"), self.length_spin, tr(
            "MainWindow", "Anything longer than 0.001 is a real, hittable drumroll."))

        self.fake_sv_spin = TrimmedDoubleSpinBox()
        self.fake_sv_spin.setRange(0.01, 100.0)
        self.fake_sv_spin.setDecimals(SV_DECIMALS)
        self.fake_sv_spin.setSuffix("\u00d7")
        self.fake_sv_spin.setValue(config.fake_slider_sv)
        section.field(tr("MainWindow", "Gimmick SV"), self.fake_sv_spin, tr(
            "MainWindow",
            "With the note hidden the gimmick SV above is what takes the already "
            "squashed note the rest of the way off screen. Showing the note drops it "
            "and restates the chart's own speed instead, or the note would be flung "
            "off the screen the line was just told to keep it on.",
        ))

        self.fake_slider_bpm_spin = QDoubleSpinBox()
        self.fake_slider_bpm_spin.setRange(0.001, 1000.0)
        self.fake_slider_bpm_spin.setDecimals(3)
        self.fake_slider_bpm_spin.setSuffix("\u00d7")
        self.fake_slider_bpm_spin.setValue(config.fake_slider_bpm_multiplier)
        section.field(tr("MainWindow", "Red line BPM"), self.fake_slider_bpm_spin, tr(
            "MainWindow", "The slider's own red line as a multiple of the chart's BPM. 1\u00d7 restates the BPM in force."))

        self.omit_barline_check = QCheckBox(tr("MainWindow", "Omit barline"))
        self.omit_barline_check.setChecked(config.omit_barline)
        section.switch(self.omit_barline_check, tr(
            "MainWindow", "The slider's 60000 BPM line would otherwise stamp a bar nobody asked for."), span=1)
        self.hide_note_check = self._hide_note_check(config)
        section.switch(self.hide_note_check, tr("MainWindow", "Off keeps the note visible beside its slider."),
                       self._hide_note_help(), span=1)

    def _anti_page(self, config: GimmickConfig) -> None:
        section = self.sheet.add_section(self.ANTI, tr("MainWindow", "Anti-barline"), tr(
            "MainWindow", "Only plain circles convert; finishers, drumrolls and spinners are left as they are"))
        self.anti_density_spin = QSpinBox()
        self.anti_density_spin.setRange(1, 10000)
        self.anti_density_spin.setValue(config.anti_lines_per_beat)
        section.field(tr("MainWindow", "Lines per beat"), self.anti_density_spin, tr(
            "MainWindow", "How tight the wall is. The reference section (mekurume) uses 72."))

        self.anti_don_spin = QSpinBox()
        self.anti_don_spin.setRange(1, 1000)
        self.anti_don_spin.setSuffix(" " + tr("MainWindow", "ticks"))
        self.anti_don_spin.setValue(config.anti_don_ticks)
        section.field(tr("MainWindow", "Don slit"), self.anti_don_spin, tr(
            "MainWindow",
            "Wall lines left out for a Don. The slit width is what tells Don from "
            "Kat, since the notes themselves are invisible."))

        # Same shape as the Config dialog's: the chart's own BPM at each wall
        # line only moves where the bars fall.
        self.anti_bpm_check = QCheckBox(tr("MainWindow", "Custom"))
        self.anti_bpm_check.setChecked(config.anti_wall_bpm is not None)
        self.anti_bpm_spin = QDoubleSpinBox()
        self.anti_bpm_spin.setRange(0.001, 1000000.0)
        self.anti_bpm_spin.setDecimals(3)
        self.anti_bpm_spin.setSuffix(" BPM")
        self.anti_bpm_spin.setValue(
            config.anti_wall_bpm if config.anti_wall_bpm is not None else DEFAULT_RED_LINE_BPM
        )
        section.field(tr("MainWindow", "Wall BPM"), own_or_custom(
            self.anti_bpm_check, self.anti_bpm_spin, tr("MainWindow", "Chart's own"), tr("MainWindow", "Custom")),
            tr("MainWindow",
               "Below the chart's own BPM the wall packs tighter: a red line's BPM is "
               "also its scroll speed, so a third of the BPM draws the same lines a "
               "third as far apart."), span=2, scrub=self.anti_bpm_spin)

        self.anti_kat_spin = QSpinBox()
        self.anti_kat_spin.setRange(1, 1000)
        self.anti_kat_spin.setSuffix(" " + tr("MainWindow", "ticks"))
        self.anti_kat_spin.setValue(config.anti_kat_ticks)
        section.field(tr("MainWindow", "Kat slit"), self.anti_kat_spin, tr(
            "MainWindow", "Wall lines left out for a Kat. Wider than Don's, or the two cannot be told apart."))
        self.anti_hide_note_check = self._hide_note_check(config)
        section.switch(self.anti_hide_note_check, tr("MainWindow", "Off shows the note inside its slit."),
                       self._slit_note_hint(), span=1)

    def _hidden_page(self, config: GimmickConfig) -> None:
        section = self.sheet.add_section(self.HIDDEN, tr("MainWindow", "Hidden anti-barline"), tr(
            "MainWindow", "The slit is a percentage of speed: wide far away, closed at the hit position"))
        self.hidden_hide_bpm_spin = QDoubleSpinBox()
        self.hidden_hide_bpm_spin.setRange(1.0, 1000000.0)
        self.hidden_hide_bpm_spin.setDecimals(3)
        self.hidden_hide_bpm_spin.setSuffix(" BPM")
        self.hidden_hide_bpm_spin.setValue(config.hidden_hide_bpm)
        section.field(tr("MainWindow", "Hide BPM"), self.hidden_hide_bpm_spin, tr(
            "MainWindow", "The red line that carries each note off screen."))

        self.hidden_wall_bpm_spin = QDoubleSpinBox()
        self.hidden_wall_bpm_spin.setRange(1.0, 1000000.0)
        self.hidden_wall_bpm_spin.setDecimals(3)
        self.hidden_wall_bpm_spin.setSuffix(" BPM")
        self.hidden_wall_bpm_spin.setValue(config.hidden_wall_bpm)
        section.field(tr("MainWindow", "Wall BPM"), self.hidden_wall_bpm_spin, tr(
            "MainWindow", "The meter-1 red line that makes osu! draw the whole sheet."))

        # The floor is not the SV editor's 0.01: this whole gimmick lives at
        # about that value and the differences carrying the colour are several
        # decimals below it. SV_DECIMALS is what makes them typeable at all.
        sv_help = tr(
            "MainWindow",
            "Caution: the three SV values are the gimmick, and they are meant to sit "
            "within about a percent of each other. Wall SV decides how tight the sheet "
            "is; Don and Kat only read as a colour while both are above it and Kat is "
            "the larger. Ordinary-looking values will not read as this gimmick at all.",
        )
        self.hidden_base_sv_spin = self._sv_spin(config.hidden_base_sv)
        section.field(tr("MainWindow", "Wall SV"), self.hidden_base_sv_spin, sv_help)
        self.hidden_window_spin = QSpinBox()
        self.hidden_window_spin.setRange(1, 64)
        self.hidden_window_spin.setPrefix("1/")
        self.hidden_window_spin.setValue(config.hidden_window_divisor)
        section.field(tr("MainWindow", "Slit length"), self.hidden_window_spin, tr(
            "MainWindow",
            "One wall line makes osu! draw the whole sheet, and each note's slit is "
            "opened by raising SV for a fraction of a beat after it. Taiko places an "
            "object at its distance times the speed at its own time, so the raised "
            "bars sit ahead of the rest by that excess times how far away they still "
            "are -- the slit opens with distance and closes at the hit position.",
        ))
        self.hidden_don_sv_spin = self._sv_spin(config.hidden_don_sv)
        section.field(tr("MainWindow", "Don SV"), self.hidden_don_sv_spin, sv_help)
        self.hidden_kat_sv_spin = self._sv_spin(config.hidden_kat_sv)
        section.field(tr("MainWindow", "Kat SV"), self.hidden_kat_sv_spin, sv_help)
        self.hidden_hide_note_check = self._hide_note_check(config)
        section.switch(self.hidden_hide_note_check, tr("MainWindow", "Off shows the note inside its slit."),
                       self._slit_note_hint(), span=1)

    @staticmethod
    def _sv_spin(value: float) -> QDoubleSpinBox:
        spin = TrimmedDoubleSpinBox()
        spin.setRange(10.0 ** -SV_DECIMALS, 100.0)
        spin.setDecimals(SV_DECIMALS)
        spin.setSingleStep(0.0001)
        spin.setSuffix("\u00d7")
        spin.setValue(value)
        return spin

    # -- result --------------------------------------------------------------

    def mode(self) -> str:
        return self.mode_combo.currentData()

    def config(self) -> GimmickConfig:
        """The layer's config with this call's edits on it.

        Only the active page's fields are applied. The rest ride through
        untouched, so choosing a converter cannot quietly rewrite the numbers
        another one uses.
        """
        mode = self.mode()
        if mode == self.ANTI:
            return replace(
                self._base,
                anti_lines_per_beat=self.anti_density_spin.value(),
                anti_wall_bpm=(
                    self.anti_bpm_spin.value() if self.anti_bpm_check.isChecked() else None
                ),
                anti_don_ticks=self.anti_don_spin.value(),
                anti_kat_ticks=self.anti_kat_spin.value(),
                hide_note=self.anti_hide_note_check.isChecked(),
            )
        if mode == self.HIDDEN:
            return replace(
                self._base,
                hidden_hide_bpm=self.hidden_hide_bpm_spin.value(),
                hidden_wall_bpm=self.hidden_wall_bpm_spin.value(),
                hidden_base_sv=self.hidden_base_sv_spin.value(),
                hidden_don_sv=self.hidden_don_sv_spin.value(),
                hidden_kat_sv=self.hidden_kat_sv_spin.value(),
                hidden_window_divisor=self.hidden_window_spin.value(),
                hide_note=self.hidden_hide_note_check.isChecked(),
            )
        if self.layer_id == "barline":
            return replace(
                self._base,
                gimmick_bpm=self.bpm_spin.value(),
                spacing_ms=self.spacing_spin.value(),
                kat_spacing1_ms=self.kat_spins[0].value(),
                kat_spacing2_ms=self.kat_spins[1].value(),
                kat_spacing3_ms=self.kat_spins[2].value(),
                mirror_don_lines=self.mirror_don_check.isChecked(),
                mirror_kat_lines=self.mirror_kat_check.isChecked(),
                hide_note=self.hide_note_check.isChecked(),
                omit_note_barline=self.omit_note_barline_check.isChecked(),
            )
        return replace(
            self._base,
            gimmick_bpm=self.bpm_spin.value(),
            fake_slider_offset_ms=self.fake_offset_spin.value(),
            fake_slider_length=self.length_spin.value(),
            fake_slider_sv=self.fake_sv_spin.value(),
            fake_slider_bpm_multiplier=self.fake_slider_bpm_spin.value(),
            omit_barline=self.omit_barline_check.isChecked(),
            hide_note=self.hide_note_check.isChecked(),
        )

    def accept(self) -> None:
        # The three Kat spacings have no shared range to keep them distinct, so
        # like the Config dialog this one combination is checked before the
        # dialog closes rather than raising in the caller with nothing focused.
        try:
            self.config()
        except GimmickConfigError as error:
            QMessageBox.warning(self, tr("MainWindow", "Cannot convert with this"), str(error))
            return
        super().accept()


class BarlineFunctionDialog(SheetDialog):
    """Fill a dragged range with red lines, every `n` ms or every `n` snaps.

    The barline layer's answer to the SV editor's function tool. Two rhythms,
    because a run of barlines is one of two different things:

    * **Every n (ms)** -- scenery. n = 1 is the default because a barline
      gimmick's whole vocabulary is lines packed as tightly as the format
      allows, and coarser runs are what you tune it up to, not down from.
    * **Every n snaps** -- rhythm. Walks the chart's own beat grid at the chosen
      divisor, so the bars land where the music does rather than on a
      millisecond count that drifts against it.

    The snap walk uses the base timing snapshot, not the document: the document
    is the file being filled with 60000 BPM lines, and stepping along *those*
    would collapse the run into the first few milliseconds.
    """

    def __init__(
        self, start_ms: float, end_ms: float, parent=None,
        base_timing: list[TimingPoint] | None = None, snap_divisor: int = 4,
        note_times: set[int] | None = None, current_sv: float = 1.0, meter: int = 4,
    ) -> None:
        super().__init__(
            self._title(),
            tr("MainWindow", "Range: {0} to {1}").format(format_time(round(start_ms)), format_time(round(end_ms))),
            action=tr("MainWindow", "Generate"), rail=False, restore=False, parent=parent)
        icon = application_icon()
        if not icon.isNull():
            self.setWindowIcon(icon)
        self.start_ms = start_ms
        self.end_ms = end_ms
        self.base_timing = base_timing or []
        self.note_times = note_times or set()
        sheet = self.sheet
        # Rows are sheet fields; set_row_visible finds them by property.
        self._form_layout = None

        self.mode_combo = QComboBox()
        # Literal tr() calls, one per option -- see AddViewDialog on why a dict
        # lookup here would escape the i18n coverage gate.
        self.mode_combo.addItem(tr("MainWindow", "Every n (ms)"), "ms")
        self.mode_combo.addItem(tr("MainWindow", "Every n snaps"), "snaps")
        for text, data in self._extra_modes():
            self.mode_combo.addItem(text, data)
        where = sheet.add_section("where", tr("MainWindow", "Where"))
        pills = bind_segments(self.mode_combo)
        where.field(tr("MainWindow", "Generate at"), pills, tr(
            "MainWindow",
            "Every n ms is scenery: a barline gimmick's vocabulary is lines packed as tight as "
            "the format allows. Every n snaps walks the chart's own beat grid, so the lines land "
            "where the music does."), span=2)

        self.spacing_spin = QSpinBox()
        self.spacing_spin.setRange(1, 10000)
        self.spacing_spin.setSuffix(" ms")
        self.spacing_spin.setValue(1)
        where.field(tr("MainWindow", "Every"), self.spacing_spin, tr(
            "MainWindow", "One line every n milliseconds across the range."))

        self.snap_count_spin = QSpinBox()
        self.snap_count_spin.setRange(1, 64)
        self.snap_count_spin.setSuffix(" " + tr("MainWindow", "snaps"))
        self.snap_count_spin.setValue(1)
        where.field(tr("MainWindow", "Every"), self.snap_count_spin, tr(
            "MainWindow", "One line every n gridlines of the snap."))

        self.snap_combo = QComboBox()
        for divisor in SNAP_DIVISORS:
            self.snap_combo.addItem(f"1/{divisor}", divisor)
        found = self.snap_combo.findData(int(snap_divisor))
        self.snap_combo.setCurrentIndex(found if found >= 0 else self.snap_combo.findData(4))
        where.field(tr("MainWindow", "Snap"), self.snap_combo, tr(
            "MainWindow", "The gridline spacing the snaps are counted in."))

        # Shifts where the walk itself begins -- the first "every n (ms)" line,
        # or (in snap mode) the anchor `_snap_times` snaps to before it starts
        # counting divisions. That anchor is what "every n snaps" counts from,
        # so this is a phase shift of *which* grid lines get chosen, not a
        # shift of where the chosen ones land.
        self.start_offset_spin = QSpinBox()
        self.start_offset_spin.setRange(-10000, 10000)
        self.start_offset_spin.setSuffix(" ms")
        self.start_offset_spin.setValue(0)
        where.field(tr("MainWindow", "Starting offset"), self.start_offset_spin, tr(
            "MainWindow",
            "Moves where the walk starts counting from. In snap mode this changes which "
            "gridlines are picked, not where the picked ones land."))

        # Shifts every already-selected line by a fixed amount, after the walk
        # (or the note filter) has picked which milliseconds those are. A
        # snap-mode run wants this far more often than a starting offset: it
        # is what puts a red line consistently early or late of the beat
        # itself rather than of wherever the range happened to start.
        self.snap_offset_spin = QSpinBox()
        self.snap_offset_spin.setRange(-10000, 10000)
        self.snap_offset_spin.setSuffix(" ms")
        self.snap_offset_spin.setValue(0)
        where.field(tr("MainWindow", "Snap offset"), self.snap_offset_spin, tr(
            "MainWindow",
            "Moves every picked line by the same amount: consistently early or late of the beat."))

        # Off by default: a red line landing on a note's own millisecond resets
        # SV to 1.0x for that note and restarts measure counting under it, which
        # is a gimmick in its own right rather than scenery. Available, because
        # doing it deliberately is a real technique.
        self.allow_on_notes_check = QCheckBox(tr("MainWindow", "Allow on existing notes"))
        self.allow_on_notes_check.setChecked(False)
        self.allow_on_notes_check.toggled.connect(self._update_count)
        where.switch(self.allow_on_notes_check, tr(
            "MainWindow", "Off skips any millisecond that already has a note."))

        # A run of red lines at the chart's own BPM is scenery standing still.
        # Ramping it across the range is what makes the bars accelerate, and the
        # growth functions are the SV generator's own (`sv_ease`), so a barline
        # sweep and an SV sweep shaped "Exp 1.6" mean the same curve.
        # Literal tr() calls, one per option -- see AddViewDialog on why a dict
        # lookup here would escape the i18n coverage gate.
        bpm = sheet.add_section("bpm", tr("MainWindow", "BPM"))
        self._bpm_section = bpm
        self.bpm_curve_combo = QComboBox()
        self.bpm_curve_combo.addItem(tr("MainWindow", "Base timing BPM"), "none")
        self.bpm_curve_combo.addItem(tr("MainWindow", "Linear"), "linear")
        self.bpm_curve_combo.addItem(tr("MainWindow", "Exp 1.3"), "exp1.3")
        self.bpm_curve_combo.addItem(tr("MainWindow", "Exp 1.6"), "exp1.6")
        self.bpm_curve_combo.addItem(tr("MainWindow", "True Exp"), "true_exp")
        self.bpm_curve_combo.currentIndexChanged.connect(self._update_mode)
        curve_pills = bind_segments(self.bpm_curve_combo)
        bpm.field(tr("MainWindow", "BPM growth"), curve_pills, tr(
            "MainWindow",
            "Base timing BPM writes the chart's own BPM: the lines change where the bars fall "
            "and nothing else. A curve ramps the BPM from Start to End across the range, which "
            "is what makes the bars accelerate."), span=2)
        self.bpm_curve_combo.setProperty("sheetField", curve_pills.property("sheetField"))

        start_bpm = base_bpm_at(self.base_timing, start_ms) if self.base_timing else 120.0
        self.start_bpm_spin = QDoubleSpinBox()
        self.start_bpm_spin.setRange(1.0, 1000000.0)
        self.start_bpm_spin.setDecimals(4)
        self.start_bpm_spin.setSuffix(" BPM")
        self.start_bpm_spin.setValue(start_bpm)
        bpm.field(tr("MainWindow", "Start BPM"), self.start_bpm_spin, tr(
            "MainWindow", "The first line's BPM."))

        self.end_bpm_spin = QDoubleSpinBox()
        self.end_bpm_spin.setRange(1.0, 1000000.0)
        self.end_bpm_spin.setDecimals(4)
        self.end_bpm_spin.setSuffix(" BPM")
        self.end_bpm_spin.setValue(start_bpm * 2)
        bpm.field(tr("MainWindow", "End BPM"), self.end_bpm_spin, tr(
            "MainWindow", "The last line's BPM."))

        # Same reason as the Red Line tool's Config row: osu! takes meter from
        # the uninherited point in force, so every line in the run re-bars what
        # follows it. Seeded from that Config so the two tools agree.
        self.meter_spin = QSpinBox()
        self.meter_spin.setRange(1, 10000)
        self.meter_spin.setValue(int(meter))
        bpm.field(tr("MainWindow", "Meter"), self.meter_spin, tr(
            "MainWindow",
            "Beats per bar for each line. osu! reads meter from the red line in force, so every "
            "line in the run re-bars what follows it."))

        # Every uninherited point resets SV to 1.0x, so a run of red lines
        # silently flattens the chart's scroll speed for its whole length
        # unless a green line goes down with each one. "Current speed" writes
        # exactly the SV already in force at each millisecond -- the run then
        # changes where the bars fall and nothing else, which is what you
        # almost always want and why it is the default. A typed value drives
        # the whole run at one speed instead.
        # Literal tr() calls, one per option -- see AddViewDialog on the gate.
        speed = sheet.add_section("speed", tr("MainWindow", "Speed"))
        self.sv_mode_combo = QComboBox()
        self.sv_mode_combo.addItem(tr("MainWindow", "Current speed"), "current")
        self.sv_mode_combo.addItem(tr("MainWindow", "Custom"), "custom")
        self.sv_mode_combo.currentIndexChanged.connect(self._update_mode)
        speed.field(tr("MainWindow", "SV"), bind_segments(self.sv_mode_combo), tr(
            "MainWindow",
            "Every red line resets SV to 1\u00d7, so each gets a green line too. Current speed "
            "writes the SV already in force there; Custom drives the whole run at one speed."))

        self.sv_spin = TrimmedDoubleSpinBox()
        self.sv_spin.setRange(0.01, 100.0)
        self.sv_spin.setDecimals(SV_DECIMALS)
        self.sv_spin.setSingleStep(0.05)
        self.sv_spin.setSuffix("\u00d7")
        self.sv_spin.setValue(float(current_sv))
        speed.field(tr("MainWindow", "SV multiplier"), self.sv_spin, tr(
            "MainWindow", "The speed every line in the run carries."))

        # The count Generate will write, in the footer where the action is.
        self.count_label = self.summary
        sheet.set_help_default(
            tr("MainWindow", "What Generate writes"),
            tr("MainWindow", "Each tick above is one line in the range, drawn over the notes already there."))
        self.run_diagram = Diagram(self._paint_run, 110)
        sheet.set_diagram(self.run_diagram, tr("MainWindow", "Preview"))
        for widget in (
            self.spacing_spin, self.snap_count_spin,
            self.start_offset_spin, self.snap_offset_spin,
        ):
            widget.valueChanged.connect(self._update_count)
        self.snap_combo.currentIndexChanged.connect(self._update_count)
        self.mode_combo.currentIndexChanged.connect(self._update_mode)
        self._update_mode()
        self.resize(900, 600)

    # The preview's tick colour: what one line of the run is.
    RUN_COLOR = "#ff5a5a"

    def _title(self) -> str:
        return tr("MainWindow", "Generate red lines")

    def _extra_modes(self) -> list[tuple[str, str]]:
        """Rhythms a subclass adds to Generate at, before its pills are drawn."""
        return []

    def _paint_run(self, painter: QPainter, rect: QRect) -> None:
        """Where the run lands across the range, over the notes in it."""
        span = max(1.0, self.end_ms - self.start_ms)
        left, right = rect.left() + 10, rect.right() - 10

        def x_of(at: float) -> float:
            return left + (at - self.start_ms) / span * (right - left)

        base = rect.top() + rect.height() * 0.62
        painter.setPen(QPen(_DIAGRAM_RULE, 1))
        painter.drawLine(QPointF(left, base), QPointF(right, base))
        painter.setPen(Qt.NoPen)
        painter.setBrush(QColor(*DON_COLOR))
        for at in self.note_times:
            if self.start_ms <= at <= self.end_ms:
                painter.drawEllipse(QPointF(x_of(at), base), 3.5, 3.5)
        times = self.times()
        painter.setPen(QPen(QColor(self.RUN_COLOR), 1))
        for at in times[:4000]:
            x = x_of(at)
            painter.drawLine(QPointF(x, rect.top() + 12), QPointF(x, base - 8))
        _diagram_text(painter, left, rect.bottom() - 6, format_time(round(self.start_ms)))
        _diagram_text(painter, right, rect.bottom() - 6, format_time(round(self.end_ms)), align=Qt.AlignRight)

    def _update_mode(self) -> None:
        """Show only the rhythm the chosen mode actually uses.

        setRowVisible collapses the whole form row; hiding the widget alone
        would leave its label and blank space behind.
        """
        mode = str(self.mode_combo.currentData())
        snaps = mode == "snaps"
        set_row_visible(self._form_layout, self.spacing_spin, mode == "ms")
        set_row_visible(self._form_layout, self.snap_count_spin, snaps)
        set_row_visible(self._form_layout, self.snap_combo, snaps)
        # Starting offset shifts an anchor "notes" mode does not have -- the
        # chart's own notes are picked by their fixed positions in range, not
        # walked from one. Snap offset shifts each already-picked line, which
        # a flat "every n (ms)" run has no separate use for: sliding every
        # line by the same amount there is just a different starting offset.
        set_row_visible(self._form_layout, self.start_offset_spin, mode != "notes")
        set_row_visible(self._form_layout, self.snap_offset_spin, mode != "ms")
        ramping = str(self.bpm_curve_combo.currentData()) != "none"
        set_row_visible(self._form_layout, self.start_bpm_spin, ramping)
        set_row_visible(self._form_layout, self.end_bpm_spin, ramping)
        set_row_visible(
            self._form_layout, self.sv_spin, self.sv_multiplier() is not None
        )
        self._update_count()

    def sv_multiplier(self) -> float | None:
        """The SV every generated line carries, or None for "current speed".

        None rather than a number, because "current" is a different value at
        every millisecond in the run once the chart has SV of its own -- the
        caller reads it per line.
        """
        if str(self.sv_mode_combo.currentData()) == "custom":
            return float(self.sv_spin.value())
        return None

    def _update_count(self) -> None:
        """Say how many lines Ok will write. At n = 1 a careless drag is
        thousands of them, and the number is the only warning worth giving."""
        count = len(self.times())
        self.set_summary(tr("MainWindow", "{0} red lines").format(count), bad=count == 0)
        self.action_button.setEnabled(count > 0)
        self.run_diagram.refresh()

    def times(self) -> list[int]:
        """Every millisecond a line lands on, in order.

        Bounded by the dragged range rather than by a typed cap: how many lines
        a gimmick wants is the mapper's call, and the selection is where they
        already said how far it goes.

        Two offsets, not one, because they answer different questions.
        Starting offset moves the anchor the walk counts *from* -- in snap
        mode that is a phase shift, changing which grid lines "every n snaps"
        picks, not just where the picked ones land. Snap offset moves each
        already-picked line by a fixed amount afterward, which is what puts a
        run consistently early or late of the beat rather than of wherever
        the range started.
        """
        start_offset = self.start_offset_spin.value()
        snap_offset = self.snap_offset_spin.value()
        last = round(self.end_ms)
        mode = str(self.mode_combo.currentData())
        if mode == "notes":
            # The chart's own notes inside the range. Offered only where a
            # subclass adds the option (FakeSliderFunctionDialog): a run of red
            # lines has no reason to land on notes, and refuses to by default.
            # Fixed positions, not a walk -- there is no anchor for a starting
            # offset to shift, so only the snap offset reaches this mode.
            return sorted(
                at + snap_offset for at in self.note_times
                if round(self.start_ms) <= at <= last
            )
        if mode == "snaps":
            times = [
                at + snap_offset for at in self._snap_times(start_offset)
                if at + snap_offset <= last
            ]
        else:
            first = osu_snap_ms(self.start_ms) + start_offset
            times = list(range(first, last + 1, self.spacing_spin.value())) if first <= last else []
        if self.allow_on_notes_check.isChecked() or not self.note_times:
            return times
        return [at for at in times if at not in self.note_times]

    def bpms(self, times: list[int]) -> list[float]:
        """The BPM each line in `times` carries, in the same order.

        The base timing's own BPM by default -- a line that changes nothing but
        where the bars fall. With a growth function chosen, a ramp from Start to
        End BPM eased across the range instead, which is what makes a run of
        bars accelerate rather than just repeat.

        Progress is measured in *time*, not in line index, so the curve is the
        same shape whether the run is packed every millisecond or spread over
        the beat grid.
        """
        function_id = str(self.bpm_curve_combo.currentData())
        if function_id == "none" or not times:
            return [base_bpm_at(self.base_timing, at) for at in times]
        start_bpm = self.start_bpm_spin.value()
        end_bpm = self.end_bpm_spin.value()
        span = times[-1] - times[0]
        return [
            start_bpm + (end_bpm - start_bpm) * sv_ease(
                function_id, 0.0 if span <= 0 else (at - times[0]) / span,
                start_bpm, end_bpm,
            )
            for at in times
        ]

    def _snap_times(self, start_offset: int = 0) -> list[int]:
        """The beat grid across the range, every `n` divisions.

        Stepped one division at a time and then taken every `n`th rather than
        multiplied out, because beat length can change mid-range: a BPM section
        starting inside the selection has to re-anchor the walk, which a single
        multiplication cannot express.

        `start_offset` moves the anchor the walk snaps to before counting
        divisions -- a phase shift of which grid lines "every n" lands on,
        not a shift of the range itself. `end_ms` stays put regardless: the
        dragged range's own end is still the hard bound.
        """
        if not self.base_timing:
            return []
        divisor = int(self.snap_combo.currentData())
        every = self.snap_count_spin.value()
        anchor = self.start_ms + start_offset
        cursor = snap_time(self.base_timing, anchor, divisor)
        if cursor < anchor - 0.001:
            cursor += active_uninherited_at(self.base_timing, cursor).beat_length / divisor
        times: list[int] = []
        index = 0
        # A pathological beat length would otherwise walk forever; the SV
        # generator caps its own walk at the same order of magnitude.
        while cursor <= self.end_ms + 0.001 and len(times) < 20001:
            if index % every == 0:
                # osu_snap_ms, not round: a beat position commits to a whole
                # millisecond by truncating, same as every other snapped
                # gridline in the app (time_axis.osu_snap_ms). round()'s
                # banker's rounding sent adjacent grid lines up or down
                # depending on which side of a half-millisecond they happened
                # to fall on -- invisible on an exact-dividing beat length,
                # but on a real one it made a fixed snap offset land 1ms off
                # depending on which snap it was relative to.
                times.append(osu_snap_ms(cursor))
            step = active_uninherited_at(self.base_timing, cursor + 0.001).beat_length / divisor
            if step <= 0:
                break
            cursor += step
            index += 1
        return times


class FakeSliderFunctionDialog(BarlineFunctionDialog):
    """Fill a dragged range with fake sliders, or with shiny notes.

    A subclass rather than a second dialog: the two rhythms ("every n ms" for
    scenery, "every n snaps" for something the music can be read against), the
    offset, and the walk along the base timing grid are the same question the
    barline generator already asks, and answering it twice in two places is how
    the two drifted apart last time. What differs is what lands on each
    millisecond, which is the two rows this adds -- and the BPM ramp, which
    belongs to red lines and is hidden.
    """

    def __init__(
        self, start_ms: float, end_ms: float, parent=None,
        base_timing: list[TimingPoint] | None = None, snap_divisor: int = 4,
        shiny_count: int = DEFAULT_SHINY_COUNT,
        shiny_bpm_multiplier: float = 1.0, fake_slider_bpm_multiplier: float = 1.0,
        note_times: set[int] | None = None,
    ) -> None:
        self._subclass_ready = False
        super().__init__(
            start_ms, end_ms, parent, base_timing=base_timing, snap_divisor=snap_divisor,
            note_times=note_times,
        )

        # Each object kind keeps its own remembered multiplier -- switching
        # the combo below is a change of *which* object this run builds, not
        # an edit to either number, so it must not clobber the other kind's
        # setting the way a single shared value would.
        self._kind_multipliers = {
            "shiny": float(shiny_bpm_multiplier), "regular": float(fake_slider_bpm_multiplier),
        }

        # Literal tr() calls, one per option -- see AddViewDialog on why a dict
        # lookup here would escape the i18n coverage gate.
        self.object_combo = QComboBox()
        self.object_combo.addItem(tr("MainWindow", "Fake slider"), "regular")
        self.object_combo.addItem(tr("MainWindow", "Shiny"), "shiny")
        self.object_combo.currentIndexChanged.connect(self._object_kind_changed)

        self.shiny_count_spin = QSpinBox()
        self.shiny_count_spin.setRange(1, 50)
        self.shiny_count_spin.setValue(int(shiny_count))

        # A red line's BPM is also its scroll speed, so retiming a structure's
        # own governing line is how it gets room to move. For a shiny the SV
        # written alongside it divides by the same number, so the note travels
        # at the speed it did before; a fake slider has no such green line to
        # pay it back with (see the hint below), so this is a plain speed
        # change there. The named multiples are the ones this is actually used
        # at; Custom is there because the list can never be complete.
        # Literal tr() calls, one per option -- see AddViewDialog on the gate.
        self.bpm_multiplier_combo = QComboBox()
        self.bpm_multiplier_combo.addItem(tr("MainWindow", "Current BPM"), 1.0)
        self.bpm_multiplier_combo.addItem(tr("MainWindow", "Half"), 0.5)
        self.bpm_multiplier_combo.addItem(tr("MainWindow", "2x"), 2.0)
        self.bpm_multiplier_combo.addItem(tr("MainWindow", "3x"), 3.0)
        self.bpm_multiplier_combo.addItem(tr("MainWindow", "4x"), 4.0)
        self.bpm_multiplier_combo.addItem(tr("MainWindow", "8x"), 8.0)
        self.bpm_multiplier_combo.addItem(tr("MainWindow", "Custom"), None)
        self.bpm_multiplier_combo.currentIndexChanged.connect(self._update_object_mode)

        self.bpm_multiplier_spin = QDoubleSpinBox()
        self.bpm_multiplier_spin.setRange(0.001, 1000.0)
        self.bpm_multiplier_spin.setDecimals(3)

        self.bpm_multiplier_spin.setSuffix("\u00d7")

        self.multiplier_hint = QLabel()
        self.multiplier_hint.setObjectName("fieldNote")
        self.multiplier_hint.setWordWrap(True)
        self.multiplier_hint.setProperty("sheetField", self.multiplier_hint)

        what = self.sheet.add_section("what", tr("MainWindow", "What"))
        self.sheet.body_layout.removeWidget(what)
        self.sheet.body_layout.insertWidget(1, what)
        object_pills = bind_segments(self.object_combo)
        what.field(tr("MainWindow", "Object"), object_pills, tr(
            "MainWindow", "A shiny is a stack of fake sliders under a note."), span=2)
        self.shiny_count_spin.setSuffix(" " + tr("MainWindow", "sliders"))
        what.field(tr("MainWindow", "Stack size"), self.shiny_count_spin, tr(
            "MainWindow", "How many fake sliders sit under each shiny note."))
        what.break_row()
        multiplier_pills = bind_segments(self.bpm_multiplier_combo)
        what.field(tr("MainWindow", "Red line BPM"), multiplier_pills, tr(
            "MainWindow",
            "A red line's BPM is also its scroll speed, so retiming a structure's own line is "
            "how it gets room to move. The named multiples are the ones this is used at."), span=2)
        what.field(tr("MainWindow", "Custom multiplier"), self.bpm_multiplier_spin)
        what.add(self.multiplier_hint, 2)

        # The BPM ramp writes a growing BPM onto each red line; here the red
        # lines are a structure's own and their BPM is not the mapper's to bend.
        self._bpm_section.hide()
        self._subclass_ready = True
        # Snaps, not milliseconds. A barline run wants every millisecond it can
        # get; a run of drawn objects at that density is thousands of sliders
        # nobody can see past.
        snaps = self.mode_combo.findData("snaps")
        if snaps >= 0:
            self.mode_combo.setCurrentIndex(snaps)
        self._load_kind_multiplier()
        self._update_object_mode()

    RUN_COLOR = "#fbb706"

    def _title(self) -> str:
        return tr("MainWindow", "Generate fake sliders")

    def _extra_modes(self) -> list[tuple[str, str]]:
        # A third rhythm the barline generator has no use for: the chart's own
        # notes. Turning a run of notes into shiny ones is the same generation
        # with the beat grid swapped for where the notes actually are.
        return [(tr("MainWindow", "At each note"), "notes")]

    def _object_kind_changed(self) -> None:
        self._load_kind_multiplier()
        self._update_object_mode()

    def _load_kind_multiplier(self) -> None:
        """Show the selected object's own remembered multiplier."""
        value = self._kind_multipliers[self.object_kind()]
        found = self.bpm_multiplier_combo.findData(value)
        self.bpm_multiplier_combo.setCurrentIndex(
            found if found >= 0 else self.bpm_multiplier_combo.findData(None)
        )
        self.bpm_multiplier_spin.setValue(value)

    def _update_object_mode(self) -> None:
        shiny = self.object_kind() == "shiny"
        # The combo itself is shown for both kinds now -- a fake slider's own
        # restore line is retimed the same way a shiny's is. The hint below it
        # stays shiny-only: it explains the SV compensation that pays the
        # retime back, and a fake slider has no green line to do that with.
        custom = self.bpm_multiplier_combo.currentData() is None
        set_row_visible(self._form_layout, self.bpm_multiplier_spin, custom)
        set_row_visible(self._form_layout, self.shiny_count_spin, shiny)
        multiplier = self.bpm_multiplier()
        show_hint = shiny and multiplier != 1.0
        self.multiplier_hint.setText(
            tr(
                "MainWindow",
                "Shiny only: the red line is written at {0}x the chart's BPM, "
                "with a green line right after it dividing SV by the same "
                "amount, so the shiny travels at the speed it already did. A "
                "fake slider's restore line has no such green line, so retiming "
                "it there is a plain speed change with nothing to compensate.",
            ).format(f"{multiplier:g}") if show_hint else ""
        )
        set_row_visible(self._form_layout, self.multiplier_hint, show_hint)
        self._update_count()

    def bpm_multiplier(self) -> float:
        """The chosen multiple of the chart's own BPM, named or typed."""
        chosen = self.bpm_multiplier_combo.currentData()
        return float(self.bpm_multiplier_spin.value() if chosen is None else chosen)

    def _update_count(self) -> None:
        # Overrides the barline generator's "N red lines", which is not what
        # this one writes.
        if not getattr(self, "_subclass_ready", False):
            return  # still inside the base __init__
        count = len(self.times())
        self.set_summary(tr("MainWindow", "{0} objects").format(count), bad=count == 0)
        self.action_button.setEnabled(count > 0)
        self.run_diagram.refresh()

    def object_kind(self) -> str:
        return str(self.object_combo.currentData())

    def shiny_count(self) -> int:
        return int(self.shiny_count_spin.value())


class MultiFakeSliderDialog(SheetDialog):
    """The Multiple Fake Slider tool's config: a run's shape, chosen once.

    Opened by `_set_gimmick_tool` when the tool is *selected*, not on every
    click -- a run's start, end and spacing describe the tool, not one
    placement, so asking on each click would be the same question asked a
    dozen times over a dozen sliders. Start and end locate the run's
    *structures*; each structure's own slider then lands its usual
    `fake_slider_offset_ms` further on, exactly where one click of the plain
    Fake Slider tool would put it -- see `MainWindow._multi_fake_slider_commands`.
    """

    def __init__(self, parent=None) -> None:
        super().__init__(
            tr("MainWindow", "Multiple fake slider"),
            tr("MainWindow", "The run each click of the tool places, around the snap you click."),
            action=tr("MainWindow", "OK"), rail=False, explain=False, restore=False, parent=parent)
        self.action_button.clicked.disconnect()
        self.action_button.clicked.connect(self._accept)
        icon = application_icon()
        if not icon.isNull():
            self.setWindowIcon(icon)
        section = self.sheet.add_section("run", tr("MainWindow", "Run"))

        self.start_spin = QSpinBox()
        # Negative allowed and asymmetric with End on purpose: a run is
        # routinely wanted leading into the click as well as following it.
        self.start_spin.setRange(-10000, 10000)
        self.start_spin.setSuffix(" ms")
        self.start_spin.setValue(0)
        section.field(tr("MainWindow", "Start offset"), self.start_spin)

        self.end_spin = QSpinBox()
        self.end_spin.setRange(-10000, 10000)
        self.end_spin.setSuffix(" ms")
        self.end_spin.setValue(16)
        section.field(tr("MainWindow", "End offset"), self.end_spin)

        self.distance_spin = QSpinBox()
        self.distance_spin.setRange(1, 10000)
        self.distance_spin.setSuffix(" ms")
        self.distance_spin.setValue(2)
        section.field(tr("MainWindow", "Distance"), self.distance_spin)
        self.resize(460, 300)

    def _accept(self) -> None:
        # Clamped up rather than refused: End below Start is "I want just the
        # one structure at Start", not a mistake to bounce back to the user.
        if self.end_spin.value() < self.start_spin.value():
            self.end_spin.setValue(self.start_spin.value())
        self.accept()

    def parameters(self) -> tuple[int, int, int]:
        """(start, end, distance), all in ms."""
        return (self.start_spin.value(), self.end_spin.value(), self.distance_spin.value())


class TimingLineDialog(SheetDialog):
    """Retype one timing line: its value, and the millisecond it sits on.

    One dialog for both kinds, because the only difference is what the value
    means -- BPM on a red line, SV multiplier on a green one. Both carry a time,
    and moving a line is the edit that has no other keyboard route: dragging
    retimes it only as far as the snap grid allows.
    """

    def __init__(self, point: TimingPoint, parent=None) -> None:
        self.uninherited = point.uninherited
        super().__init__(
            tr("MainWindow", "Red line") if self.uninherited else tr("MainWindow", "Green line"),
            format_time(round(point.time)),
            action=tr("MainWindow", "OK"), rail=False, explain=False, restore=False, parent=parent)
        icon = application_icon()
        if not icon.isNull():
            self.setWindowIcon(icon)
        section = self.sheet.add_section("line", tr("MainWindow", "Line"))

        self.value_spin = TrimmedDoubleSpinBox()
        if self.uninherited:
            self.value_spin.setRange(0.001, 1000000.0)
            self.value_spin.setDecimals(3)
            self.value_spin.setSuffix(" BPM")
            self.value_spin.setValue(point.bpm or 120.0)
            section.field(tr("MainWindow", "BPM"), self.value_spin)
        else:
            self.value_spin.setRange(0.01, 100.0)
            self.value_spin.setDecimals(SV_DECIMALS)
            self.value_spin.setSuffix("\u00d7")
            self.value_spin.setValue(point.sv_multiplier)
            section.field(tr("MainWindow", "SV multiplier"), self.value_spin)

        self.time_spin = QSpinBox()
        self.time_spin.setRange(0, 100000000)
        self.time_spin.setSuffix(" ms")
        self.time_spin.setValue(round(point.time))
        section.field(tr("MainWindow", "Time"), self.time_spin)

        # Beats per bar, which is where this line's barlines fall. Red lines
        # only: osu! reads meter from the uninherited point in force, so on a
        # green line the field is written but never counts. The ceiling is
        # generous on purpose -- anti-barline writes 999 so a line never stamps
        # a second bar, and clamping that on open would silently rewrite it.
        self.meter_spin = None
        if self.uninherited:
            self.meter_spin = QSpinBox()
            self.meter_spin.setRange(1, 10000)
            self.meter_spin.setValue(max(1, point.meter))
            section.field(tr("MainWindow", "Meter"), self.meter_spin)

        # The two effects bits, editable where the line itself is. Both are
        # things a gimmick has to fix line by line -- a stray bar to hide, a
        # kiai section a generated line switched off -- and until now the only
        # way to reach either was a text editor.
        section.break_row()
        self.kiai_check = QCheckBox(tr("MainWindow", "Kiai"))
        self.kiai_check.setChecked(point.kiai)
        section.switch(self.kiai_check, span=1)

        self.omit_barline_check = QCheckBox(tr("MainWindow", "Omit barline"))
        self.omit_barline_check.setChecked(point.omit_first_barline)
        section.switch(self.omit_barline_check, span=1)
        self.resize(460, 320)

    def effects(self, point: TimingPoint) -> int:
        """`point.effects` with only the two checkboxes' bits rewritten.

        Masked rather than rebuilt: the field carries bits this dialog does not
        offer, and dropping them would be a silent edit.
        """
        effects = point.effects
        for bit, checked in (
            (EFFECT_KIAI, self.kiai_check.isChecked()),
            (EFFECT_OMIT_FIRST_BARLINE, self.omit_barline_check.isChecked()),
        ):
            effects = (effects | bit) if checked else (effects & ~bit)
        return effects

    def changes(self, point: TimingPoint) -> dict:
        """`EditTimingPoint` changes, holding only the fields that moved.

        Every field in one command, so retiming a line, changing its value and
        toggling kiai together is one Ctrl+Z rather than three.
        """
        changes = {}
        time_ms = float(self.time_spin.value())
        if time_ms != point.time:
            changes["time"] = (point.time, time_ms)
        value = self.value_spin.value()
        beat_length = 60000.0 / value if self.uninherited else -100.0 / value
        if beat_length != point.beat_length:
            changes["beat_length"] = (point.beat_length, beat_length)
        if self.meter_spin is not None and self.meter_spin.value() != point.meter:
            changes["meter"] = (point.meter, self.meter_spin.value())
        effects = self.effects(point)
        if effects != point.effects:
            changes["effects"] = (point.effects, effects)
        return changes


# sv_ease and _true_exp_ease live in sv_curves now, beside the detector that
# reads their curves back out of a chart (experimental conversion).


# Relative, not absolute, because the BPMs compared here span five orders of
# magnitude: a chart line at 176.9 and a gimmick line at 60000 cannot share one
# millisecond-scale epsilon. A red line's BPM is never stored -- it is
# 60000/beat_length, recomputed from a beat_length that has been through a text
# file with a handful of decimals -- so an authored 60000 and a computed one
# differ in the last few digits and `==` says no. One part in a million is far
# tighter than any two red lines a human would ever want to tell apart, and far
# looser than the round trip's error.
BPM_MATCH_RELATIVE_EPSILON = 1e-6


def bpm_matches(bpm: float | None, wanted: float) -> bool:
    """Is `bpm` the same red-line BPM as `wanted`, allowing for float drift?"""
    if bpm is None:
        return False
    return abs(bpm - wanted) <= BPM_MATCH_RELATIVE_EPSILON * max(abs(bpm), abs(wanted), 1.0)


def bpm_in_range(bpm: float | None, low: float, high: float) -> bool:
    """Is `bpm` within [low, high], inclusive, allowing for the same float
    drift bpm_matches guards against?

    The tolerance is applied per end rather than as one shared absolute
    slop, for the same reason bpm_matches scales it by the value being
    compared: a red line's BPM is recomputed as 60000/beat_length, so an
    authored 500.0 can come back as 499.99999...  and a fixed epsilon would
    be wrong by orders of magnitude between a 60 BPM line and a 60000 BPM
    barline gimmick one.
    """
    if bpm is None:
        return False
    low_tolerance = BPM_MATCH_RELATIVE_EPSILON * max(abs(bpm), abs(low), 1.0)
    high_tolerance = BPM_MATCH_RELATIVE_EPSILON * max(abs(bpm), abs(high), 1.0)
    return bpm >= low - low_tolerance and bpm <= high + high_tolerance


class SVFunctionPreview(QWidget):
    """20 dots showing what Generate would actually produce.

    Plots the real rate at each step (initial -> final through `sv_ease`), not
    a normalised 0..1 curve, so a 1.10x -> 0.90x sweep is drawn *descending*.
    The old version always rose left-to-right whatever the rates were, which
    made it a picture of the easing function rather than of the result -- the
    one case where the preview mattered most (did I get the direction right?)
    was the case it could not show.
    """

    def __init__(self, width: int = 190, height: int = 130, *, labels: bool = True) -> None:
        super().__init__()
        self.function_id = "linear"
        self.initial_rate = 1.0
        self.final_rate = 1.0
        # "", "point" or "pair" -- see SVFunctionDialog's mode combo. Oscillation
        # is the same easing function read as an *amplitude* rather than as a
        # position, so it belongs here rather than in a second preview widget:
        # the curve drawn is still exactly what Generate writes.
        self.oscillate = ""
        # The dialog renders one of these per function button, at button size
        # and without the endpoint labels -- there is no room for them there,
        # and the same two numbers on all seven tiles say nothing anyway.
        self.labels = labels
        self.setFixedSize(width, height)

    def set_function(self, function_id: str) -> None:
        self.function_id = function_id
        self.update()

    def set_range(self, initial_rate: float, final_rate: float) -> None:
        self.initial_rate = float(initial_rate)
        self.final_rate = float(final_rate)
        self.update()

    def set_oscillate(self, mode: str) -> None:
        self.oscillate = mode
        self.update()

    def rate_at(self, t: float) -> float:
        return self.initial_rate + (self.final_rate - self.initial_rate) * sv_ease(
            self.function_id, t, self.initial_rate, self.final_rate,
        )

    def rates(self, count: int) -> list[float]:
        """The `count` values Generate would write, in order.

        One function for the preview and for `_generate_sv`'s own loop would be
        better still, but that loop also applies the position offset and the
        BPM compensation, neither of which the preview knows about. This is the
        shape; that is the shape with the map's own numbers folded in.
        """
        if self.oscillate:
            return oscillating_series(
                self.initial_rate,
                abs(self.final_rate - self.initial_rate),
                count,
                lambda t: sv_ease(self.function_id, t, self.initial_rate, self.final_rate),
                per_pair=self.oscillate == "pair",
            )
        return [self.rate_at(index / max(1, count - 1)) for index in range(count)]

    def paintEvent(self, event) -> None:
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing, True)
        painter.fillRect(self.rect(), theme.color("#151b24"))
        painter.setPen(QPen(theme.color("#3a4554"), 1))
        painter.drawRect(self.rect().adjusted(0, 0, -1, -1))

        margin = 22.0 if self.labels else 10.0
        width = self.width() - margin * 2
        height = self.height() - margin * 2

        rates = self.rates(20)
        low, high = min(rates), max(rates)
        span = high - low

        dots = []
        for i, rate in enumerate(rates):
            t = i / 19
            # A flat sweep has no span to normalise against; draw it down the
            # middle rather than dividing by zero or pinning it to an edge.
            ratio = 0.5 if span < 1e-9 else (rate - low) / span
            dots.append(QPointF(margin + t * width, margin + (1 - ratio) * height))

        painter.setPen(QPen(theme.rgba(243, 166, 189, 110), 1))
        painter.drawPolyline(QPolygonF(dots))
        painter.setPen(Qt.NoPen)
        painter.setBrush(theme.color("#f3a6bd"))
        radius = 3 if self.labels else 2
        for dot in dots:
            painter.drawEllipse(dot, radius, radius)

        if not self.labels:
            return

        painter.setPen(QPen(QColor(225, 230, 240, 220), 1))
        painter.drawText(QPointF(4, dots[0].y() - 6), f"{rates[0]:.2f}x")
        final_text = f"{rates[-1]:.2f}x"
        text_width = painter.fontMetrics().horizontalAdvance(final_text)
        painter.drawText(QPointF(self.width() - text_width - 4, dots[-1].y() - 6), final_text)


class SVFunctionDialog(SheetDialog):
    """M4 function mode: drag-select a range, then generate an eased SV sweep
    across it.

    A config sheet: the plot of every rate Generate will write across the
    top, the curves as a row of chips under it, then the numbers in sections.
    The curves used to be eight 144px tiles, each plotting its own preview of
    the typed range -- which at the default 1.00x -> 1.00x made all eight the
    same flat line. A chip draws the *shape* (rising or falling with the
    range) and the one large plot draws the result.

    "Generate at" decides the point positions:

    * **Each note** (default) -- one SV point per hit object inside the
      selected range, and nothing between them. This is what an SV sweep is
      usually for: the scroll speed only has to be right where a note is.
    * **Every snap** -- one point per beat subdivision of the chosen divisor,
      for sweeps that must move continuously rather than note by note.

    Position offset defaults to -5ms: an SV point has to take effect
    *slightly before* the note it governs, or that note is still drawn at the
    previous speed.
    """

    DEFAULT_POSITION_OFFSET_MS = -5
    # Square tile, with its graph above the name. The tile *is* the preview now,
    # so it is worth the room: at the old 78px there was nothing to read.
    TILE_SIZE = 144
    TILE_GRAPH_SIZE = (TILE_SIZE - 16, TILE_SIZE - 34)

    # SV ceiling. Matches TimingLineDialog's own range: a barline gimmick is
    # routinely driven at speeds an ordinary chart never asks for, and there is
    # no reason for the two places that type an SV to disagree about the limit.
    MAX_RATE = 100.0

    def __init__(
        self, start_ms: float, end_ms: float, parent=None, snap_divisor: int = 4,
        initial_rate: float = 1.0, final_rate: float = 1.0,
        gimmick_layer: str | bool | None = False,
        position_offset: int | None = None,
        base_timing: list[TimingPoint] | None = None,
        volume: bool = False,
    ) -> None:
        title = tr("MainWindow", "Generate Volume") if volume else tr("MainWindow", "Generate SV")
        super().__init__(
            title,
            tr("MainWindow", "Range: {0} to {1}").format(format_time(round(start_ms)), format_time(round(end_ms))),
            action=tr("MainWindow", "Generate"), rail=False, restore=False, parent=parent)
        self.action_button.clicked.disconnect()
        self.action_button.clicked.connect(self._accept)
        self.start_ms = start_ms
        self.end_ms = end_ms
        # Only for the BPM filter's default, and only layer 6 asks for it. The
        # *base* snapshot rather than the document's own timing for the same
        # reason BarlineFunctionDialog uses it: by the second placement the
        # gimmick difficulty is full of 60000 BPM lines, so its own timing is
        # the worst possible answer to "what BPM are we at".
        self.base_timing = base_timing or []
        # The Kiai and Sound Volume layer's Volume tool is this same generator
        # pointed at TimingPoint.volume: same functions, same modes, same
        # placement. Only the quantity differs -- whole percent in 0..100
        # instead of a scroll rate -- so it is a flag rather than a second
        # dialog with three hundred copied lines behind it.
        self.volume = volume
        # A gimmick SV layer owns exactly one structure's green lines, matched
        # by millisecond (MainWindow._sv_layer_times). A point generated
        # anywhere else is invisible in the layer that made it *and* silently
        # wiped by the next uninherited line, so the two controls that can move
        # a point off its object are taken away rather than merely defaulted.
        self.gimmick_layer = gimmick_layer
        icon = application_icon()
        if not icon.isNull():
            self.setWindowIcon(icon)
        sheet = self.sheet
        # Rows are fields on the sheet now; set_row_visible finds them there.
        self._form_layout = None

        # Volume is a whole percent in 0..100 (what the .osu field holds and
        # what the writer validates), so the same two spin boxes are told to
        # carry integers rather than a second pair being built beside them.
        low, high = (0.0, 100.0) if volume else (0.01, self.MAX_RATE)
        # SV_DECIMALS for a rate: -100/beat_length routinely lands on a repeating
        # decimal (e.g. 1.4286x), and 2 was rounding the prefilled "nearest
        # green line" value before Generate ever saw it -- so it looked like
        # the generator wasn't reading the existing line at all.
        step, decimals = (1.0, 0) if volume else (0.05, SV_DECIMALS)
        suffix = "%" if volume else "\u00d7"

        # The result, large, at the top: every value Generate will write.
        self.preview = SVFunctionPreview(420, 170)
        self.preview.setMinimumWidth(0)
        self.preview.setMaximumWidth(16777215)
        self.preview.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        sheet.add_widget(self.preview)

        # Literal tr() calls, one per function -- see AddViewDialog's note on
        # why a dynamic lookup here would silently escape the i18n gate.
        functions = (
            ("linear", tr("MainWindow", "Linear")),
            ("sin_in", tr("MainWindow", "Sin In")),
            ("sin_out", tr("MainWindow", "Sin Out")),
            ("exp1.3", tr("MainWindow", "Exp 1.3")),
            ("exp1.6", tr("MainWindow", "Exp 1.6")),
            ("true_exp", tr("MainWindow", "True Exp")),
            ("sin", tr("MainWindow", "Sin")),
            ("exp_x", tr("MainWindow", "Exp x")),
        )
        self.function_buttons: dict[str, QToolButton] = {}
        self._function_group = QButtonGroup(self)
        self._function_group.setExclusive(True)
        chips = QWidget()
        chips.setStyleSheet(
            "QToolButton { background: #222a36; color: #aeb8c5; border: 1px solid #303947;"
            " border-radius: 6px; padding: 4px 9px 4px 5px; font-size: 12px; font-weight: 600; }"
            "QToolButton:hover { background: #2a3341; color: #e8edf3; }"
            "QToolButton:checked { background: #2a2230; color: #ffffff; border: 1px solid #ff66aa; }")
        chip_rows = QGridLayout(chips)
        chip_rows.setContentsMargins(0, 0, 0, 0)
        chip_rows.setSpacing(6)
        for index, (function_id, label) in enumerate(functions):
            button = QToolButton()
            button.setText(label)
            button.setToolButtonStyle(Qt.ToolButtonTextBesideIcon)
            button.setIconSize(QSize(*self.CHIP_ICON_SIZE))
            button.setCheckable(True)
            button.setFocusPolicy(Qt.NoFocus)
            button.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            button.setChecked(function_id == "linear")
            button.toggled.connect(
                lambda checked, f=function_id: self._update_preview() if checked else None
            )
            self._function_group.addButton(button)
            self.function_buttons[function_id] = button
            chip_rows.addWidget(button, index // 4, index % 4)
        curve_help = tr(
            "MainWindow",
            "How the value moves from Initial to Final. Sin In is fast at the start and slow at "
            "the end, following TaikoEditor's naming (the reverse of easings.net). True Exp bends "
            "by the range itself, so 1\u00d7 to 10\u00d7 is a hard curve and 1\u00d7 to 1.1\u00d7 "
            "is nearly straight.")
        sheet.add_widget(sheet.field(tr("MainWindow", "Curve"), chips, curve_help))

        rates = sheet.add_section("rates", tr("MainWindow", "Volume") if volume else tr("MainWindow", "Rates"))
        self.initial_rate_spin = TrimmedDoubleSpinBox()
        self.initial_rate_spin.setRange(low, high)
        self.initial_rate_spin.setSingleStep(step)
        self.initial_rate_spin.setDecimals(decimals)
        self.initial_rate_spin.setSuffix(suffix)
        self.initial_rate_spin.setValue(round(float(initial_rate), decimals))
        self.initial_rate_spin.valueChanged.connect(self._update_preview)
        rates.field(
            tr("MainWindow", "Initial volume") if volume else tr("MainWindow", "Initial rate"),
            self.initial_rate_spin,
            tr("MainWindow", "The value at the first point."))

        self.final_rate_spin = TrimmedDoubleSpinBox()
        self.final_rate_spin.setRange(low, high)
        self.final_rate_spin.setSingleStep(step)
        self.final_rate_spin.setDecimals(decimals)
        self.final_rate_spin.setSuffix(suffix)
        self.final_rate_spin.setValue(round(float(final_rate), decimals))
        self.final_rate_spin.valueChanged.connect(self._update_preview)
        rates.field(
            tr("MainWindow", "Final volume") if volume else tr("MainWindow", "Final rate"),
            self.final_rate_spin,
            tr("MainWindow", "The value at the last point."))

        # The exponent behind the "Exp x" chip. The two fixed exp curves are
        # the shapes that get used most and stay as one click each; this is the
        # same curve with the number exposed, for a sweep that wants to bend
        # harder than 1.6 or softer than 1.3. Floored at 1, because below it
        # the curve bends the other way and the chip would stop being an exp
        # curve.
        self.exp_spin = QDoubleSpinBox()
        self.exp_spin.setRange(1.0, 10.0)
        self.exp_spin.setDecimals(2)
        self.exp_spin.setSingleStep(0.1)
        self.exp_spin.setValue(2.0)
        self.exp_spin.valueChanged.connect(self._update_preview)
        self._exp_field = rates.field(tr("MainWindow", "Exponent"), self.exp_spin, tr(
            "MainWindow", "The x in t^x for the Exp x curve. Floored at 1: below it the curve bends the other way."))

        # Sweep or oscillation. The same growth function drives both: a sweep
        # eases the rate from Initial to Final, an oscillation eases the
        # *amplitude* it fans out to either side of Initial, reaching Final at
        # the last point. Per point opens the fan on every step (the two sides
        # peak at different widths); per pair opens it once per up/down pair,
        # so every pair is symmetric about the base.
        # Literal tr() calls, one per option -- see AddViewDialog's note on why
        # a dict lookup here would silently escape the i18n coverage gate.
        where = sheet.add_section("where", tr("MainWindow", "Where the points go"))
        self.mode_combo = QComboBox()
        self.mode_combo.addItem(tr("MainWindow", "Sweep"), "")
        self.mode_combo.addItem(tr("MainWindow", "Oscillate (per point)"), "point")
        self.mode_combo.addItem(tr("MainWindow", "Oscillate (per pair)"), "pair")
        self.mode_combo.currentIndexChanged.connect(self._update_preview)
        where.field(tr("MainWindow", "Mode"), bind_segments(self.mode_combo), tr(
            "MainWindow",
            "Sweep eases from Initial to Final. Oscillate fans out either side of Initial, "
            "reaching Final at the last point: per point on every step, per pair once per "
            "up/down pair."), span=2)
        self.mode_combo.setProperty("sheetField", self.mode_combo.parentWidget().property("sheetField"))

        self.placement_combo = QComboBox()
        # Literal tr() calls, one per option -- see AddViewDialog's note on why
        # a dict lookup here would silently escape the i18n coverage gate.
        self.placement_combo.addItem(tr("MainWindow", "Each note"), "notes")
        self.placement_combo.addItem(tr("MainWindow", "Every snap"), "snaps")
        self.placement_combo.currentIndexChanged.connect(self._update_placement_controls)
        placement = bind_segments(self.placement_combo)
        where.field(tr("MainWindow", "Generate at"), placement, tr(
            "MainWindow",
            "Each note puts a line just before every note in the range. Every snap puts one on "
            "every gridline of the snap below."))
        self.placement_combo.setProperty("sheetField", placement.property("sheetField"))

        self.snap_combo = QComboBox()
        for divisor in SNAP_DIVISORS:
            self.snap_combo.addItem(f"1/{divisor}", divisor)
        found = self.snap_combo.findData(int(snap_divisor))
        self.snap_combo.setCurrentIndex(found if found >= 0 else self.snap_combo.findData(4))
        self.snap_label = QLabel(tr("MainWindow", "Snap"))
        where.field(tr("MainWindow", "Snap"), self.snap_combo, tr(
            "MainWindow", "The gridline spacing for Every snap."))

        self.position_offset_spin = QSpinBox()
        self.position_offset_spin.setRange(-5000, 5000)
        self.position_offset_spin.setSuffix(" ms")
        # An SV point governs what comes after it, so it has to land slightly
        # before the note it is meant to affect. In a gimmick layer the value
        # comes from that layer's config, which is also what decides which
        # milliseconds the layer recognises as its own.
        self.position_offset_spin.setValue(
            self.DEFAULT_POSITION_OFFSET_MS if position_offset is None else int(position_offset)
        )
        where.field(tr("MainWindow", "Position offset"), self.position_offset_spin, tr(
            "MainWindow",
            "How far ahead of its note each line sits. An SV point governs what comes after "
            "it, so a note needs its line slightly early."))

        self.omit_barline_check = QCheckBox(tr("MainWindow", "Omit barline"))
        self.omit_barline_check.setChecked(False)
        where.switch(self.omit_barline_check, tr(
            "MainWindow", "Only matters where a generated point lands on a red line."), span=1)

        self.relative_to_final_bpm_check = QCheckBox(tr("MainWindow", "Relative to final BPM"))
        # Off in a gimmick layer. It multiplies every generated rate by
        # local_bpm / start_bpm, and a gimmick's local BPM is 60000 against a
        # chart's 180 -- so a "1.0x to 2.0x" sweep came out in the hundreds and
        # neither end landed on the number that was typed.
        self.relative_to_final_bpm_check.setChecked(not gimmick_layer and not volume)
        where.switch(self.relative_to_final_bpm_check, tr(
            "MainWindow", "Scales each rate so the scroll speed holds across BPM changes in the range."), span=1)
        if volume:
            # Position offset and Omit barline describe an *inserted* point;
            # the Volume tool edits the timing points already in the range.
            # Relative to final BPM is a statement about scroll speed, and a
            # hitsound is as loud as it is whatever the BPM is doing.
            for widget in (self.position_offset_spin, self.omit_barline_check,
                           self.relative_to_final_bpm_check):
                set_row_visible(None, widget, False)

        self.include_shiny_check = QCheckBox(tr("MainWindow", "Include shiny notes"))
        self.include_shiny_check.setChecked(False)
        # Layer 6 owns *every* red line -- the chart's own timing, a barline
        # gimmick's 60000 BPM run, hand-placed lines -- and a sweep across a
        # dragged range hits all of them indiscriminately. This narrows it to
        # one BPM range, which is how you drive a single gimmick run without
        # disturbing the ordinary timing lines interleaved with it.
        self.bpm_filter_check = QCheckBox(tr("MainWindow", "Only red lines at this BPM"))
        self.bpm_filter_check.setChecked(False)
        self.bpm_filter_spin = QDoubleSpinBox()
        self.bpm_filter_spin.setRange(1.0, 1000000.0)
        self.bpm_filter_spin.setDecimals(4)
        self.bpm_filter_spin.setSuffix(" BPM")
        # The BPM in force where the drag started -- the run you are looking at
        # is almost always the one you want, so the default costs no typing.
        self.bpm_filter_spin.setValue(
            base_bpm_at(self.base_timing, start_ms) if self.base_timing else 120.0
        )
        # An inclusive range rather than one exact BPM: an exact match is just
        # the degenerate case where the two ends are equal.
        self.bpm_filter_max_spin = QDoubleSpinBox()
        self.bpm_filter_max_spin.setRange(1.0, 1000000.0)
        self.bpm_filter_max_spin.setDecimals(4)
        self.bpm_filter_max_spin.setSuffix(" BPM")
        self.bpm_filter_max_spin.setValue(self.bpm_filter_spin.value())
        # Layer 5's counterpart: two fake sliders can sit on the same
        # millisecond and differ only in `length` (-0.001 vs -0.0011), which is
        # how a mapper encodes "these get one SV, those get another".
        self.length_filter_check = QCheckBox(tr("MainWindow", "Only fake sliders with this length"))
        self.length_filter_check.setChecked(False)
        self.length_filter_spin = QDoubleSpinBox()
        self.length_filter_spin.setRange(-100000.0, FAKE_SLIDER_MAX_LENGTH)
        self.length_filter_spin.setDecimals(4)
        self.length_filter_spin.setValue(-0.001)
        self.length_filter_max_spin = QDoubleSpinBox()
        self.length_filter_max_spin.setRange(-100000.0, FAKE_SLIDER_MAX_LENGTH)
        self.length_filter_max_spin.setDecimals(4)
        self.length_filter_max_spin.setValue(-0.001)
        if gimmick_layer in ("sv_barline", "sv_fake_slider"):
            filters = sheet.add_section("filters", tr("MainWindow", "Which lines"))
            if gimmick_layer == "sv_fake_slider":
                filters.switch(self.include_shiny_check, tr(
                    "MainWindow",
                    "This layer holds the speed of plain fake sliders. Shiny notes "
                    "are left out by default -- their gimmick line sits on the note, "
                    "so the normal chart SV layer already moves the note and its "
                    "shine together -- but this sweep can add them in as well.",
                ))
                filters.switch(self.length_filter_check, tr(
                    "MainWindow", "Sweep one length family of fake sliders and leave the rest."))
                filters.field(tr("MainWindow", "Length from"), self.length_filter_spin)
                filters.field(tr("MainWindow", "Length to"), self.length_filter_max_spin)
                self.length_filter_check.toggled.connect(self._update_length_filter_row)
            else:
                filters.switch(self.bpm_filter_check, tr(
                    "MainWindow", "Drive one gimmick run without touching the chart's own timing lines."))
                filters.field(tr("MainWindow", "BPM from"), self.bpm_filter_spin)
                filters.field(tr("MainWindow", "BPM to"), self.bpm_filter_max_spin)
                self.bpm_filter_check.toggled.connect(self._update_bpm_filter_row)

        sheet.set_help_default(
            tr("MainWindow", "Curve"),
            tr("MainWindow", "The plot shows every value Generate will write, in order. This picture is the curve alone, first point to last."))
        self.curve = Diagram(self._paint_curve, 130)
        sheet.set_diagram(self.curve, tr("MainWindow", "Curve"))
        self.resize(980, 700)

        self._update_preview()
        self._update_placement_controls()
        self._update_bpm_filter_row()
        self._update_length_filter_row()

    CHIP_ICON_SIZE = (30, 20)

    def _curve_pixmap(self, function_id: str, size: tuple[int, int], width: float) -> QPixmap:
        """`function_id`'s shape, rising or falling with the typed range.

        Normalised, so a 1.00x -> 1.00x range still shows the curve rather
        than eight flat lines -- but True Exp bends by the range itself, so it
        is read with the real endpoints whenever they differ.
        """
        initial, final = self.initial_rate_spin.value(), self.final_rate_spin.value()
        falling = final < initial
        a, b = (initial, final) if initial != final else (1.0, 4.0)
        w, h = size
        pixmap = QPixmap(w * 2, h * 2)
        pixmap.setDevicePixelRatio(2.0)
        pixmap.fill(Qt.transparent)
        painter = QPainter(pixmap)
        painter.setRenderHint(QPainter.Antialiasing)
        points = []
        for index in range(33):
            t = index / 32
            eased = sv_ease(function_id, t, a, b)
            y = eased if not falling else 1 - eased
            points.append(QPointF(2 + t * (w - 4), h - 2 - y * (h - 4)))
        painter.setPen(QPen(theme.color("#f3a6bd"), width, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
        painter.drawPolyline(QPolygonF(points))
        painter.end()
        return pixmap

    def _paint_curve(self, painter: QPainter, rect: QRect) -> None:
        inner = rect.adjusted(16, 12, -16, -22)
        painter.setPen(QPen(theme.color("#3a4554"), 1))
        painter.drawLine(inner.bottomLeft(), inner.bottomRight())
        painter.drawLine(inner.bottomLeft(), inner.topLeft())
        pixmap = self._curve_pixmap(self.selected_function(), (inner.width(), inner.height()), 2.2)
        painter.drawPixmap(inner.topLeft(), pixmap)
        _diagram_text(painter, inner.left(), rect.bottom() - 6, tr("MainWindow", "first point"))
        _diagram_text(painter, inner.right(), rect.bottom() - 6, tr("MainWindow", "last point"), align=Qt.AlignRight)

    def _resolved_function(self, key: str) -> str:
        """The curve id a tile stands for.

        Every tile but one is its own id. "Exp x" is the exponent box's current
        value spelled as an id (`sv_ease` parses it back out), which is what
        lets one tile be any exponent without a second argument on every call
        that takes a function.
        """
        if key == "exp_x":
            return f"exp{self.exp_spin.value():g}"
        return key

    def selected_function(self) -> str:
        for key, button in self.function_buttons.items():
            if button.isChecked():
                return self._resolved_function(key)
        return "linear"

    def set_selected_function(self, function_id: str) -> None:
        button = self.function_buttons.get(function_id)
        if button is None and function_id.startswith("exp") and function_id != "true_exp":
            # A typed exponent comes back as its own id; put the number back in
            # the box and light the tile it belongs to.
            try:
                self.exp_spin.setValue(float(function_id[3:]))
            except ValueError:
                return
            button = self.function_buttons.get("exp_x")
        if button is not None:
            button.setChecked(True)

    def _update_preview(self) -> None:
        """Re-plot the result and every chip's curve against the current rates.

        The chips follow the range's direction -- a 1.10x -> 0.90x sweep shows
        every curve falling -- and "Exp x" draws the exponent in its box.
        """
        self.preview.set_range(self.initial_rate_spin.value(), self.final_rate_spin.value())
        self.preview.set_oscillate(str(self.mode_combo.currentData()))
        for key, button in self.function_buttons.items():
            button.setIcon(QIcon(self._curve_pixmap(self._resolved_function(key), self.CHIP_ICON_SIZE, 1.6)))
        self.preview.set_function(self.selected_function())
        self._exp_field.setVisible(self.function_buttons["exp_x"].isChecked())
        self.curve.refresh()

    def _update_placement_controls(self) -> None:
        """The snap divisor only means anything in "Every snap" mode.

        setRowVisible collapses the whole form row; hiding the two widgets
        individually would leave the row's blank space behind.

        A gimmick layer has no "where" to offer: its points go on its own
        objects or they do not exist. The position offset stays -- it is how far
        ahead of those objects they sit, which is a real choice and the one the
        normal chart layer needs.

        Volume mode has no "where" either, for a different reason: it edits
        the timing points already in the range rather than placing new ones,
        so there is no position to offer a choice about.
        """
        if self.gimmick_layer or self.volume:
            set_row_visible(self._form_layout, self.snap_combo, False)
            set_row_visible(self._form_layout, self.placement_combo, False)
            return
        every_snap = str(self.placement_combo.currentData()) == "snaps"
        set_row_visible(self._form_layout, self.snap_combo, every_snap)

    def _update_bpm_filter_row(self) -> None:
        """The BPM only means anything while the filter is on.

        Hidden rather than disabled, same as the snap divisor above: a greyed
        control still takes a row of an already tall form and still invites a
        click that does nothing.
        """
        if self.gimmick_layer != "sv_barline":
            return
        visible = self.bpm_filter_check.isChecked()
        set_row_visible(self._form_layout, self.bpm_filter_spin, visible)
        set_row_visible(self._form_layout, self.bpm_filter_max_spin, visible)

    def _update_length_filter_row(self) -> None:
        """The length range only means anything while the filter is on --
        same reasoning as `_update_bpm_filter_row`."""
        if self.gimmick_layer != "sv_fake_slider":
            return
        visible = self.length_filter_check.isChecked()
        set_row_visible(self._form_layout, self.length_filter_spin, visible)
        set_row_visible(self._form_layout, self.length_filter_max_spin, visible)

    def _accept(self) -> None:
        # Clamped up rather than refused, same reasoning as
        # MultiFakeSliderDialog._accept: "to" below "from" is "I only meant
        # the one BPM at from", not a mistake worth bouncing back to the user.
        if self.bpm_filter_max_spin.value() < self.bpm_filter_spin.value():
            self.bpm_filter_max_spin.setValue(self.bpm_filter_spin.value())
        if self.length_filter_max_spin.value() < self.length_filter_spin.value():
            self.length_filter_max_spin.setValue(self.length_filter_spin.value())
        self.accept()

    def parameters(self) -> dict:
        return {
            "initial_rate": self.initial_rate_spin.value(),
            "final_rate": self.final_rate_spin.value(),
            "placement": str(self.placement_combo.currentData()),
            "snap_divisor": int(self.snap_combo.currentData()),
            # Zero in volume mode, not merely hidden: the Volume tool edits
            # the timing points already in the range, so there is nothing to
            # offset and no path may act as though there were.
            "position_offset": 0 if self.volume else self.position_offset_spin.value(),
            "omit_barline": self.omit_barline_check.isChecked(),
            "relative_to_final_bpm": self.relative_to_final_bpm_check.isChecked(),
            "function": self.selected_function(),
            "oscillate": str(self.mode_combo.currentData()),
            "include_shiny": self.include_shiny_check.isChecked(),
            # One key rather than a flag and a value: None *is* "no filter",
            # so no consumer can read the BPM interval without first having
            # checked whether it applies. The value is a (low, high) tuple,
            # inclusive at both ends -- an exact single BPM is just low == high.
            "only_red_line_bpm": (
                (self.bpm_filter_spin.value(), self.bpm_filter_max_spin.value())
                if self.bpm_filter_check.isChecked() else None
            ),
            "only_fake_slider_length": (
                (self.length_filter_spin.value(), self.length_filter_max_spin.value())
                if self.length_filter_check.isChecked() else None
            ),
        }


class LanguageDialog(QDialog):
    """First-start language choice, shown before anything else is built.

    Deliberately not translated: it is the one screen that cannot assume which
    language the reader wants, so both options are written in their own
    language and there is nothing else on it to translate.
    """

    def __init__(self, parent=None) -> None:
        super().__init__(parent)
        self.setWindowTitle("Language / 言語")
        self.language = "en"
        layout = QVBoxLayout(self)
        layout.setContentsMargins(24, 20, 24, 20)
        layout.setSpacing(14)
        heading = QLabel("Choose your language\n言語を選んでください")
        heading.setAlignment(Qt.AlignCenter)
        heading.setStyleSheet("font-size: 15px; font-weight: 600;")
        layout.addWidget(heading)
        for code, label in (("en", "English"), ("ja", "日本語")):
            button = QPushButton(label)
            button.setMinimumHeight(44)
            button.clicked.connect(lambda _checked=False, value=code: self._choose(value))
            layout.addWidget(button)
        self.setStyleSheet(
            """
            QDialog { background: #191f29; }
            QLabel { color: #e8edf3; }
            QPushButton { background: #f3a6bd; color: #17191f; border: 0; border-radius: 6px;
                          padding: 10px 18px; font-weight: 600; font-size: 14px; }
            QPushButton:hover { background: #f7bfd0; }
            """
        )

    def _choose(self, code: str) -> None:
        self.language = code
        self.accept()


# osu!'s star-rating colours (OsuColour.STAR_DIFFICULTY_SPECTRUM, as osu!-web
# draws them): the list dots and the difficulty pills both read these, so a
# set's spread shows before it is opened.
STAR_SPECTRUM = (
    (0.1, "#4290fb"), (1.25, "#4fc0ff"), (2.0, "#4fffd5"), (2.5, "#7cff4f"),
    (3.3, "#f6f05c"), (4.2, "#ff8068"), (4.9, "#ff4e6f"), (5.8, "#c645b8"),
    (6.7, "#6563de"), (7.7, "#18158e"), (9.0, "#000000"),
)
STAR_TEXT_SPECTRUM = (
    (9.0, "#f6f05c"), (9.9, "#ff8068"), (10.6, "#ff4e6f"), (11.5, "#c645b8"), (12.4, "#6563de"),
)
STAR_UNRATED = "#aaaaaa"


def _sample_spectrum(stops, value: float) -> QColor:
    """osu!-web's d3 scale: clamped, interpolated at gamma 2.2."""
    if value <= stops[0][0]:
        return QColor(stops[0][1])
    for (low, low_hex), (high, high_hex) in zip(stops, stops[1:]):
        if value <= high:
            t = (value - low) / (high - low)
            a, b = QColor(low_hex), QColor(high_hex)
            mix = lambda x, y: round(255 * ((x / 255) ** 2.2 + t * ((y / 255) ** 2.2 - (x / 255) ** 2.2)) ** (1 / 2.2))
            return QColor(mix(a.red(), b.red()), mix(a.green(), b.green()), mix(a.blue(), b.blue()))
    return QColor(stops[-1][1])


def star_colour(stars: float | None) -> QColor:
    """The pill and dot colour. osu! rounds to 2dp away from zero first, so
    1.245 samples as 1.25, and anything under 0.1 is its grey."""
    if stars is None:
        return QColor(STAR_UNRATED)
    stars = float(Decimal(str(stars)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
    return QColor(STAR_UNRATED) if stars < 0.1 else _sample_spectrum(STAR_SPECTRUM, stars)


def star_text_colour(stars: float | None) -> QColor:
    """Dark below 6.5, gold below 9, then its own spectrum -- osu!-web's pill."""
    if stars is None or stars < 6.5:
        return QColor(0, 0, 0, 191)
    if stars < 9.0:
        return QColor("#ffd966")
    return _sample_spectrum(STAR_TEXT_SPECTRUM, stars)


def format_length(ms: int) -> str:
    seconds = max(0, int(ms)) // 1000
    return f"{seconds // 60}:{seconds % 60:02d}"


def format_bpm(low: float, high: float, common: float | None = None) -> str:
    # A gimmick's beat length can be subnormal (EGTS 2022's
    # `1.14514535393084E-319`), and 60000 over that is inf: round() raised,
    # and the song's difficulty list stopped filling at its first chart.
    def text(bpm: float) -> str:
        return str(round(bpm)) if math.isfinite(bpm) else "∞"

    if not high:
        return "–"
    if text(low) == text(high):
        return text(high)
    # A range says which tempo it mostly is, as lazer's "a-b (mostly c)" and
    # the density view do: aleph-0 is "125–400 (250)" (owner, 2026-10-09).
    if common:
        return f"{text(low)}–{text(high)} ({text(common)})"
    return f"{text(low)}–{text(high)}"


def keep_width_under_scrollbar(area: QScrollArea, layout) -> None:
    """Hold `area`'s content at one width whether or not its vertical
    scrollbar is showing. The bar takes its width out of the viewport when it
    appears, so everything inside reflowed -- tiles jumped, labels rewrapped
    -- the moment a panel grew past the window (owner, 2026-10-09). While the
    bar is hidden, `layout` carries that width as extra right margin."""
    left, top, right, bottom = layout.getContentsMargins()
    bar = area.verticalScrollBar()

    def fit(_minimum=0, maximum=0) -> None:
        reserve = 0 if maximum > 0 else bar.sizeHint().width()
        layout.setContentsMargins(left, top, right + reserve, bottom)

    bar.rangeChanged.connect(fit)
    fit(bar.minimum(), bar.maximum())


def decode_background_image(path: Path, max_width: int) -> QImage | None:
    """A beatmap background, decoded no wider than `max_width`: a 4K
    background at full size costs a visible pause on every selection.
    A QImage, so it can be decoded off the GUI thread (a QPixmap cannot)."""
    reader = QImageReader(str(path))
    reader.setAutoTransform(True)
    size = reader.size()
    if size.isValid() and size.width() > max_width:
        reader.setScaledSize(size.scaled(max_width, max_width, Qt.KeepAspectRatio))
    image = reader.read()
    return image if not image.isNull() else None


def decode_background(path: Path, max_width: int) -> QPixmap | None:
    image = decode_background_image(path, max_width)
    return QPixmap.fromImage(image) if image is not None else None


class BackgroundJobs(QObject):
    """Work song select must not do on the GUI thread, handed back to it.

    Measured (tools/measure_song_switch.py, 4101 songs): picking a song held
    the event loop for 99ms median and 208ms at worst -- 62ms of it hashing
    every difficulty for osu!.db's staleness check, 33ms decoding the
    background. That is the stutter before the chart preview loads. Both
    release the GIL (file reads, hashlib over large buffers, Qt's image
    decoders), so a thread really does take them off the frame.

    `deliver` runs on the GUI thread: the done signal is emitted from the
    worker, and Qt queues a cross-thread emit to the receiver's thread.
    """

    _done = Signal(object)

    def __init__(self, parent: QObject | None = None) -> None:
        super().__init__(parent)
        self._pool = ThreadPoolExecutor(max_workers=2, thread_name_prefix="song-select")
        self._pending: set = set()
        self._done.connect(self._deliver)

    def submit(self, work, deliver) -> None:
        try:
            future = self._pool.submit(work)
        except RuntimeError:
            return  # shut down with the window: a late selection has nobody to show it to
        self._pending.add(future)
        future.add_done_callback(lambda done: self._emit(done, deliver))

    def _emit(self, future, deliver) -> None:
        try:
            self._done.emit((future, deliver))
        except RuntimeError:
            pass  # the window, and this object with it, is already gone

    def _deliver(self, payload) -> None:
        future, deliver = payload
        self._pending.discard(future)
        if future.cancelled() or future.exception() is not None:
            return  # an unreadable file keeps what was shown, as before
        deliver(future.result())

    def drain(self) -> None:
        """Wait for everything submitted and deliver it (tests)."""
        while self._pending:
            futures_wait(list(self._pending))
            QCoreApplication.processEvents()

    def shutdown(self) -> None:
        self._pool.shutdown(wait=False, cancel_futures=True)


def tabular(font: QFont) -> QFont:
    """Exo 2's tabular figures, so the stat columns line up digit for digit."""
    font = QFont(font)
    try:
        font.setFeature(QFont.Tag("tnum"), 1)
    except (AttributeError, TypeError):
        pass  # A Qt without OpenType features: proportional figures, still legible.
    return font


# The widest the playhead readouts ever get: format_time's mm.ss.mmm, three
# spaces, and a percentage.
READOUT_WIDEST = "00.00.000   100.0%"


def steady_readout(label: QLabel, widest: str = READOUT_WIDEST) -> None:
    """Stop a ticking number from moving what is beside it.

    Exo 2's default figures are proportional, so "01.58.111" is narrower than
    "01.58.000", and a label sized to its own text changed width every few
    frames during playback -- which, beside a stretching timing bar, shook the
    bar left and right. Tabular figures make every digit one width, and the
    floor at the widest text the readout can show keeps it from shrinking.
    """
    label.ensurePolished()
    label.setFont(tabular(label.font()))
    label.setMinimumWidth(label.fontMetrics().horizontalAdvance(widest) + 6)


# The song and difficulty rows carry what they paint under this role; their
# display text stays the plain label, which is what search, tests and screen
# readers see.
ROW_ROLE = Qt.UserRole + 1
ROW_INK, ROW_INK_2, ROW_INK_3 = "#e8edf3", "#aeb8c5", "#7d8794"
ROW_HOVER, ROW_PINK_ON = "#2a3341", "#ff66aa"
# The detail pane keeps room for DIFFICULTY_RESERVED_SLOTS difficulties when
# it can (owner, 2026-10-08), the banner having the rest up to 16:9; a window
# too short for both gives the list up to its floor of DIFFICULTY_SLOTS.
DIFFICULTY_SLOTS, DIFFICULTY_ROW_HEIGHT = 2, 48
DIFFICULTY_RESERVED_SLOTS = 5


class ResizeHook(QObject):
    """Call `callback` whenever `widget` is resized."""

    def __init__(self, widget: QWidget, callback) -> None:
        super().__init__(widget)
        self.callback = callback
        widget.installEventFilter(self)

    def eventFilter(self, watched, event) -> bool:
        if event.type() == QEvent.Resize:
            self.callback()
        return False
# The song list's wheel and arrow scrolling glide over this long.


# The song preview: how long the selection has to rest before it starts (so
# holding an arrow down does not open every song on the way), and its fade in.
PREVIEW_SETTLE_MS = 250
PREVIEW_FADE_MS = 400
# The chart preview's notes fading out of the song left and into the next
# (owner, 2026-10-09). Out is shorter than the settle, so it is gone before
# the next chart is read; in is the mockup's entering 250ms.
CHART_FADE_OUT_MS = 150
CHART_FADE_IN_MS = 250
# The song list's difficulty dots, one per chart in its star colour.
SONG_DOT_RADIUS, SONG_DOT_PITCH = 5.0, 14
# A pack lists dozens of charts, and a dot each pushed the title off its own
# row. Past this many, or past the share of the row they may take, the rest
# are a "+n" (owner, 2026-10-08).
SONG_DOTS_MAX = 20
SONG_DOTS_SHARE = 0.4


def song_dots_shown(count: int, row_width: float) -> tuple[int, int]:
    """(dots drawn, how many the "+n" stands for) for a row this wide."""
    room = min(SONG_DOTS_MAX, int(row_width * SONG_DOTS_SHARE // SONG_DOT_PITCH))
    if count <= room:
        return count, 0
    # One slot (and a bit) gives way to the "+n" itself.
    shown = max(0, room - 2)
    return shown, count - shown


def paint_selected_row(painter: QPainter, rect: QRectF, active: bool) -> None:
    tint = QLinearGradient(rect.topLeft(), rect.topRight())
    tint.setColorAt(0.0, theme.rgba(255, 102, 170, 46))
    tint.setColorAt(0.7, theme.rgba(255, 102, 170, 10))
    painter.setPen(Qt.NoPen)
    painter.setBrush(tint)
    painter.drawRoundedRect(rect.adjusted(0.5, 0.5, -0.5, -0.5), 4, 4)
    paint_living_rim(painter, rect, 4, 1.5, active)


def glide_selection(rows: QListWidget, inset: tuple[int, int, int, int]) -> None:
    """Give `rows` a selection that glides between rows (SelectionGlide);
    `inset` is how far inside the item rect its delegate draws one."""
    rows.selection_glide = SelectionGlide(
        rows, lambda painter, rect: paint_selected_row(painter, rect, rows.hasFocus()), inset)


def _enter_row(painter: QPainter, option, entrance) -> None:
    """Draw the row lifted and faded by its RowEntrance progress."""
    if entrance is None:
        return
    progress = entrance.progress(option.index.row())
    if progress < 1.0:
        painter.setOpacity(progress)
        painter.translate(0, RowEntrance.RISE_PX * (1.0 - progress))


def _paint_selection(painter: QPainter, rect: QRectF, option) -> None:
    """The selected tint fades left to right, as in the mockup, inside a rim
    with two small lights running round it (motion.paint_living_rim). In the
    list that has the keys; the other list's selection keeps a dimmer, still
    rim, so it is clear which one Up/Down will move.

    While the list's SelectionGlide is flying to this row, the flight draws
    the selection and the row draws only itself."""
    widget = option.widget
    glide = getattr(widget, "selection_glide", None)
    if option.state & QStyle.State_Selected:
        if glide is None or not glide.covers(option.index.row()):
            paint_selected_row(painter, rect, widget is not None and widget.hasFocus())
    elif option.state & QStyle.State_MouseOver:
        painter.setPen(Qt.NoPen)
        painter.setBrush(theme.color(ROW_HOVER))
        painter.drawRoundedRect(rect, 4, 4)


class SongRowDelegate(QStyledItemDelegate):
    """A song: bold title over "artist · mapped by X", a dot per difficulty in
    its star colour. A group header: small caps in the accent pink."""

    # Set by the page: rows rising in after a search (RowEntrance).
    entrance = None

    def sizeHint(self, option, index):
        header = index.data(Qt.UserRole) is None
        return QSize(option.rect.width(), 28 if header else 46)

    def paint(self, painter, option, index):
        painter.save()
        painter.setRenderHint(QPainter.Antialiasing, True)
        rect = QRectF(option.rect)
        row = index.data(ROW_ROLE)
        font = QFont(option.font)
        _enter_row(painter, option, self.entrance)
        if row is None:  # a group header
            font.setBold(True)
            font.setPointSizeF(font.pointSizeF() * 0.8)
            font.setCapitalization(QFont.AllUppercase)
            font.setLetterSpacing(QFont.PercentageSpacing, 106)
            painter.setFont(font)
            painter.setPen(QColor(index.data(Qt.ForegroundRole).color()))
            painter.drawText(rect.adjusted(8, 0, -8, -2), Qt.AlignLeft | Qt.AlignBottom, index.data())
            painter.setPen(theme.color("#303947"))
            painter.drawLine(rect.bottomLeft() + QPointF(4, 0), rect.bottomRight() - QPointF(4, 0))
            painter.restore()
            return
        _paint_selection(painter, rect.adjusted(2, 1, -2, -1), option)
        stars = row["stars"]
        small = QFont(option.font)
        small.setPointSizeF(small.pointSizeF() * 0.86)
        shown, more = song_dots_shown(len(stars), rect.width())
        more_text = f"+{more}" if more else ""
        more_width = QFontMetrics(small).horizontalAdvance(more_text) + 4 if more else 0
        dots_width = shown * SONG_DOT_PITCH + more_width
        text = rect.adjusted(13, 5, -(dots_width + 18), -5)
        font.setWeight(QFont.DemiBold)
        painter.setFont(font)
        painter.setPen(theme.color(ROW_INK))
        metrics = QFontMetrics(font)
        painter.drawText(text, Qt.AlignLeft | Qt.AlignTop, metrics.elidedText(row["title"], Qt.ElideRight, int(text.width())))
        painter.setFont(small)
        painter.setPen(theme.color(ROW_INK_2))
        painter.drawText(text, Qt.AlignLeft | Qt.AlignBottom,
                         QFontMetrics(small).elidedText(row["subtitle"], Qt.ElideRight, int(text.width())))
        x = rect.right() - dots_width - 8
        y = rect.center().y()
        if more:
            painter.drawText(QRectF(rect.right() - 8 - more_width, rect.top(), more_width, rect.height()),
                             Qt.AlignRight | Qt.AlignVCenter, more_text)
        for value in stars[:shown]:
            if value is None:
                painter.setPen(QPen(QColor(STAR_UNRATED), 1.5))
                painter.setBrush(Qt.NoBrush)
            else:
                # A faint rim: osu!'s colours run to black past 9 stars, which
                # on this navy is no dot at all.
                painter.setPen(QPen(QColor(255, 255, 255, 46), 1))
                painter.setBrush(star_colour(value))
            painter.drawEllipse(QPointF(x + SONG_DOT_PITCH / 2, y), SONG_DOT_RADIUS, SONG_DOT_RADIUS)
            x += SONG_DOT_PITCH
        painter.restore()


class DifficultyRowDelegate(QStyledItemDelegate):
    """A difficulty: star pill and name, "mapped by X" under it, notes,
    length and BPM on the right in tabular figures."""

    # Set by the page: a new song's rows arriving one by one, their note
    # counts rolling up as they come (RowEntrance).
    entrance = None

    def sizeHint(self, option, index):
        return QSize(option.rect.width(), DIFFICULTY_ROW_HEIGHT)

    def paint(self, painter, option, index):
        painter.save()
        painter.setRenderHint(QPainter.Antialiasing, True)
        rect = QRectF(option.rect).adjusted(2, 2, -2, -2)
        row = index.data(ROW_ROLE) or {}
        _enter_row(painter, option, self.entrance)
        _paint_selection(painter, rect, option)
        inner = rect.adjusted(10, 6, -10, -6)
        stats_font = tabular(option.font)
        stats_font.setPointSizeF(stats_font.pointSizeF() * 0.86)
        stats_font.setWeight(QFont.DemiBold)
        stats_metrics = QFontMetrics(stats_font)
        stats = final_stats = row.get("stats", ("", ""))
        notes = row.get("notes")
        if notes and self.entrance is not None:
            shown = round(notes * out_cubic(self.entrance.progress(index.row()) * 1.5))
            if shown != notes:
                # Measured against the final count below, so the column does
                # not shift as the digits roll.
                stats = (tr("MainWindow", "{n} notes").format(n=shown), stats[1])
        stats_width = max(stats_metrics.horizontalAdvance(line) for line in final_stats) if any(final_stats) else 0
        painter.setFont(stats_font)
        painter.setPen(theme.color(ROW_INK_2))
        painter.drawText(inner, Qt.AlignRight | Qt.AlignTop, stats[0])
        painter.drawText(inner, Qt.AlignRight | Qt.AlignBottom, stats[1])

        stars = row.get("stars")
        pill_font = tabular(option.font)
        pill_font.setBold(True)
        pill_font.setPointSizeF(pill_font.pointSizeF() * 0.82)
        pill_text = f"★ {stars:.2f}" if stars is not None else "★ –"
        pill_metrics = QFontMetrics(pill_font)
        pill = QRectF(inner.left(), inner.top(), max(52, pill_metrics.horizontalAdvance(pill_text) + 16),
                      pill_metrics.height() + 4)
        painter.setOpacity(0.5 if row.get("stale") else 1.0)
        painter.setPen(QPen(QColor(255, 255, 255, 102), 1, Qt.DashLine) if row.get("stale") else Qt.NoPen)
        painter.setBrush(star_colour(stars))
        painter.drawRoundedRect(pill, pill.height() / 2, pill.height() / 2)
        painter.setFont(pill_font)
        painter.setPen(star_text_colour(stars))
        painter.drawText(pill, Qt.AlignCenter, pill_text)
        painter.setOpacity(1.0)

        text_left = pill.right() + 8
        width = int(inner.right() - stats_width - 12 - text_left)
        name_font = QFont(option.font)
        name_font.setBold(True)
        painter.setFont(name_font)
        painter.setPen(theme.color(ROW_INK))
        painter.drawText(QRectF(text_left, pill.top(), max(0, width), pill.height()), Qt.AlignLeft | Qt.AlignVCenter,
                         QFontMetrics(name_font).elidedText(index.data() or "", Qt.ElideRight, max(0, width)))
        by_font = QFont(option.font)
        by_font.setPointSizeF(by_font.pointSizeF() * 0.86)
        painter.setFont(by_font)
        painter.setPen(theme.color(ROW_INK_3))
        painter.drawText(QRectF(inner.left(), inner.top(), inner.width() - stats_width - 12, inner.height()),
                         Qt.AlignLeft | Qt.AlignBottom,
                         QFontMetrics(by_font).elidedText(row.get("by", ""), Qt.ElideRight,
                                                          int(inner.width() - stats_width - 12)))
        painter.restore()


class SongBanner(QWidget):
    """The selected song's own background, heading the detail pane the way
    osu!'s song select does, with the title over a wash at its foot.

    Along the bottom runs the seek band (mockup, 2026-10-09): the elapsed
    time, a track that is the whole song, and the total. A playhead circle
    in the focus colour rides it, growing and glowing on each beat of the
    selected difficulty. Kiai sections
    and the preview point are marked on the track, and inside a kiai the art
    itself lifts on the beat. The beats are the difficulty's own red lines,
    read against `clock` (song milliseconds), so a BPM change or a second
    audio file in the folder keeps time. A new song crossfades its art in
    and its title rises in.

    Under reduced motion the playhead still moves -- it is a position, not
    an effect -- and everything that pulses holds still.
    """

    BEAT_REST = 0.15
    KIAI_LIFT = 0.06
    MIN_HEIGHT = 150
    # The strip the band takes at the foot, which is also the height that
    # takes the pointer: a track you have to land a 6px line on is not one
    # anybody uses.
    BAND_HEIGHT = 30
    TRACK_REST, TRACK_HOVER = 6.0, 10.0
    HEAD_RADIUS = 8.0
    # The playhead flies to a new song's preview point rather than jumping:
    # back to the start of the track first, then out to the preview point
    # (owner, 2026-10-09), REWIND_SHARE of the flight on the way back.
    GLIDE_MS = 320
    REWIND_GLIDE_MS = 560
    REWIND_SHARE = 0.4
    TEXT_RISE_PX = 8.0
    seek_fraction = Signal(float)
    seek_step = Signal(int)

    def __init__(self, parent=None) -> None:
        super().__init__(parent)
        self._seeking = False
        # The height the difficulty slots leave; see DIFFICULTY_SLOTS.
        self.setMinimumHeight(self.MIN_HEIGHT)
        self.setSizePolicy(QSizePolicy.Preferred, QSizePolicy.Expanding)
        self.setMouseTracking(True)
        self.title = ""
        self.subtitle = ""
        self._art: QPixmap | None = None
        self._previous: QPixmap | None = None
        self._scaled: dict[int, QPixmap] = {}
        self._fade = 1.0
        self._beat_phase = 1.0
        self.fade = QVariantAnimation(self)
        self.fade.setStartValue(0.0)
        self.fade.setEndValue(1.0)
        self.fade.setDuration(250)
        self.fade.valueChanged.connect(self._set_fade)
        self._tempo: list[tuple[float, float]] = []
        self._tempo_times: list[float] = []
        self._clock = None
        self._playing = lambda: True
        self._now = 0.0
        self._duration_ms = 0.0
        self._preview_ms = -1.0
        self._kiai: list[tuple[float, float]] = []
        self._hover_x: float | None = None
        self._grow = 0.0
        self.grow = QVariantAnimation(self)
        self.grow.setDuration(160)
        self.grow.setEasingCurve(QEasingCurve.OutCubic)
        self.grow.valueChanged.connect(self._set_grow)
        self._glide_from = 0.0
        self._glide_t = 1.0
        self._glide_rewinds = False
        # Linear: each leg of the flight eases itself (_shown_fraction).
        self.glide_animation = QVariantAnimation(self)
        self.glide_animation.setDuration(self.GLIDE_MS)
        self.glide_animation.setStartValue(0.0)
        self.glide_animation.setEndValue(1.0)
        self.glide_animation.valueChanged.connect(self._set_glide)
        self._text_in = 1.0
        self.text_animation = QVariantAnimation(self)
        self.text_animation.setDuration(300)
        self.text_animation.setStartValue(0.0)
        self.text_animation.setEndValue(1.0)
        self.text_animation.setEasingCurve(QEasingCurve.OutCubic)
        self.text_animation.valueChanged.connect(self._set_text_in)
        self.beat = QTimer(self)
        self.beat.setInterval(16)
        self.beat.timeout.connect(self._tick_beat)

    def _set_fade(self, value) -> None:
        self._fade = float(value)
        self.update()

    def _set_grow(self, value) -> None:
        self._grow = float(value)
        self.update()

    def _set_glide(self, value) -> None:
        self._glide_t = float(value)
        self.update()

    def _set_text_in(self, value) -> None:
        self._text_in = float(value)
        self.update()

    def beat_phase_at(self, time_ms: float) -> float:
        """0 on a beat of the red line in force at `time_ms`, rising to 1."""
        if not self._tempo:
            return 1.0
        index = max(0, bisect_right(self._tempo_times, time_ms) - 1)
        start, beat = self._tempo[index]
        # Past 300 BPM a flash per beat is a flicker, not a pulse.
        while beat < 200:
            beat *= 2
        return ((time_ms - start) % beat) / beat

    def _tick_beat(self) -> None:
        if self._clock is None:
            return
        self._now = self._clock()
        self._beat_phase = self.beat_phase_at(self._now)
        self.update()

    def set_tempo(self, tempo: list[tuple[float, float]], clock, playing=None) -> None:
        """Keep time with `tempo`'s red lines, read against `clock()`.
        `playing()` False holds the pulse still: a paused song has no beat."""
        self._tempo = tempo
        self._tempo_times = [time for time, _beat in tempo]
        self._clock = clock
        if playing is not None:
            self._playing = playing
        self._beat_phase = 1.0
        self._sync_beat()

    def set_duration(self, duration_ms: float) -> None:
        """The song's length, which the track's width stands for."""
        duration_ms = max(0.0, float(duration_ms))
        # A flight already under way reads the new length live, so it is left
        # to finish: restarted, a new song's rewind would be cut short.
        if (self._duration_ms > 0 and abs(duration_ms - self._duration_ms) > self._duration_ms * 0.005
                and self.glide_animation.state() != QVariantAnimation.Running):
            self.glide()
        self._duration_ms = duration_ms
        self.update()

    def set_preview(self, preview_ms: float) -> None:
        self._preview_ms = float(preview_ms)
        self.update()

    def set_kiai(self, spans) -> None:
        self._kiai = list(spans)
        self.update()

    def glide(self, rewind: bool = False) -> None:
        """Fly the playhead from where it is drawn to wherever the clock
        says next, instead of jumping there: a new length, or with `rewind`
        a new song -- back to the start of the track, then out to it."""
        if reduced_motion() or self._seeking:
            return
        self._glide_from = self._shown_fraction()
        self._glide_rewinds = rewind
        self.glide_animation.stop()
        self.glide_animation.setDuration(self.REWIND_GLIDE_MS if rewind else self.GLIDE_MS)
        self._glide_t = 0.0
        self.glide_animation.start()

    def _fraction(self) -> float:
        if self._duration_ms <= 0:
            return 0.0
        return min(1.0, max(0.0, self._now / self._duration_ms))

    def _shown_fraction(self) -> float:
        target = self._fraction()
        if self.glide_animation.state() != QVariantAnimation.Running:
            return target
        t = self._glide_t
        if not self._glide_rewinds:
            return self._glide_from + (target - self._glide_from) * out_cubic(t)
        if t < self.REWIND_SHARE:
            # In and out on the way back, so it settles at the start before
            # setting off again rather than bouncing off it.
            back = t / self.REWIND_SHARE
            eased = 4 * back ** 3 if back < 0.5 else 1 - (-2 * back + 2) ** 3 / 2
            return self._glide_from * (1.0 - eased)
        return target * out_cubic((t - self.REWIND_SHARE) / (1.0 - self.REWIND_SHARE))

    def _sync_beat(self) -> None:
        running = self._clock is not None and self.isVisible()
        if running and not self.beat.isActive():
            self.beat.start()
        elif not running:
            self.beat.stop()
            self._beat_phase = 1.0
            self.update()

    def set_text(self, title: str, subtitle: str) -> None:
        if (title, subtitle) == (self.title, self.subtitle):
            return
        self.title, self.subtitle = title, subtitle
        self.text_animation.stop()
        if reduced_motion():
            self._text_in = 1.0
        else:
            self._text_in = 0.0
            self.text_animation.start()
        self.update()

    def set_art(self, art: QPixmap | None) -> None:
        self._previous, self._art = self._art, art
        self._scaled = {}
        self.fade.stop()
        if reduced_motion():
            self._fade = 1.0
        else:
            self._fade = 0.0
            self.fade.start()
        self.update()

    def showEvent(self, event) -> None:
        super().showEvent(event)
        self._sync_beat()

    def hideEvent(self, event) -> None:
        self.beat.stop()  # nothing to keep time for on a page nobody is looking at
        super().hideEvent(event)

    # -- the seek band ------------------------------------------------------

    def _band_font(self) -> QFont:
        font = tabular(self.font())
        font.setPointSizeF(font.pointSizeF() * 0.82)
        font.setWeight(QFont.DemiBold)
        return font

    def _label_width(self) -> float:
        return QFontMetrics(self._band_font()).horizontalAdvance("88:88") + 10

    def track_rect(self) -> QRectF:
        """The track, at the height it is drawn right now."""
        label = self._label_width()
        height = self.TRACK_REST + (self.TRACK_HOVER - self.TRACK_REST) * self._grow
        centre = self.height() - self.BAND_HEIGHT / 2
        return QRectF(12 + label, centre - height / 2, max(1.0, self.width() - 24 - 2 * label), height)

    def _in_seek_band(self, position) -> bool:
        return position.y() >= self.height() - self.BAND_HEIGHT

    def _seek_to(self, position) -> None:
        # The track is read here, per event, so a pane the splitter has
        # widened or narrowed maps the same 0-100% across whatever it is now.
        track = self.track_rect()
        self.seek_fraction.emit(min(1.0, max(0.0, (position.x() - track.left()) / track.width())))

    def _hover(self, inside: bool, x: float | None = None) -> None:
        self._hover_x = x if inside else None
        target = 1.0 if inside else 0.0
        if reduced_motion():
            self._grow = target
        elif self._grow != target and self.grow.endValue() != target:
            self.grow.stop()
            self.grow.setStartValue(self._grow)
            self.grow.setEndValue(target)
            self.grow.start()
        self.update()

    def mousePressEvent(self, event) -> None:
        if event.button() == Qt.LeftButton and self._in_seek_band(event.position()):
            self._seeking = True
            self.glide_animation.stop()  # dragged, the head is under the pointer
            self._seek_to(event.position())
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event) -> None:
        position = event.position()
        self._hover(self._seeking or self._in_seek_band(position), position.x())
        if self._seeking:
            self._seek_to(position)
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event) -> None:
        if self._seeking and event.button() == Qt.LeftButton:
            self._seeking = False
            self._hover(self._in_seek_band(event.position()), event.position().x())
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def leaveEvent(self, event) -> None:
        if not self._seeking:
            self._hover(False)
        super().leaveEvent(event)

    def wheelEvent(self, event) -> None:
        if not self._in_seek_band(event.position()):
            super().wheelEvent(event)
            return
        delta = event.angleDelta().y() or event.angleDelta().x()
        if delta:
            self.seek_step.emit(-1 if delta > 0 else 1)
        event.accept()

    def _cover(self, art: QPixmap) -> QPixmap:
        key = art.cacheKey()
        if key not in self._scaled:
            self._scaled[key] = art.scaled(self.size(), Qt.KeepAspectRatioByExpanding, Qt.SmoothTransformation)
        return self._scaled[key]

    def resizeEvent(self, event) -> None:
        self._scaled = {}
        super().resizeEvent(event)

    def paintEvent(self, event) -> None:
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing, True)
        rect = QRectF(self.rect())
        clip = QPainterPath()
        clip.addRoundedRect(rect, 6, 6)
        painter.setClipPath(clip)
        painter.fillRect(rect, theme.color("#222a36"))
        for art, opacity in ((self._previous, 1.0 - self._fade), (self._art, self._fade)):
            if art is not None and not art.isNull() and opacity > 0:
                cover = self._cover(art)
                painter.setOpacity(opacity)
                painter.drawPixmap(int((rect.width() - cover.width()) / 2),
                                   int((rect.height() - cover.height()) / 2), cover)
        painter.setOpacity(1.0)

        pulsing = self._playing() and not reduced_motion() and bool(self._tempo)
        phase = self._beat_phase
        beat = max(0.0, 1.0 - phase / 0.6) if pulsing else 0.0
        if beat > 0.0 and any(start <= self._now < end for start, end in self._kiai):
            # The kiai lifts the art on the beat, additively: lighting it, not
            # laying a film over it. KIAI_LIFT, not the preview's 0.15 -- over
            # a whole background that read too bright (owner, 2026-10-09).
            painter.setCompositionMode(QPainter.CompositionMode_Plus)
            painter.fillRect(rect, QColor(255, 255, 255, round(255 * self.KIAI_LIFT * beat)))
            painter.setCompositionMode(QPainter.CompositionMode_SourceOver)

        wash = QLinearGradient(rect.topLeft(), rect.bottomLeft())
        wash.setColorAt(0.25, QColor(0, 0, 0, 0))
        wash.setColorAt(0.6, theme.rgba(255, 102, 170, 20))
        wash.setColorAt(1.0, QColor(13, 17, 23, 242))
        painter.fillRect(rect, wash)

        text = rect.adjusted(14, 10, -14, -(self.BAND_HEIGHT + 2))
        title_font = QFont(self.font())
        title_font.setPointSizeF(title_font.pointSizeF() * 1.55)
        title_font.setWeight(QFont.ExtraBold)
        sub_font = QFont(self.font())
        sub_font.setPointSizeF(sub_font.pointSizeF() * 0.93)
        sub_height = QFontMetrics(sub_font).height()
        painter.save()
        if self._text_in < 1.0:
            painter.setOpacity(self._text_in)
            painter.translate(0, self.TEXT_RISE_PX * (1.0 - self._text_in))
        painter.setFont(sub_font)
        painter.setPen(theme.color("#d5dce5"))
        painter.drawText(text, Qt.AlignLeft | Qt.AlignBottom,
                         QFontMetrics(sub_font).elidedText(self.subtitle, Qt.ElideRight, int(text.width())))
        painter.setFont(title_font)
        painter.setPen(theme.color(ROW_INK))
        painter.drawText(text.adjusted(0, 0, 0, -sub_height), Qt.AlignLeft | Qt.AlignBottom | Qt.TextWordWrap,
                         self.title)
        painter.restore()
        self._paint_band(painter, pulsing, phase, beat)

    def _paint_band(self, painter: QPainter, pulsing: bool, phase: float, beat: float) -> None:
        focus = theme.color(ROW_PINK_ON)
        track = self.track_rect()
        radius = track.height() / 2
        shape = QPainterPath()
        shape.addRoundedRect(track, radius, radius)
        painter.setPen(Qt.NoPen)
        painter.setBrush(theme.color("#2a3341"))
        painter.drawPath(shape)
        dim = QColor(focus)
        dim.setAlphaF(0.18)
        painter.setBrush(dim)
        painter.drawPath(shape)

        band_font = self._band_font()
        painter.setFont(band_font)
        painter.setPen(theme.color(ROW_INK_3))
        labels = QRectF(12, track.center().y() - 10, self.width() - 24, 20)
        painter.drawText(labels, Qt.AlignLeft | Qt.AlignVCenter, format_length(self._now))
        if self._duration_ms <= 0:
            return
        painter.drawText(labels, Qt.AlignRight | Qt.AlignVCenter, format_length(self._duration_ms))

        def x_of(ms: float) -> float:
            return track.left() + track.width() * min(1.0, max(0.0, ms / self._duration_ms))

        painter.save()
        painter.setClipPath(shape, Qt.IntersectClip)
        kiai = QColor(focus)
        kiai.setAlphaF(0.34)
        for start, end in self._kiai:
            if start < self._duration_ms:
                painter.fillRect(QRectF(x_of(start), track.top(), x_of(end) - x_of(start), track.height()), kiai)
        # No fill for the part already played: a gradient trailing behind the
        # head covered the kiai marks it ran over (owner, 2026-10-09). The
        # head alone says where the song is, and its pop and glow keep time.
        head_x = track.left() + track.width() * self._shown_fraction()
        painter.restore()

        centre_y = track.center().y()
        if self._preview_ms >= 0:
            mark = QColor(theme.color(ROW_INK_2))
            mark.setAlphaF(0.5)
            painter.setPen(QPen(mark, 2, Qt.SolidLine, Qt.RoundCap))
            x = x_of(self._preview_ms)
            painter.drawLine(QPointF(x, track.top() - 4), QPointF(x, track.bottom() + 4))

        if self._hover_x is not None and not self._seeking:
            hover_x = min(track.right(), max(track.left(), self._hover_x))
            ghost = QColor(theme.color(ROW_INK))
            ghost.setAlphaF(0.85 * self._grow)
            painter.setPen(Qt.NoPen)
            painter.setBrush(ghost)
            painter.drawEllipse(QPointF(hover_x, centre_y), 5, 5)
            time_text = format_length((hover_x - track.left()) / track.width() * self._duration_ms)
            metrics = QFontMetrics(band_font)
            bubble = QRectF(0, 0, metrics.horizontalAdvance(time_text) + 12, metrics.height() + 4)
            bubble.moveCenter(QPointF(hover_x, track.top() - 8 - bubble.height() / 2))
            bubble.moveLeft(min(self.width() - 4 - bubble.width(), max(4.0, bubble.left())))
            painter.setOpacity(self._grow)
            painter.setBrush(theme.color("#3a4554"))
            painter.drawRoundedRect(bubble, 4, 4)
            painter.setPen(theme.color(ROW_INK))
            painter.drawText(bubble, Qt.AlignCenter, time_text)
            painter.setOpacity(1.0)

        centre = QPointF(head_x, centre_y)
        head = self.HEAD_RADIUS
        # No ring shed on the beat: spreading over the track it hid the kiai
        # marks under it (owner, 2026-10-09). The pop and the glow keep time.
        glow_radius = head + 6 + 10 * beat
        glow = QRadialGradient(centre, glow_radius)
        halo = QColor(focus)
        halo.setAlphaF(0.35 + 0.4 * beat)
        glow.setColorAt(0.0, halo)
        glow.setColorAt(1.0, QColor(0, 0, 0, 0))
        painter.setPen(Qt.NoPen)
        painter.setBrush(glow)
        painter.drawEllipse(centre, glow_radius, glow_radius)
        scale = 1.3 if self._seeking else 1.0 + 0.3 * beat
        painter.setPen(QPen(theme.color(ROW_INK), 2))
        painter.setBrush(focus)
        painter.drawEllipse(centre, head * scale, head * scale)


class ContinueCard(QFrame):
    """One recent chart: title and difficulty, over its own background very
    dim. "Opened N min ago" went on 2026-10-07 (owner's call): the order of
    the cards already says which was most recent."""

    # How much of the chart's art shows through. Enough to tell two cards
    # apart at a glance, not so much that it competes with the title.
    ART_OPACITY = 0.12  # 0.16 until 2026-10-08: the owner wanted it fainter

    clicked = Signal(str)

    def __init__(self, parent=None) -> None:
        super().__init__(parent)
        self.setObjectName("continueCard")
        self.setCursor(Qt.PointingHandCursor)
        self.path = ""
        layout = QVBoxLayout(self)
        layout.setContentsMargins(10, 5, 10, 5)
        layout.setSpacing(0)
        # The words at the foot, as on the banner: the card is as tall as its
        # art's 16:9 now, and the art is what fills the top of it.
        layout.addStretch(1)
        self.title = QLabel()
        self.title.setStyleSheet(f"font-weight: 700; color: {ROW_INK};")
        self.version = QLabel()
        self.version.setStyleSheet(f"color: {ACCENT_PINK};")
        for label in (self.title, self.version):
            # Ignored: the card's width is a share of the row, not its text's.
            label.setSizePolicy(QSizePolicy.Ignored, QSizePolicy.Preferred)
            layout.addWidget(label)
        self.art: QPixmap | None = None
        self._cover: tuple[tuple, QPixmap] | None = None
        self._texts = ("", "")
        # Hovered, the art slowly comes forward: zooms a little, brightens,
        # and the rim lights (mockup, 2026-10-09). The card stays where the
        # layout put it -- a lift would fight the layout for its position.
        self._lift = 0.0
        self.lift = QVariantAnimation(self)
        self.lift.setEasingCurve(QEasingCurve.OutCubic)
        self.lift.valueChanged.connect(self._set_lift)

    def _set_lift(self, value) -> None:
        self._lift = float(value)
        self.update()

    def _lift_to(self, target: float, duration_ms: int) -> None:
        self.lift.stop()
        if reduced_motion():
            self._set_lift(target)
            return
        self.lift.setStartValue(self._lift)
        self.lift.setEndValue(target)
        self.lift.setDuration(duration_ms)
        self.lift.start()

    def enterEvent(self, event) -> None:
        self._lift_to(1.0, 500)
        super().enterEvent(event)

    def leaveEvent(self, event) -> None:
        self._lift_to(0.0, 200)
        super().leaveEvent(event)

    def show_chart(self, path: str, title: str, version: str, art: QPixmap | None = None) -> None:
        self.path = path
        self._texts = (title, version)
        self._elide()
        self.art = art
        self.setToolTip(path)
        self.update()

    def _elide(self) -> None:
        room = max(0, self.contentsRect().width() - 20)
        for label, text in zip((self.title, self.version), self._texts):
            # The title is bold by stylesheet, which font() does not report.
            font = QFont(label.font())
            font.setBold(label is self.title)
            label.setText(QFontMetrics(font).elidedText(text, Qt.ElideRight, room))

    def resizeEvent(self, event) -> None:
        super().resizeEvent(event)
        # 16:9 of its width, a background's own shape (owner, 2026-10-08),
        # and never too short for its two lines. Height follows width only,
        # so this settles in one pass.
        height = max(self.layout().minimumSize().height(), round(self.width() * 9 / 16))
        if height != self.height():
            self.setFixedHeight(height)
        self._elide()

    def paintEvent(self, event) -> None:
        super().paintEvent(event)  # the sheet's fill and rim
        if self.art is None:
            return
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing, True)
        painter.setRenderHint(QPainter.SmoothPixmapTransform, True)
        # Inside the 1px rim, on the same 6px corners, cropped to fill.
        inner = QRectF(self.rect()).adjusted(1, 1, -1, -1)
        clip = QPainterPath()
        clip.addRoundedRect(inner, 5, 5)
        painter.setClipPath(clip)
        painter.setOpacity(self.ART_OPACITY + 0.14 * self._lift)
        # Scaled once per size, not per paint: the hover redraws it every frame.
        key = (self.art.cacheKey(), inner.size().toSize().width(), inner.size().toSize().height())
        if self._cover is None or self._cover[0] != key:
            self._cover = (key, self.art.scaled(
                inner.size().toSize(), Qt.KeepAspectRatioByExpanding, Qt.SmoothTransformation))
        cover = self._cover[1]
        zoom = 1.0 + 0.06 * self._lift
        painter.translate(inner.center())
        painter.scale(zoom, zoom)
        painter.drawPixmap(QPointF(-cover.width() / 2, -cover.height() / 2), cover)
        painter.resetTransform()
        if self._lift > 0.0:
            rim = QColor(theme.color(ROW_PINK_ON))
            rim.setAlphaF(0.55 * self._lift)
            painter.setOpacity(1.0)
            painter.setClipping(False)
            painter.setPen(QPen(rim, 1))
            painter.setBrush(Qt.NoBrush)
            painter.drawRoundedRect(QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5), 6, 6)

    def mouseReleaseEvent(self, event) -> None:
        if event.button() == Qt.LeftButton and self.rect().contains(event.position().toPoint()):
            self.clicked.emit(self.path)
        super().mouseReleaseEvent(event)


class LibraryKeys(QObject):
    """The song select's keyboard: type anywhere to search, arrows between
    the songs and their difficulties, Enter opens, Left/Esc goes back."""

    def __init__(self, controller: "LibraryPageController") -> None:
        super().__init__(controller.window)
        self.controller = controller

    def eventFilter(self, watched, event) -> bool:
        if event.type() != QEvent.KeyPress:
            return False
        c = self.controller
        key = event.key()
        if key == Qt.Key_F5:
            c.reload_current_song()
            return True
        # Space pauses and resumes the preview, as in a music player -- except
        # mid-query, where it is a space in what is being searched for.
        if key == Qt.Key_Space and not event.modifiers() and not (
            watched is c.library_search and c.library_search.text()
        ):
            c.toggle_preview()
            return True
        if watched is c.library_search:
            if key in (Qt.Key_Up, Qt.Key_Down):
                c.move_song(-1 if key == Qt.Key_Up else 1)
                return True
            if key in (Qt.Key_Return, Qt.Key_Enter) and c.difficulty_list.count():
                c.difficulty_list.setFocus()
                return True
            return False
        if watched is c.song_list:
            if key in (Qt.Key_Up, Qt.Key_Down):
                c.move_song(-1 if key == Qt.Key_Up else 1)
                return True
            if key == Qt.Key_Right and c.difficulty_list.count():
                c.move_focus(c.difficulty_list)
                return True
            if key == Qt.Key_Escape and c.library_search.text():
                c.library_search.clear()
                return True
        elif watched is c.difficulty_list:
            if key in (Qt.Key_Left, Qt.Key_Escape):
                c.move_focus(c.song_list)
                return True
            if key in (Qt.Key_Return, Qt.Key_Enter):
                c.open_selected_difficulty()
                return True
        text = event.text()
        if text and text.isprintable() and not text.isspace() and not event.modifiers() & (Qt.ControlModifier | Qt.AltModifier):
            c.library_search.setFocus()
            c.library_search.insert(text)
            return True
        return False


class LibraryPageController:
    """Library page: browse every taiko chart under the osu! Songs folder,
    song then difficulty, and hand the chosen one back to the window.

    Owns the page's widgets and the scan state behind them. `_library_cache_path`
    stays on MainWindow itself rather than moving here -- tests monkeypatch it
    per-instance (`window._library_cache_path = lambda: ...`) to point a scan at
    a temp file, and a copy made here would not see that patch.
    """

    def __init__(self, window: "MainWindow") -> None:
        self.window = window
        # {song folder: [TaikoDifficulty, ...]} for every mode=1 chart found
        # under the configured osu! Songs folder. Filled by the sliced scan
        # (scan_step), persisted between runs in library_cache.
        self.library_songs: dict[Path, list] = {}
        self.library_cache: dict[str, list] = {}
        self._scan_songs: dict[Path, list] = {}
        self.listed_paths: set[Path] = set()
        # osu!stable's own star ratings, {(folder, file): DbBeatmap}; None when
        # there is no readable osu!.db beside the Songs folder.
        self.star_ratings: dict | None = None
        # The song preview. A QMediaPlayer rather than TrackPlayer: it streams,
        # so a preview starts at once instead of after decoding the whole
        # track, and nothing here needs the editor's sample-accurate clock.
        # Made on first use -- most windows (every test's) never preview.
        self.preview_player: QMediaPlayer | None = None
        self._preview_audio: Path | None = None
        self._preview_ms = -1
        self._preview_pending: tuple[Path, int] | None = None
        # One start somewhere other than the preview point: the editor's
        # playhead, handed over on the way back to the song list.
        self._resume_ms: int | None = None
        self._preview_loading = False
        # The player's Next/Previous walk: every song once, shuffled the first
        # time it is wanted and then kept, so Previous retraces Next.
        self._song_order: list[Path] | None = None
        self.preview_timer = QTimer(window)
        self.preview_timer.setSingleShot(True)
        self.preview_timer.setInterval(PREVIEW_SETTLE_MS)
        self.preview_timer.timeout.connect(self.start_preview)
        self._scan_iterator = None
        self._scan_files = 0
        self._scan_since_refresh = 0
        self.scan_timer = QTimer(window)
        self.scan_timer.setInterval(0)
        self.scan_timer.timeout.connect(self.scan_step)
        # Hashing and image decoding, off the GUI thread (BackgroundJobs).
        self.jobs = BackgroundJobs(window)
        # Each audio file's real length once the player has opened it: the
        # seek band stands for the song, and a chart's length stops at its
        # last note.
        self._audio_durations: dict[Path, float] = {}
        # Each difficulty's most common BPM, once read (_show_common_bpm).
        self._common_bpm: dict[Path, float | None] = {}

    def build_page(self) -> QWidget:
        """Browse every taiko chart under the osu! Songs folder: song, then difficulty.

        Laid out as the approved mockup (docs/DEVELOPMENT_PLAN.md, 3d): search
        and pills on one row, a Continue row of recent charts, the song list
        beside a detail pane headed by the map's own background.
        """
        page = QWidget()
        page.setObjectName("libraryPage")
        layout = QVBoxLayout(page)
        layout.setContentsMargins(12, 10, 12, 6)
        layout.setSpacing(8)

        top = QHBoxLayout()
        top.setSpacing(10)
        self.library_search = QLineEdit()
        self.library_search.setPlaceholderText(
            tr("MainWindow", "Search artist, title, difficulty, mapper or tags")
        )
        self.library_search.setToolTip(tr("MainWindow", "Type anywhere on this page to search"))
        self.library_search.setClearButtonEnabled(True)
        self.library_search.setMinimumWidth(240)
        self.library_search.textChanged.connect(lambda _text: self.rebuild_song_list_entering())

        # The combos are the model the pills drive: everything that reads the
        # grouping or the sort (and the tests) reads them.
        self.library_group_combo = QComboBox(page)
        self.library_group_combo.addItem(tr("MainWindow", "Nothing"), "none")
